BEGIN;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"d1714877-532c-49df-8548-efbe1bb2fada": {"definition": "A relatively small commercial venue whose primary purpose is presenting live, usually amplified, musical performance, typically featuring a stage, a house sound-reinforcement and lighting system, a bar, and an assembly occupancy governed by egress and capacity limits.", "plain_english": "A live-music club is a small venue built for live bands, usually with amplified sound. It has a stage, a sound and lighting system, a bar, and a limit on how many people can enter.", "purpose_function": "It provides a compact, purpose-fitted space for amplified live music close to the audience, with a permanent or semi-permanent PA and lighting rig.", "practical_application": "A house engineer runs and maintains the club's sound system nightly, mixing a range of visiting acts within the room's tight acoustics and legal capacity.", "category": "Performance Venue", "related_terms": ["Front-of-house position", "Stage monitor", "Sound reinforcement", "Auditorium", "Loading door"], "common_mistakes": ["UNSAFE: Admitting more people than the posted occupant load, or blocking exits, doors, or aisles with gear", "Assuming club acoustics behave like a large hall rather than a small, reflective room", "Overpowering a small room with a system sized for a much larger venue"], "scenario_contexts": ["Mixing a touring band on a club's house PA", "Setting up backline and monitors on a small club stage", "Checking occupant load and exit paths before doors open"]}, "cbe09969-73ce-4a61-a40c-db9155f99fd7": {"definition": "An outdoor or semi-enclosed area at a venue where trucks and vehicles park and manoeuvre to be loaded and unloaded, adjacent to the loading dock or get-in, providing vehicle access and space for moving production equipment and scenery into and out of the building.", "plain_english": "A loading bay is the outdoor area where trucks pull in to be loaded and unloaded. It sits next to the doors used to move gear into the building.", "purpose_function": "It gives production vehicles a safe place to park and manoeuvre while crew move heavy equipment, scenery, and cases between the truck and the venue.", "practical_application": "Crew back trucks into the loading bay and move flight cases from the vehicle to the stage during load-in and load-out.", "category": "Service Spaces", "related_terms": ["Loading dock", "Loading door", "Loading corridor", "Get-in", "Backstage"], "common_mistakes": ["Confusing the outdoor loading bay with the raised loading dock platform itself", "UNSAFE: Standing behind or between reversing vehicles in the bay, where drivers cannot see you", "UNSAFE: Blocking the loading bay so it cannot serve as an emergency vehicle or exit route"], "scenario_contexts": ["Positioning trucks in the loading bay for a load-in", "Moving cases from a parked vehicle into the venue", "Coordinating vehicle movements during a busy load-out"]}, "de8c139f-ef63-41dd-8f5b-b9ff7dbe5335": {"definition": "An internal passage connecting the loading dock or get-in to the stage, storage, and technical areas, sized and finished so bulky flight cases, scenery, and equipment can be wheeled through the building without obstruction.", "plain_english": "A loading corridor is a wide indoor hallway. It links the loading doors to the stage and store rooms, so crew can wheel heavy cases through the building.", "purpose_function": "It provides a clear, level route for moving large equipment between the delivery point and the stage, keeping heavy traffic away from public and performance areas.", "practical_application": "Crew wheel cases and scenery along the loading corridor during load-in, keeping it clear so traffic and any emergency exit path stay open.", "category": "Service Spaces", "related_terms": ["Loading dock", "Loading door", "Loading bay", "Crossover corridor", "Backstage"], "common_mistakes": ["UNSAFE: Storing cases or parking gear in the loading corridor, blocking the route and any exit it serves", "Confusing a loading corridor with a public cross aisle or a backstage crossover", "Underestimating the corridor width and door heights needed for large cases"], "scenario_contexts": ["Wheeling flight cases from the dock to the stage", "Planning a route for oversized scenery through the building", "Keeping the corridor clear as an exit path during a show"]}, "6ddffae0-0416-4ea2-a13e-ac559c8c699a": {"definition": "A raised platform, typically built at the bed height of delivery trucks, where vehicles are loaded and unloaded; it may be fitted with a dock leveller, bumpers, and a roller or overhead door, and forms the main goods entrance for production equipment and scenery.", "plain_english": "A loading dock is a raised platform set at the height of a truck's floor. Trucks back up to it so crew can roll gear straight off the truck and into the building.", "purpose_function": "It matches the truck bed to floor level so heavy equipment rolls on and off quickly without lifting, forming the venue's main goods entrance.", "practical_application": "During load-in, crew back the truck to the dock, set the leveller, and wheel flight cases from the truck straight onto the dock and inside.", "category": "Service Spaces", "related_terms": ["Loading bay", "Loading door", "Loading corridor", "Get-in", "Backstage"], "common_mistakes": ["UNSAFE: Stepping or rolling a case off an unguarded dock edge or open dock door, risking a fall to the ground below", "UNSAFE: Working between a reversing truck and the dock, where you can be crushed", "Confusing the raised dock platform with the outdoor loading bay where the truck parks"], "scenario_contexts": ["Backing a truck to the dock and setting the leveller for load-in", "Rolling flight cases off the dock into the loading corridor", "Checking dock edge guarding and lighting for a safe night load-out"]}, "96f50bf2-05a7-4579-a8d7-1719065e08d9": {"definition": "A large door, often a roller shutter or tall hinged door, through which scenery, equipment, and flight cases are moved into and out of a venue; it is sized to admit bulky loads and usually opens from the loading dock or bay into the stage, corridor, or scene dock.", "plain_english": "A loading door is a large door used to move gear in and out of a venue. It is tall and wide, often a roller shutter, so big cases and scenery fit through.", "purpose_function": "It provides an opening large enough for oversized production equipment and scenery to pass, connecting the delivery point to the working areas inside.", "practical_application": "Crew open the loading door at the dock to move flight cases and scenery in, then secure it; it can also serve as a fire or emergency exit.", "category": "Service Spaces", "related_terms": ["Loading dock", "Loading bay", "Loading corridor", "Get-in", "Scene dock"], "common_mistakes": ["Confusing the loading door with the loading dock platform or bay it opens onto", "UNSAFE: Standing under a partly open roller shutter, or leaving it unsecured so it can fall", "UNSAFE: Blocking or chaining a loading door that also serves as a required emergency exit"], "scenario_contexts": ["Moving scenery through the loading door during a get-in", "Checking a load's height and width against the door opening", "Securing the loading door after load-in"]}, "41b2ec68-52cf-4064-b509-74ec18f69585": {"definition": "A backstage room where performers apply and remove stage makeup, typically fitted with mirrors, even task lighting (often a lit mirror surround), counters, and washing facilities; it may be combined with or adjacent to dressing rooms.", "plain_english": "A makeup room is a backstage room where performers put on and take off stage makeup. It has mirrors, bright even lighting, and counters, often next to the dressing rooms.", "purpose_function": "It gives performers a well-lit, dedicated space to apply makeup accurately before a show and remove it afterwards.", "practical_application": "Audio crew may fit or check wireless microphones and earpieces on performers here while they are in the makeup chair, before they reach the stage.", "category": "Production Spaces", "related_terms": ["Dressing room", "Green room", "Wardrobe", "Costume shop", "Wireless microphone"], "common_mistakes": ["Confusing a makeup room with a dressing room, though the two are often combined", "Fitting a body microphone before makeup is done, so it gets smudged or knocked loose", "UNSAFE: Overloading mirror-light and small-appliance circuits, risking overheating and fire"], "scenario_contexts": ["Fitting a lavalier microphone on a performer in the makeup chair", "Doing a radio-mic check before performers leave for the stage", "Coordinating call times with performers in makeup"]}, "b597dc2f-35cd-419a-b6bb-25c8cfaf26ee": {"definition": "In theatre and stage design, the masking line is a line of sight projected from an extreme audience seat that defines the boundary of what the audience can see into the wings, flies, or offstage areas. Masking such as legs, borders, and tabs is positioned along or beyond this line so that backstage space, rigging, and crew remain concealed from view.", "plain_english": "A masking line shows how far into the wings or up toward the ceiling the audience can see. The crew hangs curtains along this line to hide the backstage area from view.", "purpose_function": "It gives designers a reference for placing drapes and scenery so that offstage equipment, performers, and rigging stay hidden from every seat in the house.", "practical_application": "A technician uses masking lines to position legs and borders so lighting units and crew waiting in the wings are not visible to the audience.", "category": "Sightlines & Masking", "related_terms": ["Maximum sightline", "Wings", "Fly tower", "Proscenium", "Auditorium", "Setting line"], "common_mistakes": ["Checking masking from only one central seat instead of the extreme side and front-row seats", "Confusing the masking line with the setting line or the plaster line", "Assuming top borders mask overhead rigging when steep or high side seats can still see into the flies"], "scenario_contexts": ["Positioning stage legs and borders during a theatre load-in", "Reviewing sightlines from front corner seats before a show opens", "Designing masking for a thrust or open stage with wide audience viewing angles"]}, "9f6ee459-3892-4c27-9f11-1495b1d1e6e5": {"definition": "The maximum sightline is the most extreme line of sight from an audience seat — typically the front-row end seats, the widest side seats, or the highest gallery seats — that governs how much of the stage, and how far into offstage and overhead areas, can be seen. It defines the worst-case viewing condition that stage layout, scenery, and masking must satisfy.", "plain_english": "The maximum sightline is the widest or steepest view any seat in the house has. Designers plan for these worst-case seats so no one can see backstage.", "purpose_function": "It sets the limits that masking, scenery, and stage layout must meet, so that even the most extreme seats get an acceptable view and no unwanted areas are exposed.", "practical_application": "Designers and technicians check the maximum sightlines from corner and top seats to decide where masking and scenery edges must be placed.", "category": "Sightlines & Masking", "related_terms": ["Masking line", "Proscenium", "Auditorium", "Gallery", "Setting line", "Fly tower"], "common_mistakes": ["Designing only for the central seat and ignoring the extreme corner or gallery seats", "Confusing the maximum worst-case sightline with the average or ideal viewing line", "Forgetting the vertical sightline from steep balcony seats up into the flies"], "scenario_contexts": ["Determining masking positions from the extreme side seats of a proscenium house", "Checking whether high balcony seats can see over the top border into the fly loft", "Setting the height of a set piece so it clears the worst-case sightline"]}, "fa4ef4ee-64ea-48b0-b59a-9b0290225420": {"definition": "The mix position, or front-of-house mix position, is the location in the audience seating area from which the sound engineer operates the main mixing console. It is chosen to lie within the main loudspeaker coverage and away from acoustic anomalies, so the engineer hears a representative sample of the audience's experience.", "plain_english": "The mix position is where the sound engineer and the main mixing desk sit out among the audience. It should be placed where the sound is typical of what the crowd hears.", "purpose_function": "Placing the console among the audience lets the engineer mix by what listeners actually hear, rather than guessing from backstage or from the side of the stage.", "practical_application": "A technician sets up the front-of-house console at the mix position, typically near the centre line and within the main speaker coverage, clear of rear and side walls.", "category": "Operating Position", "related_terms": ["Mix tower", "Monitor-world position", "Front of house", "Loudspeaker coverage", "Auditorium", "Masking line"], "common_mistakes": ["Placing the console against the rear wall, where bass build-up and reflections colour the sound", "Tucking the mix position under a balcony overhang, outside the main loudspeaker coverage", "Assuming the mix position sounds like every seat, when it is only one sample point in the room"], "scenario_contexts": ["Choosing where to build the front-of-house platform when advancing a concert", "Relocating the console after finding a coverage dead spot at the planned location", "Negotiating with a venue over seats lost to the mix position footprint"]}, "d7fb408f-27c0-4d50-afb7-cd81a8194a1d": {"definition": "A mix tower is a raised, engineered platform or scaffold structure erected in the audience area to carry the front-of-house mixing position, and often lighting control and follow-spot operators. It elevates the console for clear sightlines to the stage and to keep it within the main loudspeaker coverage above a standing crowd at large-scale events.", "plain_english": "A mix tower is a raised platform built out in the crowd. It holds the sound desk up high. The engineer can see the stage and stay in the main speaker coverage.", "purpose_function": "It provides a stable, elevated home for front-of-house control at festivals and arenas, giving clear sightlines and placing the desk in good coverage above the audience.", "practical_application": "Riggers and technicians build the mix tower to its rated load, guard its edges and access, and run signal and power up to the console platform.", "category": "Operating Position", "related_terms": ["Mix position", "Front of house", "Follow spot", "Loudspeaker coverage", "Egress", "Monitor-world position"], "common_mistakes": ["UNSAFE: Overloading the platform beyond its rated capacity with extra gear, cases, or people", "UNSAFE: Working on an elevated mix tower without guardrails, edge protection, or fall protection", "UNSAFE: Positioning the tower where it blocks or narrows an audience egress route", "Building the tower so far back or so high that the console leaves the main loudspeaker coverage"], "scenario_contexts": ["Erecting a scaffold mix tower at an outdoor music festival", "Coordinating the tower footprint with the venue's egress and sightline plan", "Running weather-protected power and signal up to an elevated front-of-house platform"]}, "f38aeab8-df1f-4824-b0b6-15ce96dbe972": {"definition": "Monitor world, or the monitor-world position, is the operating position — normally located just offstage at one wing — where the monitor engineer and the monitor mixing console are stationed. From here the engineer builds and adjusts the performers' stage monitor and in-ear mixes with clear sightlines to the stage.", "plain_english": "Monitor world is the spot at the side of the stage where the monitor engineer works. From there they mix what the band hears in their floor wedges or earpieces.", "purpose_function": "Placing the monitor desk beside the stage keeps the engineer close to the performers, so they can read cues and adjust each player's on-stage sound quickly.", "practical_application": "A technician sets up monitor world in the wing with sightlines to every performer, then patches the stage inputs into the monitor console and in-ear systems.", "category": "Operating Position", "related_terms": ["Mix position", "Front of house", "Stage monitor", "In-ear monitor", "Wings", "Wedge"], "common_mistakes": ["Placing monitor world where the engineer cannot see the performers or read their hand cues", "Confusing monitor world with the front-of-house mix position", "UNSAFE: Running monitor cabling across a wing walkway without matting or cable ramps, creating a trip hazard in the dark backstage"], "scenario_contexts": ["Setting up the monitor console in the stage-left wing before a concert", "Ringing out floor wedge monitors from monitor world during soundcheck", "Managing in-ear monitor mixes for a touring band from the side of the stage"]}, "9927af99-84c2-4e29-86b4-34a6b4f8c5a3": {"definition": "A multipurpose hall is an auditorium or hall designed to accommodate a wide range of event types — such as amplified and acoustic concerts, theatre, conferences, and banquets — usually through flexible seating, staging, and variable acoustic elements. This flexibility comes at the cost of not being acoustically optimal for any single use.", "plain_english": "A multipurpose hall is a space built to host many kinds of events. It uses movable seats and adjustable acoustics so it can work for concerts, talks, and shows.", "purpose_function": "It lets one venue serve many uses, which is cost-effective, though its adjustable acoustics are a compromise rather than ideal for any single type of event.", "practical_application": "A technician working a multipurpose hall often adds sound reinforcement and adjusts acoustic drapes or panels to suit each event's needs.", "category": "Performance Venue", "related_terms": ["Variable acoustics", "Concert hall", "Auditorium", "Reverberation time", "Acoustic banner", "Proscenium"], "common_mistakes": ["Expecting concert-hall acoustics from a hall designed as a compromise for many uses", "Ignoring variable acoustic elements such as drapes and panels that can be tuned for each event", "Assuming one loudspeaker setup suits every event a multipurpose hall hosts"], "scenario_contexts": ["Deploying a PA in a reverberant multipurpose hall for a rock show", "Adjusting deployable acoustic banners before a spoken-word event", "Reconfiguring seating and stage between a banquet and a concert"]}, "f52fad66-e9bf-48e7-a40c-9709bf7c68a1": {"definition": "A music venue is any space designed or adapted for the live performance of music before an audience. It spans a wide range of scales and types — from small clubs and bars to theatres, concert halls, arenas, and stadiums — each with acoustic and sound-reinforcement characteristics suited to its size and program.", "plain_english": "A music venue is any place where live music is played for an audience. It can be as small as a bar or as big as a stadium.", "purpose_function": "It provides the stage, audience space, and infrastructure — power, rigging, and often a house sound system — needed to present live music.", "practical_application": "A technician reads a venue's size and acoustics to choose the right PA, microphone technique, and system tuning for the room.", "category": "Performance Venue", "related_terms": ["Concert hall", "Nightclub", "Multipurpose hall", "Auditorium", "Front of house", "Reverberation time"], "common_mistakes": ["Bringing a PA sized for the wrong scale of venue", "Ignoring how a venue's acoustics change once a crowd fills the room", "Assuming every venue provides house power, rigging points, or a house PA"], "scenario_contexts": ["Advancing a show by gathering a venue's technical specifications", "Choosing a compact line array for a mid-sized music venue", "Adjusting system tuning between an empty soundcheck and a full house"]}, "64163c23-2c24-4b0f-b62d-574909a884f0": {"definition": "A narthex is an entrance area, vestibule, or portico at the west (main-entrance) end of a church, situated between the outer doors and the nave. Historically it served as a transitional space separating those not yet admitted to the main body of the church from the congregation.", "plain_english": "A narthex is the entrance hall of a church, just inside the main doors. It sits before the nave, the large space where the congregation gathers.", "purpose_function": "It serves as a transitional entrance space and buffer between the outside and the worship area, and is usually acoustically separated from the resonant nave.", "practical_application": "A technician setting up sound in a church treats the narthex as a distinct, less reverberant space that may need its own delay loudspeaker for coverage.", "category": "Architectural Space", "related_terms": ["Nave", "Chancel", "Apse", "Reverberation time", "Delay speaker", "Auditorium"], "common_mistakes": ["Confusing the narthex (entrance vestibule) with the nave (the main seating area)", "Assuming the narthex shares the nave's long reverberation, when it is usually separated from it", "Overlooking that the narthex may need its own delay loudspeaker for even coverage"], "scenario_contexts": ["Placing an overflow or delay loudspeaker in a church narthex", "Routing cabling from an entrance narthex through to the chancel", "Assessing acoustics when a service extends out into the narthex"]}, "a508aef7-b28a-4703-ae9d-1c703547c6aa": {"definition": "A nightclub is an entertainment venue, typically operating in the evening and late at night, that provides amplified recorded or live music, a dance floor, lighting, and bar service. Acoustically it is usually a small, hard-surfaced space run at high sound-pressure levels for dancing.", "plain_english": "A nightclub is an evening venue for dancing to loud, amplified music. A DJ or band plays while a sound system and lighting fill a usually small, hard room.", "purpose_function": "It provides a space for social dancing and entertainment built around a high-output sound system and lighting, rather than around natural acoustics.", "practical_application": "A technician tunes a nightclub system for even dance-floor coverage while managing high sound levels and hearing-exposure limits for staff.", "category": "Performance Venue", "related_terms": ["Music venue", "Loudspeaker coverage", "Subwoofer", "Hearing protection", "Front of house", "Reverberation time"], "common_mistakes": ["UNSAFE: Running sustained sound levels that exceed safe occupational hearing-exposure limits for staff", "UNSAFE: Blocking, locking, or overcrowding exits beyond the room's rated occupancy", "Ignoring how a small, hard-surfaced room causes bass build-up and harshness"], "scenario_contexts": ["Tuning a nightclub system for even dance-floor coverage", "Monitoring staff sound-exposure levels over a long DJ set", "Managing occupancy and keeping exits clear during a busy night"]}, "e02dc033-a5bf-4b30-a444-7b0194bfb4a9": {"definition": "A performance venue in which stage and audience seating are outdoors with no roof enclosing the space, so there is little or no room reverberation and the sound field is governed by the direct sound, the ground, and any raked seating rather than by enclosing surfaces. Ranging from ancient Greek theatres and Roman amphitheatres to modern amphitheatres and bandshells, such venues rely on raked seating, hard forestage reflectors, or electronic sound reinforcement for adequate loudness and intelligibility.", "plain_english": "An open-air theater is a stage and seating built outdoors with no roof. There are no walls or ceiling to bounce sound back. So the audience relies on sloped seating or loudspeakers to hear clearly.", "purpose_function": "It stages performances outdoors for large crowds, but because it lacks enclosing surfaces it gives no natural reverberation, so loudness and clarity must come from the seating rake or from reinforcement.", "practical_application": "Technicians deploy sound reinforcement and weather-protected equipment at open-air venues, and plan for wind, temperature gradients, and the absence of helpful room reflections.", "category": "Performance Venue", "related_terms": ["Amphitheater", "Bandshell", "Sound reinforcement", "Reverberation time", "Raked seating", "Auditorium"], "common_mistakes": ["Assuming an open-air theater has helpful room reverberation like an indoor hall, when it has almost none", "UNSAFE: Failing to weatherproof power distribution and equipment outdoors, risking electric shock and equipment damage", "Ignoring wind and temperature gradients that bend and disrupt sound outdoors"], "scenario_contexts": ["Designing a reinforcement system for an outdoor amphitheater concert", "Weatherproofing power and audio equipment for an open-air performance", "Planning loudspeaker coverage where no walls provide reflected sound"]}, "de1c7ae6-b35d-42b6-a7bc-06e27cb075d6": {"definition": "In British theatre convention, opposite prompt (OP) is the side of the stage opposite the prompt side (PS); as the prompt corner is conventionally at stage left, OP denotes stage right, that is, the actor's right when facing the audience. It is a fixed directional reference used to locate scenery, equipment, and crew regardless of the way a performer happens to be facing.", "plain_english": "Opposite prompt, or OP, is a British name for one side of the stage. The prompt side is usually stage left, so opposite prompt means stage right. It is the actor's right as they face the audience.", "purpose_function": "It gives crew a fixed way to name the sides of the stage that does not change with the direction a performer is facing.", "practical_application": "Stage and sound crew use OP in cue sheets and plots to say which side of the stage scenery, loudspeakers, or gear belongs on.", "category": "Stage geography", "related_terms": ["Prompt side", "Stage left", "Stage right", "Wings", "Crossover corridor", "Proscenium"], "common_mistakes": ["Confusing opposite prompt (stage right) with the prompt side (stage left)", "Reading OP from the audience's viewpoint instead of the performer's, which reverses left and right", "Assuming the prompt corner is always stage left when some houses reverse it"], "scenario_contexts": ["Labelling which side of the stage a loudspeaker stack goes on in a plot", "Directing crew during a scene change using PS and OP", "Reading a stage plan that marks positions as prompt or opposite prompt"]}, "6f0e729f-a5ea-4a33-97b9-6424da8c4bdb": {"definition": "The raised staging area on which an orchestra is seated to perform, typically an open platform (often tiered with risers) at the front of a concert hall or the performance end of a multipurpose auditorium, without a proscenium or fly tower. It may be fitted with an acoustic shell or canopy to aid ensemble hearing and projection to the house.", "plain_english": "The orchestra platform is the raised stage where an orchestra sits to play. It is usually open to the room. Step-like risers let the players see and hear each other.", "purpose_function": "It groups the players as an ensemble and, with risers and reflectors, helps them hear one another while sending sound out to the audience.", "practical_application": "Crew set the platform with risers, chairs, stands, and a shell, then place overhead or spot microphones for recording or reinforcement.", "category": "Performance Spaces", "related_terms": ["Concert platform", "Acoustic shell", "Riser", "Orchestra pit", "Concert hall", "Spot microphone"], "common_mistakes": ["Confusing an open orchestra platform with a proscenium stage that has wings and a fly tower", "Forgetting that risers change sightlines and microphone placement for the back rows", "Positioning an acoustic shell so it no longer projects sound toward the audience"], "scenario_contexts": ["Setting risers and chairs for an orchestra on the platform", "Positioning overhead microphones above the platform for a broadcast", "Arranging an acoustic shell around the platform to reflect sound to the house"]}, "2800ff7f-276d-4304-b3f5-dd13f63ce4f7": {"definition": "An enclosed architectural space, usually recessed into or built above the walls of a church or auditorium, that houses the pipes and mechanism of a pipe organ; the sound emerges into the room through a tone opening or grille, frequently fitted with a swell box and hinged shutters to control loudness. Enclosing the pipes in a chamber colours and can attenuate the tone compared with pipes standing free in the room.", "plain_english": "An organ chamber is a walled-in room that holds the pipes of a large pipe organ. The sound leaves through an opening or grille facing the audience. Shutters on the opening can make the organ louder or softer.", "purpose_function": "It houses and protects the organ's pipes and lets the tone be shaped and, with swell shutters, controlled in loudness as it enters the room.", "practical_application": "When recording or reinforcing an organ, engineers place microphones at the chamber's tone opening, since that is where the sound actually leaves the pipes.", "category": "Acoustic Enclosure", "related_terms": ["Organ loft", "Organ console position", "Pipe organ", "Swell box", "Reverberation time"], "common_mistakes": ["Assuming pipes in a chamber sound as strong as pipes standing openly in the room, when the chamber muffles them", "Miking the organ out in the room instead of at the chamber's tone opening", "Confusing the organ chamber, which holds the pipes, with the console the organist plays"], "scenario_contexts": ["Placing microphones at an organ chamber's tone opening for a recording", "Assessing why a chambered organ sounds muffled in the room", "Coordinating with an organ builder about swell-shutter control in the chamber"]}, "5ce4a052-32df-44b4-b4e6-074fc6d14a70": {"definition": "The location within a venue of the organ console — the desk of keyboards (manuals), pedalboard, and stops from which the organist plays — which may be built into the organ case or detached and movable, and whose placement determines the organist's sightlines to conductor and performers and the perceptible delay between a key being pressed and the pipes speaking when the console is remote from the pipework.", "plain_english": "The organ console is the desk of keyboards and pedals the organist plays. Its position in the room matters. If it sits far from the pipes, the player hears a short delay. The gap is between pressing a key and the pipe sounding.", "purpose_function": "Placing the console well gives the organist clear sightlines to the conductor and singers and manages the timing delay when the pipes are far away.", "practical_application": "Engineers account for the console position when planning talkback, sightlines, and any latency between the organist's playing and the pipe sound in a recording.", "category": "Stage geography", "related_terms": ["Organ chamber", "Organ loft", "Pipe organ", "Concertmaster position", "Latency"], "common_mistakes": ["Confusing the console, which the organist plays, with the pipes or chamber that make the sound", "Ignoring the delay an organist faces when the console sits far from distant pipes", "Assuming every organ console is fixed, when many are detached and movable"], "scenario_contexts": ["Planning sightlines from a movable console to the conductor", "Coordinating a recording where the console is remote from the pipes", "Positioning a detached console for a concerto performance with orchestra"]}, "ac8f8555-f624-4df3-a9e2-993968498880": {"definition": "An elevated gallery or raised platform, typically at the rear or a side of a church or concert hall, on which a pipe organ — and often the choir — is placed; its height and position help project the organ and voices over the congregation or audience. It is also called an organ gallery.", "plain_english": "An organ loft is a raised balcony that holds a pipe organ, often with the choir. It is usually at the back or side of a church. Its height helps the organ and singers carry over the people below.", "purpose_function": "Raising the organ and choir on a loft helps their sound project over the heads of the audience and fill the room more evenly.", "practical_application": "Engineers rig or place choir and organ microphones in the loft, working around its height, railings, and limited access.", "category": "Performance Spaces", "related_terms": ["Organ chamber", "Organ console position", "Pipe organ", "Gallery", "Choir"], "common_mistakes": ["Confusing the organ loft, a raised gallery, with the organ chamber that encloses the pipes", "Underestimating how the loft's height changes microphone rigging and cable runs", "Assuming the choir always stands at floor level when it often sits in the organ loft"], "scenario_contexts": ["Rigging choir microphones in a rear organ loft", "Recording an organ and choir together from the loft", "Running cable safely up to an elevated organ loft"]}, "f3924e62-20ff-46d4-a590-7b035d0135a5": {"definition": "A secondary room, separate from the main auditorium or worship space, used to seat attendees beyond the primary room's occupant load, into which a live audio (and usually video) relay of the event is fed. It extends effective capacity while each space is kept within the occupant load set by the applicable life-safety code.", "plain_english": "An overflow room is an extra room used when the main hall is full. A live sound and video feed of the event plays in it. This lets more people attend while keeping each room within its safe crowd limit.", "purpose_function": "It adds seating capacity for large events by relaying the program to a separate room, while keeping every space within its legal occupant load.", "practical_application": "Audio crew commission a dedicated feed to the overflow room, checking level, sync with any video, and coverage before doors open.", "category": "Audience Spaces", "related_terms": ["Zone feed", "Cry room", "Auditorium", "Occupant load", "Distributed loudspeaker"], "common_mistakes": ["UNSAFE: Packing an overflow room past its posted occupant load, which blocks safe egress", "Sending the overflow room audio without checking it stays in sync with the video feed", "Forgetting the overflow room entirely, so its audience gets no usable feed"], "scenario_contexts": ["Feeding audio and video to an overflow room for a full church service", "Commissioning an overflow feed for a sold-out conference session", "Setting loudspeaker levels in an overflow room during a system check"]}, "b5950e6f-5330-4d25-9426-83a5ea9262d1": {"definition": "A crossover route located at high level rather than at stage-floor level, allowing performers or crew to pass from one side of the stage to the other above the performance area — for example across a bridge, catwalk, or fly gallery — where no ground-level crossover behind the setting is available.", "plain_english": "A crossover is a hidden path from one side of the stage to the other. An overhead crossover is that path built up high, like a bridge or catwalk over the stage. Crew use it when there is no route at floor level.", "purpose_function": "It provides a way to cross the stage unseen when scenery or a solid back wall blocks a floor-level crossover, keeping traffic out of the audience's view.", "practical_application": "Crew move quietly across an overhead crossover during a scene, and secure any tools or cable at height so nothing can fall to the stage below.", "category": "Backstage Spaces", "related_terms": ["Crossover corridor", "Catwalk", "Fly gallery", "Grid", "Wings"], "common_mistakes": ["UNSAFE: Carrying loose tools or cable across an overhead crossover without securing them, risking a fall onto people below", "UNSAFE: Using a high-level crossover without proper guardrails or fall protection", "Confusing an overhead crossover with a floor-level crossover corridor"], "scenario_contexts": ["Crossing the stage at high level when a solid setting blocks the floor route", "Routing crew over a catwalk during a scene change", "Securing gear before moving along an overhead crossover"]}, "fc3e59a8-28f7-4dee-91e6-4147c4c6f776": {"definition": "A production workshop where scenery and stage cloths are painted and finished, typically equipped with a vertical paint frame or a horizontal paint deck, strong even lighting, ventilation, and space for mixing and drying; it is also called a scenic paint shop or scenic art studio.", "plain_english": "The paint shop is the workshop where scenery is painted. It has big frames or floor space for large backdrops, bright lighting, and good ventilation. Painting and drying happen here, away from the stage.", "purpose_function": "It gives scenic artists a dedicated, well-lit, ventilated space to paint large scenery and let it dry, separate from the stage and other trades.", "practical_application": "Audio crew coordinate with the paint shop over schedule and ventilation, and keep equipment clear of wet paint, solvents, and drying scenery.", "category": "Production Spaces", "related_terms": ["Scene shop", "Paint frame", "Costume shop", "Crew room", "Scenery"], "common_mistakes": ["UNSAFE: Working with solvents, pigments, or aerosols without adequate ventilation and protective equipment", "Confusing the paint shop, where scenery is painted, with the scene shop, where scenery is built", "Storing sensitive audio gear near wet paint, dust, and solvent fumes"], "scenario_contexts": ["Painting a large backdrop on a paint frame before a get-in", "Coordinating equipment storage away from the paint shop's fumes and dust", "Scheduling scenic painting and drying time before load-in"]}, "ad998693-023f-4d85-9ea4-0e1faa16ca01": {"definition": "A parking position is a designated location within or adjacent to the stage where movable equipment - such as scenery wagons, acoustic shell towers, pianos, stage lifts, or powered hoist units - is placed and held when not in use. Planning these positions into the layout keeps circulation routes, exits, and the playing area clear, and gives powered stage machinery a defined home, or parked, position.", "plain_english": "A parking position is a set spot where movable stage gear waits when it is not in use. Wagons, pianos, and lifts each get a home out of the way. This keeps the stage and walkways clear and safe.", "purpose_function": "It gives large, movable stage equipment a planned home so it does not block traffic, exits, or the performance. Defined parking positions also let powered machinery rest in a known, safe position.", "practical_application": "Stage crew return wagons, towers, and lifts to their marked parking positions after a scene change or show, keeping crossovers and exits clear.", "category": "Stage geography", "related_terms": ["Scene dock", "Scenery wagon", "Stage lift", "Wings", "Get-in", "Orchestra shell"], "common_mistakes": ["Treating any open floor as a parking spot instead of the planned positions that keep sightlines and traffic clear.", "Confusing a parking position with long-term storage; parking is a temporary, show-ready holding spot near the stage.", "UNSAFE: Parking wagons, cases, or towers across a fire exit or egress route, blocking escape in an emergency.", "UNSAFE: Leaving powered stage machinery out of its designated parked position and not de-energized, so it can move unexpectedly."], "scenario_contexts": ["Returning scenery wagons to their parking positions after a set change.", "Rolling an acoustic shell tower to its offstage parking position to open up the stage.", "Lowering a stage lift to its parked position before a performance."]}, "c110042c-0499-4fe5-bd19-a5ae8e1f89ef": {"definition": "The performance area is the part of a venue set aside for performers to present to an audience, whether a formal raised stage, a thrust or arena platform, or an open floor in a flexible space. It is defined in contrast to the audience seating and the backstage and support areas, and its size, shape, and boundaries depend on the venue type and staging format.", "plain_english": "The performance area is the space where the show actually happens. It is where the performers are, not the seats or backstage. Its size and shape change with the venue and the kind of event.", "purpose_function": "It defines where the action takes place so seating, sightlines, lighting, and sound can all be planned around it. Separating it from audience and support space organises how the whole venue works.", "practical_application": "A technician sets up lighting and sound to cover the whole performance area evenly and checks that sightlines from the seats reach all of it.", "category": "Performance space", "related_terms": ["Stage", "Playing area", "Acting area", "Auditorium", "Sightline", "Thrust stage"], "common_mistakes": ["Assuming the performance area is always a raised proscenium stage, when it can be a thrust, arena floor, or open studio space.", "Confusing the performance area with the whole stage house, which also includes wings and backstage.", "Forgetting that the performance area's edges may change with each production's staging."], "scenario_contexts": ["Planning a lighting rig to cover an arena performance area seen from all sides.", "Marking out the performance area on the floor of a black-box studio.", "Setting sightlines so every seat sees the full performance area."]}, "24e7f57c-9764-4abc-b3cb-094ee3107715": {"definition": "A performing-arts center is a building or complex of buildings containing one or more purpose-designed venues - such as a theatre, concert hall, recital hall, or studio - together with the front-of-house, backstage, and technical support spaces needed to present live performance. Multi-venue centers group different room types under shared circulation, box office, and production facilities so a range of events can run in one facility.", "plain_english": "A performing-arts center is a building, or group of buildings, built for live shows. It often holds several spaces, like a theatre and a concert hall, under one roof. It also has lobbies, backstage rooms, and technical support.", "purpose_function": "It brings several performance spaces and their support areas together so one facility can host many kinds of events. Sharing lobbies, box office, and workshops makes the whole complex more efficient.", "practical_application": "A touring technician arriving at a performing-arts center checks which of its venues the show is in and what shared loading dock and power it offers.", "category": "Venue type", "related_terms": ["Concert hall", "Recital hall", "Auditorium", "Black-box theater", "Front of house", "Civic theater"], "common_mistakes": ["Assuming a performing-arts center is a single hall, when it often contains several separate venues.", "Expecting every venue in the center to share the same acoustics or rigging; each room is designed for its own use.", "Overlooking shared spaces like the loading dock and workshops when planning a load-in."], "scenario_contexts": ["A touring show loading into one theatre within a multi-venue performing-arts center.", "A city building a performing-arts center that houses a concert hall and a drama theatre.", "Scheduling several events at once across the different halls of one center."]}, "68ae72d9-7ca0-4ab9-ad80-88eb33b2f21d": {"definition": "The piano position is the designated location on the stage, or on a stage or pit lift, where a grand piano is placed for performance, chosen for sightlines, acoustic projection, and the orientation of the raised lid toward the audience. In concert halls the preferred positions for a solo recital, a concerto with orchestra, or chamber use are often established and sometimes marked on the stage floor.", "plain_english": "The piano position is the spot on stage where the grand piano is set for a show. It is picked so the audience can see and hear it well, with the open lid aimed their way. Different kinds of concerts use different spots.", "purpose_function": "It fixes where the piano sits so its sound projects to the audience and it works with other performers and sightlines. A consistent position also speeds setup and keeps the sound predictable.", "practical_application": "Stage crew place the grand piano on its marked position and angle the lid toward the house for a recital, then move it within the orchestra for a concerto.", "category": "Stage geography", "related_terms": ["Piano storage", "Concertmaster position", "Concert platform", "Stage", "Sightline", "Concert hall"], "common_mistakes": ["Placing the piano anywhere convenient instead of the position that projects the open lid toward the audience.", "Using the same position for a solo recital and a concerto, when the piano must sit differently within the orchestra.", "Forgetting to allow room for the bench, page-turner, and safe crew access when setting the position."], "scenario_contexts": ["Setting a concert grand for a solo recital with the lid open toward the house.", "Positioning the piano within the orchestra for a concerto.", "Marking the stage floor so the piano returns to the same spot each show."]}, "ea4776f3-3b5f-47de-8e67-5dac92f274c8": {"definition": "Piano storage is a dedicated, protected space for keeping grand and upright pianos when not in use, ideally at stage level with step-free access and controlled temperature and humidity to preserve tuning and the instrument's structure. Because a concert grand is heavy and awkward, the store is planned so instruments can be moved to the stage safely on their casters or a piano board without lifting over steps or thresholds.", "plain_english": "Piano storage is a special room for keeping pianos safe when not in use. It is kept at a steady temperature and humidity so the piano stays in tune and does not crack. It sits near stage level so the piano can roll straight to the stage.", "purpose_function": "It protects valuable pianos from damage and climate swings and keeps them out of the way between uses. Placing it near the stage lets crew move a heavy piano to the performance position safely.", "practical_application": "Crew wheel a grand from the climate-controlled piano store to the stage on its casters or a piano board, avoiding steps, then let it settle before it is tuned.", "category": "Support space", "related_terms": ["Piano position", "Scene dock", "Backline storage", "Get-in", "Stage", "Concert hall"], "common_mistakes": ["UNSAFE: Trying to lift or tip a grand piano over steps or a threshold by hand, risking crush injuries and a dropped instrument.", "Storing pianos in a damp, hot, or fluctuating space, which ruins tuning and can crack the soundboard.", "Parking pianos where they block a get-in or exit route instead of in the dedicated store.", "Forgetting a piano needs time to acclimatise after a move before it will hold tune."], "scenario_contexts": ["Keeping a concert grand in a climate-controlled store between recitals.", "Wheeling a piano from its store to the stage on a piano board.", "Planning a step-free route from the piano store to the stage."]}, "a63abe4b-2056-4e91-93bf-263cc0cc1a5a": {"definition": "A pit cover is a removable or mechanized decking system installed over an orchestra pit to close the opening and create a usable floor at stage or auditorium level. It is used to extend the forestage, to add rows of seating, or to make the pit safe to walk on when musicians are not using it, and it must be rated for the loads placed on it.", "plain_english": "A pit cover is a strong deck placed over the orchestra pit. It turns the open pit into a solid floor. Crews use it to make the stage bigger, add seats, or close off the pit safely.", "purpose_function": "It lets a venue reuse the orchestra pit as stage or seating when live musicians are not needed. It also closes a deep opening that would otherwise be a fall hazard.", "practical_application": "Crew install the pit cover to extend the stage for a play, checking each panel is seated and locked and that no gap is left at the edge.", "category": "Stage equipment", "related_terms": ["Pit filler", "Orchestra pit", "Forestage", "Apron", "Stage lift", "Stage"], "common_mistakes": ["UNSAFE: Loading a pit cover with people or scenery beyond its rated capacity, risking collapse into the pit.", "UNSAFE: Leaving gaps, unlocked panels, or an unguarded edge at the pit, creating a fall hazard.", "Assuming any decking can cover a pit, when only a system rated for the span and load is safe.", "Confusing a pit cover with a pit filler that raises the whole pit floor to level."], "scenario_contexts": ["Covering the orchestra pit to extend the stage for a spoken-word play.", "Decking the pit to add front rows of seating for a sold-out show.", "Closing an unused pit so it is safe to walk across."]}, "c4f3c3cf-4b88-4881-913f-937cad17bdbc": {"definition": "A pit filler is a system of demountable platforms or infill units used to fill an orchestra pit up to stage or auditorium level, producing a flat, load-bearing surface. Often used with an orchestra-pit lift, the filler bridges the gap between the raised lift and the surrounding floor so the pit can serve as a forestage extension or additional seating, and it must carry its intended load.", "plain_english": "A pit filler is a set of strong platforms that fill in the orchestra pit. They bring the pit floor up level with the stage or seats. This turns the pit into extra stage or seating space.", "purpose_function": "It converts the pit into usable stage or seating by raising it to a level, walkable surface. Filler units let a venue change quickly between an open pit and a solid floor.", "practical_application": "Crew raise the pit lift and drop in pit-filler platforms to close the gap, locking each unit and confirming the surface is flush and level before use.", "category": "Stage equipment", "related_terms": ["Pit cover", "Orchestra pit", "Stage lift", "Forestage", "Apron", "Stage"], "common_mistakes": ["UNSAFE: Standing or loading pit fillers beyond their rated capacity, risking collapse into the pit.", "UNSAFE: Leaving an open gap or trip edge between filler units and the fixed floor.", "Assuming pit fillers are interchangeable with any decking, ignoring the rated span and load.", "Forgetting to level and lock every unit, leaving an uneven or shifting surface."], "scenario_contexts": ["Raising the pit lift and adding fillers to extend the stage.", "Filling the pit to level to install extra seating rows.", "Bridging the gap between a raised pit lift and the auditorium floor."]}, "a5ea81da-907b-4db5-97a4-c14f0d114129": {"definition": "The plaster line is a horizontal reference datum running left-to-right across the stage, defined at the upstage face of the proscenium opening (commonly the line of the fire-curtain smoke pocket) at stage-floor level. Together with the center line, it is the origin from which all upstage/downstage and left/right dimensions on stage are measured in drafting and layout.", "plain_english": "The plaster line is a reference line drawn across the stage at the back of the proscenium opening. It works with the center line to measure positions on stage. Every set piece and rigging point is measured from these two lines.", "purpose_function": "It gives everyone one fixed starting line so scenery, rigging, and lighting positions can be measured and repeated exactly. Without it, plans from the venue and the touring show would not line up.", "practical_application": "A designer measures set positions from the plaster line on the ground plan, and crew tape out those distances onstage from the same line during load-in.", "category": "Stage geography", "related_terms": ["Center line", "Set line", "Proscenium", "Ground plan", "Fire curtain", "Smoke pocket"], "common_mistakes": ["Assuming the plaster line is at literal plaster, when it is usually the upstage face of the proscenium or the smoke-pocket line.", "Confusing the plaster line with the set line, which the designer places for a particular production.", "Measuring from the downstage face of the proscenium instead of the upstage plaster line.", "Forgetting to combine it with the center line, so left-right positions are lost."], "scenario_contexts": ["Measuring scenery positions from the plaster line on a ground plan.", "Taping out the deck during load-in using distances from the plaster line.", "Aligning a touring set's plan to the house plaster line and center line."]}, "6765b6b9-103b-4508-92a1-fdbe2c5fe9dc": {"definition": "The playing area is the portion of the stage or performance space within which performers actually act, dance, or play during a production, excluding the wings, backstage, and any masked-off areas. It defines the effective performing space seen by the audience and, in flexible or non-proscenium venues, may be reshaped for each production.", "plain_english": "The playing area is the part of the stage where performers actually work. It leaves out the wings and backstage that the audience cannot see. Its size and shape can change for each show.", "purpose_function": "It defines the usable performing space so directors can plan movement and designers can plan sets, sightlines, lighting, and sound around it. It marks where the audience's attention is meant to be.", "practical_application": "A lighting technician makes sure the whole playing area is evenly lit, and the set designer keeps furniture and scenery within it and clear of the wings.", "category": "Performance space", "related_terms": ["Acting area", "Performance area", "Stage", "Wings", "Sightline", "Proscenium"], "common_mistakes": ["Confusing the playing area with the entire stage, which also includes wings and backstage.", "Assuming the playing area is fixed, when it changes with the set and staging.", "Leaving the edges of the playing area unlit, so performers vanish as they move outward."], "scenario_contexts": ["Lighting the full playing area evenly for a dance piece.", "Setting sightlines so every seat sees the whole playing area.", "Reshaping the playing area for a new production in a black-box space."]}, "549edbf0-7f45-4b43-933d-43784c0bd775": {"definition": "A masking assembly of two vertical legs and a horizontal border (header) that forms a frame within or immediately behind the proscenium. It masks the wings and overhead machinery and can be adjusted to reduce or reshape the stage opening; a portal carrying a lighting bridge is a portal bridge.", "plain_english": "A portal is a frame of tall side curtains and a top border. It shapes the stage opening and hides the wings and rigging from the audience.", "purpose_function": "It frames the visible stage picture and conceals offstage areas and overhead equipment, while letting the crew resize the opening to suit each production.", "practical_application": "Technicians set and trim portal legs and border to control sightlines, then rig lights or scenery behind them for each show.", "category": "Stage masking", "related_terms": ["Proscenium", "Border", "Leg", "Teaser", "Tormentor", "Masking"], "common_mistakes": ["Confusing a portal with the permanent proscenium arch; a portal is movable masking set inside or behind the arch.", "Assuming portal legs hide all sightlines without checking from the extreme audience seats.", "Using teaser and tormentor loosely instead of naming the specific portal border and legs."], "scenario_contexts": ["Narrowing a wide proscenium with a portal to suit a small-scale touring set.", "Rigging a portal bridge to hold front-of-scene lighting close to the opening.", "Adjusting portal legs during a fit-up to hide the wings from side seats."]}, "1c7b4fb0-ec8a-45f4-84bf-bc7271b0546c": {"definition": "The pre-marked location where a piece of scenery, a prop, or a performer is placed ready before the performance begins or before its cue. It is part of the production's preset, the starting arrangement of stage elements.", "plain_english": "A preset position is where something on stage waits before it is needed. Props, scenery, and actors start each show in their marked spots.", "purpose_function": "It fixes a repeatable starting point so every performance opens and runs the same way, letting cues and moves happen safely, often in low light.", "practical_application": "Stage crew place and spike props and scenery at their preset positions during the pre-show check before the house opens.", "category": "Stage management", "related_terms": ["Preset", "Spike mark", "Prop table", "Blocking", "Cue", "Dead"], "common_mistakes": ["Confusing the preset position of an object with a lighting preset, which is a stored lighting state.", "Failing to reset items to their preset positions after a scene, causing missed props or unsafe moves.", "Removing the spike marks that define preset positions before the run has ended."], "scenario_contexts": ["Running a pre-show checklist to confirm every prop is at its preset position.", "Spiking furniture on the deck so it returns to its preset position each night.", "Setting a flown piece to its preset trim before the audience enters."]}, "ad64814b-499e-466f-bcf9-ae710e94aea9": {"definition": "An administrative workroom in a venue or on a production used by production and company management. It provides desks, communications, and network access for coordinating scheduling, logistics, budgets, and paperwork during fit-up, rehearsals, and the run.", "plain_english": "A production office is the venue's work room for the people running the show behind the scenes. They handle schedules, paperwork, phones, and internet from there.", "purpose_function": "It gives the management team a fixed base with power, data, and phones so the many parts of a production can be planned and tracked in one place.", "practical_application": "Touring production managers set up laptops, printers, and comms in the production office on arrival to run the get-in and the show.", "category": "Backstage spaces", "related_terms": ["Green room", "Dressing room", "Get-in", "Stage door", "Prop room", "Wardrobe"], "common_mistakes": ["Confusing the production office with the box office, which handles ticket sales rather than production management.", "Assuming the production office is the same as the stage manager's prompt desk on stage.", "Overlooking the need for reliable network and phone service when siting a temporary production office."], "scenario_contexts": ["A touring company using the venue production office as its base during a week-long run.", "Holding production meetings and printing schedules in the production office during fit-up.", "Routing venue phone and internet service to the production office for a visiting company."]}, "afe09805-a2dc-4bd6-a366-1057f523c7a9": {"definition": "The position from which a show is run and called, traditionally set in the downstage corner at the side of the stage. In UK practice it is conventionally at stage left, giving that side its name, and it houses the prompt desk and prompt copy.", "plain_english": "The prompt corner is the spot at the side of the stage where the show is run. From here the stage manager calls the cues that keep the show together.", "purpose_function": "It gives the stage manager a fixed station with a view of the stage to call cues, cue performers, and coordinate the whole show.", "practical_application": "The deputy stage manager stands at the prompt corner during performances, calling lighting, sound, and flying cues from the prompt book.", "category": "Stage management", "related_terms": ["Prompt desk", "Prompt side", "Prompt book", "Cue light", "Opposite prompt", "Deputy stage manager"], "common_mistakes": ["Assuming the prompt corner is always at stage left; in some theatres it is on the opposite side.", "Confusing the prompt corner, which is a location, with the prompt desk, which is the equipment there.", "Thinking its only job is prompting lines, when its main modern role is calling the show."], "scenario_contexts": ["Calling a performance from the prompt corner using cue lights and headset.", "Relocating the prompt corner to stage right when wing space demands it.", "Running a technical rehearsal from the prompt corner with the full prompt book."]}, "5b92c844-6715-4394-940d-b98134e3ff11": {"definition": "The stage manager's control station at the prompt corner from which the show is called. It typically carries the production intercom, cue-light controls, stage and backstage paging, show relay and monitors, production clocks, and working light for the prompt copy.", "plain_english": "The prompt desk is the control station where the stage manager calls the show. It holds the headset, cue lights, and screens needed to run each cue.", "purpose_function": "It brings the show-running controls together in one place so the stage manager can cue departments and communicate with the whole team reliably.", "practical_application": "Before a show the crew power the prompt desk and test its cue lights, comms, and paging during the pre-show check.", "category": "Stage management", "related_terms": ["Prompt corner", "Cue light", "Production intercom", "Paging", "Show relay", "Prompt book"], "common_mistakes": ["UNSAFE: Calling flying or automation cues when the prompt desk's cue lights or comms are untested, since a missed or mistimed cue can injure people moving scenery.", "Confusing the prompt desk with the front-of-house lighting or sound control positions.", "Assuming every prompt desk is identical instead of checking its layout in each venue."], "scenario_contexts": ["Calling lighting, sound, and flying cues from the prompt desk during a performance.", "Testing all cue-light outstations from the prompt desk during setup.", "Fitting a temporary prompt desk for a touring show in a venue without one."]}, "0e1166c9-5a5f-4cd2-846b-26f4bf930fd3": {"definition": "The side of the stage where the prompt corner is located, conventionally stage left in UK practice, that is, the actor's left when facing the audience. The opposite side is called opposite prompt (OP).", "plain_english": "Prompt side is the side of the stage that holds the prompt corner. In the UK it is usually the actor's left as they face the audience.", "purpose_function": "It gives the crew a fixed, shared way to name the sides of the stage so directions and moves are never confused.", "practical_application": "Crew label wings, cables, and flight cases prompt side or opposite prompt so gear is set on the correct side.", "category": "Stage geography", "related_terms": ["Opposite prompt", "Prompt corner", "Stage left", "Stage right", "Wings", "Prompt desk"], "common_mistakes": ["Assuming prompt side always equals stage left; some venues have the prompt corner at stage right.", "Confusing prompt side with the audience's left instead of the actor's left.", "Using house left and right instead of stage terms, which reverses the sense."], "scenario_contexts": ["Marking which wing is prompt side during a get-in.", "Directing an actor to exit prompt side during blocking.", "Splitting stage crew into prompt-side and opposite-prompt teams."]}, "27a75b74-ac6f-44ff-82f4-63c4deef65c2": {"definition": "A storage and preparation space where stage properties are kept, sorted, maintained, and made ready for use. It may serve as long-term storage or hold the props required for the current production.", "plain_english": "A prop room is where a theatre stores and prepares its props. Objects used on stage are kept, fixed, and organised there between shows.", "purpose_function": "It keeps props secure, organised, and in good repair so the right items can be found and readied for each performance.", "practical_application": "Stage management and props crew pull items from the prop room and lay them out on prop tables before each show.", "category": "Backstage spaces", "related_terms": ["Prop table", "Property", "Scene dock", "Wardrobe", "Green room", "Production office"], "common_mistakes": ["Confusing the prop room, which is storage, with a prop table, which is an offstage staging point during a show.", "Leaving props unlabelled or unsorted, so items cannot be found quickly.", "Storing perishable or hazardous prop items in the prop room without proper handling."], "scenario_contexts": ["Cataloguing and storing a show's props in the prop room after a run.", "Pulling furniture and hand props from the prop room during fit-up.", "Repairing a damaged prop in the prop room between performances."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"c1b77246-5a1c-4589-8e0c-e6aeaed1fc4a": {"definition": "A table set in the wings offstage where hand props are laid out ready for use during a performance. Positions are commonly marked or taped and labelled so performers and crew can collect and return each item quickly in low light.", "plain_english": "A prop table is a table just offstage that holds the small props for a show. Each item has a marked spot so it is easy to grab in the dark.", "purpose_function": "It gives every hand prop a known offstage home so items are collected and returned reliably, keeping the show running smoothly.", "practical_application": "Before curtain the crew set the prop table, taping and labelling each item's place and checking that every prop is present.", "category": "Props", "related_terms": ["Prop room", "Property", "Preset position", "Wings", "Spike mark", "Offstage"], "common_mistakes": ["Confusing the prop table, used offstage during a show, with the prop room, used for storage between shows.", "Not returning props to the prop table after use, so they are missing for the next scene.", "Leaving the prop table unmarked, causing wrong or missed props in the dark."], "scenario_contexts": ["Setting and taping the prop table before the house opens.", "An actor collecting a hand prop from the prop table before an entrance.", "Checking the prop table against a props list during the pre-show."]}, "e4dde0c6-fde0-42c9-a385-4c5a3b30ca22": {"definition": "A small offstage space, usually in the wings and screened by a curtain or flats, where a performer makes a rapid costume change during a performance when there is no time to return to a dressing room.", "plain_english": "A quick-change area is a small hidden spot just offstage. Actors change clothes there fast during a show. There is no time to run back to a dressing room.", "purpose_function": "It gives performers a private, close-to-stage place for very fast costume or wig changes, so entrances and exits stay on cue.", "practical_application": "Sound crew work with wardrobe to fit or swap a performer's bodypack and microphone in the quick-change area, keeping the space lit, quiet, and clear of cable.", "category": "Backstage Spaces", "related_terms": ["Quick-change room", "Wings", "Dressing room", "Wardrobe", "Crossover corridor", "Wireless microphone"], "common_mistakes": ["Confusing an open quick-change area in the wings with an enclosed quick-change room", "UNSAFE: Leaving cable, cases, or scenery in the quick-change area, creating a trip hazard in the dark", "Working a body microphone swap without the wardrobe team, causing rustle, visible packs, or a missed cue"], "scenario_contexts": ["Swapping a performer's wireless bodypack during a fast costume change beside the stage", "Setting a small work light and mirror in the wings for a quick change", "Keeping the wing crossover clear so a quick-change area does not block traffic"]}, "e62b6442-50b8-4a47-873b-e92de587963c": {"definition": "An enclosed room located immediately adjacent to the stage, fitted with mirrors, task lighting, and costume rails, in which a performer makes a rapid costume or wig change during a performance without returning to a main dressing room.", "plain_english": "A quick-change room is a small closed room right next to the stage. Actors change clothes there in a hurry during a show. It has a mirror, lights, and racks for costumes.", "purpose_function": "It provides an enclosed, private space close to the stage for fast changes, giving more room and privacy than an open wing position.", "practical_application": "Audio crew may pre-set a spare bodypack or complete a microphone swap in the quick-change room, coordinating with dressers so the performer returns on cue.", "category": "Backstage Spaces", "related_terms": ["Quick-change area", "Dressing room", "Wardrobe", "Wings", "Green room", "Wireless microphone"], "common_mistakes": ["Confusing an enclosed quick-change room with a small open quick-change area in the wings", "UNSAFE: Overcrowding the room or blocking its door so a performer cannot exit quickly in an emergency", "Placing a quick-change room too far from the stage, so the change cannot be made in time"], "scenario_contexts": ["Fitting or swapping a wireless microphone in a quick-change room between scenes", "Locating a quick-change room close to a specific stage entrance during planning", "Pre-setting a spare transmitter pack in the room before a fast change"]}, "b7047ddb-fd5a-436a-9177-8aa41356ba44": {"definition": "A relatively small auditorium, typically seating a few hundred, designed for the unamplified performance of solo and chamber music, with a volume and acoustic treatment tuned for intimacy, clarity, and a shorter reverberation time than a large concert hall; performance is described by room-acoustic parameters measured per ISO 3382.", "plain_english": "A recital hall is a small concert room. It is built for a soloist or a small group playing without microphones. Its shape carries the sound clearly to every seat.", "purpose_function": "It gives solo and chamber musicians an intimate acoustic space where natural sound reaches the audience with clarity, without electronic reinforcement.", "practical_application": "In a recital hall a technician usually keeps reinforcement minimal, placing recording or spot microphones to capture the natural room sound rather than fight the live acoustics.", "category": "Performance Venue", "related_terms": ["Recital platform", "Concert hall", "Reverberation time", "Auditorium", "Early reflections", "Acoustic shell"], "common_mistakes": ["Treating a small live recital hall like a dead studio and adding heavy reinforcement that muddies the natural sound", "Confusing a recital hall for solo and chamber music with a large orchestral concert hall", "Assuming a short reverberation time can be fixed with reverb effects rather than acoustic design"], "scenario_contexts": ["Recording a solo piano or string quartet in a recital hall", "Deciding whether a spoken introduction needs light speech reinforcement", "Measuring reverberation time to document the hall's acoustic condition"]}, "fa8a8477-139d-4128-b3ba-3a1ac07b7146": {"definition": "The raised performing area within a recital hall on which a soloist or small ensemble performs, typically an open platform without a proscenium, fly tower, or scenery, sometimes fitted with a reflective canopy or shell to aid projection to the audience.", "plain_english": "A recital platform is the raised stage in a recital hall. A soloist or small group performs on it. It is open to the room, with no big scenery or curtains.", "purpose_function": "It raises and groups the performers so the audience can see and hear them clearly, and any reflector helps project the sound outward.", "practical_application": "Crew set the platform with chairs, stands, and a piano, then place spot or overhead microphones for recording or light reinforcement.", "category": "Performance Spaces", "related_terms": ["Recital hall", "Concert platform", "Acoustic shell", "Riser", "Auditorium", "Spot microphone"], "common_mistakes": ["Confusing an open recital platform with a proscenium stage that has wings and a fly tower", "Positioning a reflective canopy so it no longer projects sound toward the audience", "Forgetting that microphone stands on an open platform are visible and must be placed neatly"], "scenario_contexts": ["Setting a grand piano and chairs for a chamber recital", "Placing overhead microphones above the platform for a live recording", "Positioning an acoustic reflector to aid projection on an open platform"]}, "3661846c-f55d-4ef2-ba1b-5e9869d45ef7": {"definition": "A large dedicated room, ideally matching the plan dimensions of the main stage, in which a company rehearses a production before moving onto the performance stage; typically an unencumbered floor with clear height, marked-out staging, and provision for temporary lighting and sound.", "plain_english": "A rehearsal hall is a large practice room. A cast rehearses a show there before moving onto the real stage. It is often the same size as the stage.", "purpose_function": "It lets a company rehearse full staging and movement at true stage size, freeing the actual stage for building sets and technical work.", "practical_application": "Sound crew may set temporary loudspeakers and playback in the rehearsal hall so cues and levels are worked out before the move onto the stage.", "category": "Production Spaces", "related_terms": ["Rehearsal room", "Scene shop", "Green room", "Stage", "Crew room", "Dressing room"], "common_mistakes": ["Assuming a rehearsal hall's acoustics match the performance stage, so cues need re-checking after the move", "Confusing a full-size rehearsal hall with a small individual practice or warm-up room", "Marking staging without matching the true stage dimensions, so blocking has to be reworked"], "scenario_contexts": ["Running a full staging rehearsal at stage size before the technical move-in", "Setting temporary playback and loudspeakers to rehearse sound cues", "Marking out the stage plan on the rehearsal hall floor"]}, "55603320-7739-4afd-93ba-e4056f748a05": {"definition": "A rotating circular section of stage floor, permanently built in or laid on as a portable unit, that turns about a central axis to move scenery and performers and to change scenes; larger installations may combine concentric revolves that rotate independently.", "plain_english": "A revolve is a turntable built into the stage floor. It spins to move scenery and actors around. This lets one scene change into the next quickly.", "purpose_function": "It allows fast, continuous scene changes and dramatic movement by turning whole settings into and out of view, often while the audience watches.", "practical_application": "Sound crew route performer wireless and any on-revolve microphone cabling so it does not snag as the deck turns, and confirm the move with stage management.", "category": "Stage Machinery", "related_terms": ["Stage", "Wagon", "Trap", "Scene shop", "Deck", "Stage management"], "common_mistakes": ["UNSAFE: Standing, resting, or storing gear on a revolve without knowing the cue, risking being carried, thrown, or crushed when it turns", "UNSAFE: Running cable across the gap at a revolve's edge, where it can be dragged, cut, or trap a foot as the deck moves", "Confusing a revolve, which rotates, with a wagon or truck, which rolls in a straight line"], "scenario_contexts": ["Planning cable and microphone routing for performers on a moving revolve", "Coordinating a scene change as the revolve turns during a blackout", "Checking clearances and pinch points before a revolve is operated"]}, "9d103f00-a320-4a0c-985f-1e6080757bd8": {"definition": "A dedicated storage space, usually near the get-in or loading dock, where road (flight) cases are kept during a production, so that once the equipment they carry is unpacked and in use, the emptied cases are held clear of working and circulation areas.", "plain_english": "Road case storage is a space to keep road cases. Road cases are the tough boxes that hold touring gear. This space keeps them out of walkways while the gear is in use.", "purpose_function": "It keeps bulky empty cases out of stage, backstage, and egress routes during a run, and gives a clear place to repack for the load-out.", "practical_application": "During load-in, crew wheel empty road cases to storage so working areas stay clear, then retrieve them for the load-out at the end of the run.", "category": "Facility Spaces", "related_terms": ["Road case", "Get-in", "Loading dock", "Scene shop", "Wings", "Crew room"], "common_mistakes": ["UNSAFE: Storing road cases in corridors, stairwells, or by exit doors, which blocks the means of egress", "UNSAFE: Stacking heavy cases too high or unbraked, so they can topple or roll and crush someone", "Leaving empty cases in the wings or on stage instead of moving them to storage"], "scenario_contexts": ["Wheeling empty road cases to storage after a load-in", "Keeping cases clear of fire exits and cross aisles during a run", "Retrieving and repacking cases for the load-out"]}, "dc1d58f9-26f8-4b82-a129-d150b2fb3ae3": {"definition": "A narrow extension of the stage that projects out into or over the auditorium, allowing performers to move among or above the audience; used in fashion shows, concerts, and some theatrical productions, and often decked over part of the seating.", "plain_english": "A runway is a narrow strip of stage that reaches out into the audience. Performers walk along it to get closer to the crowd. Fashion shows use one for models.", "purpose_function": "It brings performers physically closer to and among the audience, extending the acting or presentation area beyond the main stage.", "practical_application": "Sound and lighting crew cover a runway with extra fill loudspeakers and fixtures, and secure or ramp any cable so performers and audience do not trip.", "category": "Performance Spaces", "related_terms": ["Thrust stage", "Apron", "Auditorium", "Stage", "Cross aisle", "Fill loudspeaker"], "common_mistakes": ["UNSAFE: Running cable across a runway without a proper ramp or cover, creating a trip hazard for performers and the public", "UNSAFE: Building a runway over seating without keeping the required egress width and access clear", "Confusing a performance runway with a lighting or access catwalk above the stage"], "scenario_contexts": ["Adding fill loudspeakers so a runway that reaches into the audience is still covered", "Ramping and securing cable where a runway crosses the audience floor", "Planning a fashion-show runway that keeps aisles and exits clear"]}, "f7ffdc88-ab4e-4882-b204-fddd5b8a08e4": {"definition": "A production workshop in which stage scenery is constructed, assembled, and painted, typically equipped with woodworking and metalworking tools, a paint frame or paint area, and access sized to move built scenery to the stage.", "plain_english": "A scene shop is a workshop where a show's scenery is built and painted. Workers cut, join, and paint the set pieces there. The finished scenery then moves to the stage.", "purpose_function": "It provides the dedicated space and tools to build and finish scenery, keeping heavy construction work away from the stage and audience areas.", "practical_application": "Audio crew coordinate with the scene shop so that microphone mounts, cable runs, or loudspeaker pockets are built into scenery during construction rather than added later.", "category": "Production Spaces", "related_terms": ["Scenery", "Paint frame", "Rehearsal hall", "Get-in", "Fly tower", "Road case storage"], "common_mistakes": ["Confusing the scene shop, where scenery is built, with backstage storage where finished scenery is kept", "UNSAFE: Operating shop power tools without guards, eye protection, or dust and fume extraction", "Failing to plan an access route wide and tall enough to move finished scenery from the shop to the stage"], "scenario_contexts": ["Building set pieces and flats ahead of a production", "Fitting loudspeaker pockets or microphone mounts into scenery during construction", "Painting a backdrop on the paint frame before it moves to the stage"]}, "01684cec-b171-47d9-a2d4-0fcd74129857": {"definition": "A reference line drawn parallel to the proscenium, usually just upstage of the house curtain and clear of permanent obstructions, from which the positions of scenery, equipment, and stage furniture are dimensioned on the ground plan and marked out on the stage floor.", "plain_english": "The setting line is a mark on the stage floor, set behind the main curtain. Crew measure from it to place scenery in the same spot every show.", "purpose_function": "It provides a fixed downstage datum so every scenic element and marker can be measured and reproduced accurately between the drawing and the actual stage and from show to show.", "practical_application": "A technician measures upstage from the setting line when spiking the deck and positioning scenery, so the ground plan translates exactly onto the real stage.", "category": "Stage geography", "related_terms": ["Plaster line", "Centre line", "Proscenium", "Ground plan", "Spike mark", "Sightline"], "common_mistakes": ["Confusing the setting line with the plaster line or centre line, which are separate reference lines", "Measuring scenery positions from the physical edge of the stage instead of the established setting line", "Assuming the setting line sits in the same place in every venue rather than checking the specific ground plan"], "scenario_contexts": ["Transferring a scenic ground plan onto the stage floor during a load-in", "Spiking furniture positions so they repeat exactly each performance", "Coordinating a touring set's measurements with a new venue's stage geometry"]}, "73868059-fd86-4e2d-b4d2-3284b73640a5": {"definition": "SL is the standard abbreviation for stage left: the portion of the stage to the performer's left when the performer stands facing the audience, which corresponds to the audience's right.", "plain_english": "Stage left is the left side of the stage from a performer's view while facing the audience. From the seats it looks like the right side. SL is its short label.", "purpose_function": "It gives cast and crew an unambiguous, performer-referenced direction for placing scenery, equipment, and movement, independent of where any individual happens to be standing.", "practical_application": "A technician reads SL on a stage plot or plan and places the labelled monitor wedge, amplifier, or scenery on the performer's left side of the stage.", "category": "Stage geography", "related_terms": ["SR", "Downstage", "Upstage", "Wings", "Centre line", "Prompt side"], "common_mistakes": ["Reading stage left from the audience's viewpoint instead of the performer's, so left and right are reversed", "Confusing stage left with the house-left or audience-left convention used in some seating plans", "Assuming stage left is a fixed direction in space rather than defined by the performer facing the audience"], "scenario_contexts": ["Interpreting a band's stage plot to position wedges and backline", "Calling a performer's entrance from stage left during a rehearsal", "Labelling loudspeaker and cable runs on a stage layout drawing"]}, "d03c2fc6-d3e9-43d3-b61f-ab00e354710f": {"definition": "A reference line on the stage ground plan that marks the plane of the smoke pockets — the vertical steel guide channels on each side of the proscenium that enclose the edges of the fire (safety) curtain — indicating where the fire curtain descends and seals the proscenium opening; scenery and equipment must be kept clear of it.", "plain_english": "This is a line on stage plans showing where the fire curtain's side guides sit. Scenery must stay clear of it so the fire curtain can drop and seal.", "purpose_function": "It records on the plan where the safety curtain and its side guides come down, so the clearance below the curtain is respected and the proscenium can be sealed against smoke and flame in a fire.", "practical_application": "When setting scenery, a technician keeps all decks, props, and rigging upstage of the smoke-pocket line and out of the fire line so the safety curtain can deploy fully.", "category": "Fire Safety", "related_terms": ["Smoke pocket", "Fire curtain", "Safety curtain", "Proscenium", "Fire line", "Setting line"], "common_mistakes": ["UNSAFE: Storing scenery, road cases, or a piano across the smoke-pocket line so the fire curtain cannot fully descend and seal", "Confusing the smoke-pocket line with the setting line or plaster line", "UNSAFE: Assuming the fire-curtain path can be blocked briefly during a scene change without consequence"], "scenario_contexts": ["Planning scenery positions so nothing fouls the safety curtain's descent", "Marking the fire line on the deck during a proscenium theatre load-in", "Inspecting the smoke pockets and curtain travel before opening the house"]}, "abbdec41-83df-48c0-b1bf-dc35d9e2aeab": {"definition": "The location at the downstage front edge of the platform, immediately in front of the conductor, where a concerto or featured soloist stands or sits so as to project clearly to the audience while maintaining visual contact with the conductor and ensemble.", "plain_english": "This is the spot at the front of the stage where a solo star performs. It sits just ahead of the conductor so the two can see each other.", "purpose_function": "Placing the soloist forward of the ensemble lets their sound reach the audience without being masked by the orchestra, while keeping them within the conductor's sightline for tight coordination.", "practical_application": "For recording or reinforcement, an engineer places the soloist's spot microphone at this forward position and lays out the stage so the soloist is not buried in the orchestra.", "category": "Stage geography", "related_terms": ["Concert platform", "Concertmaster position", "Spot microphone", "Downstage", "Conductor's podium", "Orchestra pit"], "common_mistakes": ["Placing the soloist within the orchestra rather than downstage, so the solo line is masked", "Forgetting that a grand piano's lid orientation depends on the soloist facing the conductor", "Positioning the soloist's microphone for overall orchestral balance instead of soloist prominence"], "scenario_contexts": ["Setting the stage for a violin or piano concerto with the orchestra", "Placing a spot microphone on a featured soloist for a live broadcast", "Arranging a soloist and accompanist within the conductor's sightlines"]}, "909f9c2a-7195-4135-9656-a8d4de6bebb8": {"definition": "An entrance vestibule fitted with two sets of doors in series (an acoustic airlock) between the auditorium and the adjoining lobby or circulation space, arranged so at least one door is always closed to block the transmission of external noise and light into the hall; also called a sound lock or sound-and-light lock.", "plain_english": "A sound-lock entrance is a small room with two doors between the lobby and the hall. It traps noise and light, like an airlock, so the show stays quiet inside.", "purpose_function": "The double-door lobby prevents noise and light from the foyer entering the auditorium as patrons come and go, preserving the low background-noise level the space is designed for.", "practical_application": "A technician relies on the sound-lock to keep lobby noise out during quiet passages and avoids propping both sets of doors open, which defeats the acoustic isolation.", "category": "Building element", "related_terms": ["Acoustic door", "Auditorium", "Vestibule", "Background noise", "Sound isolation", "Foyer"], "common_mistakes": ["UNSAFE: Locking or chaining the sound-lock doors in a way that blocks a required means of egress", "Propping both sets of doors open at once, which defeats the acoustic isolation", "Assuming a single door isolates as well as the two-door lock"], "scenario_contexts": ["Latecomers entering a concert during a quiet passage without disturbing the hall", "Designing a control-room or studio entrance to keep corridor noise out", "Checking that the door seals and closers on the sound lock work before a recording"]}, "768bbd62-eef6-4fff-aaa0-449304893551": {"definition": "SR is the standard abbreviation for stage right: the portion of the stage to the performer's right when the performer stands facing the audience, which corresponds to the audience's left.", "plain_english": "Stage right is the right side of the stage from a performer's view while facing the audience. From the seats it looks like the left side. SR is its short label.", "purpose_function": "It gives cast and crew an unambiguous, performer-referenced direction for placing scenery, equipment, and movement, independent of where any individual happens to be standing.", "practical_application": "A technician reads SR on a stage plot or plan and places the labelled monitor wedge, amplifier, or scenery on the performer's right side of the stage.", "category": "Stage geography", "related_terms": ["SL", "Downstage", "Upstage", "Wings", "Centre line", "Prompt side"], "common_mistakes": ["Reading stage right from the audience's viewpoint instead of the performer's, so left and right are reversed", "Confusing stage right with the house-right convention used in some seating plans", "Assuming stage right is a fixed compass direction rather than performer-referenced"], "scenario_contexts": ["Positioning backline and monitors from a stage plot", "Calling an entrance from stage right during a rehearsal", "Marking loudspeaker and cable positions on a stage plan"]}, "f52d400d-f456-45e9-8b46-c7259f9b9efe": {"definition": "A large, often partly or fully roofed venue built with tiered seating surrounding a central sports field or performance area and seating many thousands of spectators; acoustically it presents very long source-to-listener distances and hard reflective surfaces, so distributed and time-delayed loudspeaker systems are required for intelligible sound reinforcement.", "plain_english": "A stadium is a huge venue with seats built around a sports field. It is so big and echoey that crews use many delayed speakers to reach every seat clearly.", "purpose_function": "It houses large-scale sporting events and concerts for very large audiences; its scale and hard surfaces make even coverage and speech intelligibility the central sound-system challenges.", "practical_application": "A technician working a stadium deploys distributed loudspeaker zones with signal delay so fans in far seats hear speech clearly and in time with nearer speakers.", "category": "Venue type", "related_terms": ["Arena", "Amphitheater", "Distributed system", "Signal delay", "Reverberation time", "Line array"], "common_mistakes": ["Assuming a single central cluster can cover a whole stadium without delayed fill loudspeakers", "Ignoring long reflections and echoes from far grandstands and the roof", "Confusing a stadium, which surrounds a field, with an arena or amphitheatre"], "scenario_contexts": ["Designing delayed loudspeaker zones for even coverage of a stadium concert", "Managing echoes and intelligibility for public-address announcements", "Setting time alignment between a main line array and distant delay towers"]}, "db5c6ae7-fe0c-45c9-bac2-88906732a235": {"definition": "A designated marked location just offstage, typically in the wings, where a performer, or a piece of scenery or equipment, waits ready to enter the stage or be moved on the stage manager's cue.", "plain_english": "A standby position is a marked spot just offstage where a performer waits. They stand ready there to enter the moment they get their cue.", "purpose_function": "It keeps performers and moving scenery pre-positioned and out of the audience's sightline so that entrances and scene changes happen promptly and safely on cue.", "practical_application": "A stage manager calls a 'standby' and the performer or crew takes the marked standby position in the wings, ready to move the instant 'go' is given.", "category": "Stage geography", "related_terms": ["Wings", "Crossover", "Cue", "Stage manager", "Prompt side", "Downstage"], "common_mistakes": ["UNSAFE: Taking a standby position where it blocks a crossover, an exit, or the fire-curtain path", "Standing where the audience can see the standby position", "Confusing the stage manager's 'standby' warning with the 'go' cue and moving too early"], "scenario_contexts": ["A performer waiting in the wings for an entrance cue", "Pre-setting a scenery truck ready for a fast change", "Positioning a follow-spot operator or crew member before a cue sequence"]}, "01d217b2-cc94-432c-8dc6-8f713b187f14": {"definition": "The principal dressing room in a theatre: a private, well-appointed room, usually the largest and located closest to the stage, reserved for the leading performer or headline act, often with its own washroom and preparation facilities.", "plain_english": "A star dressing room is the best private dressing room, closest to the stage. It is set aside for the show's lead performer.", "purpose_function": "It gives the lead performer private, convenient space to prepare and rest close to the stage, minimising travel to entrances and reflecting the dressing-room hierarchy of a producing house.", "practical_application": "House and touring crews confirm the star dressing room's location and its power, show-relay, and paging connections when advancing a show and running backstage comms.", "category": "Backstage space", "related_terms": ["Dressing room", "Chorus dressing room", "Green room", "Wings", "Show relay", "Crossover"], "common_mistakes": ["Assuming every performer gets a private room, when only the principal has the star dressing room", "Forgetting to run show-relay or paging to the star dressing room so the occupant misses calls", "Confusing the star dressing room with the green room, which is a shared waiting area"], "scenario_contexts": ["Advancing a touring artist's backstage requirements", "Wiring show-relay and paging to the principal's room", "Allocating dressing rooms by role during a production's load-in"]}, "30d39a19-02c9-4fe5-9dea-bbbbc24b7e7e": {"definition": "A small, adaptable performance space, often called a black box, in which the stage and audience seating can be reconfigured for each production. Its neutral, usually dark-walled room supports intimate, experimental, and training work rather than fixed proscenium staging.", "plain_english": "A studio theater is a small, plain room for plays. The stage and seats can be moved around. Crews set it up in different ways for each show. It suits small, close-up shows.", "purpose_function": "It provides a flexible, low-cost venue whose seating and staging can be rearranged, letting a company stage work in the round, thrust, or end-on formats within one room.", "practical_application": "A technician rigs lighting and audio from an exposed overhead grid and re-patches for each seating layout, since nothing is permanently tied to a proscenium.", "category": "Performance venue", "related_terms": ["Black box theater", "Thrust theater", "Theater-in-the-round", "Proscenium", "Lighting grid", "Flexible seating"], "common_mistakes": ["Assuming a studio theater is just a small proscenium house rather than a reconfigurable room", "Thinking the layout is fixed, when seating and stage position change between productions", "Confusing a studio theater with a broadcast or recording studio"], "scenario_contexts": ["A university drama program staging an experimental play with the audience on two sides", "Re-rigging overhead lighting and speakers when converting from thrust to in-the-round", "A small touring company mounting an intimate production in a black-box room"]}, "48dff21a-877d-4de8-bd75-30cdbba39226": {"definition": "A hospitality venue that combines full sit-down dining service with live entertainment, such as music, cabaret, or a floor show, performed for patrons seated at tables oriented toward a stage or performance area.", "plain_english": "A supper club is a restaurant with live shows. Guests eat dinner at tables while a band or act performs. The tables face a small stage. It mixes dining with a show.", "purpose_function": "It exists to sell dining and live performance together, so its layout places a stage or floor within sightlines of table seating rather than in a separate auditorium.", "practical_application": "A technician manages tight sightlines, a low stage, and the shift from background to featured audio, balancing speech and music over the noise of dining service.", "category": "Performance venue", "related_terms": ["Dinner theater", "Cabaret", "Nightclub", "Club venue", "Floor show", "House sound system"], "common_mistakes": ["Confusing a supper club with a dinner theater, where a full staged play is the main event", "Underestimating dining-service noise when setting speech and music levels", "Assuming it needs only background music rather than a proper reinforcement system for featured acts"], "scenario_contexts": ["Mixing a jazz trio at low volume during dinner, then raising levels for a featured singer", "Placing compact speakers to cover table seating without a raised auditorium", "Managing feedback from a low stage set close to dining tables and hard surfaces"]}, "4d6615bd-94d2-44ec-a837-69e97b098e71": {"definition": "A horizontal masking border, usually drapery or a framed flat, hung immediately upstage of the proscenium and spanning its width to conceal the fly loft, overhead borders, and lighting. With the tormentors it forms an adjustable inner frame that sets the height of the visible stage opening.", "plain_english": "A teaser is a wide cloth border hung across the top of the stage. It hides the lights and rigging above the stage from the crowd. It works with side pieces called tormentors. Together they frame the opening.", "purpose_function": "It masks everything above the stage opening and lets crews lower the top of the frame, controlling how tall the visible opening appears to the audience.", "practical_application": "A technician sets the teaser height to hide overhead lighting and rigging while keeping the intended sightline, adjusting it when a set needs a shorter or taller opening.", "category": "Stage masking", "related_terms": ["Tormentor", "Proscenium", "Grand drape", "Border", "Masking", "Fly loft"], "common_mistakes": ["Confusing the teaser (horizontal, at the top) with the tormentor (vertical, at the sides)", "Thinking the teaser is the main house curtain rather than a masking border", "Setting it too high and revealing overhead lighting or the fly loft to the audience"], "scenario_contexts": ["Lowering the teaser to hide a lighting pipe that would otherwise be seen from the front rows", "Framing the stage opening to a shorter height for an intimate scene", "Coordinating teaser and tormentor positions to form a clean inner frame"]}, "9e65be52-e72d-410c-8967-9c4ae7af5ec7": {"definition": "A performance space, also called an arena stage, in which the audience is seated on all sides surrounding a central acting area. Performers enter through aisles or vomitories, and scenery is kept low to preserve sightlines from every direction.", "plain_english": "Theater-in-the-round puts the audience all the way around the stage. The acting happens in the middle. People watch from every side. Scenery must stay low so everyone can see.", "purpose_function": "It creates an intimate, shared experience by surrounding the action, but it forces low scenery and careful blocking so no seat's view is blocked.", "practical_application": "A technician hangs lighting and speakers overhead from all directions and hides cabling in the floor or aisles, since there is no backstage wall to conceal equipment.", "category": "Venue type", "related_terms": ["Arena", "Thrust theater", "Vomitory", "Proscenium", "Sightline", "Studio theater"], "common_mistakes": ["Using tall scenery that blocks sightlines from the opposite side of the house", "Assuming there is a hidden backstage, when entrances run through the audience aisles", "Confusing it with thrust staging, which seats the audience on only three sides"], "scenario_contexts": ["Rigging a central overhead lighting cluster to cover actors facing every direction", "Running audio and control cable under the floor because there are no wings", "Planning performer entrances through vomitories in a round configuration"]}, "ba2682fd-6cb5-45f8-a47b-9e7608b0c78f": {"definition": "A theater in which the stage projects into the auditorium so the audience is seated on three sides of the acting area, with the fourth (upstage) side used for scenery, entrances, and backstage. It blends the intimacy of arena staging with the scenic backdrop of a proscenium.", "plain_english": "A thrust theater has a stage that sticks out into the crowd. The audience sits on three sides of it. The back side holds scenery and exits. It feels close but still has a backdrop.", "purpose_function": "It brings the audience close on three sides for intimacy, while keeping one side for scenery and backstage access that pure arena staging lacks.", "practical_application": "A technician places lighting and speakers to cover a stage viewed from three sides and manages sightlines so upstage scenery and equipment do not block the side seats.", "category": "Venue type", "related_terms": ["Thrust stage", "Apron", "Theater-in-the-round", "Proscenium", "Arena", "Sightline"], "common_mistakes": ["Confusing a thrust with theater-in-the-round, which seats the audience on all sides", "Lighting only from the front and leaving actors dark to the side seats", "Placing scenery so it blocks sightlines from the extreme side seats"], "scenario_contexts": ["Covering a projecting stage with lighting angled from three sides", "Positioning speakers so side-seated audiences get even coverage", "Blocking a scene so an actor's back is not turned to a whole section for too long"]}, "29425cc3-393c-493d-9ca6-178a1178da7a": {"definition": "A vertical masking piece, either a curtain or a framed flat, standing at each side of the proscenium just upstage of the opening to conceal the wings and offstage areas. With the horizontal teaser it forms an adjustable inner frame that sets the width of the visible stage opening.", "plain_english": "A tormentor is a tall, narrow screen at each side of the stage opening. It hides the wings, where crew and props wait offstage. It pairs with the teaser across the top. Together they frame the stage.", "purpose_function": "It masks the offstage wings from the audience and lets crews narrow the sides of the frame, controlling how wide the visible opening appears.", "practical_application": "A technician positions the tormentors to hide side lighting booms and waiting performers while keeping the desired opening width and sightlines.", "category": "Stage masking", "related_terms": ["Teaser", "Proscenium", "Wings", "Masking", "Leg", "False proscenium"], "common_mistakes": ["Confusing the tormentor (vertical, at the sides) with the teaser (horizontal, at the top)", "Setting the tormentors too wide so the audience sees into the wings", "Thinking a tormentor is a set piece rather than permanent masking"], "scenario_contexts": ["Repositioning tormentors to hide a side lighting boom from the front seats", "Narrowing the opening width for a scene that needs a smaller frame", "Masking waiting actors and crew in the wings during a performance"]}, "704cd57c-a806-41de-86c9-a9243499773f": {"definition": "The staging space at a venue, usually adjacent to the loading dock, where scenery, equipment, and road cases are organized and loaded into or out of touring trucks in a planned sequence. Its size and access strongly affect how quickly a production can load in and load out.", "plain_english": "The truck-pack area is the space by the loading dock. Crews line up cases here to load them into trucks. They pack in a set order so everything fits. Good access speeds up load-in and load-out.", "purpose_function": "It provides room to marshal cases and scenery near the dock so a road crew can load the trucks in a repeatable, space-efficient order for the next venue.", "practical_application": "A technician stages road cases in truck-pack order near the dock during load-out, matching the crew's plan so gear fills each truck safely and in the right sequence.", "category": "Support space", "related_terms": ["Loading dock", "Road case", "Load-in", "Load-out", "Get-in", "Staging area"], "common_mistakes": ["Confusing the truck-pack area with permanent storage rather than a temporary loading zone", "Ignoring the planned pack order, which wastes truck space and time", "UNSAFE: Blocking egress paths or fire lanes with staged road cases, which violates required exit clearance"], "scenario_contexts": ["Lining up road cases near the dock in truck-pack order during a show's load-out", "Coordinating forklift and dock-plate use to move heavy cases to the trucks", "Assessing whether a venue's dock and pack area can handle a large touring rig"]}, "5c759821-18ab-4fbd-a477-551df5cd0054": {"definition": "An abbreviation for upstage center, the stage position on the center line farthest from the audience. 'Upstage' means away from the audience toward the rear, a convention inherited from historically raked stages that sloped upward away from the house.", "plain_english": "USC means upstage center. It is the spot in the middle of the stage, at the very back. Upstage means the part farthest from the crowd. The name comes from old stages that sloped up at the back.", "purpose_function": "It gives directors, performers, and crew a shared shorthand for the back-center area of the stage when planning blocking, scenery, and equipment placement.", "practical_application": "A technician reads 'USC' on a stage plot or lighting plan and places a set piece, microphone, or fixture at the rear center of the stage.", "category": "Stage geography", "related_terms": ["USL", "USR", "Downstage", "Stage left", "Stage right", "Center line"], "common_mistakes": ["Reading upstage and downstage from the audience's view instead of the performer's", "Thinking 'upstage' means toward the audience rather than away from it", "Confusing the center-stage abbreviation with the left and right ones on a plot"], "scenario_contexts": ["Placing a backdrop or riser at the rear center from a 'USC' note on the stage plot", "Directing a performer to move to upstage center during blocking", "Marking a fixture focus at upstage center on a lighting plan"]}, "705774bb-7b3c-47a1-9e0f-c6f4bb0d144b": {"definition": "An abbreviation for upstage left, the area toward the rear of the stage on the performer's left as they face the audience. 'Upstage' denotes the region away from the audience, and 'left' is always taken from the performer's point of view, not the viewer's.", "plain_english": "USL means upstage left. It is the back area of the stage on the actor's left side. Left is judged from the actor facing the crowd. So it is the audience's right, at the back.", "purpose_function": "It provides a shared shorthand for the rear-left region of the stage, from the performer's viewpoint, used when planning blocking, scenery, and equipment placement.", "practical_application": "A technician reads 'USL' on a plot and places a set piece, monitor, or fixture at the rear of the stage on the performer's left, which is the audience's right.", "category": "Stage geography", "related_terms": ["USC", "USR", "Stage left", "Downstage", "Stage right", "Center line"], "common_mistakes": ["Taking 'left' from the audience's view instead of the performer's", "Confusing USL (upstage left) with DSL (downstage left)", "Forgetting that upstage means away from the audience"], "scenario_contexts": ["Placing a monitor wedge at upstage left from a stage plot", "Focusing a lighting fixture on the rear performer's-left area", "Directing a performer to cross to upstage left during blocking"]}, "d60f3d05-d28f-44d5-abc6-44abbc7b7ee3": {"definition": "A stage-geography abbreviation for Upstage Right: the area of the stage farthest from the audience and to the performer's right (the audience's left) as the performer faces the house. It is one cell of the standard nine-area grid used to map positions on a proscenium stage.", "plain_english": "USR means Upstage Right. It is the back corner of the stage on the actor's right as they face the crowd.", "purpose_function": "It gives directors, stage managers and crew a shared shorthand for exact stage positions, so blocking, scenery and equipment placement are communicated without confusion.", "practical_application": "A technician uses USR to note where to place a monitor wedge, floor mic or cable run, reading blocking notes from the stage manager.", "category": "Stage geography", "related_terms": ["Downstage", "Upstage", "Stage right", "Stage left", "Proscenium", "Blocking"], "common_mistakes": ["Confusing stage right with the viewer's right; stage directions are given from the performer's point of view, not the audience's.", "Mixing up upstage and downstage, which come from old raked stages that sloped up away from the audience.", "Assuming the labels apply unchanged on a thrust or in-the-round stage, where the nine-area grid no longer maps the same way."], "scenario_contexts": ["Marking a monitor wedge position as USR on a stage plot.", "Reading a stage manager's blocking note to place a prop microphone USR.", "Coordinating with the lighting crew about a cable run in the USR corner."]}, "0f14ad60-9069-4f33-a607-f6369b0de9c2": {"definition": "A separately addressable loudspeaker zone within a distributed audio or paging system that covers a building's vestibule, the enclosed entry space between the exterior doors and the interior of the venue. Being its own zone lets background music, paging or emergency voice messages be routed to the entrance independently of the main house.", "plain_english": "This is the speaker zone that covers the entrance lobby. It can play music or announcements to that area on its own, apart from the main room.", "purpose_function": "Zoning the vestibule separately lets staff play greetings or background music, page arriving guests, and deliver clear emergency messages without disturbing or being masked by the main room.", "practical_application": "A technician wires the vestibule speakers to their own amplifier channel or zone output, sets the level, and confirms paging and alarm messages are clearly audible there.", "category": "Audio zone", "related_terms": ["Paging system", "Distributed audio", "Foyer", "Zone control", "Background music", "Mass notification"], "common_mistakes": ["Grouping the vestibule with the main house on one zone, so background music or paging cannot be controlled separately.", "Setting the vestibule level from memory instead of measuring, so paging is too quiet against door and street noise.", "UNSAFE: Failing to verify that emergency voice messages meet required intelligibility and audibility in the vestibule as part of the notification system."], "scenario_contexts": ["Adding a separate background-music feed to a theater's entrance vestibule.", "Paging latecomers in the lobby without interrupting the performance.", "Commissioning a mass-notification system and testing message clarity in the vestibule."]}, "bfe5e8b0-8885-46e2-a2e4-06f721487245": {"definition": "A backstage support room where a production's costumes are stored, maintained, laundered, repaired and organized, and from which the wardrobe crew dresses performers and runs quick changes. It is distinct from the costume shop, where garments are built.", "plain_english": "A wardrobe room is where costumes are kept, cleaned and fixed during a show. The wardrobe crew works there to help performers get dressed.", "purpose_function": "It keeps a production's costumes organized, clean and repaired close to the stage, so performers can change reliably show after show.", "practical_application": "A technician may route show-relay and paging audio into the wardrobe room so the crew hears stage cues and calls while prepping costumes.", "category": "Backstage space", "related_terms": ["Costume shop", "Dressing room", "Quick-change booth", "Show relay", "Paging system", "Backstage"], "common_mistakes": ["Confusing the wardrobe room with the costume shop; one maintains and runs costumes, the other builds them.", "Forgetting to feed show relay or paging into the wardrobe room, so the crew misses cues.", "UNSAFE: Storing fabrics, rails and cases so they block the room's exit or a corridor used as a means of egress."], "scenario_contexts": ["Installing a show-relay speaker in the wardrobe room for a touring musical.", "Running paging so the stage manager can reach the wardrobe crew.", "Planning quick-change stations near the wardrobe room and stage."]}, "f959ae1d-2982-4566-ac54-1b8f14e6d173": {"definition": "A specialized backstage room dedicated to the construction, styling, fitting, storage and maintenance of wigs, hairpieces and facial hair for a production, worked by the wig and hair crew. It is usually located near the dressing rooms and stage and equipped with mirrors, ventilation and heat tools.", "plain_english": "A wig room is where wigs and hairpieces are made, styled and stored for a show. The wig crew fits and cares for them there.", "purpose_function": "It gives the wig crew a dedicated, ventilated space with mirrors and tools to prepare and maintain hairpieces so they look right and stay consistent each performance.", "practical_application": "A technician provides show-relay and paging feeds to the wig room and ensures its many hot tools and mirror lights run on properly rated, grounded circuits.", "category": "Backstage space", "related_terms": ["Makeup room", "Dressing room", "Wardrobe room", "Show relay", "Quick-change booth", "Backstage"], "common_mistakes": ["Confusing the wig room with general makeup or dressing space; wig work needs its own ventilated, equipped area.", "UNSAFE: Overloading circuits with many hot styling tools, or leaving heated irons unattended near flammable hair products and aerosols.", "Forgetting show relay and paging, so the wig crew misses quick-change and entrance cues."], "scenario_contexts": ["Wiring a show-relay speaker into the wig room for an opera.", "Checking that wig-room styling tools run on properly rated outlets.", "Coordinating quick wig changes with cues heard over paging."]}, "3b368d48-280b-4110-992a-f00899f794ed": {"definition": "The raised staging area at the front of a worship space from which the worship band, praise team, clergy and speakers lead the service, equivalent to a stage or chancel in a contemporary house of worship. It carries the microphones, monitors, instruments and frequently the primary loudspeakers.", "plain_english": "A worship platform is the raised stage at the front of a church. The band, singers and speakers lead the service from it.", "purpose_function": "It raises the leaders and performers so the congregation can see and hear them, and it provides a defined area to place mics, monitors and instruments.", "practical_application": "A technician sets up mics, DI boxes and monitor wedges or in-ear systems on the worship platform and manages its cabling and feedback from live sources.", "category": "Worship space", "related_terms": ["Chancel", "Worship sanctuary", "Stage monitor", "In-ear monitor", "Praise team", "Front of house"], "common_mistakes": ["Placing main loudspeakers behind the platform mics, feeding sound back into open vocal and instrument channels.", "Treating a worship platform like a fixed studio; volunteers and layouts change weekly, so cabling must stay flexible and labeled.", "UNSAFE: Leaving cables untaped and the platform edge or steps unmarked, creating trip and fall hazards."], "scenario_contexts": ["Setting up wedge monitors for a praise band on the worship platform.", "Managing feedback from open mics on a reflective platform.", "Rigging in-ear monitor systems for a Sunday worship team."]}, "70704c5f-78ba-4ce8-88fe-86fa0c9c56da": {"definition": "The main worship room of a house of worship, where the congregation gathers for services; it is the worship equivalent of an auditorium and contains the seating, the platform or chancel, and the primary sound-reinforcement system. Its size, shape and reverberant acoustics strongly shape how speech and music are reproduced.", "plain_english": "A worship sanctuary is the main room of a church where people gather for services. It holds the seats, the stage and the main sound system.", "purpose_function": "It houses the congregation and the service, so its acoustics and sound system must deliver clear speech and balanced music to every seat.", "practical_application": "A technician designs and aims loudspeakers, sets gain structure and manages reverberation so speech stays intelligible throughout the sanctuary.", "category": "Worship space", "related_terms": ["Worship platform", "Chancel", "Reverberation time", "Speech intelligibility", "Congregation", "Distributed loudspeaker system"], "common_mistakes": ["Underestimating long reverberation in a hard, high sanctuary, which blurs speech intelligibility.", "Aiming a few loud loudspeakers at the room instead of covering seats evenly with a distributed design.", "UNSAFE: Ignoring occupant-load and means-of-egress limits when adding staging, seating or equipment in the sanctuary."], "scenario_contexts": ["Tuning a sound system for speech clarity in a reverberant sanctuary.", "Designing loudspeaker coverage for every seat in a large sanctuary.", "Balancing music and spoken word during a worship service."]}, "dc5f13bc-3403-4847-b15a-d9c72ba052f9": {"definition": "The dedicated technical control position in a house of worship that houses the audio console and often lighting, video and presentation control, usually at the rear or side of the sanctuary with sightlines to the platform. It centralizes operation of the service's production systems in one staffed location.", "plain_english": "A worship technology booth is where the tech team runs the service. It holds the sound, lighting and video controls with a view of the stage.", "purpose_function": "It brings audio, lighting and video control together with a clear view of the platform, so operators can run the service in sync and hear a representative mix.", "practical_application": "A technician operates the front-of-house console and presentation systems from the booth, so its location and any glass front affect how the mix translates to the room.", "category": "Technical Spaces", "related_terms": ["Church sound booth", "Front of house", "Mixing console", "Worship platform", "Sightline", "Video switcher"], "common_mistakes": ["Placing the booth under a balcony or in a corner, where the operator hears an unrepresentative mix.", "Enclosing the booth behind closed glass, so the operator mixes to a sound the congregation never hears.", "UNSAFE: Powering consoles, computers and video gear from daisy-chained power strips instead of properly rated, grounded branch circuits."], "scenario_contexts": ["Running audio, lighting and lyrics from the worship technology booth on Sunday.", "Positioning the booth for a representative front-of-house mix.", "Training volunteers to operate the console and presentation software in the booth."]}, "07903832-655e-4ad5-ac07-8a116e8f3ac9": {"definition": "The area of the stage floor that projects toward the audience beyond the proscenium arch and the main curtain line. Also called the forestage, it is the part of the stage in front of the house curtain and closest to the audience.", "plain_english": "The apron is the front strip of the stage. It sticks out past the main curtain, toward the crowd. Actors on the apron are the closest ones to the audience.", "purpose_function": "It extends the acting space in front of the curtain, letting performers work closer to the audience and allowing scenes to continue while the main curtain is closed behind them.", "practical_application": "A technician places downstage lighting, foot mics, or set pieces on the apron and keeps its edge clearly marked so performers do not step off into the pit or house.", "category": "Stage Areas", "related_terms": ["Proscenium", "Forestage", "Thrust stage", "Orchestra pit", "Downstage", "Deck"], "common_mistakes": ["Confusing the apron with a full thrust stage; the apron is the shallow area just in front of the proscenium, not a stage surrounded by audience on three sides", "Assuming the apron sits behind the main curtain; it lies in front of it, downstage of the curtain line", "UNSAFE: Working or performing near an unmarked apron edge above an open orchestra pit, risking a fall"], "scenario_contexts": ["A singer steps onto the apron to perform a solo close to the audience while a set change happens behind the closed curtain", "A lighting designer adds apron-edge fixtures to cover performers who play downstage of the proscenium", "Crew mark the apron edge with glow tape before a show to warn performers of the drop to the pit"]}, "7374071f-0c50-48d1-aa41-fffbe0d58265": {"definition": "A stage configuration in which the audience is seated on all sides of a central performance area, also known as theatre-in-the-round. Performers enter through aisles or corner vomitories, and scenery is kept low so it does not block any sightline.", "plain_english": "An arena stage sits in the middle, with seats all around it. The crowd surrounds the actors on every side, like fans around a boxing ring. Sets must stay low so no one's view is blocked.", "purpose_function": "It creates an intimate, shared space that brings the audience close on every side, while requiring designers to keep scenery low and stage action open to all viewpoints.", "practical_application": "A technician rigs lighting and sound overhead and routes cables under the floor or through aisles, because an arena stage has no backstage wall or side masking to hide equipment.", "category": "Stage Configuration", "related_terms": ["Thrust stage", "Proscenium", "Vomitory", "Sightline", "Center stage", "Backstage"], "common_mistakes": ["Confusing an arena stage with a thrust stage; a thrust has audience on only three sides, while an arena has audience on all sides", "Using tall scenery or backdrops that block sightlines for part of the surrounding audience", "Forgetting that there is no hidden upstage area, so entrances and crew paths must run through the aisles"], "scenario_contexts": ["A theatre-in-the-round production stages a play with the audience seated on all four sides", "A boxing-ring-style concert uses a central arena stage so fans surround the performer", "A designer plans overhead lighting positions because an arena stage has no wings to hide fixtures"]}, "569b0381-2f99-4e71-8d2b-27660026d627": {"definition": "A secondary, usually smaller performance stage placed out among the audience, away from the main stage, common on large concert tours. It lets performers move into the middle or rear of the crowd to play closer to seats far from the main stage, often reached by a runway or thrust.", "plain_english": "A B-stage is a second, smaller stage built out in the crowd. The band walks to it so fans in the far seats get a close-up view. A runway often links it back to the main stage.", "purpose_function": "It brings the performance nearer to audience members seated far from the main stage, improving intimacy and sightlines in large arenas and stadiums.", "practical_application": "A touring technician runs power, audio, and lighting to the B-stage and plans a safe, protected performer and crew path from the main stage, often along a barricaded runway.", "category": "Stage Configuration", "related_terms": ["Main stage", "Catwalk stage extension", "Thrust stage", "Runway", "Arena stage", "Barricade"], "common_mistakes": ["Assuming the B-stage is a spare backup stage; it is a planned secondary stage used within the same show", "Forgetting to secure and light the path between the main stage and B-stage, creating a trip or fall hazard in the crowd", "UNSAFE: Running unprotected cable across audience walkways to the B-stage instead of using cable ramps or overhead routing"], "scenario_contexts": ["An arena tour builds a small B-stage at the back of the floor so the band can play a few songs near distant fans", "A performer walks a runway from the main stage to a B-stage in the middle of the crowd", "Crew rig a lighting truss and monitor wedges over a B-stage before doors open"]}, "4ca3e89e-36e4-4644-b35a-2e730cf6acfa": {"definition": "The area of a theatre or venue behind and to the sides of the stage setting, hidden from the audience's view. It covers the wings, crossover, dressing rooms, and other spaces where crew and performers work and prepare out of sight.", "plain_english": "Backstage means everywhere the audience cannot see. It is behind and beside the set, plus the dressing rooms and side spaces. This is where the cast and crew get ready and work out of view.", "purpose_function": "It provides hidden space for entrances, exits, quick changes, scenery storage, and crew work, keeping the stage picture clean for the audience.", "practical_application": "A technician keeps backstage areas dark, quiet, and clear of clutter, using dim running lights and glow tape so crew and performers move safely between cues.", "category": "Backstage", "related_terms": ["Wings", "Crossover", "Green room", "Dressing room", "Onstage", "Backstage area"], "common_mistakes": ["Using bright white light backstage during a show, which spills onto the stage and breaks the illusion", "UNSAFE: Leaving cables, set pieces, or tools in backstage paths, creating trip hazards in the dark", "Talking or making noise backstage loud enough for the audience to hear"], "scenario_contexts": ["A stage manager calls cues from a backstage position with a clear view of the stage", "Performers wait backstage in the wings for their entrance cue", "Crew store scenery and props backstage between scene changes"]}, "6a9d834b-caa1-48a2-8b95-a4d2b291271e": {"definition": "The collective offstage and behind-the-scenes spaces of a venue that support a production but stay hidden from the audience. These include the wings, crossover, dressing rooms, green room, scene and prop storage, loading dock, and crew work areas. Where 'backstage' names the general region behind the set, 'backstage area' refers to this full collection of named support spaces taken together.", "plain_english": "The backstage area is all the work and prep space out of the audience's view. It covers the side wings, dressing rooms, storage, and crew paths. Everything needed to run the show happens here, unseen.", "purpose_function": "It houses the people, equipment, and activities that keep a show running, giving space to prepare, store scenery, and move unseen around the stage.", "practical_application": "A technician plans clear, well-marked backstage traffic routes and storage so crew can move set pieces and reach positions quickly and safely in low light.", "category": "Backstage", "related_terms": ["Backstage", "Wings", "Crossover", "Green room", "Loading dock", "Deck"], "common_mistakes": ["Treating the backstage area as loose storage and blocking crew paths and exits", "UNSAFE: Overcrowding the backstage area so fire exits or crossover paths are obstructed", "Assuming every venue has a large backstage area; some stages have very limited offstage space"], "scenario_contexts": ["A touring crew surveys the backstage area to plan where cases, wardrobe, and scenery will live during a run", "A stage manager assigns dressing rooms and quick-change booths within the backstage area", "Crew keep the backstage area clear so performers can cross from one side to the other unseen"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"c5a14767-bc3e-4611-a4bf-58921555f6e3": {"definition": "A long, narrow stage extension, or runway, that projects from the main stage into or through the audience, letting performers walk out among spectators. It resembles a fashion-show catwalk and is common in concerts and fashion or awards events.", "plain_english": "This is a narrow strip of stage that reaches out into the crowd. Performers walk down it, like models on a fashion runway. It brings them closer to more of the audience.", "purpose_function": "It carries performers out into the audience, improving closeness and sightlines for people seated away from the main stage.", "practical_application": "A technician builds the extension level and stable, lights it evenly, and routes and protects any cable running along or beneath it to prevent trips and falls.", "category": "Stage Configuration", "related_terms": ["Thrust stage", "B-stage", "Runway", "Apron", "Barricade", "Deck"], "common_mistakes": ["Confusing this walkway with an overhead catwalk; a stage catwalk extension is a floor-level runway, not a lighting access bridge above the stage", "Underestimating the load and bracing a long, narrow extension needs to stay stable under moving performers", "UNSAFE: Leaving the catwalk extension edges unlit or unmarked above a crowd, risking a fall into the audience"], "scenario_contexts": ["A pop artist walks a catwalk extension into the middle of the arena floor during a show", "A fashion show uses a long catwalk extension so models pass close to guests on both sides", "Crew add edge lighting and grip tape to a catwalk extension before performers use it"]}, "be3176d8-db10-40d0-b222-3c03b6ebadd6": {"definition": "The middle area of the stage, midway between the upstage and downstage edges and midway between stage left and stage right. It is one of the nine standard acting areas used to describe a performer's position, named from the performer's point of view while facing the audience.", "plain_english": "Center stage is the middle of the stage. It sits halfway front-to-back and halfway side-to-side. Left and right are named from the actor's view while facing the audience.", "purpose_function": "It gives directors, performers, and crew a shared, precise word for the middle position, so blocking, focus, and set placement can be communicated clearly.", "practical_application": "A stage manager records an actor's blocking as center stage, and a technician focuses a key light or places a set piece to that spot using the stage's center line.", "category": "Stage Positions", "related_terms": ["Upstage", "Downstage", "Stage left", "Stage right", "Center line", "Apron"], "common_mistakes": ["Reading stage left and right from the audience's view instead of the performer's view while facing the audience", "Confusing center stage with the apron; center stage is the middle area, not the front edge", "Assuming center stage means one exact point rather than the whole middle acting area"], "scenario_contexts": ["A director blocks the lead actor to deliver a monologue from center stage", "A lighting technician focuses a spotlight on center stage for a solo moment", "A stage manager marks center stage on the deck with spike tape during setup"]}, "a02539fa-ae9c-47ba-9e56-8205b1096732": {"definition": "The working surface, or floor, of the stage on which performers move and scenery sits. The term often refers to a temporary floor or platform system built and laid over the permanent stage floor for a particular production.", "plain_english": "The deck is the stage floor that people work and perform on. Sometimes it is the building's real floor. Often it is a special floor built and laid on top for one show.", "purpose_function": "It provides a flat, level, safe surface for performers, scenery, and stage machinery, and can be built up to hide tracks, lifts, or trap doors for a production.", "practical_application": "A technician checks the deck is level, secure, and free of gaps or trip hazards, spikes set positions on it, and confirms it can bear the load of scenery and traffic.", "category": "Stage Structure", "related_terms": ["Stage floor", "Apron", "Wings", "Trap", "Spike mark", "Backstage"], "common_mistakes": ["Assuming the deck is always the building's permanent floor rather than a built surface laid over it for the show", "UNSAFE: Leaving gaps, lifted seams, or loose panels in the deck, creating trip and fall hazards for performers", "Overloading a built deck beyond its rated capacity with heavy scenery or machinery"], "scenario_contexts": ["A crew installs a raked deck over the permanent stage floor for a touring set", "A stage manager spikes furniture positions onto the deck during technical rehearsal", "A carpenter builds trap doors and cable tracks into a show deck before load-in"]}, "802a6b84-68c0-46f7-ba5c-ed7a731f8df1": {"definition": "The area of the stage nearest the audience and on the centre line, where the downstage edge meets the front-to-back centre axis. Downstage denotes the part of the stage closest to the house, a convention inherited from historically raked stages that sloped upward away from the audience.", "plain_english": "It is the spot at the front and middle of the stage, closest to the crowd. Actors stand here to be seen and heard well.", "purpose_function": "It provides a shared, named reference point so directors, actors, and crew all describe the same exact stage location the same way.", "practical_application": "A stage manager blocks a solo to downstage center so the performer is closest to the audience and the main microphone.", "category": "Stage Directions", "related_terms": ["Downstage left", "Downstage right", "Upstage center", "Proscenium", "Forestage"], "common_mistakes": ["Reading downstage as away from the audience; downstage is toward the audience, upstage is away", "Confusing the actor-based left and right with the audience's view when locating stage positions"], "scenario_contexts": ["A director calling an actor to downstage center for a monologue delivered straight to the house", "A lighting designer focusing a special on downstage center for a featured moment"]}, "2b46af29-9894-42eb-bb84-b46f3252a633": {"definition": "The area of the stage nearest the audience and to the actor's left when facing the house. Stage left is defined from the performer's viewpoint, so downstage left lies on the audience's right-hand side.", "plain_english": "It is the front part of the stage, on the actor's left as they face the crowd. From a seat, that is the right side.", "purpose_function": "It names a precise downstage position on the performer's left, so blocking and cues stay consistent for everyone on the production.", "practical_application": "A stage manager notes an entrance downstage left, and the actor enters near the front on the performer's left side.", "category": "Stage Directions", "related_terms": ["Downstage center", "Downstage right", "Stage left", "Upstage left", "Wing"], "common_mistakes": ["Judging stage left from the audience's seats instead of the performer's viewpoint, which reverses left and right", "Forgetting that downstage means toward the audience when combining it with the left direction"], "scenario_contexts": ["A choreographer setting a dancer's exit downstage left toward the first wing", "A director placing a prop table downstage left for a quick pickup during a scene"]}, "f6803a35-257d-405b-aa41-890dc2593aaf": {"definition": "The area of the stage nearest the audience and to the actor's right when facing the house. Stage right is defined from the performer's viewpoint, so downstage right lies on the audience's left-hand side.", "plain_english": "It is the front part of the stage, on the actor's right as they face the crowd. From a seat, that is the left side.", "purpose_function": "It names a precise downstage position on the performer's right, so blocking, cues, and crew moves stay consistent across the production.", "practical_application": "A stage manager marks a prop table downstage right so the actor can grab a prop just after a front entrance.", "category": "Stage Directions", "related_terms": ["Downstage center", "Downstage left", "Stage right", "Upstage right", "Wing"], "common_mistakes": ["Judging stage right from the audience's seats instead of the performer's viewpoint, which reverses left and right", "Mixing up downstage right with upstage right by forgetting that downstage is toward the audience"], "scenario_contexts": ["A director blocking an entrance downstage right from the first wing on that side", "A lighting technician focusing a follow spot on a performer moving to downstage right"]}, "47f397b0-b54e-4806-a798-52d4bea48a81": {"definition": "A stage, or a section of the stage floor, mounted on a powered lift that can be raised or lowered to change level, reveal scenery, or move performers and set pieces between the stage deck and areas below. It is also called a stage lift or lift stage.", "plain_english": "It is a part of the stage floor that moves up and down like an elevator. Crews use it to lift scenery or actors into view.", "purpose_function": "It changes stage levels and moves heavy scenery or performers vertically, so productions can make fast reveals and scene changes without carrying items on and off.", "practical_application": "A crew loads a set piece onto the elevator stage below the deck, then raises it into position for the next scene.", "category": "Stage Machinery", "related_terms": ["Trap", "Revolve", "Understage", "Orchestra pit lift", "Deck"], "common_mistakes": ["UNSAFE: Standing at or reaching into the edge of a moving stage lift, where a person can be caught in the shear point between the platform and the fixed floor", "UNSAFE: Loading the lift beyond its rated capacity, risking mechanical failure or a dropped load", "Confusing an elevator stage, which changes height, with a revolve, which rotates on the same level"], "scenario_contexts": ["An opera house raising a full set from the understage on an elevator stage during a blackout", "A concert venue using a stage lift to bring a drum riser up to deck level between acts"]}, "886eef21-38d8-45ea-8f97-d56ca8bf3db3": {"definition": "A stage configuration in which the audience is seated on one side only, facing an acting area at one end of the room, without a framing proscenium arch. It resembles a proscenium layout, but the stage and auditorium share the same architectural volume.", "plain_english": "It is a stage set at one end of a room, with all the seats facing it from the front. There is no arch framing the stage.", "purpose_function": "It concentrates the whole audience on a single frontal sightline for a clear shared view, while keeping the flexible open feel of a room with no proscenium.", "practical_application": "A black-box theatre is arranged as an end stage, with rows of seats facing a playing area built along one wall.", "category": "Stage Configurations", "related_terms": ["Thrust stage", "Arena stage", "Proscenium stage", "Black box theatre", "Sightline"], "common_mistakes": ["Confusing an end stage with a proscenium stage; an end stage has no proscenium arch framing the opening", "Assuming end-stage seating allows entrances from several sides, when the audience actually faces only one front"], "scenario_contexts": ["A festival converting a hall into an end stage with all seating facing one wall", "A touring band playing a club laid out as an end stage, with the audience in front only"]}, "1a925887-5a10-4bd2-97b3-ace956374563": {"definition": "A temporary frame built just inside the permanent proscenium arch to reduce or reshape the size of the stage opening, and to mask offstage areas and carry scenery or lighting. It is also known as an inner proscenium, show portal, or false pros.", "plain_english": "It is an extra frame set inside the real stage arch to make the opening smaller. It also hides the side spaces from view.", "purpose_function": "It lets a production tailor the opening's width and height to its set, and it masks the wings while hiding lighting and rigging from the audience.", "practical_application": "A touring show installs a false proscenium so its scenery fits venues with differently sized proscenium openings.", "category": "Stage Architecture", "related_terms": ["Proscenium", "Teaser", "Tormentor", "Portal", "Masking"], "common_mistakes": ["Confusing the false proscenium with the permanent proscenium arch, which is part of the building structure", "Setting a false proscenium too far in, which reduces the opening and can block sightlines for side seats"], "scenario_contexts": ["A production adding a false proscenium to narrow a wide house opening for an intimate set", "A designer building a decorated show portal as a false proscenium to frame the scene"]}, "34132f57-8b7b-4e38-bfbd-7d81f23689ac": {"definition": "A large, often temporary or outdoor performance platform used for music festivals and large-scale concerts, typically presented as an open end stage with a wide unframed front, a roof or canopy carrying rigging and weather protection, and flanking areas for the PA, video walls, and backline. It prioritises broad sightlines, load-bearing overhead structure, and rapid changeovers between acts.", "plain_english": "It is a big stage built for music festivals, often outdoors. It has a wide open front and a strong roof to hang lights and sound.", "purpose_function": "It supports large crowds and heavy production, giving room for big sound, video, and fast band changeovers, while the roof carries rigging loads and shields gear from weather.", "practical_application": "A crew rigs line-array speakers and video walls on a festival stage and uses rolling risers to swap bands quickly between sets.", "category": "Stage Configurations", "related_terms": ["End stage", "Line array", "Rolling riser", "Rigging", "Front of house"], "common_mistakes": ["UNSAFE: Adding rigging or equipment to a festival stage roof beyond its rated load or ignoring wind-load limits, which can cause structural collapse", "Treating a temporary festival stage like an indoor stage and skipping weather and wind monitoring"], "scenario_contexts": ["An outdoor music festival running several bands a day on a large festival stage with rolling risers", "A production manager scheduling tight changeovers on a festival stage between headline acts"]}, "76713bac-2178-4893-b9b8-9c45f1fd3f40": {"definition": "The offstage space and entrance nearest the proscenium on either side of the stage; wing positions are numbered from downstage to upstage, so the first wing is the one closest to the audience. The term covers both the masking (leg) position and the entrance and exit gap at that point.", "plain_english": "It is the hidden side space closest to the front of the stage. Actors use it as the first place to enter or wait offstage.", "purpose_function": "It provides the downstage-most entrance and offstage staging area, and its masking hides the audience's view into the side spaces.", "practical_application": "An actor waits in the first wing for a downstage entrance, staying just out of the audience's sightline.", "category": "Backstage Spaces", "related_terms": ["Wing", "Leg", "Offstage", "Masking", "Crossover"], "common_mistakes": ["Counting wings from upstage; wing positions are numbered from downstage, so the first wing is nearest the audience", "Standing too far downstage in the first wing and being seen by audience members seated at the sides"], "scenario_contexts": ["A stage manager setting a quick-change station in the first wing for a fast costume swap", "A dancer entering from the first wing for an opening downstage sequence"]}, "b75cb0c1-d632-4716-9868-01b341d702f2": {"definition": "The part of the stage that projects toward the audience in front of the proscenium arch and the main curtain line. It is synonymous with the apron, the acting area downstage of the house curtain.", "plain_english": "It is the front strip of stage that sticks out past the arch and curtain. Actors can play here in front of a closed curtain.", "purpose_function": "It gives performers an acting area in front of the curtain, so scenes can continue there while scenery is changed behind the closed curtain.", "practical_application": "A performer delivers a speech on the forestage while the crew resets the scene behind the closed main curtain.", "category": "Stage Architecture", "related_terms": ["Apron", "Proscenium", "Main curtain", "Orchestra pit", "Downstage center"], "common_mistakes": ["Confusing the forestage with the full stage; the forestage is only the area downstage of the curtain line", "Assuming overhead stage bars light the forestage, when it often needs front-of-house lighting instead"], "scenario_contexts": ["An actor playing an intimate scene on the forestage in front of a closed curtain", "A concert vocalist stepping onto the forestage to get closer to the audience"]}, "07f0485c-6510-4a4a-8140-fd71c2c8d886": {"definition": "The parts of the stage and stage house that lie outside the acting area and are not visible to the audience, chiefly the wings and backstage spaces. Used as a direction, offstage also means toward the nearest side of the stage, away from the centre line; the opposite of onstage.", "plain_english": "Offstage is any part of the stage the audience cannot see, like the sides behind the curtains. As a direction, it also means moving toward the nearest side, away from the middle.", "purpose_function": "It names the hidden zones and the sideways direction so cast and crew can describe where people, props, and moves happen out of the audience's view.", "practical_application": "A stage manager tells an actor to wait offstage until their cue, meaning stand in the wings out of sight of the house.", "category": "Stage Areas", "related_terms": ["Onstage", "Wing", "Backstage", "Offstage crossover", "Offstage of", "Proscenium"], "common_mistakes": ["Treating offstage as only the wings, forgetting it also works as a direction meaning toward the nearest side", "Confusing offstage with upstage; offstage moves sideways toward the wings, upstage moves away from the audience"], "scenario_contexts": ["A stage manager cueing performers to hold offstage in the wings until their entrance", "A director asking an actor to take one step offstage to clear the sightline to a set piece"]}, "20c6c191-584e-40c2-b930-162dc80a3d36": {"definition": "A concealed route that lets performers and crew pass from one side of the stage to the other without being seen by the audience, either behind the backdrop or scenery upstage or through a corridor around or behind the stage house. Often shortened to crossover.", "plain_english": "An offstage crossover is a hidden path that lets people get from one side of the stage to the other. The audience never sees them cross.", "purpose_function": "It exists so a performer or technician can reach the opposite wing for an entrance or a task without walking across the visible stage.", "practical_application": "An actor who exits stage left but must enter stage right uses the offstage crossover behind the set to get there unseen during the scene.", "category": "Backstage Spaces", "related_terms": ["Offstage", "Wing", "Backstage", "Backdrop", "Proscenium"], "common_mistakes": ["Blocking the crossover with cases, cables, or stored scenery so performers cannot pass in the dark", "Assuming a crossover always exists; some stages force a long route through the building or none at all"], "scenario_contexts": ["A quick-change plan that routes an actor along the upstage crossover between two entrances", "A stage manager keeping the crossover clear and lit with blue running lights for safe passage during a blackout"]}, "12f4d95b-4247-4dbb-b0b9-1877fc75b388": {"definition": "A relative directional phrase meaning nearer to the closest side of the stage than a given reference point, that is, farther from the centre line and toward the wings. It is the opposite of onstage of.", "plain_english": "Offstage of means closer to the side of the stage than something else. If you stand offstage of a chair, you are on the side nearer the wings.", "purpose_function": "It lets a director or stage manager fix a position in relation to another object or actor, without giving an absolute stage location.", "practical_application": "A director says to stand offstage of the table, so the actor moves to the side of the table that is closer to the nearest wing.", "category": "Stage Directions", "related_terms": ["Onstage of", "Offstage", "Onstage", "Stage left", "Stage right"], "common_mistakes": ["Reading offstage of as a fixed spot rather than a position relative to the named reference object", "Mixing up offstage of with upstage of; offstage of is sideways toward the wings, not away from the audience"], "scenario_contexts": ["A director blocking one actor to stand offstage of another so the audience sees both faces", "A designer noting that a lamp sits just offstage of the doorway to keep the entrance clear"]}, "534a5c03-649b-4fa1-b057-b510dad4aa98": {"definition": "The acting area within view of the audience, where the performance takes place. Used as a direction, onstage also means toward the centre line of the stage, away from the wings; the opposite of offstage.", "plain_english": "Onstage means the part of the stage the audience can see, where the show happens. As a direction, it also means moving toward the middle of the stage.", "purpose_function": "It names both the visible playing space and the sideways direction toward centre, so cast and crew share one clear reference.", "practical_application": "A stage manager cues a performer to move onstage, meaning step into the visible acting area or shift toward the centre line.", "category": "Stage Areas", "related_terms": ["Offstage", "Onstage of", "Center stage", "Wing", "Proscenium"], "common_mistakes": ["Using onstage only for the visible area and forgetting it also means the direction toward the centre line", "Confusing onstage with downstage; onstage moves sideways toward centre, downstage moves toward the audience"], "scenario_contexts": ["A director calling an actor onstage from the wings for an entrance", "A choreographer asking a dancer to move one step onstage to tighten a group formation"]}, "88c993c9-fcd8-4453-bdf5-d16037e3a44e": {"definition": "A relative directional phrase meaning nearer to the centre line of the stage than a given reference point, that is, farther from the wings and toward centre. It is the opposite of offstage of.", "plain_english": "Onstage of means closer to the middle of the stage than something else. If you stand onstage of a chair, you are on the side nearer the center.", "purpose_function": "It fixes a position in relation to another object or actor by placing it on the centre side of that reference, without an absolute location.", "practical_application": "A director says to stand onstage of the sofa, so the actor moves to the side of the sofa that is closer to the centre line.", "category": "Stage Directions", "related_terms": ["Offstage of", "Onstage", "Offstage", "Center stage", "Stage left"], "common_mistakes": ["Treating onstage of as a fixed location rather than a position relative to the named reference object", "Mixing up onstage of with downstage of; onstage of is sideways toward centre, not toward the audience"], "scenario_contexts": ["A director placing one actor onstage of another to balance a picture across the stage", "A stage manager noting a prop table onstage of the pillar so it stays inside the sightlines"]}, "57361f1c-b3f2-4dbf-b9df-eee64480f92c": {"definition": "A basic stage form in which the acting area is a raised platform set before the audience, without a proscenium arch and its associated masking. The audience faces the platform from one side, and in some arrangements from more than one side.", "plain_english": "A platform stage is a simple raised stage with no picture-frame opening around it. The audience usually sits in front of it and looks up at the action.", "purpose_function": "It raises and defines the playing area for clear sightlines while keeping the open, direct actor-audience relationship of the earliest stage forms.", "practical_application": "A crew builds a platform stage from decking and legs in a hall or outdoors when no permanent proscenium theatre is available.", "category": "Stage Configuration", "related_terms": ["Proscenium", "Arena stage", "Thrust stage", "End stage", "Deck"], "common_mistakes": ["Assuming a platform stage needs a proscenium arch; its defining feature is an open raised platform with no such frame", "UNSAFE: Building the platform without proper bracing, rated decking, or guardrails and edge marking, risking collapse or falls"], "scenario_contexts": ["A touring show setting up a platform stage in a school gymnasium for a one-night performance", "An outdoor festival erecting a raised platform stage so a standing crowd can see the performers"]}, "e65a40ba-f744-4b44-843e-435b7f75c7a3": {"definition": "In modern theatre, the dividing structure between the acting area and the seating, pierced by the framed opening through which the audience views the performance. By extension, the term also names that opening and the picture-frame style of stage it defines.", "plain_english": "The proscenium is the wall with a large opening that separates the stage from the seats. The audience watches the show through this opening, like a picture in a frame.", "purpose_function": "It frames the view of the stage and hides the wings, flies, and backstage from the audience, creating a controlled picture-frame presentation.", "practical_application": "A technician measures set pieces against the proscenium opening to be sure scenery fits and stays masked from the audience's view.", "category": "Stage Architecture", "related_terms": ["Proscenium arch", "Proscenium line", "Apron", "Wing", "Fly system"], "common_mistakes": ["Assuming the modern picture-frame meaning matches the ancient Greek proskenion, which named a different part of the theatre", "Confusing the proscenium wall with the apron; the apron is the stage floor in front of the proscenium"], "scenario_contexts": ["A designer planning masking so scenery stays hidden behind the proscenium from every seat", "A crew hanging a main curtain just upstage of the proscenium opening"]}, "bfc7ab45-83d7-4e79-9c2f-1644818314bf": {"definition": "The architectural frame surrounding the proscenium opening, forming the picture-frame border through which the audience views the stage and marking the division between the stage and the auditorium. Despite the name, the opening is frequently rectangular rather than arched.", "plain_english": "The proscenium arch is the frame around the stage opening. It works like a picture frame, so the audience sees the show inside it.", "purpose_function": "It defines and decorates the edge of the stage picture and, with masking behind it, conceals the offstage machinery and wings from the audience.", "practical_application": "A crew hangs a border and legs just behind the proscenium arch so the audience cannot see over or around the frame into the flies and wings.", "category": "Stage Architecture", "related_terms": ["Proscenium", "Proscenium line", "Border", "Teaser", "Tormentor"], "common_mistakes": ["Assuming the opening is always curved; many proscenium arches are plain rectangular openings", "Confusing the proscenium arch with a false proscenium, which is a temporary frame set inside the real one"], "scenario_contexts": ["A lighting designer mounting a bridge or booms just inside the proscenium arch to light the downstage area", "A scenic crew sizing a drop to fill the proscenium arch opening without gaps at the edges"]}, "2032e999-6eb4-4396-871e-9d14adfb8bb6": {"definition": "An imaginary line drawn across the stage floor in the plane of the proscenium opening, marking the boundary between the stage proper upstage and the apron or forestage downstage. It serves as a reference datum for laying out scenery and stage positions, closely related to the plaster line at the upstage face of the proscenium wall.", "plain_english": "The proscenium line is an imaginary line across the floor at the front frame of the stage. Crews use it as a starting point to measure where scenery goes.", "purpose_function": "It gives designers and crew a fixed reference across the stage so scenery, positions, and measurements can be laid out consistently from one known line.", "practical_application": "A technician measures a set piece a set distance upstage of the proscenium line to place it exactly where the ground plan shows.", "category": "Stage Architecture", "related_terms": ["Proscenium", "Proscenium arch", "Plaster line", "Setting line", "Center line"], "common_mistakes": ["Confusing the proscenium line with the setting line, which marks the downstage edge of the standing scenery", "Ignoring which reference line a ground plan is dimensioned from, which shifts every scenery position"], "scenario_contexts": ["A stage manager taping the deck relative to the proscenium line and centre line before a load-in", "A designer dimensioning a ground plan from the proscenium line so the crew can spike scenery accurately"]}, "d11a2318-7ae9-4357-b2e9-b575f2d500df": {"definition": "The framed rectangular opening in the proscenium wall through which the audience views the stage, bounded by the proscenium arch at the sides and top and by the stage floor below. Its width and height set the maximum visible picture and the sightline limits of a proscenium stage.", "plain_english": "It is the framed opening in the wall that the audience looks through to see the stage. Think of it as a giant picture frame around the acting area.", "purpose_function": "It defines the visible stage picture and the sightlines, framing the action and letting the surrounding structure hide the offstage wings, rigging, and lighting from the audience.", "practical_application": "A designer measures the proscenium opening to size scenery, borders, and masking so nothing offstage is seen and the set fits the framed view.", "category": "Stage Architecture", "related_terms": ["Proscenium arch", "Proscenium stage", "False proscenium", "Sightline", "Masking", "Teaser"], "common_mistakes": ["Confusing the proscenium opening with the proscenium arch; the opening is the framed gap, the arch is the surrounding structure", "Designing scenery to the full stage width and forgetting the opening limits what the audience can actually see", "Ignoring the opening height when hanging borders, leaving rigging or lights visible from the front rows"], "scenario_contexts": ["A scenic designer sizing a backdrop to fill the proscenium opening without spilling into the wings", "A touring company checking a venue's proscenium opening dimensions before load-in", "A lighting designer setting a teaser height to trim the top of the proscenium opening"]}, "a08a6900-5f8b-4a89-bb68-b60c9be86723": {"definition": "A stage configuration in which the acting area is framed by a proscenium arch and the audience views the performance from one side, through the proscenium opening. The arrangement creates a clear separation between the stage picture and the auditorium and supports front-facing scenery, masking, and an overhead fly system.", "plain_english": "It is a stage set inside a big frame, with the audience seated on one side facing it. The frame works like a window the crowd watches the show through.", "purpose_function": "It presents the performance as a single framed picture to a one-sided audience, so scenery, masking, and rigging can be hidden behind and beside the frame.", "practical_application": "A crew rigging a proscenium stage hangs legs, borders, and drops upstage of the arch, knowing the audience only sees the action inside the opening.", "category": "Stage Configuration", "related_terms": ["Proscenium arch", "Proscenium opening", "Proscenium theater", "Fly system", "Wing", "Apron"], "common_mistakes": ["Assuming a proscenium stage has audience on more than one side, when it is viewed only from the front", "Forgetting that anything beyond the masking lines can be seen by side seats, so sightlines must be checked", "Confusing a proscenium stage with a thrust or arena stage, which are surrounded on more sides by audience"], "scenario_contexts": ["A stage manager blocking entrances from the wings of a proscenium stage", "A designer planning fly-in scenery for a proscenium stage with a working fly tower", "A touring show adapting its set to fit different proscenium stages on a national tour"]}, "50a0747d-b0fd-49d9-b02f-0efce4d9df3f": {"definition": "A theater building whose auditorium and stage are arranged around a proscenium arch, with all seating facing the framed stage opening from the front. It typically pairs a raked or tiered auditorium with a stage house that may include a fly tower, wings, and sometimes side and rear stages.", "plain_english": "It is a theater built around a framed stage opening. All the seats face the same way, toward the framed stage.", "purpose_function": "It organizes a large audience on one side of a framed stage, giving strong sightlines to the stage picture while housing the machinery, wings, and rigging out of view.", "practical_application": "A production touring a proscenium theater plans its load-in around the building's fly tower height, wing depth, and proscenium opening size.", "category": "Venue Type", "related_terms": ["Proscenium stage", "Proscenium opening", "Fly tower", "Auditorium", "Wing", "Rear stage"], "common_mistakes": ["Using 'proscenium theater' to mean only the stage; the term names the whole building and audience layout", "Assuming every proscenium theater has a full fly tower or side stages, which vary widely between venues", "Confusing a proscenium theater with a black box or arena venue, which surround the audience differently"], "scenario_contexts": ["A company comparing proscenium theaters to book a venue with enough wing space for a large set", "A technical director reviewing a proscenium theater's stage house dimensions during a site survey", "A touring crew scaling scenery to fit the proscenium theaters on their route"]}, "1b2dfdcf-2af9-4c08-a35d-f28a1c188bb1": {"definition": "A stage-sized space located directly upstage of the main acting area, used for scenery storage, preset scenes, or as additional playing depth. In large stage houses it commonly holds a full-size stage wagon so an entire scene can be preset and rolled forward onto the main stage.", "plain_english": "It is a large open space right behind the main stage. Crews use it to store scenery or to preset a whole scene ready to move on.", "purpose_function": "It extends the stage depth and provides offstage room to preset large scenery, so complete scenes can be changed quickly by rolling them onto the main stage.", "practical_application": "A crew presets the next act's set on a wagon in the rear stage, then rolls it downstage during a blackout for a fast scene change.", "category": "Stage Areas", "related_terms": ["Side stage", "Slip stage", "Rolling stage platform", "Backstage", "Crossover", "Main stage"], "common_mistakes": ["Confusing the rear stage with the backstage crossover; the rear stage is a full playing space, not just a passage", "Presetting a wagon in the rear stage without checking it clears the main stage rigging and legs when moved", "UNSAFE: Storing scenery in the rear stage so it blocks a marked fire exit or crossover route"], "scenario_contexts": ["A large opera house presetting a full scene in the rear stage for a fast changeover", "A crew using the rear stage as extra depth for a deep perspective set", "A stage manager routing a crossover behind a set piece parked in the rear stage"]}, "7706a6d2-5c18-48b5-8aa0-7dcd1e49f003": {"definition": "A wheeled platform, often called a wagon or truck, used to move scenery, set pieces, or performers on and off the stage. It rides on casters or a track and lets heavy or complex scenery be repositioned quickly for scene changes.", "plain_english": "It is a platform on wheels used to move scenery or people on and off stage. It rolls like a big cart so heavy sets can shift fast.", "purpose_function": "It allows large, heavy, or pre-built scenery to be moved as a single unit, speeding scene changes and reducing the manual lifting a crew must do.", "practical_application": "A crew builds a room set on a rolling stage platform in the wings, then pushes it into position for the scene and rolls it off afterward.", "category": "Stage Machinery", "related_terms": ["Slip stage", "Rear stage", "Side stage", "Deck", "Elevator stage", "Scene change"], "common_mistakes": ["UNSAFE: Rolling a heavy platform without spotters or a clear path, risking crushing crew or striking scenery", "UNSAFE: Failing to lock casters or brakes once the platform is in position, letting it drift under load", "Overloading a rolling platform beyond its rated capacity so it becomes unstable or hard to steer", "Ignoring the floor edge or pit, letting a rolling platform run off the deck"], "scenario_contexts": ["A crew moving a full room set on a rolling platform during a blackout", "A concert crew rolling a drum riser platform on and off the stage between acts", "A stagehand parking a loaded platform in the wings and locking its brakes before the show"]}, "93e9d3e5-55a8-4064-929f-b3aaed7c1d0c": {"definition": "A secondary, usually smaller stage positioned away from the main stage, often within or beyond the audience, used so performers can play closer to distant spectators. It is common in large concert and arena productions and may be linked to the main stage by a runway or thrust.", "plain_english": "It is a smaller extra stage set away from the main one, often out among the crowd. It lets performers get closer to fans far from the main stage.", "purpose_function": "It brings the performance nearer to audience areas far from the main stage, improving engagement and sightlines in large venues where many seats are distant.", "practical_application": "A touring crew builds a satellite stage at the back of an arena floor and runs audio, power, and lighting to it so the artist can perform in the round mid-show.", "category": "Stage Configuration", "related_terms": ["B-stage", "Thrust stage", "Main stage", "Runway", "Arena stage", "Side stage"], "common_mistakes": ["Confusing a satellite stage with the main stage; the satellite is a smaller remote playing area", "Underestimating the cable runs and delay-speaker timing needed to serve a distant satellite stage", "UNSAFE: Routing audience-area cable to a satellite stage without ramps or covers, creating a trip hazard"], "scenario_contexts": ["An arena tour adding a satellite stage so the artist can perform among the back sections", "A festival building a satellite stage in the crowd for an acoustic mid-set", "An audio crew timing delay speakers to a satellite stage placed away from the main PA"]}, "568ba3d4-cf03-43ba-9cc8-8af9425ef97b": {"definition": "The offstage space and entrance second from the proscenium on either side of the stage; wing positions are numbered from downstage to upstage, so the second wing lies just upstage of the first wing. The term covers both the masking (leg) position and the entrance and exit gap at that point.", "plain_english": "It is the hidden side space that is second closest to the front of the stage. Actors wait and enter there, just out of the audience's view.", "purpose_function": "It provides a numbered offstage entrance and staging area upstage of the first wing, and its masking hides the audience's view into the side space.", "practical_application": "A stage manager calls an actor to enter from the second wing, and the performer stands ready in the side space upstage of the first entrance.", "category": "Backstage Spaces", "related_terms": ["First wing", "Wing", "Leg", "Masking", "Offstage", "Crossover"], "common_mistakes": ["Counting wings from upstage; wing positions are numbered from downstage, so the second wing is the second from the front", "Confusing the second wing's leg position with its entrance gap when marking blocking", "Blocking the second-wing entrance with scenery or road cases, cutting off an actor's exit"], "scenario_contexts": ["A choreographer setting a dancer's entrance from the second wing during a number", "A stage manager placing a prop table in the second wing for a mid-scene pickup", "A crew keeping the second-wing entrance clear for a fast actor cross"]}, "ade8df6d-232d-4a8b-9c7f-99cba06dc07c": {"definition": "A stage space located to the left or right of the main acting area, off the audience's sightlines, used for scenery storage, preset scenes, or additional playing width. In large stage houses side stages are often full stage size and hold wagons so scenes can be preset and rolled laterally onto the main stage.", "plain_english": "It is the space just off to the side of the main stage, out of the audience's view. Crews use it to hold scenery or roll sets on and off.", "purpose_function": "It provides offstage room beside the main stage to preset and store large scenery, so full scenes can be rolled sideways into position for fast changes.", "practical_application": "A crew presets the next scene on a wagon in the side stage, then slides it onto the main stage during a scene change.", "category": "Stage Areas", "related_terms": ["Rear stage", "Slip stage", "Wing", "Rolling stage platform", "Main stage", "Crossover"], "common_mistakes": ["Confusing a side stage with the wings; a side stage is a full-depth playing space, while wings are the narrower masking entrances", "Presetting a wagon in the side stage without checking it clears the proscenium and legs when rolled on", "UNSAFE: Overfilling a side stage with stored scenery so it blocks a fire exit or crossover route"], "scenario_contexts": ["An opera house presetting a full scene on a side stage for a lateral scene shift", "A crew using a side stage to store a wagon between its appearances", "A stage manager keeping a side-stage crossover clear for actors moving between wings"]}, "93985e81-0308-4d2d-a140-dcfac217a7d2": {"definition": "A large rolling platform, typically the size of the main acting area, that carries a complete set and slips onto the main stage from a side or rear stage to effect a full scene change. It is a form of stage wagon and may run on casters or in a floor track.", "plain_english": "It is a huge platform on wheels that holds a full set. It slides in from the side or back to swap the whole scene at once.", "purpose_function": "It lets an entire preset scene be moved onto the stage as one unit, so a full change can happen quickly and smoothly instead of striking pieces one at a time.", "practical_application": "A crew presets a full set on a slip stage in the side stage, then rolls it into position during a blackout while the previous set slips off.", "category": "Stage Machinery", "related_terms": ["Rolling stage platform", "Side stage", "Rear stage", "Wagon", "Scene change", "Deck"], "common_mistakes": ["Confusing a slip stage with a small scenery wagon; a slip stage carries a whole set the size of the stage", "UNSAFE: Moving a loaded slip stage without spotters and a locked path, risking crushing crew or hitting scenery", "UNSAFE: Failing to secure or brake a slip stage in position, letting the loaded platform drift under performers", "Presetting a slip stage without confirming it aligns with the floor track and clears the proscenium"], "scenario_contexts": ["A large musical using slip stages from the side stages to swap complete sets in seconds", "An opera house rolling a slip stage forward from the rear stage for the next act", "A crew aligning a slip stage to its floor track during a technical rehearsal"]}, "dddad475-44b5-49e6-bb65-09ccf90fafa5": {"definition": "The part of the stage floor that projects toward the audience beyond the proscenium arch and the main curtain line. Also called the apron or forestage, it is the acting area closest to the house and downstage of the house curtain.", "plain_english": "It is the front strip of the stage. It reaches out past the main curtain, toward the crowd. People standing here are the closest ones to the audience.", "purpose_function": "It extends the playing space in front of the curtain, so performers can work close to the audience and scenes can continue while the main curtain is closed behind them.", "practical_application": "A technician marks the apron edge with glow tape and sets downstage lighting or foot mics there, so performers do not step off into the pit or house.", "category": "Stage Areas", "related_terms": ["Apron", "Proscenium", "Forestage", "Orchestra pit", "Downstage center", "Deck"], "common_mistakes": ["Assuming the apron sits behind the main curtain; it lies in front of it, downstage of the curtain line", "Confusing the apron with a full thrust stage, which has audience on three sides rather than a shallow front edge", "UNSAFE: Working or performing near an unmarked apron edge above an open orchestra pit, risking a fall"], "scenario_contexts": ["A singer steps onto the apron for a solo close to the audience while a set change happens behind the closed curtain", "A lighting designer adds apron-edge fixtures to cover performers who play downstage of the proscenium", "Crew mark the apron edge with glow tape before a show to warn performers of the drop to the pit"]}, "10c1d094-03ac-414d-adb5-dec1c41dcadd": {"definition": "The space directly beneath the stage floor, also called the understage, cellar, or trap room. It houses stage machinery, lifts, and traps, and gives access to the underside of the stage deck for effects and scene changes.", "plain_english": "It is the space right under the stage floor. Machines, lifts, and trap doors sit down here. Crews use it to move things up onto the stage from below.", "purpose_function": "It provides room for the machinery, lifts, and traps that move scenery and performers up through the stage floor, and access to service the deck from underneath.", "practical_application": "A technician works in the stage basement to load a lift or set a trap, keeping the low, cramped space clear, well lit, and free of trip hazards.", "category": "Backstage Spaces", "related_terms": ["Trap", "Stage lift", "Understage", "Stage floor", "Gridiron", "Deck"], "common_mistakes": ["Confusing the stage basement with general backstage storage; it is the machinery space under the stage deck", "UNSAFE: Standing under a trap or lift opening while it is in use, risking being struck or crushed by a moving platform or falling object", "Assuming every stage has a basement; many stages sit on a solid floor with no usable space below"], "scenario_contexts": ["A crew loads a set piece onto a lift in the stage basement to raise it through a trap", "A technician routes cabling and machinery controls through the stage basement below the deck", "An effects operator waits in the stage basement to send a performer up through a trap on cue"]}, "994b91c7-b3d4-4da9-9ee4-ec092c9e0a1e": {"definition": "The exterior entrance used by performers, crew, and staff to reach the backstage areas of a theatre, kept separate from the public front-of-house entrances. It is typically located away from the audience lobby and controlled by a stage doorkeeper.", "plain_english": "It is the back entrance to a theatre for the cast and crew. The public uses the front doors instead. A doorkeeper often watches who comes in and out.", "purpose_function": "It gives cast and crew private, controlled access to backstage spaces, keeping their movements separate from the audience and helping the venue manage security.", "practical_application": "A technician signs in at the stage door on arrival, carries small gear through it, and follows the venue's sign-in and security rules there.", "category": "Backstage Spaces", "related_terms": ["Backstage", "Green room", "Loading dock", "Dressing room", "Stage house"], "common_mistakes": ["Confusing the stage door with the loading dock; the stage door is for people, while the dock is for scenery and equipment", "Assuming the stage door is a public entrance; it is a controlled crew and cast entrance", "Propping the stage door open, which defeats the venue's access control and security"], "scenario_contexts": ["A crew member signs in at the stage door before a load-in", "Fans wait at the stage door after a show hoping to meet the cast", "A doorkeeper checks credentials at the stage door before allowing entry"]}, "6919289f-d952-4605-911a-500819befe3b": {"definition": "A temporary or permanent platform that enlarges the playing area beyond the normal stage edge, commonly built out over the orchestra pit or into the house. It increases the downstage or thrust acting space for a particular production.", "plain_english": "It is an add-on that makes the stage bigger at the front. Crews often build it out over the orchestra pit. This gives performers more room closer to the crowd.", "purpose_function": "It gives a production extra playing space toward the audience, letting performers work closer to the house or covering an unused pit to widen the acting area.", "practical_application": "A crew decks over the orchestra pit to build a stage extension, then checks it is level, load-rated, and has its edge clearly marked.", "category": "Stage Architecture", "related_terms": ["Apron", "Thrust stage", "Orchestra pit", "Forestage", "Deck", "Stage floor"], "common_mistakes": ["UNSAFE: Building a stage extension over a pit without a properly load-rated, secured support structure, risking collapse under performers", "UNSAFE: Leaving the extension edge unmarked above the pit or house floor, creating a fall hazard", "Confusing a fixed apron with a stage extension, which is an added platform beyond the normal stage edge"], "scenario_contexts": ["A touring musical decks over the orchestra pit to build a stage extension for a bigger downstage area", "A concert adds a stage extension into the house to bring the artist closer to the front rows", "A crew load-tests and marks a new stage extension before performers rehearse on it"]}, "01ed7a9c-6847-4a5b-84f1-05c11f1fd8f4": {"definition": "The horizontal working surface of the stage on which performers move and scenery stands. Traditionally a sprung wooden floor able to accept traps, screws, and scenery fixings, it is often overlaid with a temporary deck for a particular production.", "plain_english": "It is the floor of the stage that people perform on. It is usually made of wood so crews can screw scenery into it. A special floor is often laid on top for a show.", "purpose_function": "It provides a flat, level, load-bearing surface for performers, scenery, and machinery, and its wood build lets crews fix scenery to it and cut traps into it.", "practical_application": "A technician checks the stage floor is level, sound, and free of gaps, and confirms it can take the load and the screws or fixings a set needs.", "category": "Stage Structure", "related_terms": ["Deck", "Stage apron", "Trap", "Stage basement", "Spike mark", "Rake"], "common_mistakes": ["UNSAFE: Leaving gaps, lifted boards, or loose panels in the stage floor, creating trip and fall hazards", "Screwing or cutting into a finished or historic stage floor without permission, causing costly damage", "Assuming every stage floor is flat; some are raked, sloping up away from the audience"], "scenario_contexts": ["A carpenter lays a temporary dance floor over the stage floor for a performance", "A stage manager spikes furniture positions onto the stage floor during a technical rehearsal", "A crew inspects the stage floor for damage and trip hazards before doors open"]}, "b3d49bbb-18f3-43b8-ba43-eeb827c12303": {"definition": "The part of a theatre building that encloses the stage, including the wings and the fly tower or loft above, extending from the stage floor up to the gridiron. In proscenium theatres it is usually much taller than the stage opening so scenery can fly out of sight, and it is structurally separated from the auditorium.", "plain_english": "It is the tall part of the building that holds the stage. It rises high above the stage so scenery can be lifted out of view. It sits apart from the seating area.", "purpose_function": "It provides the height and volume needed to fly scenery and lighting above the stage, plus the offstage wing space, while separating the stage from the audience area.", "practical_application": "A technician uses the stage house height to fly backdrops and lighting out of sight, and inspects the grid and fly-system rigging at the top of it.", "category": "Stage Architecture", "related_terms": ["Fly tower", "Gridiron", "Proscenium", "Wing", "Fly system", "Auditorium"], "common_mistakes": ["Confusing the stage house with the auditorium; the stage house encloses the stage, not the seats", "Assuming every venue has a full stage house with a fly tower; many stages have low or no fly space", "Using the term only for the stage floor, when it means the whole stage enclosure up to the grid"], "scenario_contexts": ["A rigger works at the top of the stage house to hang points from the gridiron", "A designer checks the stage house height to confirm a backdrop can fly fully out of sight", "A fire curtain drops to seal the stage house opening from the auditorium in an emergency"]}, "64e80188-9cfe-4ac0-a3ab-4c71322fd44b": {"definition": "The side of the stage to the performer's left when facing the audience. Stage directions are given from the performer's viewpoint, so stage left is on the audience's right-hand side.", "plain_english": "It is the left side of the stage from the actor's point of view, while they face the crowd. From a seat, that side is on your right.", "purpose_function": "It names one side of the stage from a fixed viewpoint, so directors, performers, and crew all mean the same side when giving directions and cues.", "practical_application": "A stage manager calls an entrance from stage left, and the actor enters from the performer's left even though it looks like the right from the seats.", "category": "Stage Directions", "related_terms": ["Stage right", "Downstage left", "Upstage left", "Wing", "Center stage"], "common_mistakes": ["Judging stage left from the audience's seats instead of the performer's viewpoint, which reverses left and right", "Confusing stage left with house left; house left is named from the audience's side and is the opposite side"], "scenario_contexts": ["A director blocks an exit to stage left toward the wing on the performer's left", "A crew member sets a prop table just offstage of stage left for a quick pickup", "A stage manager cues a lighting effect on the stage-left side of the acting area"]}, "1404ce3d-8c6d-492e-8a06-369b0bbdba9e": {"definition": "A powered platform forming a section of the stage floor that can be raised or lowered to change level, reveal scenery, or move performers and set pieces between the stage deck and the space below. It is also known as an elevator stage or stage elevator.", "plain_english": "It is a part of the stage floor that moves up and down like an elevator. Crews use it to lift scenery or performers into view from below.", "purpose_function": "It changes stage levels and moves heavy scenery or performers vertically, so a production can make fast reveals and scene changes without carrying items on and off.", "practical_application": "A technician loads a set piece onto the stage lift below the deck, checks the load and the clear zone, then raises it into position on cue.", "category": "Stage Machinery", "related_terms": ["Elevator stage", "Trap", "Orchestra pit lift", "Understage", "Deck", "Stage basement"], "common_mistakes": ["UNSAFE: Standing at or reaching into the edge of a moving stage lift, where a person can be caught in the shear point between the platform and the fixed floor", "UNSAFE: Loading the lift beyond its rated capacity, risking mechanical failure or a dropped load", "Confusing a stage lift, which changes height, with a revolve, which turns on the same level"], "scenario_contexts": ["An opera house raises a full set from the understage on a stage lift during a blackout", "A concert venue uses a stage lift to bring a drum riser up to deck level between acts", "A crew lowers the stage lift to load scenery below before a reveal"]}, "2dea2411-c760-4c22-92d4-a91e3a2508c8": {"definition": "The fixed position from which the stage manager runs the performance, usually located in the wings with a clear view of the stage. It carries the show communications and control gear, typically a headset intercom, cue-light controls, a paging and program microphone, production and video monitors, and a production clock. In UK usage it is often called the prompt corner or prompt desk.", "plain_english": "It is the spot where the stage manager runs the show. It has a headset, cue lights, and screens to watch the stage. From here the stage manager calls every cue.", "purpose_function": "It gives the stage manager one place with the sightlines and communications needed to call cues and coordinate cast and crew throughout the performance.", "practical_application": "A stage manager stands at the station on headset, watching monitors and using cue lights to call lighting, sound, and fly cues in sequence.", "category": "Backstage Spaces", "related_terms": ["Prompt corner", "Cue light", "Intercom", "Wings", "Green room"], "common_mistakes": ["Confusing the stage manager station with the front-of-house control booth; the station is a backstage calling position, not the lighting or sound operator's booth", "Assuming the station is always at stage left; the prompt side varies by venue and country", "Blocking sightlines from the station with scenery or crew, so the stage manager cannot see the stage to call cues"], "scenario_contexts": ["A stage manager calls a show from the station using cue lights and a headset", "A crew sets up a portable stage manager station in the wings for a touring production", "A technician runs comms and cue-light lines to the stage manager station during setup"]}, "6e7509b2-50f7-4675-97a0-82a6647c594b": {"definition": "A metal box recessed flush into the stage floor, usually with a hinged lid, that houses electrical power receptacles and often audio or communication connectors. Also called a floor pocket, it provides fixed connection points on the deck so equipment can be powered and patched without cables running across the stage from the wings.", "plain_english": "A stage pocket is a small box built into the stage floor. It holds power outlets and audio jacks under a lid. Crews plug gear into it, so cables do not run all the way across the stage.", "purpose_function": "It brings power and signal connections out to points on the stage floor, reducing long cable runs and trip hazards while keeping connectors protected and out of sight beneath a flush lid.", "practical_application": "A technician runs a stage monitor, powered speaker, or practical lamp from the nearest stage pocket, then closes the lid and tapes any cable exit to keep the deck safe to walk on.", "category": "Stage Structure", "related_terms": ["Deck", "Substage", "Snake", "Patch panel", "Stage box", "Cable ramp"], "common_mistakes": ["Assuming every stage pocket carries audio lines; many hold only electrical power, so confirm the connector type before patching", "Leaving the pocket lid open across a walking path, creating a trip and fall hazard on the deck", "UNSAFE: Plugging high-current gear into a pocket without checking its circuit rating, which can overload the branch circuit"], "scenario_contexts": ["A sound technician powers an onstage monitor from a stage pocket to avoid trailing a cable from the wings", "A crew patches a downstage microphone line into an audio floor pocket during setup", "An electrician traces which breaker feeds a stage pocket before connecting a heavy lighting practical"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"0b72dc52-eeeb-4af3-a2ff-7b8e68e50076": {"definition": "The side of the stage to the performer's right when the performer stands facing the audience. Because it is defined from the performer's viewpoint, stage right corresponds to the audience's left-hand side.", "plain_english": "Stage right is the actor's right side as they face the crowd. From a seat in the audience, that same side is on your left.", "purpose_function": "It gives a fixed, performer-based reference for one side of the stage, so directors, actors, and crew describe positions and moves the same way regardless of where they stand.", "practical_application": "A stage manager notes an entrance from stage right, and the performer enters from their own right side as they face the house.", "category": "Stage Directions", "related_terms": ["Stage left", "Downstage right", "Upstage right", "Stage-right wing", "Centerstage", "House"], "common_mistakes": ["Judging stage right from the audience's seats instead of the performer's viewpoint, which reverses left and right", "Assuming stage right is fixed to the building; it is always relative to a performer facing the audience"], "scenario_contexts": ["A director blocks a character to exit stage right into the wing on that side", "A follow-spot operator is told to pick up a performer entering from stage right"]}, "3dca08c6-f8f1-4440-aa4a-7b1b99928877": {"definition": "The offstage space at either side of the acting area, hidden from the audience by masking such as legs and borders. The wings are used for performer entrances and exits, waiting offstage, quick changes, and the temporary staging of scenery and equipment.", "plain_english": "The wings are the hidden side spaces next to the stage. Actors wait there and enter from there. The audience cannot see into them.", "purpose_function": "They provide concealed side areas for performers and crew to prepare, enter, exit, and store scenery, while masking keeps these spaces out of the audience's sightlines.", "practical_application": "A technician keeps clear, marked pathways in the wings and stages set pieces there so scene changes and entrances run without collisions in the dark.", "category": "Backstage Spaces", "related_terms": ["Leg", "Masking", "Offstage", "First wing", "Crossover", "Wing space"], "common_mistakes": ["Standing too far onstage in the wings and being seen by audience members seated to the sides", "UNSAFE: Blocking wing pathways with cases or cable, creating trip hazards where performers move in near-darkness"], "scenario_contexts": ["A stage manager sets a quick-change booth in the wing for a fast costume swap between scenes", "A crew stores a rolling set piece in the wing, ready to push on during a blackout"]}, "4770e38d-87c9-4188-9ea8-bfae441910d2": {"definition": "An audio operating or equipment location established on the stage-left side of the stage, typically holding a monitor console, stage patch, or amplifier and processing racks. It places the audio department's on-stage resources at that side, just out of the audience's sightlines behind the masking.", "plain_english": "This is the audio team's spot on the stage's left side. Crews may put a mixing desk or gear racks there. It sits just out of the audience's view.", "purpose_function": "It gives the sound crew a defined working position and connection point near the performers on the stage-left side, so monitors, patching, and stage gear can be run and reached quickly during a show.", "practical_application": "A monitor engineer sets up the monitor console at the stage-left audio position and patches the stage snake there so performers' foldback mixes come from that side.", "category": "Stage Positions", "related_terms": ["Stage left", "Stage-left wing", "Monitor console", "Stage box", "Stage pocket", "Front of house"], "common_mistakes": ["Confusing the stage-left audio position with front of house; front of house sits out in the audience, not at the side of the stage", "Judging the stage-left side from the audience's viewpoint instead of the performer's, placing the position on the wrong side"], "scenario_contexts": ["A monitor engineer works the show from the stage-left audio position beside the wing", "A crew locates the stage patch and amp racks at the stage-left audio position during load-in"]}, "9b3371fc-4336-4f34-a035-7fd6b67d3202": {"definition": "The offstage wing space on the performer's left side of the stage, hidden from the audience by masking. Because sides are named from the performer's viewpoint, the stage-left wing lies on the audience's right-hand side and is used for entrances, exits, and offstage staging on that side.", "plain_english": "This is the hidden side space on the actor's left as they face the crowd. Actors enter and exit from here. It is on the audience's right side.", "purpose_function": "It provides the concealed offstage area and entrances on the stage-left side, letting performers and crew wait, enter, exit, and stage scenery without being seen by the audience.", "practical_application": "A stage manager cues an actor waiting in the stage-left wing to enter, and stores props on a table there for pickups on that side.", "category": "Backstage Spaces", "related_terms": ["Stage left", "Stage wing", "Stage-right wing", "Masking", "Offstage", "Crossover"], "common_mistakes": ["Judging the stage-left wing from the audience's viewpoint, which puts it on the wrong side of the stage", "UNSAFE: Cluttering the stage-left wing with cases or loose cable, creating trip hazards where performers move in the dark"], "scenario_contexts": ["A dancer waits in the stage-left wing for an entrance onto the performer's left side", "A crew stages a rolling flat in the stage-left wing to push on during a scene change"]}, "a50e5774-1bbb-4d22-aa3d-9aa857f8adf3": {"definition": "The location from which the stage manager runs the performance, usually at the side of the stage (the prompt corner) or in a control booth. It is equipped with the prompt book, headset communications, cue lights, production monitors, and paging so the stage manager can call the show's cues.", "plain_english": "This is the spot where the stage manager runs the show. From here they call cues over a headset. It is usually at the side of the stage or in a booth.", "purpose_function": "It centralizes the tools the stage manager needs to coordinate a performance, so all lighting, sound, fly, and actor cues can be called and timed from one controlled point.", "practical_application": "A stage manager stands at the stage-management position with the prompt book and headset, watching the stage and calling standby and go cues to each department.", "category": "Stage Positions", "related_terms": ["Prompt corner", "Cue light", "Prompt book", "Headset", "Control booth", "Stage manager"], "common_mistakes": ["Assuming the stage-management position is always in a booth; it is often at the side of the stage in the prompt corner", "Placing the position where the stage manager cannot see the acting area, making it hard to call visual cues accurately"], "scenario_contexts": ["A stage manager calls a complex scene change from the stage-management position over the headset", "A crew wires cue lights and a monitor feed to the stage-management position during setup"]}, "bda12152-d9a5-4153-8410-35e2bbdebf02": {"definition": "The offstage wing space on the performer's right side of the stage, hidden from the audience by masking. Because sides are named from the performer's viewpoint, the stage-right wing lies on the audience's left-hand side and is used for entrances, exits, and offstage staging on that side.", "plain_english": "This is the hidden side space on the actor's right as they face the crowd. Actors enter and exit from here. It is on the audience's left side.", "purpose_function": "It provides the concealed offstage area and entrances on the stage-right side, letting performers and crew wait, enter, exit, and stage scenery without being seen by the audience.", "practical_application": "A stage manager cues an actor waiting in the stage-right wing to enter, and keeps a prop table there for pickups on that side.", "category": "Backstage Spaces", "related_terms": ["Stage right", "Stage wing", "Stage-left wing", "Masking", "Offstage", "Crossover"], "common_mistakes": ["Judging the stage-right wing from the audience's viewpoint, which puts it on the wrong side of the stage", "UNSAFE: Cluttering the stage-right wing with cases or loose cable, creating trip hazards where performers move in the dark"], "scenario_contexts": ["An actor waits in the stage-right wing for an entrance onto the performer's right side", "A crew stages a set piece in the stage-right wing to bring on during a blackout"]}, "7c6339db-93e1-4e10-9dd8-24963ebd4cb7": {"definition": "The area located directly beneath the stage floor. In equipped theatres it houses trap mechanisms, lifts, elevators, and stage machinery, and provides access and space for effects that rise through or drop below the deck.", "plain_english": "The substage is the space under the stage floor. It holds lifts, traps, and machines. Trap doors let actors or props rise up through the floor.", "purpose_function": "It gives room below the deck for machinery, lifts, and trap effects, so scenery and performers can appear or disappear through the stage floor and equipment can be worked from underneath.", "practical_application": "A technician rigs a trap lift in the substage and checks clearances there so a performer can rise smoothly through the stage floor on cue.", "category": "Stage Structure", "related_terms": ["Trap", "Deck", "Stage lift", "Grid", "Understage", "Stage machinery"], "common_mistakes": ["Confusing the substage with the orchestra pit; the substage is beneath the deck, while the pit sits in front of it below the audience level", "UNSAFE: Working under an open trap in the substage without guarding the opening above, risking a fall from the stage level"], "scenario_contexts": ["A crew installs and tests a trap-door lift in the substage before a magic or ghost effect", "A technician runs cabling and machinery access through the substage during a fit-up"]}, "2515fcee-e71b-498f-b930-5a97a7ed9175": {"definition": "The third offstage wing position on either side of the stage, counting from downstage toward upstage. Wing positions are numbered from the proscenium back, so the third wing is the third masking-and-entrance gap upstage of the audience on that side.", "plain_english": "The wings are hidden side spaces along the stage. The third wing is the third one back from the front. Actors use it to enter further upstage.", "purpose_function": "It names a specific offstage entrance and masking position, so blocking, entrances, and scenery placement can be located precisely along the depth of the stage.", "practical_application": "A stage manager cues an actor to enter through the third wing, and the performer comes on well upstage of the proscenium on that side.", "category": "Backstage Spaces", "related_terms": ["First wing", "Stage wing", "Leg", "Masking", "Offstage", "Upstage"], "common_mistakes": ["Counting wings from upstage; wing positions are numbered from downstage, so the third wing is farther upstage than the first", "Confusing the wing number with the leg number when masking and entrances do not line up one to one"], "scenario_contexts": ["A director blocks an entrance from the third wing so a character appears upstage during a scene", "A crew sets a masking leg at the third wing to hide the offstage space at that depth"]}, "5186b4aa-a836-41bc-9cda-ffb31b173881": {"definition": "A stage configuration in which the acting area projects out into the auditorium so that the audience is seated on three sides of it, with the fourth (upstage) side backing onto a scenic wall, backstage, or proscenium. It combines a projecting platform with a rear stage house.", "plain_english": "A thrust stage pushes out into the crowd. The audience sits on three sides of it. Only the back of the stage faces a wall or backdrop.", "purpose_function": "It brings performers much closer to the audience and surrounds them on three sides, creating an intimate, in-the-round feel while still allowing scenery and entrances at the rear.", "practical_application": "A technician plans sightlines, low-profile lighting, and floor-level cabling carefully because the audience can see the stage from three directions and there are few wings to hide gear.", "category": "Stage Configuration", "related_terms": ["Arena stage", "Proscenium", "Apron", "End stage", "Downstage", "Upstage"], "common_mistakes": ["Confusing a thrust stage with an arena (in-the-round) stage; a thrust seats the audience on only three sides, while an arena surrounds the stage on all four", "Treating the deep apron of a proscenium theatre as a thrust; a true thrust has audience seating flanking its sides", "UNSAFE: Leaving unmarked or unlit platform edges on a thrust, where performers can step off into the audience or onto steps"], "scenario_contexts": ["A company stages a Shakespeare production on a thrust to place actors in the middle of the audience", "A lighting designer rigs side and front-of-house positions to cover a thrust evenly from three viewing directions", "Crew rehearse entrances through vomitories or the upstage wall because the thrust has limited wing space"]}, "b942042f-6722-4910-85c4-3e7dfa2c96f3": {"definition": "An opening built into the stage floor, normally closed by a removable or hinged section, through which performers, scenery, props, or effects can pass between the stage surface and the space directly beneath it. Types include the grave trap, corner trap, and various lift or star traps.", "plain_english": "A trap is an opening in the stage floor. A cover hides it until it is needed. Actors, scenery, or effects can move through it from below.", "purpose_function": "It lets people and objects appear, disappear, or be raised and lowered through the stage floor, enabling sudden entrances, exits, and special effects that would be impossible from the wings.", "practical_application": "A technician confirms a trap's cover, guardrails, and lift are secure and load-rated before a show, and coordinates cues so nothing crosses an open trap unexpectedly.", "category": "Stage Structure", "related_terms": ["Trap door", "Trap room", "Understage", "Deck", "Elevator stage", "Grave trap"], "common_mistakes": ["Using 'trap' and 'trap door' interchangeably; the trap is the opening in the floor, while the trap door is the cover that closes it", "Assuming every stage has traps; many stages have a solid deck with no trap openings at all", "UNSAFE: Leaving a trap open and unguarded or unlit backstage, creating a fall hazard for performers and crew"], "scenario_contexts": ["A ghost rises slowly through a grave trap during a scene change", "Crew lower a large prop through a trap into the understage rather than carrying it off through the wings", "A stage manager calls a warning cue before a trap opens so nearby performers stay clear of the edge"]}, "8db30827-d81b-4390-bd1a-f4c28cda5afe": {"definition": "The hinged or removable section of stage floor that covers a trap, forming part of the walking surface when closed and opening to allow passage between the stage and the understage below. It may be operated by hand or as part of a mechanized lift.", "plain_english": "A trap door is the lid that covers a trap. It is a piece of the stage floor that can open. When it opens, someone or something can come up from below.", "purpose_function": "It seals the trap opening flush with the deck for safe walking, then opens on cue to permit entrances, exits, and effects through the stage floor.", "practical_application": "A technician checks that the trap door sits flush and latches securely, that hinges and supports carry the rated load, and that its edge is marked before performers work over it.", "category": "Stage Structure", "related_terms": ["Trap", "Trap room", "Understage", "Deck", "Grave trap", "Elevator stage"], "common_mistakes": ["Confusing the trap door with the trap itself; the door is the movable cover, while the trap is the opening it closes", "Assuming a closed trap door can always bear full stage loads; some are rated lighter than the surrounding deck", "UNSAFE: Standing or setting heavy pieces on a trap door that is unlatched or partly open, risking a sudden fall through the floor"], "scenario_contexts": ["An actor drops out of sight through a trap door for a magical disappearance", "Crew latch every trap door flush before a dance number to protect performers moving quickly across the deck", "A stage manager checks that the trap door is closed and secured before allowing anyone to cross that part of the stage"]}, "95d7200e-9c0f-4bd4-aa05-d844a38eb684": {"definition": "The working space directly beneath the stage floor where traps, lifts, and related machinery are operated, and from which performers and scenery are moved up through traps to the stage. It is part of, or synonymous with, the understage or stage cellar.", "plain_english": "The trap room is the space right under the stage. Crew work there to run traps and lifts. It sits below the floor the actors stand on.", "purpose_function": "It houses the mechanisms and gives crew and performers a place to wait, operate traps, and prepare entrances and effects that come up through the stage floor.", "practical_application": "A technician keeps the trap room clear, well lit, and organized so crew can safely stage performers and equipment for cues that rise through the traps above.", "category": "Backstage Spaces", "related_terms": ["Trap", "Trap door", "Understage", "Understage area", "Deck", "Elevator stage"], "common_mistakes": ["Treating the trap room as mere storage; it is an active working area for trap and lift operation during performances", "Confusing the trap room with the orchestra pit; the trap room lies under the stage, not under the front edge for musicians", "UNSAFE: Working in a cluttered or poorly lit trap room beneath open traps, where falling objects or trip hazards can cause injury"], "scenario_contexts": ["Crew wait in the trap room to help an actor onto a lift before it rises through a trap", "A technician routes power and control lines through the trap room to run an understage elevator", "Performers gather in the trap room before making a surprise entrance up through the stage floor"]}, "4f790ec6-1cc6-4f57-8419-e9b980c6dcbd": {"definition": "The space beneath the stage floor, also called the substage or stage cellar, used for traps, lifts, machinery, storage, and performer or scenery movement out of the audience's view. Its depth and access depend on the theatre's design.", "plain_english": "Understage means the space beneath the stage floor. Crew use it for storage, machines, and traps. The audience never sees it.", "purpose_function": "It provides room below the deck for trap and lift mechanisms, hidden crossovers, and storage, expanding what a production can do without cluttering the visible stage.", "practical_application": "A technician stores gear, runs cabling, and stages trap or lift moves in the understage, keeping walkways clear and edges guarded beneath any open trap.", "category": "Backstage Spaces", "related_terms": ["Understage area", "Trap", "Trap room", "Trap door", "Deck", "Elevator stage"], "common_mistakes": ["Assuming every stage has a usable understage; on a ground-level or platform stage there may be little or no space below the deck", "Confusing the understage with the fly loft; the understage is below the stage floor, while the fly loft is high above it", "UNSAFE: Moving through an understage in darkness or beneath an unguarded open trap, risking falls or head injuries on low framing"], "scenario_contexts": ["Crew run a hidden crossover through the understage so actors reach the far side of the stage unseen", "A production installs a lift in the understage to raise scenery through a trap", "A technician clears and lights the understage before a show so crew can work traps safely"]}, "afc70f25-c309-415c-bfaa-7a101de096f0": {"definition": "The area beneath the stage deck used for machinery, traps, lifts, storage, and concealed movement of performers and scenery; it is the general term for the usable space of the understage or stage cellar. Its access, height, and layout are set by the building's design.", "plain_english": "The understage area is the room below the stage floor. It holds machines, storage, and trap gear. Actors and crew can also move through it out of sight.", "purpose_function": "It gives a production hidden working and storage space below the deck, supporting traps, lifts, crossovers, and effects without taking up room on the visible stage.", "practical_application": "A technician organizes storage, cable runs, and staging positions in the understage area so crew can prepare cues and cross beneath the stage safely.", "category": "Backstage Spaces", "related_terms": ["Understage", "Trap room", "Trap", "Trap door", "Deck", "Upstage crossover"], "common_mistakes": ["Assuming the understage area is always tall enough to stand and work in; clearance varies and can be very low in some theatres", "Using it only as dead storage and blocking the paths crew need for crossovers and trap work", "UNSAFE: Leaving trip hazards, unmarked steps, or open traps in a dim understage area where crew move quickly during shows"], "scenario_contexts": ["Crew store set pieces and scene-change trucks in the understage area between acts", "Performers pass through the understage area to reach an entrance on the opposite side of the stage", "A technician surveys the understage area's height and access before planning a trap or lift effect"]}, "73ca62c6-db8a-4257-a693-71f31b089300": {"definition": "The stage position at the horizontal center of the stage and at its rear, farthest from the audience, where the upstage line meets the centerline. It is one of the nine standard acting areas used to give blocking directions, often abbreviated UC or USC.", "plain_english": "Upstage center is the middle of the stage, at the back. It is the spot farthest from the audience. 'Upstage' means away from the crowd.", "purpose_function": "It gives directors, performers, and crew a shared, precise name for the rear-center acting area so blocking, scenery, and lighting can be placed and repeated consistently.", "practical_application": "A technician uses upstage center as a reference to position backdrops, focus lights, or set the spike marks that tell performers exactly where to stand at the rear center of the stage.", "category": "Stage Positions", "related_terms": ["Center stage", "Upstage", "Downstage center", "Stage left", "Stage right", "Upstage crossover"], "common_mistakes": ["Thinking 'upstage' means the audience's side or a raised area; it means the part of the stage farthest from the audience, a term from old raked stages that sloped up toward the back", "Reversing upstage and downstage, or left and right, which are given from the performer's point of view facing the audience", "Placing a spike or set piece at true center instead of the rear centerline meant by upstage center"], "scenario_contexts": ["A director blocks a chorus to enter and line up at upstage center behind the lead", "A lighting designer focuses a special on upstage center for an entrance at the back of the stage", "Crew place a spike mark at upstage center so a large set piece lands in the same spot each night"]}, "b2f02838-9b46-42c6-94e8-954ad6a8bea7": {"definition": "A placement of a choir or vocal ensemble at the upstage area of the stage, farthest from the audience and behind the main downstage action, typically on risers so singers are visible and grouped together. The location trades vocal immediacy for an unobstructed downstage playing area.", "plain_english": "This is where a choir stands at the back of the stage. It is far from the audience, behind the main action. Singers group there so they do not block the front.", "purpose_function": "It keeps a large group of singers together and out of the way of the principal action downstage, while risers help their sound and sightlines reach the audience over the front performers.", "practical_application": "A sound technician places choir microphones and monitors for an upstage group, allowing for the extra distance to the audience and the risk of picking up the band or downstage vocalists.", "category": "Stage Positions", "related_terms": ["Upstage", "Upstage center", "Riser", "Center stage", "Downstage", "Upstage crossover"], "common_mistakes": ["Assuming an upstage choir needs the same mic and monitor setup as downstage soloists, despite the greater distance to the audience", "Forgetting that an upstage choir behind a band can be masked in the mix or bleed into the drum and instrument mics", "UNSAFE: Crowding singers onto poorly guarded upstage risers, where a misstep off the back or edge can cause a fall"], "scenario_contexts": ["A worship band places its choir in an upstage position on risers behind the lead vocalists", "A musical seats its ensemble at an upstage choir position so the downstage area stays clear for principals", "A sound engineer adds delay and gain for upstage choir mics to balance them against closer performers"]}, "11bd6705-a615-4d90-8fa3-17405d46496c": {"definition": "A concealed route across the rear (upstage) of the stage that lets performers and crew pass from one side to the other without being seen by the audience. It may run behind the backdrop or upstage wall, or through an offstage corridor or the understage.", "plain_english": "A crossover is a hidden path across the back of the stage. Actors use it to get from one side to the other. The audience cannot see them use it.", "purpose_function": "It allows entrances and quick changes on the opposite side of the stage from an exit, without a performer walking across in view of the audience or disturbing the scene.", "practical_application": "A technician keeps the upstage crossover clear, taped, and dimly lit with running lights, and routes cables safely so performers can move fast in the dark without tripping.", "category": "Backstage Spaces", "related_terms": ["Upstage", "Backstage", "Understage", "Wings", "Upstage center", "Running lights"], "common_mistakes": ["Confusing the crossover with the wings; the crossover is the connecting path between the two sides, not the offstage space beside the acting area", "Blocking the crossover with stored scenery or cable, forcing performers to cross in view of the audience", "UNSAFE: Leaving the crossover cluttered or unlit, so performers trip or fall while moving through it in the dark during a show"], "scenario_contexts": ["An actor exits stage right and uses the upstage crossover to make an entrance from stage left", "Crew keep the crossover clear and marked with glow tape before a fast-paced show", "A stage manager checks the upstage crossover for hazards during the preshow safety walk"]}, "cd67aed1-6af4-4344-bdfb-c625beb363d3": {"definition": "The area of the acting space that is both away from the audience (toward the rear of the stage) and to the performer's left as they face the audience. Abbreviated UL, it lies in the rear-left quadrant from the actor's viewpoint, which corresponds to the audience's rear-right.", "plain_english": "This is a spot near the back of the stage. It is on the actor's left side as they look out at the crowd. From the audience's seats, it is toward the back on their right.", "purpose_function": "It gives directors and crew a shared, unambiguous name for one corner of the stage so blocking, set placement, and cues can be recorded and repeated exactly.", "practical_application": "A technician uses upstage left to spike scenery, aim a light, or note where a performer stands, always reading left and right from the actor's point of view, not the audience's.", "category": "Stage Directions", "related_terms": ["Upstage right", "Downstage left", "Stage left", "Upstage", "Center stage", "Stage directions"], "common_mistakes": ["Reading left from the audience's seats instead of from the performer facing the audience; stage left is always the actor's left", "Confusing upstage (away from the audience) with downstage (toward the audience)", "Assuming upstage means physically higher, forgetting the term comes from old raked stages that sloped up toward the back"], "scenario_contexts": ["A director tells an actor to cross and stand upstage left for a scene, and the stage manager records it in the prompt book", "A lighting technician focuses a fixture to cover the upstage-left corner of the acting area", "A stagehand spikes the floor upstage left so a rolling set piece lands in the same place every night"]}, "fd9ae88c-f850-487d-870b-8350532b58d1": {"definition": "The area of the acting space that is both away from the audience (toward the rear of the stage) and to the performer's right as they face the audience. Abbreviated UR, it lies in the rear-right quadrant from the actor's viewpoint, which corresponds to the audience's rear-left.", "plain_english": "This is a spot near the back of the stage. It is on the actor's right side as they look out at the crowd. From the audience's seats, it is toward the back on their left.", "purpose_function": "It gives directors and crew a shared, unambiguous name for one corner of the stage so blocking, set placement, and cues can be recorded and repeated exactly.", "practical_application": "A technician uses upstage right to spike scenery, aim a light, or note where a performer stands, always reading left and right from the actor's point of view, not the audience's.", "category": "Stage Directions", "related_terms": ["Upstage left", "Downstage right", "Stage right", "Upstage", "Center stage", "Stage directions"], "common_mistakes": ["Reading right from the audience's seats instead of from the performer facing the audience; stage right is always the actor's right", "Confusing upstage (away from the audience) with downstage (toward the audience)", "Assuming upstage means physically higher, forgetting the term comes from old raked stages that sloped up toward the back"], "scenario_contexts": ["A director tells an actor to enter and move upstage right, and the stage manager records it in the prompt book", "A lighting technician focuses a fixture to cover the upstage-right corner of the acting area", "A stagehand spikes the floor upstage right so a set piece is reset to the same mark for every performance"]}, "d2d7c3c0-e781-4b19-93b3-546a447fc82f": {"definition": "A scene-change system built around wagons, which are large low platforms mounted on casters that carry scenery or a whole set and roll on and off the acting area. Wagons may be stored on side stages or a rear stage and moved into position for rapid changes; a full wagon-stage installation uses platforms sized to fill the stage.", "plain_english": "A wagon is a big rolling platform on wheels that holds a set. Crew build a scene on it offstage, then roll the whole thing into view. This lets a show swap large sets quickly and quietly.", "purpose_function": "It exists to change bulky scenery fast and smoothly by moving prebuilt units as a single rolling unit, cutting long, noisy changeovers and reducing manual carrying.", "practical_application": "A technician builds a set on a wagon in the wings or rear stage, checks its casters and brakes, then rolls or drives it to its spiked position on cue during a scene change.", "category": "Stage Machinery", "related_terms": ["Wagon", "Deck", "Revolve", "Elevator stage", "Wing space", "Scene shift"], "common_mistakes": ["Confusing a wagon with a revolve; a wagon rolls in and out in a straight path while a revolve turns on a pivot", "Forgetting to spike the wagon's landing position, so the set lands off its marks and out of the lighting", "UNSAFE: Rolling a loaded wagon without setting its brakes at the stop or without spotters, letting a heavy platform drift into people or off the stage edge"], "scenario_contexts": ["A musical uses wagons pre-set with room interiors that roll on from the wings for instant location changes", "A crew stores a fully dressed set on a rear-stage wagon and rolls it downstage during a blackout", "A technician inspects wagon casters, decking, and brakes before a performance to ensure smooth, safe travel"]}, "b48c19f0-5a89-44fa-8bde-f130f37f1bc3": {"definition": "The offstage space at either side of the acting area, hidden from the audience's sightlines, where performers wait to enter and scenery, props, and crew are held. The term also names the masking flats or drapes (legs) set at the sides that conceal that space.", "plain_english": "The wings are the hidden side areas just off the stage. Actors wait there to go on, and crew keep props and scenery there. The audience cannot see into the wings.", "purpose_function": "Wings give performers a concealed place to enter and exit and give crew room to store and handle scenery, while masking keeps all of it out of the audience's view.", "practical_application": "A technician stages props and set pieces in the wings, keeps clear entry and exit lanes, and runs cabling and running lights there so people can move safely in the dark.", "category": "Backstage Spaces", "related_terms": ["Wing space", "Wing entrance", "Leg", "Masking", "Backstage", "Crossover"], "common_mistakes": ["Confusing the wing (the offstage side space) with a leg (the specific masking drape that hides it)", "Cluttering the wings with gear so performers and crew have no clear path to enter or exit", "UNSAFE: Leaving the wings dark and blocked with cables or set pieces, creating trip and fall hazards during fast entrances and exits"], "scenario_contexts": ["Actors line up in the wings just before their entrance while the stage manager gives the go cue", "A stagehand pre-sets a prop table in the wings so props are grabbed quickly during the show", "A crew hangs legs to mask the wings and hide waiting performers and stored scenery"]}, "6dd0b2c5-d868-4c46-ba55-ef7c76bb3e78": {"definition": "An entrance made by a performer coming onto the stage from the wings, the offstage side space, rather than through a door or opening built into the scenery. It is the point or act of stepping into the audience's view from either side of the acting area.", "plain_english": "A wing entrance is when an actor walks onstage from the hidden side area. They come in from the side, not through a set door. It is one of the most common ways to get onstage.", "purpose_function": "It lets performers appear from the sides of the acting area, giving directors flexible entry points that do not depend on doors or openings in the set.", "practical_application": "A technician keeps the wing entrance path clear and lit with running lights, spikes the offstage edge, and stations crew so performers can find their mark and enter on cue in the dark.", "category": "Entrances and Exits", "related_terms": ["Wing exit", "Wing", "Wing space", "Crossover", "Sightline", "Blocking"], "common_mistakes": ["Standing too close to the masking before an entrance and becoming visible to part of the audience through a sightline gap", "Blocking the entrance lane with props or cable so the performer cannot enter cleanly on cue", "UNSAFE: Rushing a dark wing entrance over untaped cables or unmarked set edges, risking a trip or fall on the way onstage"], "scenario_contexts": ["An actor makes a wing entrance from stage left on the stage manager's go cue", "A dancer enters from the wings at speed, so crew keep the lane clear and the offstage edge marked", "A director changes a character's entrance from a set door to a wing entrance to speed up a scene"]}, "08706651-0883-48d5-a09a-18a0a9f1e921": {"definition": "An exit in which a performer leaves the stage by moving off into the wings, the offstage side space, rather than through a door or opening built into the scenery. It is the point or act of leaving the audience's view at either side of the acting area.", "plain_english": "A wing exit is when an actor walks off the stage into the hidden side area. They leave to the side, not through a set door. It is one of the most common ways to get offstage.", "purpose_function": "It lets performers leave the acting area at the sides, giving directors flexible exit points that do not rely on doors or openings in the set.", "practical_application": "A technician keeps the wing exit path clear and lit with running lights and stations crew nearby to receive props or costumes and guide performers safely offstage in the dark.", "category": "Entrances and Exits", "related_terms": ["Wing entrance", "Wing", "Wing space", "Crossover", "Sightline", "Blocking"], "common_mistakes": ["Stopping just inside the masking after an exit while still visible through a sightline gap to some seats", "Leaving the exit lane blocked so a performer cannot clear the stage in time for the next cue", "UNSAFE: Exiting fast into a dark, cluttered wing with untaped cables or unmarked edges, risking a trip or fall offstage"], "scenario_contexts": ["An actor makes a quick wing exit stage right to reach a costume change in time", "Crew wait at the wing exit to take a hand prop from a performer as they come offstage", "A director stages a wing exit instead of a door exit so the scene flows straight into the next"]}, "9f7e3fdb-ef10-41ec-8083-44e871532453": {"definition": "The amount of usable offstage area at the sides of the acting space, measured beyond the masking, available for performers to wait, for scenery and equipment to be held, and for crew to work and move scenery on and off. Adequate wing space is a key factor in theatre design and in planning scene changes.", "plain_english": "Wing space is how much room there is in the hidden side areas off the stage. Crew need it to store scenery and move it on and off. A stage with tight wings makes big scene changes hard.", "purpose_function": "It provides the offstage room needed to stage waiting performers, store scenery and gear, and shift set pieces, so a production can be run smoothly and safely.", "practical_application": "A technician measures the available wing space when planning where to park wagons, prop tables, and stored flats, and to confirm large scenery can clear the stage on a change.", "category": "Backstage Spaces", "related_terms": ["Wing", "Wing storage", "Crossover", "Masking", "Wagon stage", "Sightline"], "common_mistakes": ["Overloading limited wing space so there is no clear path for performers or scenery movement", "Forgetting to allow enough wing space to fully clear a large set piece out of the audience's sightlines", "UNSAFE: Packing wing space so tightly that it blocks fire exits or emergency egress paths backstage"], "scenario_contexts": ["A designer checks the theatre's wing space before committing to large rolling scenery", "A stage manager plans prop tables and quick-change booths around the available wing space", "A touring crew adapts a set to a venue with shallow wing space by breaking scenery into smaller units"]}, "b0561312-11ea-447c-819f-48e6763baf6f": {"definition": "The use of the offstage wing space to hold scenery, props, and equipment during a performance, pre-set and organized so items can be moved on and off on cue. It refers both to the practice and to the area set aside for it at the sides of the stage.", "plain_english": "Wing storage means keeping scenery and props ready in the hidden side areas during a show. Everything is placed in order so crew can grab or roll it out on cue. It keeps changes fast and tidy.", "purpose_function": "It keeps the scenery and props needed during a show close at hand yet out of sight, so scene changes are quick and the acting area and paths stay clear.", "practical_application": "A technician lays out wing storage on a plan, spiking positions for wagons, flats, and prop tables so each item sits in a fixed, labeled spot and clear lanes remain for traffic.", "category": "Backstage Spaces", "related_terms": ["Wing space", "Wing", "Prop table", "Wagon stage", "Scene shift", "Backstage"], "common_mistakes": ["Storing items in the wings without spiking or labeling positions, so crew cannot find them in the dark", "Filling wing storage so full that performer entrances and exits are blocked", "UNSAFE: Stacking stored scenery unsecured or across egress paths, creating tip-over and blocked-exit hazards backstage"], "scenario_contexts": ["A crew pre-sets scenery and prop tables in wing storage before the house opens", "A stage manager assigns fixed wing-storage spots so every unit resets to the same place each night", "A technician reorganizes wing storage to keep fire exits and crossover paths clear"]}, "c5b81013-aa57-48d0-b90b-9a2785ea569e": {"definition": "Seating in an assembly space designed and located for patrons who use wheelchairs or have other disabilities, provided under accessibility law. Under the ADA 2010 Standards it includes wheelchair spaces with an adjoining companion seat, plus designated accessible aisle seats, dispersed horizontally and vertically through the house so these patrons have lines of sight and seating choices comparable to other spectators.", "plain_english": "Accessible seating is space set aside for people with disabilities. It fits a wheelchair and has a seat next to it for a companion. These spots are spread around the room so the view is as good as any other seat.", "purpose_function": "It ensures patrons with disabilities can enter, sit, and view the performance safely and with dignity, meeting legal accessibility requirements rather than being segregated at the edges of the house.", "practical_application": "A house manager or technician keeps wheelchair spaces clear and on an accessible route, and confirms that companion seats, sightlines, and egress paths are not blocked by cases, cable, or added chairs.", "category": "Seating & Accessibility", "related_terms": ["House", "Aisle", "Companion seat", "Wheelchair space", "Sightline", "Means of egress"], "common_mistakes": ["Treating accessible seating as a single token spot; the required number of wheelchair spaces scales with the venue's total seat count", "Placing all accessible spaces in one corner instead of dispersing them so patrons have comparable views and choices", "Assuming a companion seat is optional; each required wheelchair space must have an adjoining companion seat", "UNSAFE: Blocking a wheelchair space or its accessible route with cases, cable, or extra chairs, trapping a patron and obstructing egress"], "scenario_contexts": ["A house manager reserves and keeps clear the wheelchair spaces and companion seats before doors open", "An architect disperses accessible seating across levels and price points to give equivalent sightlines", "A touring crew checks that stacked gear does not block the accessible route to wheelchair spaces"]}, "56e945d2-ca0e-4f4b-8711-78a4f425fb8c": {"definition": "An elevated seating tier that projects over the rear or sides of the main floor of an auditorium, providing additional raked audience seating above the orchestra or stalls level. A house may have one or more balcony levels, variously called the gallery, upper circle, or dress circle depending on height and local tradition.", "plain_english": "A balcony is an upper level of seats that hangs over the main floor. It lifts people higher so they can see over the heads below. Large theatres may stack two or three balconies.", "purpose_function": "It adds audience capacity and brings more seats closer to the stage by stacking them vertically, while its raked rows improve sightlines over the seats in front.", "practical_application": "A technician uses the balcony front or rail as a lighting and loudspeaker position and checks that the balcony overhang does not shadow sound or sightlines for the seats beneath it.", "category": "Seating Areas", "related_terms": ["House", "Mezzanine", "Balcony rail", "Orchestra", "Box seating", "Sightline"], "common_mistakes": ["Confusing the balcony with the mezzanine; the mezzanine is usually the first, lower overhanging tier, with the balcony above it", "Forgetting that a deep balcony overhang creates an acoustic shadow and can muffle sound for seats underneath", "UNSAFE: Resting cases, tools, or loose gear on or over the balcony rail, where they can fall onto patrons below"], "scenario_contexts": ["A lighting designer rigs front light on the balcony rail to reach the stage at a useful angle", "A sound engineer adds delay loudspeakers under a deep balcony to cover shadowed seats", "A house manager opens the upper balcony only when the lower seating sells out"]}, "a42f7835-fefd-438e-bf19-0cab8a06d4e7": {"definition": "Small, partly enclosed seating compartments set into the side walls or front of the balconies of an auditorium, each holding only a few seats and separated from the general seating. Boxes were historically prestige seats and typically sit close to the stage along the side walls, trading a full frontal view for proximity and exclusivity.", "plain_english": "Box seats are small private booths built into the side walls of a theatre. Each holds just a few chairs. They sit close to the stage and were once the fanciest, priciest seats.", "purpose_function": "Boxes provide separated, premium seating and help shape the side walls of the auditorium, though their steep angle to the stage often gives only a partial view of the action.", "practical_application": "A technician may site loudspeakers, cameras, or a followspot in or near a box, and checks that box occupants do not sit in a followspot throw or block a loudspeaker.", "category": "Seating Areas", "related_terms": ["House", "Balcony", "Proscenium", "Sightline", "Orchestra", "Gallery"], "common_mistakes": ["Assuming box seats always give the best view; their sharp side angle often hides part of the stage", "Confusing a seating box with the technical control booth at the back of the house; they are different spaces", "Overlooking that box positions on the side walls affect the room's early reflections and acoustics"], "scenario_contexts": ["A followspot operator works from a house box with a clear line to the stage", "A house manager sells side boxes as premium seats despite their partial sightline", "A sound designer places a surround loudspeaker in a box to cover nearby seating"]}, "3c5cfd07-bc80-4b27-aea4-a4bbde07805b": {"definition": "A raised, tiered seating gallery placed above and behind the stage or orchestra platform of a concert hall, built to hold a chorus for choral works. When no choir is performing it is often sold as audience seating that faces the conductor from behind the orchestra.", "plain_english": "A choral balcony is a bank of seats above and behind the stage. It holds the choir for big choral pieces. When no choir sings, the hall often sells these seats to the audience.", "purpose_function": "It gives a large chorus a raked, elevated place to stand and project over the orchestra toward the audience, and lets the hall add flexible seating behind the platform.", "practical_application": "A technician places choir microphones, monitors, and music-stand lighting in the choral balcony and runs cabling to it without blocking the tiered steps.", "category": "Seating Areas", "related_terms": ["Balcony", "House", "Orchestra", "Riser", "Stage", "Sightline"], "common_mistakes": ["Confusing the choral balcony with a normal audience balcony; the choral balcony sits behind the performers, not in front of them", "Forgetting that choral-balcony seats face the back of the orchestra, so the view and sound there differ from the main floor", "UNSAFE: Leaving cables loose or gaps open on the tiered choir steps, creating a trip or fall hazard for singers"], "scenario_contexts": ["A chorus stands in the choral balcony behind the orchestra for a symphony with voices", "A hall sells the choral balcony as behind-orchestra audience seating for an orchestra-only concert", "A technician rigs choir mics and stand lights in the choral balcony before a rehearsal"]}, "dc3608aa-0b13-4198-94b4-e20de4d613e0": {"definition": "A designated part of the house, typically the rear rows or a separate holding space, where patrons who arrive after the performance begins are held and seated only at a suitable pause in the program. Holding latecomers there prevents them from disturbing the performers and seated audience before an appropriate break.", "plain_english": "This is where latecomers wait to be seated. Staff hold people who arrive after the show starts. They are let in at a break, so they do not disturb the performance.", "purpose_function": "It protects the performance and the seated audience from disruption by controlling when and where late arrivals enter, while still admitting them at a natural break.", "practical_application": "A house manager directs latecomers to the delayed seating area or lobby monitors, then seats them during the first suitable pause on a cue agreed with the stage manager.", "category": "House Management", "related_terms": ["House", "House manager", "Aisle", "Lobby", "Intermission", "Sightline"], "common_mistakes": ["Seating latecomers immediately during a quiet scene, distracting the performers and the audience", "Assuming every venue can late-seat; a show with no interval may hold latecomers until the end", "UNSAFE: Guiding latecomers to seats in a darkened house without a torch or clear aisle lighting, risking trips and falls"], "scenario_contexts": ["A house manager holds latecomers at the back until the first song ends, then seats them", "During a no-interval play, latecomers watch a lobby monitor from the delayed seating area", "The stage manager gives the house manager a late-seating cue at a scene change"]}, "4b033757-f7ca-40d8-9c34-d8dcb9d2985c": {"definition": "An enclosed operating room at the back of the house, usually behind or above the audience seating, from which technicians run lighting, sound, projection, or stage-management cues. Because it is typically glazed and separated from the room, a booth isolates operators but places them behind glass, away from the audience's true acoustic experience.", "plain_english": "The front-of-house booth is a small control room at the back of the audience. Technicians run the lights, sound, and cues from here. Its window keeps them separate, but they hear less of the real room sound.", "purpose_function": "It gives operators a fixed, protected position with a view of the stage to run the show, while keeping their equipment, light, and noise out of the audience's sight and hearing.", "practical_application": "A technician operates the lighting desk or calls cues from the booth and relies on a monitor feed for show audio, because glass and distance change how the room actually sounds.", "category": "Technical Positions", "related_terms": ["House", "Front-of-house mix position", "Followspot", "Balcony", "Control booth", "Sightline"], "common_mistakes": ["Mixing audio from inside a sealed booth, where the sound heard differs sharply from what the audience hears", "Assuming a booth window is open acoustically; most are sealed, so operators rely on monitors and feeds", "UNSAFE: Blocking the booth's exit or cluttering it so operators cannot leave quickly in an emergency"], "scenario_contexts": ["A board operator runs the lighting console from the rear booth during a musical", "A stage manager calls the show over headset from the front-of-house booth", "A projectionist runs media from the booth with a clear sightline to the screen"]}, "464c8c9c-6984-44a0-be7b-c5153825181c": {"definition": "The location in the audience area, out in the open house rather than in a booth, where the main audio mixing console and engineer sit during a live performance. It is ideally placed roughly two-thirds of the way back, on the centre line and clear of any balcony overhang, so the engineer hears close to what the audience hears.", "plain_english": "This is where the sound engineer and main mixing desk sit, out among the seats. A good spot is about two-thirds back and centered. There the engineer hears sound much like the crowd does.", "purpose_function": "It puts the mix engineer in a representative listening spot within the audience so mixing decisions reflect what most of the crowd actually hears, not a distorted position.", "practical_application": "A technician marks off and cables the mix position out in the seats, avoiding spots under a balcony, against a rear wall, or off the centre line, which all colour the sound.", "category": "Technical Positions", "related_terms": ["House", "Front-of-house booth", "Mixing console", "Balcony", "Sightline", "Delay loudspeaker"], "common_mistakes": ["Placing the mix position against the back wall, where bass build-up and reflections mislead the engineer", "Mixing from under a deep balcony, where the overhang dulls high frequencies and hides the true balance", "UNSAFE: Running console power and audio cable across audience aisles without ramps or covers, creating trip hazards"], "scenario_contexts": ["A sound engineer mixes a concert from a riser about two-thirds back in the seating", "A venue removes a block of seats to create a house mix position on the centre line", "An engineer rejects a booth mix and moves the console into the open house for an accurate blend"]}, "cbf7d465-2bc9-4cfd-925d-b49ad807b5cf": {"definition": "The part of a theatre or venue occupied by the audience, including the seating, aisles, and related public areas, as distinct from the stage and backstage. The term also refers to the audience itself, as in 'a full house', and forms staff titles and phrases such as house manager and house lights.", "plain_english": "The house is the part of a theatre where the audience sits. It covers the seats and aisles, not the stage. The word also means the crowd itself, as in a full house.", "purpose_function": "It names the audience side of the building, giving crew a clear word to separate patron areas from the stage and backstage when planning, running, and communicating during a show.", "practical_application": "A technician checks house lights, house loudspeaker coverage, and clear aisles, and clears the house of crew and gear before doors open so patrons can enter safely.", "category": "Audience Areas", "related_terms": ["House left", "House lights", "House manager", "Orchestra", "Balcony", "Front-of-house mix position"], "common_mistakes": ["Confusing 'the house' with the whole building; it means the audience areas, not the stage or backstage", "Mixing up house left and right, which are named from the audience's viewpoint, opposite to stage left and right", "UNSAFE: Leaving cable or cases in house aisles, blocking patron egress routes"], "scenario_contexts": ["A stage manager asks whether the house is clear before opening doors to the audience", "A technician brings up house lights at intermission so patrons can move safely", "A house manager reports the size of the house to the stage manager before curtain"]}, "85f50a1a-3cda-4348-9342-6930a0639a7d": {"definition": "The left side of the auditorium and stage from the seated audience's point of view, facing the stage. Because it is defined from the audience's perspective, house left is the opposite side to stage left, which is named from the performer's viewpoint facing the audience.", "plain_english": "House left is the left side of the room from the audience's seat, looking at the stage. It is the opposite of stage left, which uses the actor's view. So the two 'lefts' point to different sides.", "purpose_function": "It gives audience-side staff a fixed, unambiguous way to point to one side of the house or stage, avoiding confusion with the performer-based stage-left and stage-right terms.", "practical_application": "A house manager or usher directs patrons to house left, while a technician double-checks whether a note means house left or stage left before hanging or placing gear.", "category": "Orientation & Directions", "related_terms": ["House", "House right", "Stage left", "Stage right", "Center line", "Sightline"], "common_mistakes": ["Assuming house left equals stage left; they are opposite sides because they use different viewpoints", "Forgetting to state whether a direction is from the house or the stage, causing gear to land on the wrong side", "Reading house left from the stage instead of from the audience's seats facing the stage"], "scenario_contexts": ["An usher guides a patron to a seat on house left", "A designer notes a loudspeaker goes house left and confirms which side that is with the crew", "A house manager reports a spill on the house-left aisle for cleanup"]}, "4fc4612e-943d-436b-98f2-512f60d68703": {"definition": "The point in a performance's pre-show schedule at which the auditorium is opened and the audience is admitted to their seats. Opening the house is authorised by the stage manager in coordination with front-of-house staff, only after the stage and seating areas are safe, set, and clear of working crew.", "plain_english": "It is the moment the theatre lets the audience come in and find seats. The stage manager opens the house only once the space is safe and ready.", "purpose_function": "It marks the controlled hand-off of the auditorium from the working crew to the audience, so the space is safe and preset before people enter.", "practical_application": "When the stage manager calls house open, a technician stops any onstage work and clears stray cables from the seating and aisles.", "category": "House Operations", "related_terms": ["Front of house", "House manager", "Preset", "Rear house", "Orchestra seating"], "common_mistakes": ["Opening the house before the stage is set and safe, exposing the audience to onstage work", "UNSAFE: Leaving audio or power cables across seating aisles when the house opens, blocking a required means of egress"], "scenario_contexts": ["A stage manager confirming the stage is clear before calling the house open thirty minutes before curtain", "A sound technician finishing soundcheck and coiling stray cables before the house opens to patrons"]}, "bda9d693-50af-42b0-8bcf-f5f2cabd11e1": {"definition": "The right-hand side of the auditorium from the perspective of an audience member seated and facing the stage. Because performer-based stage directions are reversed, house right corresponds to stage left.", "plain_english": "It is the right side of the seating when you sit facing the stage. From the actor's view on stage, that same side is their left.", "purpose_function": "It gives crew and front-of-house staff a fixed, audience-based way to name a side of the house that does not flip with the performer's facing.", "practical_application": "A designer aiming a house-right delay speaker points it at the seating on the audience's right, which is the performers' stage left.", "category": "House Orientation", "related_terms": ["House left", "Stage left", "Stage right", "Orchestra seating", "Front of house"], "common_mistakes": ["Confusing house right with stage right; house right is the audience's right and equals stage left", "Assuming left and right are absolute rather than defined by whether you face the stage or the house"], "scenario_contexts": ["A house manager directing an usher to seat a patron in the house-right aisle", "A system tech labeling the house-right speaker hang during a load-in"]}, "370411d1-e630-485d-b4cb-d4fab87daa34": {"definition": "An intermediate seating tier positioned above the orchestra (main) floor and below the upper balcony in a multi-level auditorium. In North American usage it is typically the lowest elevated seating level, sometimes forming the front section of the first balcony.", "plain_english": "It is the first seating level raised above the main floor of a theatre. It sits below the higher balcony seats.", "purpose_function": "It adds raised seating with sightlines over the main floor, letting more people see the stage without making the room longer.", "practical_application": "A technician planning coverage checks that the mezzanine front rows are not shadowed by the balcony overhang above them.", "category": "Seating Levels", "related_terms": ["Orchestra seating", "Upper balcony", "Seating bowl", "Rear house", "Rear balcony position"], "common_mistakes": ["Treating mezzanine and balcony as identical; the mezzanine is usually the lowest raised tier", "UNSAFE: Leaning gear against or setting it on a mezzanine front guardrail, which is a fall-protection barrier, not a shelf"], "scenario_contexts": ["A mix engineer positioning a delay speaker to cover mezzanine seats blocked by the balcony overhang", "An acoustician measuring reverberation from a mezzanine seat during a room tuning"]}, "a7a407eb-4e0f-400c-ae58-ed4b8ab6a49e": {"definition": "The ground-level seating area of an auditorium, on the main floor closest to and roughly level with the stage. The name derives from the orchestra of the ancient Greek theatre, the circular ground-level space used by the chorus.", "plain_english": "It is the main floor of seats on the ground level, closest to the stage. The name comes from a ground space in ancient Greek theatres.", "purpose_function": "It provides the primary, closest audience seating at stage level, usually the largest single seating block in the house.", "practical_application": "A system tech relies on the main loudspeaker hangs to cover orchestra seating, adding front-fills for the first few rows.", "category": "Seating Levels", "related_terms": ["Mezzanine", "Upper balcony", "Seating bowl", "House right", "Rear house"], "common_mistakes": ["Confusing orchestra seating with the orchestra pit, which is the sunken area for musicians, not audience seats", "Assuming the front row is the best-sounding seat; very close seats often fall below main-array coverage"], "scenario_contexts": ["A designer planning front-fill speakers for the first rows of orchestra seating", "An usher seating latecomers at the rear of the orchestra during a scene break"]}, "66daaf1b-4926-4f17-876f-24ad82cd90ba": {"definition": "A listening or measurement location at the rearmost row of a balcony, one of the farthest and most acoustically challenging audience positions from the stage and main loudspeakers. It is often used as a worst-case reference point when designing or verifying system coverage and level.", "plain_english": "It is the back row of the upper balcony, far from the stage and speakers. Engineers check it because it is one of the hardest seats to cover well.", "purpose_function": "It serves as a benchmark for the most distant, highest seats, so a system is proven to reach even the farthest listeners at adequate level and clarity.", "practical_application": "During tuning, a tech takes a measurement mic to the rear balcony position to confirm the delay speakers deliver enough level and intelligibility.", "category": "Listening Positions", "related_terms": ["Upper balcony", "Side balcony position", "Rear house", "Mezzanine", "Seating bowl"], "common_mistakes": ["Tuning only from the mix position and ignoring the rear balcony, where coverage and level often fall short", "UNSAFE: Standing or leaning at the balcony front edge while measuring instead of staying behind the guardrail"], "scenario_contexts": ["A system engineer checking level and intelligibility from the rear balcony before doors open", "A designer aiming upper balcony delays to reach the rear balcony position on-axis"]}, "40ebd33e-c50a-4379-b5e3-4fa042378e6f": {"definition": "The rearmost portion of the audience seating area, farthest from the stage. In sound and sightline planning it denotes the back of the seating, and it should not be confused with back of house, which means the non-public backstage and support areas.", "plain_english": "It is the back part of the audience seating, farthest from the stage. Do not mix it up with back of house, which means backstage areas.", "purpose_function": "It names the most distant seating so crews can plan the extra coverage, delay, and sightline care those far seats need.", "practical_application": "A tech adds delay speakers timed to the mains so the rear house hears speech clearly and in sync with the stage.", "category": "House Orientation", "related_terms": ["Rear balcony position", "Orchestra seating", "Upper balcony", "Front of house", "House opening"], "common_mistakes": ["Confusing rear house (the rear of the audience seating) with back of house, the backstage support areas", "Leaving rear-house seats under-covered because the system was judged only from the mix position"], "scenario_contexts": ["A designer specifying rear-house delay speakers to keep speech intelligible at the back rows", "A mix engineer walking to the rear house to hear how the far seats sound during rehearsal"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"72797f33-1348-4445-8154-706f6924f0e0": {"definition": "The continuous, tiered arrangement of audience seating that slopes and wraps around the performance area, forming a bowl-like mass. The term is common in arenas, stadiums, and large auditoria where seating rises on a rake or in stacked tiers around the stage or field.", "plain_english": "It is the whole sloped block of audience seats that curves around the stage or field. It rises like the inside of a bowl so everyone can see.", "purpose_function": "It shapes rising, angled seating so most seats get clear sightlines and fairly even coverage from a central performance area.", "practical_application": "A system designer models loudspeaker coverage across the seating bowl to keep level and intelligibility even from the front rows to the top tier.", "category": "Seating Areas", "related_terms": ["Orchestra seating", "Mezzanine", "Upper balcony", "Rear house", "Sightlines"], "common_mistakes": ["Assuming a curved seating bowl needs only the main array; upper and side tiers usually need dedicated coverage", "UNSAFE: Running cable or placing gear on the bowl's steep steps and aisles, creating trip and egress hazards"], "scenario_contexts": ["An audio designer aiming several loudspeaker hangs to cover an arena seating bowl evenly", "An acoustician studying how the raked seating bowl affects reflections and reverberation"]}, "69c689a2-0593-4f5c-bfb8-e92773ac16b3": {"definition": "A listening or measurement location in the side seating of a balcony, along the auditorium's side walls. These seats sit off the main loudspeaker axis and often require dedicated side or infill coverage and careful sightline treatment.", "plain_english": "It is a seat at the side edge of the balcony, near the side wall. These seats sit off to the side of the main speakers, so they can be hard to cover.", "purpose_function": "It flags the off-axis side balcony seats so designers verify they get adequate, balanced coverage, not just the seats facing the stage head-on.", "practical_application": "A tech measures the side balcony position to decide whether side-fill or a dedicated balcony speaker is needed for even coverage.", "category": "Listening Positions", "related_terms": ["Rear balcony position", "Upper balcony", "Mezzanine", "Seating bowl", "Sightlines"], "common_mistakes": ["Ignoring side balcony seats because they fall outside the main array's forward coverage", "UNSAFE: Leaning over or setting equipment on the side balcony guardrail instead of staying behind it"], "scenario_contexts": ["A designer adding side-fill speakers after finding weak coverage at the side balcony position", "An engineer checking tonal balance from a side balcony seat during system tuning"]}, "16f19021-18e8-4704-9385-dd3d532ff764": {"definition": "The highest seating tier in a multi-level auditorium, located above the mezzanine or lower balcony and farthest and highest from the stage. Historically also called the gallery or upper circle, it typically has the steepest rake and the most distant sightlines.", "plain_english": "It is the top level of seats, highest up and farthest from the stage. These seats are steep and far, so they need extra care for sound and safety.", "purpose_function": "It adds seating capacity high in the room, extending sightlines upward while keeping the audience within reach of the stage and sound system.", "practical_application": "A system tech aims and times delay speakers to the upper balcony so the distant seats get clear, in-sync sound.", "category": "Seating Levels", "related_terms": ["Mezzanine", "Orchestra seating", "Rear balcony position", "Seating bowl", "Side balcony position"], "common_mistakes": ["Confusing the upper balcony with the mezzanine; the mezzanine is a lower tier and the upper balcony is the highest", "UNSAFE: Standing on or leaning over the steep upper balcony's front guardrail, which is fall protection, not a rail to lean on"], "scenario_contexts": ["A designer specifying delay speakers so the upper balcony hears speech in time with the stage", "An acoustician measuring clarity and level from the upper balcony's rear row"]}, "403957c2-4362-4c40-875e-92297d51e978": {"definition": "A designated, level clear floor space integrated into an assembly area's seating that accommodates one patron using a wheelchair, rather than a segregated area. Accessibility standards require a single space at least 36 in (915 mm) wide, an adjacent companion seat, comparable lines of sight, and horizontal and vertical dispersion, with the number of spaces scaled to the venue's seating capacity.", "plain_english": "It is a flat, open spot in the seating where a person in a wheelchair can watch the show. A regular seat sits next to it for a friend, and the view must be as good as other seats.", "purpose_function": "It gives people who use wheelchairs equal access, comfortable seating, and comparable sightlines, satisfying accessibility law and building codes. It exists so seating is inclusive and integrated instead of confining disabled patrons to the room's edges.", "practical_application": "A venue designer distributes wheelchair spaces across the seating chart to meet the required count and dispersion for the room's capacity. A house manager keeps those spaces clear and confirms each has its companion seat and clear floor dimensions before doors open.", "category": "Accessible Seating", "related_terms": ["Accessible seating", "Companion seat", "Sightline", "Orchestra seating", "Egress"], "common_mistakes": ["UNSAFE: Placing loose chairs or storing equipment in a wheelchair space, which blocks the space and can obstruct an accessible means of egress", "Grouping all wheelchair spaces at the back or front instead of dispersing them, failing the required horizontal and vertical dispersion", "Omitting the adjacent companion seat, so a wheelchair user cannot sit beside their guest", "Assuming one or two spaces is always enough; the required number scales with the venue's total seating capacity"], "scenario_contexts": ["A theatre designer laying out an auditorium and distributing wheelchair spaces across seating levels and sightline zones", "A house manager checking that wheelchair spaces and companion seats are clear and available before a sold-out show", "An inspector verifying the number, dimensions, and dispersion of wheelchair spaces against accessibility code during plan review"]}, "7c71f88e-6dde-4074-b61c-a943ef07d4d1": {"definition": "An acoustic banner is a large, sound-absorbing fabric panel, typically deployable or retractable, hung in a performance or multipurpose space to add variable absorption, shorten reverberation time, and control excessive liveness. It is a tool of variable (adjustable) room acoustics, raised or lowered to tune the space for speech, amplified music, or acoustic music.", "plain_english": "An acoustic banner is a big soft cloth panel that soaks up sound. Crews raise or lower it to change how echoey a room feels. Lots of banner makes a loud gym sound less boomy. Hiding it away lets the room ring again.", "purpose_function": "It adds adjustable sound absorption so one room can suit both echo-friendly acoustic music and clear, dry amplified sound or speech.", "practical_application": "A technician deploys banners to cut reverberation and flutter echo in a gym or multipurpose hall before an amplified event, then retracts them for a choir or band.", "category": "Acoustic soft goods", "related_terms": ["Acoustic curtain", "Acoustic canopy", "Reverberation time", "Sound absorption", "Variable acoustics", "Acoustic shell"], "common_mistakes": ["Assuming a banner reflects or blocks sound; it mainly absorbs sound to reduce reverberation, not to stop sound passing through a wall.", "Deploying banners for an unamplified concert, deadening the room and robbing the ensemble of natural bloom.", "UNSAFE: Hanging an untreated or uncertified fabric banner; stage and assembly soft goods must meet a flame-propagation standard such as NFPA 701."], "scenario_contexts": ["Tuning a reverberant gymnasium or multipurpose room for an amplified assembly or presentation.", "Adding absorption to a band or choir rehearsal room that rings excessively.", "Configuring a variable-acoustics hall to switch between speech and music modes."]}, "79d6c6b7-027f-4061-81b4-69dc0db5bed7": {"definition": "An acoustic canopy is an overhead array of hard, sound-reflecting panels suspended above a stage, orchestra, or platform to return early sound energy to the performers and project it toward the audience. Unlike an absorptive banner, its surfaces are reflective, improving ensemble hearing and clarity without fully enclosing the players.", "plain_english": "An acoustic canopy is a set of hard panels hung above the players like a low false ceiling. It bounces sound back down quickly. This helps the musicians hear each other. It also throws their sound out toward the audience.", "purpose_function": "It supplies strong early reflections from above so performers hear one another and the audience receives clearer, better-projected sound.", "practical_application": "A crew flies and angles reflective canopy panels over a pit or platform to strengthen ensemble sound, adjusting height and tilt for the group and room.", "category": "Stage acoustics", "related_terms": ["Acoustic shell", "Acoustic shell ceiling", "Early reflections", "Sound reflection", "Acoustic banner", "Reverberation time"], "common_mistakes": ["Confusing a reflective canopy with an absorptive banner or cloud made to deaden sound; a canopy reflects early sound, it does not soak it up.", "Hanging the canopy too high, so the reflections arrive too late to help ensemble hearing.", "UNSAFE: Flying overhead panels without rated hardware and secondary retention; suspended loads must meet entertainment rigging standards and load ratings."], "scenario_contexts": ["Improving ensemble hearing for an orchestra in a deep, over-reverberant stage house.", "Reflecting sound over an orchestra pit toward the audience in a musical.", "Tuning early reflections in a concert hall or multipurpose auditorium."]}, "56e146b7-19a7-4ae1-9eed-bf6da9916c6f": {"definition": "An acoustic curtain is a heavy, sound-absorbing drape, often fullness-gathered velour or a multi-layer/coated fabric, hung to reduce reverberation, control flutter echo, or provide modest sound reduction between spaces. Its absorption increases with mass, fullness (gathering), and the air gap left behind it.", "plain_english": "An acoustic curtain is a thick, heavy drape that soaks up sound. Gathering it into folds and hanging it with weight makes it absorb more. Crews use it to cut echo in a room. A heavy curtain can also dull sound leaking between two spaces.", "purpose_function": "It adds absorption and slight sound isolation so a space is less echoey or so noise passes less easily between areas, and it can be drawn open or closed to change the room.", "practical_application": "A technician draws heavy velour curtains to deaden a live rehearsal room or to separate a noisy area, choosing weight and fullness for the absorption needed.", "category": "Acoustic soft goods", "related_terms": ["Acoustic banner", "Velour", "Fullness", "Sound absorption", "Reverberation time", "Blackout drape"], "common_mistakes": ["Expecting a curtain to soundproof a room; fabric mainly absorbs and only lightly reduces transmission, so it cannot replace a solid wall.", "Hanging it flat with no fullness; gathering the fabric and leaving an air gap greatly increases low- and mid-frequency absorption.", "UNSAFE: Using untreated fabric; stage and assembly draperies must pass a flame-propagation test such as NFPA 701 and be kept certified."], "scenario_contexts": ["Deadening a reflective rehearsal room or vocal space.", "Temporarily dividing a hall and reducing sound spill between the two sides.", "Covering a hard wall to control flutter echo behind a performance area."]}, "49a7e10c-297c-48b8-8e3a-0520e3d77ab1": {"definition": "An acoustic shell (orchestra, band, or choral shell) is a portable enclosure of hard, reflective towers and overhead ceiling panels set up around performers on stage. It contains and reflects sound toward the audience while blending it back to the players, preventing sound from being lost into the fly loft and wings of a scenery-oriented stage house.", "plain_english": "An acoustic shell is a hard-walled room within the stage for musicians. It is built from side towers and overhead panels. The hard surfaces bounce sound back so players hear each other. They also send the sound out to the audience instead of losing it into the tall, empty stage.", "purpose_function": "It turns a scenery-oriented stage house, which absorbs and loses sound, into a reflective enclosure that projects the ensemble and lets musicians hear one another.", "practical_application": "Stage crew wheel in and lock together the towers and fly the ceiling panels to form the shell before a concert, then strike it for scenic productions.", "category": "Stage acoustics", "related_terms": ["Acoustic shell tower", "Acoustic shell ceiling", "Acoustic canopy", "Fly loft", "Early reflections", "Sound reflection"], "common_mistakes": ["Thinking the shell amplifies sound; it only reflects and contains existing sound energy and adds no power of its own.", "Leaving big gaps between towers or the ceiling, letting sound escape into the wings and fly loft and weakening the effect.", "UNSAFE: Rolling or standing towers without setting brakes, ballast, or specified bracing; tall shell towers can tip and must be secured per the manufacturer."], "scenario_contexts": ["Converting a proscenium stage house into a concert setup for an orchestra or band.", "Providing on-stage reflection so a choir or ensemble can hear and blend.", "Touring or festival use where a portable reflective enclosure is set up and struck quickly."]}, "cf976d15-4dd8-44a0-a6d6-0e7ff72addf4": {"definition": "The acoustic shell ceiling is the overhead portion of an orchestra shell: a set of hard, reflective panels flown from the stage rigging above the performers. It provides strong early overhead reflections, caps the enclosure, and stops sound from escaping upward into the fly loft.", "plain_english": "The shell ceiling is the roof of an orchestra shell. It is made of hard panels hung above the players. They bounce sound straight back down fast. This helps musicians hear each other and stops sound escaping up into the tall stage.", "purpose_function": "It supplies overhead early reflections and closes the top of the shell so sound is returned to players and audience instead of lost into the fly loft.", "practical_application": "Crew fly the ceiling panels in on line sets and adjust their angle and height to blend with the towers and suit the ensemble and room.", "category": "Stage acoustics", "related_terms": ["Acoustic shell", "Acoustic shell tower", "Acoustic canopy", "Line set", "Fly loft", "Early reflections"], "common_mistakes": ["Flying the ceiling too high, so overhead reflections arrive late and do little for ensemble hearing.", "Treating the panels as decoration; their angle and coverage set how well sound is returned and contained.", "UNSAFE: Exceeding a line set's rated capacity or omitting secondary retention when flying heavy ceiling panels; suspended loads must meet rigging standards and load ratings."], "scenario_contexts": ["Completing an orchestra shell by flying in the overhead reflective panels.", "Adjusting overhead reflections for a change in ensemble size or program.", "Striking the shell ceiling to clear the fly space for scenery."]}, "c8c577e7-62aa-46ed-82a1-e2a8b130808f": {"definition": "An acoustic shell tower is a tall, freestanding wall unit of an orchestra shell, with a hard reflective face, that forms the sides and rear of the enclosure around the performers. Towers are typically rolled into position on casters and then locked, ballasted, or braced; their reflective surfaces return sound to the players and steer it toward the audience.", "plain_english": "A shell tower is a tall, hard-faced wall panel on wheels. Several towers stand side by side to make the back and sides of an orchestra shell. Their hard faces bounce sound back to the players and out to the crowd. Crews roll them in and lock them so they cannot tip.", "purpose_function": "Towers form the reflective side and rear walls of the shell, containing sound within the performance area and projecting it forward.", "practical_application": "Stage crew wheel each tower into place, align it with its neighbors, and set brakes or ballast so the wall is stable before a concert.", "category": "Stage acoustics", "related_terms": ["Acoustic shell", "Acoustic shell ceiling", "Acoustic canopy", "Caster", "Sound reflection", "Ballast"], "common_mistakes": ["Leaving gaps between towers, letting sound leak into the wings and reducing reflection.", "Confusing a reflective tower with an absorptive banner; the tower is hard and reflective by design.", "UNSAFE: Moving or leaving towers without brakes, ballast, or bracing; a tall, top-heavy tower can tip and injure crew, so follow the manufacturer's stability instructions."], "scenario_contexts": ["Building the side and rear walls of an orchestra shell before a performance.", "Reconfiguring shell width for a larger or smaller ensemble.", "Rolling towers offstage to storage when striking the shell."]}, "7f404b29-bf74-4da4-a3f7-eb946f5383c7": {"definition": "An ADA ramp is a sloped accessible route for wheelchair and mobility access that complies with the ADA Standards for Accessible Design: a running slope no steeper than 1:12, cross slope no steeper than 1:48, a minimum 36 in (915 mm) clear width, a maximum 30 in (760 mm) rise per run with level landings, and handrails where the rise exceeds 6 in (150 mm). In theatre it provides accessible routes onto stages, platforms, and seating areas.", "plain_english": "An ADA ramp is a gentle slope that lets a wheelchair reach a stage or platform. The rule is no steeper than 1 inch of rise for every 12 inches of length. It needs flat resting landings and, when tall enough, handrails. This makes stages and risers reachable by everyone.", "purpose_function": "It provides a code-compliant accessible path so people using wheelchairs or other mobility aids can safely reach elevated stages, platforms, and seating.", "practical_application": "When building a stage or riser, technicians add a ramp at 1:12 or gentler with proper width, landings, and handrails so the setup is accessible and passes inspection.", "category": "Accessibility", "related_terms": ["Stage platform", "Riser", "Handrail", "Guardrail", "Landing", "Wheelchair lift"], "common_mistakes": ["UNSAFE: Building a ramp steeper than 1:12 to save space; an over-steep ramp is non-compliant and unsafe for wheelchair users.", "Forgetting the level top and bottom landings (60 in minimum long) and the handrails required once the rise exceeds 6 in.", "Ignoring cross slope and edge protection, so a wheelchair can drift or roll off the side."], "scenario_contexts": ["Providing accessible access onto a stage or raised platform for performers or presenters.", "Adding an accessible route to riser seating or a dais at an event.", "Meeting building-code and ADA inspection for a permanent or temporary stage."]}, "5fa89224-99e2-43ed-9aaa-7215acd8e35f": {"definition": "An Austrian curtain is a shirred stage drape gathered horizontally across its full width and lifted by vertical operating lines threaded through rings on the back, so it rises into a series of scalloped horizontal swags. It is highly decorative, sewn with great fullness, and is raised and lowered rather than drawn sideways.", "plain_english": "An Austrian curtain is a fancy stage drape sewn very full and gathered across. Lines on the back pull it up into rows of scallops, like a ruffled shade. It moves up and down, not side to side. It gives a rich, formal look.", "purpose_function": "It provides an ornate, formal front curtain or reveal that rises vertically into decorative swags, used where a lavish look is wanted.", "practical_application": "A crew operates the vertical lines to gather an Austrian curtain up into swags for a formal reveal, then lowers it flat to mask the stage.", "category": "Stage draperies", "related_terms": ["Brail curtain", "Contour curtain", "Grand drape", "Fullness", "Swag", "Backdrop"], "common_mistakes": ["Confusing an Austrian with a contour curtain; the Austrian is uniformly shirred into even horizontal swags, while a contour rises into irregular, individually set scallops.", "Assuming it opens by traveling sideways; it is raised and lowered on vertical lines like a shade.", "UNSAFE: Rigging the operating lines without checking that they and the fabric meet load ratings and flame-propagation (NFPA 701) requirements."], "scenario_contexts": ["Creating a formal, decorative front curtain for a concert, opera, or gala.", "Providing an ornate reveal that lifts into swags at the top of a show.", "Dressing a proscenium with a rich, traditional look."]}, "564e348d-019a-4ae0-bfdb-0a96421c22a0": {"definition": "A backdrop (drop) is a large expanse of fabric, often painted muslin, canvas, or seamless scrim, hung at the rear of the stage to form the visual background of a scene. It is typically battened along the top and bottom (or tied to a pipe), flown or rolled, and may be opaque, translucent, or a cyclorama-style sky.", "plain_english": "A backdrop is a big cloth hung at the back of the stage. It is often painted to show a scene, like a sky, street, or forest. It sets the background the audience sees behind the actors. Crews fly it in or roll it up to change scenes.", "purpose_function": "It supplies the painted or plain visual background of a scene quickly and lightly, without building solid scenery across the whole stage.", "practical_application": "Scenic and fly crews hang, batten, and fly backdrops, swapping them between scenes to change the location the audience sees.", "category": "Stage scenery", "related_terms": ["Cyclorama", "Scrim", "Muslin", "Batten", "Border and leg", "Line set"], "common_mistakes": ["Confusing a backdrop with a cyclorama; a cyc is a specific large, often curved sky drop, while a backdrop is any rear scenic cloth.", "Hanging a drop without a bottom pipe or chain pocket, so it wrinkles and will not hang flat.", "UNSAFE: Flying a heavy drop on an under-rated line set, or using non-flame-treated fabric that fails NFPA 701."], "scenario_contexts": ["Providing the painted background scene behind the action in a play or musical.", "Flying different location drops in and out between scenes.", "Using a translucent drop lit from behind for a sky or silhouette effect."]}, "ef012a2c-16e5-4baf-843a-c0d51320d70a": {"definition": "Black masking is the set of black, non-reflective soft goods (legs, borders, tabs, and backings), usually velour or commando cloth, hung around the acting area to conceal offstage spaces, lighting instruments, rigging, and crew from the audience's sightlines.", "plain_english": "Black masking is black stage cloth hung to hide the backstage. It stops the audience from seeing lights, ropes, and crew at the sides and top. The dull black fabric does not reflect stage light.", "purpose_function": "It exists to control what the audience sees, framing the stage picture while concealing technical gear and offstage areas. Its matte black surface also absorbs stray light so hidden areas stay dark.", "practical_application": "A stagehand hangs black legs and borders on the fly system, then checks sightlines from the extreme seats to confirm nothing offstage is visible.", "category": "Soft goods / masking", "related_terms": ["Border", "Leg", "Teaser", "Tormentor", "Sightline", "Commando cloth"], "common_mistakes": ["Confusing masking, which hides offstage areas, with a backdrop or cyclorama used as visible scenery.", "Hanging masking with gaps at the sides or top, so the audience sees offstage lights or crew.", "UNSAFE: Using drapery that is not flame-retardant to NFPA 701; venue soft goods must pass the NFPA 701 flame-propagation test and be re-treated or replaced when the treatment fails."], "scenario_contexts": ["Framing a concert stage so the audience sees only the performers and set.", "Hiding lighting booms, cable runs, and waiting performers in the wings.", "Creating a neutral black surround for a dance or drama production."]}, "3af0df97-a5c7-463f-a629-de1df8e57e87": {"definition": "A blackout drape is an opaque, light-tight stage curtain, typically heavyweight black velour or a specially coated blackout fabric, used to fully block light transmission, either to darken a space or to form a solid black background behind the acting area.", "plain_english": "A blackout drape is a heavy black curtain that light cannot pass through. It is used to make a space fully dark or to give a solid black background. Think of it like a blackout blind for a whole stage.", "purpose_function": "It exists to stop light passing through or spilling around it, so a room or backdrop reads as true black. This lets designers control darkness and hide whatever sits behind the drape.", "practical_application": "A technician hangs a blackout drape across an opening or upstage to kill light leaks from a lobby or backstage during a dark scene or a projection.", "category": "Soft goods / masking", "related_terms": ["Black masking", "Backdrop", "Border", "Leg", "Velour", "Cyclorama"], "common_mistakes": ["Assuming any black curtain is light-tight; only opaque, lined, or coated blackout fabric truly blocks light.", "Leaving edges and seams with too little overlap, so light leaks through the gaps.", "UNSAFE: Installing blackout drapes that are not flame-retardant to NFPA 701, creating a fire hazard on a stage or in an assembly space."], "scenario_contexts": ["Blocking daylight from windows or doorways in a room used for projection.", "Forming a solid black background behind performers for a dramatic look.", "Sealing an opening so backstage light does not spill onto the stage during a blackout."]}, "1b56955d-d866-455c-ba87-181f6be12ee7": {"definition": "A border is a short, wide horizontal soft-good hung above the stage and spanning its width, used to mask the fly loft, overhead lighting, and rigging from the audience and to set the top edge (height) of the visible stage opening.", "plain_english": "A border is a wide, short curtain hung across the top of the stage. It hides the lights, pipes, and ropes above from the audience. It also sets how tall the stage opening looks.", "purpose_function": "It exists to hide everything overhead the audience should not see and to frame the top of the stage picture. Its height on the batten sets the sightline for the top of the opening.", "practical_application": "A crew hangs borders on battens in front of each electric so the audience cannot see the lighting fixtures or the space above them.", "category": "Soft goods / masking", "related_terms": ["Borders", "Leg", "Teaser", "Black masking", "Batten", "Sightline"], "common_mistakes": ["Confusing a border, which is horizontal and overhead, with a leg, which is vertical and at the sides.", "Hanging a border too high, so the audience sees lights or the fly loft behind it.", "UNSAFE: Hanging drapery that is not flame-retardant to NFPA 701 above an audience or performers."], "scenario_contexts": ["Masking the first electric so lighting instruments are hidden from the audience.", "Setting the height of the stage opening for a specific production.", "Hiding the fly loft and rigging above the acting area."]}, "5a796d8e-5c2a-4993-920a-fa834811394d": {"definition": "Borders are the series of horizontal masking drapes hung in sequence from front to back above the stage; together they mask the fly loft, overhead lighting, and rigging across the full depth of the acting area from every seat in the house.", "plain_english": "Borders are the set of wide, short curtains hung one behind another across the top of the stage. As a group they hide the lights and rigging above the whole acting area. Each one covers a bit more of the space above.", "purpose_function": "They exist as a system so that, wherever a person sits, the overhead machinery and lighting stay hidden. Spaced front to back, they close the sightlines a single border would leave open.", "practical_application": "A technician spaces borders evenly over the stage depth, checking from side seats that no gap reveals lights or the grid between them.", "category": "Soft goods / masking", "related_terms": ["Border", "Leg", "Teaser", "Black masking", "Sightline", "Batten"], "common_mistakes": ["Treating one border as enough; a single border cannot close overhead sightlines for the whole house.", "Spacing borders unevenly, leaving gaps where the audience sees lights or the grid.", "UNSAFE: Using borders that are not flame-retardant to NFPA 701 above performers and audience."], "scenario_contexts": ["Masking a deep stage that has several electrics from front to back.", "Adjusting border spacing to close sightlines for a wide seating layout.", "Hiding a row of overhead lighting pipes across the full stage depth."]}, "11a78caf-616f-4513-bc63-f5369d35d9e2": {"definition": "A ceiling reflector is a hard, sound-reflecting surface or suspended panel mounted overhead in a performance space that redirects sound downward toward the audience and performers, supplying strong early reflections that improve loudness, clarity, and ensemble.", "plain_english": "A ceiling reflector is a hard panel or surface above the stage that bounces sound down. It sends early sound to the audience and players quickly. This makes music louder and clearer, and helps musicians hear each other.", "purpose_function": "It exists to control where overhead sound energy goes, turning ceiling height into useful early reflections instead of wasted delay. This raises clarity and helps performers hear one another.", "practical_application": "An acoustician positions and angles a ceiling reflector over the stage so it returns early sound to the players and out to the nearest rows.", "category": "Acoustic reflector", "related_terms": ["Concert-hall cloud", "Acoustic canopy", "Acoustic shell", "Early reflections", "Reverberation", "Sound diffuser"], "common_mistakes": ["Confusing a reflecting ceiling panel with an absorptive treatment; a reflector redirects sound rather than soaking it up.", "Placing the reflector so high that its reflection arrives too late to aid clarity.", "Ignoring the reflector's angle, so sound is sent to empty areas instead of the audience or players."], "scenario_contexts": ["Improving clarity and loudness in a multipurpose hall with a high ceiling.", "Returning early sound to an orchestra so players hear each other.", "Tuning overhead reflections during the acoustic design of a performance room."]}, "547b01f6-f508-42b7-a9be-227217af3a8f": {"definition": "A concert-hall cloud is a discrete overhead sound-reflecting panel, or array of panels, suspended above the stage or orchestra platform of a concert hall and angled to reflect early sound back to the musicians and out to the audience, strengthening ensemble, support, and clarity.", "plain_english": "A concert-hall cloud is a panel hung high above the players, like a floating piece of ceiling. It bounces early sound back down to the musicians and audience. This helps the players hear each other and makes the music clearer.", "purpose_function": "It exists to add useful early reflections in halls whose real ceiling is too high or too far to do the job alone. Adjusting its height and tilt lets designers tune stage support and clarity.", "practical_application": "In a hall with an adjustable rig, crew raise, lower, or tilt the clouds to suit an orchestra, a choir, or an amplified act.", "category": "Acoustic reflector", "related_terms": ["Ceiling reflector", "Acoustic canopy", "Acoustic shell", "Early reflections", "Reverberation", "Ensemble"], "common_mistakes": ["Thinking clouds absorb sound; suspended reflector panels return sound energy, they do not remove it.", "Setting clouds too high, so their reflections arrive too late to aid ensemble.", "UNSAFE: Suspending overhead reflector panels without rated rigging hardware and secondary safety cables, risking a fall onto people below."], "scenario_contexts": ["Providing stage support in a tall concert hall for a symphony orchestra.", "Adjusting overhead panels between a full orchestra and a solo recital.", "Reflecting early sound to the front rows in a large auditorium."]}, "4733105d-63c8-4e3e-b00e-f45ef32cb13e": {"definition": "A contour curtain is a single wide drapery panel sewn with heavy fullness and rigged with several vertical lift lines threaded through rings on its back up to a batten; raising the lines by differing amounts pulls the bottom edge up into adjustable, irregular scallops or swags rather than opening it sideways.", "plain_english": "A contour curtain is one full curtain lifted by several ropes sewn up its back. Pulling each rope a different amount gathers the bottom into curves and swags. It rises into shapes instead of sliding open to the sides.", "purpose_function": "It exists to raise and shape a curtain into decorative swags for reveals and finales, giving a formal or festive look. The separate lift lines let an operator vary the shape, not just open and close it.", "practical_application": "An operator raises the individual lines of a contour curtain to shape its swags for a grand reveal, then lowers it flat to close.", "category": "Soft goods / drapery", "related_terms": ["Austrian curtain", "Brail curtain", "Draw curtain", "Front curtain", "Fullness", "Batten"], "common_mistakes": ["Confusing a contour curtain with an Austrian curtain; the Austrian has permanent shirred swags, while the contour is a plain-faced panel that scallops only when lifted.", "Rigging too little fullness, so the raised curtain looks flat instead of forming rich swags.", "Assuming it draws sideways like a traveler; a contour curtain lifts and gathers, it does not part in the middle."], "scenario_contexts": ["Creating a decorative swagged reveal for a musical or variety show.", "Dressing a proscenium with a formal, scalloped front curtain.", "Making a shaped curtain effect for a finale or grand opening."]}, "8705c487-47f8-40d3-9bb8-6a4ead6ee3f5": {"definition": "The curtain line is the imaginary line across the stage floor directly beneath the main (front or act) curtain where it meets the deck; it marks the boundary between the stage proper and the forestage/apron and serves as a key datum for laying out and measuring onstage positions.", "plain_english": "The curtain line is a line across the stage floor right under the main curtain. It marks the spot on the floor directly under the closed main curtain. Crews measure stage positions from this line, and it divides the stage from the apron in front.", "purpose_function": "It exists as a fixed reference so everyone measures scenery, tape marks, and blocking from the same spot. It also defines where the stage ends and the apron begins.", "practical_application": "A stage manager measures set positions and spike marks as distances upstage of the curtain line.", "category": "Stage geography", "related_terms": ["Front curtain", "Proscenium", "Apron", "Plaster line", "Centerline", "Setting line"], "common_mistakes": ["Confusing the curtain line with the plaster line or setting line; these are separate reference lines at different points.", "Assuming the curtain line marks the front edge of the stage, when the apron extends in front of it.", "Forgetting that scenery downstage of the curtain line sits in front of a closed main curtain."], "scenario_contexts": ["Measuring where to place scenery relative to the front curtain.", "Laying out a ground plan using the curtain line as a datum.", "Checking that a set piece clears the path of the closing main curtain."]}, "0c347d79-a54e-4ebc-9e02-81ee47a7f503": {"definition": "A curtain pocket is a sewn sleeve or channel along the bottom hem (occasionally the top) of a stage drape that holds a weight, most often a chain, or a pipe/conduit stiffener, so the drapery hangs plumb, resists air movement, and can seal against an uneven stage floor.", "plain_english": "A curtain pocket is a sewn pocket along the bottom of a stage curtain. A chain or a pipe slides inside it to add weight. The weight makes the curtain hang straight and stops it swaying or leaving gaps at the floor.", "purpose_function": "It exists to hold weight or a stiffener at the hem so the drape stays flat and vertical instead of rippling. A chain lets the hem follow an uneven floor; a pipe keeps the hem straight and rigid.", "practical_application": "A drapery maker sews a chain pocket into a masking leg, or a pipe pocket into a cyclorama, so it hangs cleanly when flown.", "category": "Drapery construction", "related_terms": ["Chain pocket", "Pipe pocket", "Cyclorama", "Backdrop", "Fullness", "Black masking"], "common_mistakes": ["Confusing a chain pocket, which is weighted and flexible and seals to the floor, with a pipe pocket, which holds a rigid pipe for a flat, stiff hem.", "Letting the chain drag on the floor, which wears out the hem; the chain should be raised inside the pocket.", "Omitting a bottom weight or stiffener, so the drape ripples and hangs unevenly."], "scenario_contexts": ["Weighting the hem of a masking leg so it hangs straight.", "Inserting a pipe into a cyclorama's bottom pocket to keep it flat and wrinkle-free.", "Sealing a blackout drape to an uneven stage floor with a chain-weighted hem."]}, "7ddc0fbe-e78f-4043-9ce9-17fc2e0cc7b3": {"definition": "A common abbreviation for cyclorama: a large, smooth, usually light-coloured backdrop hung across the rear of the stage and lit to represent sky, open space, or a boundless background. It may be a seamless stretched cloth or a curved plaster/hard wall spanning the upstage area.", "plain_english": "Cyc is short for cyclorama. It is a big smooth backdrop at the back of the stage. Lights hit it to make a sky or open space.", "purpose_function": "It gives a clean, seamless surface that can be lit any colour, so designers can suggest sky, mood, or endless space without painted scenery.", "practical_application": "A lighting technician washes the cyc in blue to create a sky, then shifts it to warm tones for a sunset.", "category": "Backdrops", "related_terms": ["Cyclorama", "Scrim", "Backdrop", "Sky drop", "Ground row"], "common_mistakes": ["Assuming a cyc must be white; it is lit to any colour and its base fabric can be light grey or blue", "Confusing a cyc with a scrim; a scrim is a see-through gauze, while a cyc is a solid opaque surface", "Letting light spill or shadows from set pieces fall on the cyc, which breaks the illusion of open space"], "scenario_contexts": ["A lighting designer colour-washing the cyc to shift a scene from day to night", "A crew stretching and tensioning a seamless cyc across the upstage wall before a dance show"]}, "61000fda-ccb6-4d5a-80e8-fe03678a9c05": {"definition": "A large curved or flat backdrop, usually of seamless light-coloured cloth or a curved plaster wall, hung across the rear of the stage and evenly lit to represent the sky or a boundless background. The curve at the ends helps it appear to wrap the acting area and hide the offstage corners.", "plain_english": "A cyclorama is a big backdrop across the back of the stage. It is often curved at the sides. Lit evenly, it looks like the sky or open space.", "purpose_function": "It creates a smooth, seamless background that can be lit to any colour, giving depth and a sense of open space without detailed painted scenery.", "practical_application": "A designer lights the cyclorama in graded blues to suggest a daytime sky behind an outdoor scene.", "category": "Backdrops", "related_terms": ["Cyc", "Scrim", "Backdrop", "Ground row", "Sky drop"], "common_mistakes": ["Using the term only for cloth; a cyclorama can also be a permanent curved plaster wall", "Lighting a cyclorama unevenly, which creates hot spots and destroys the smooth sky effect", "Confusing a cyclorama with a scrim; the cyclorama is opaque, while a scrim can look solid or transparent depending on lighting"], "scenario_contexts": ["An opera lighting a cyclorama to shift smoothly from dawn to dusk across a scene", "A dance company using a plain cyclorama as a neutral, colour-changing backdrop for several pieces"]}, "c19ccab3-607b-4788-8525-f218e8f93635": {"definition": "A platform or section added to the existing stage deck to enlarge the playing surface, most often extending the stage forward over the orchestra pit or house floor, or building the deck outward beyond its permanent edge. It is typically built from stock platforms or staging decks levelled and secured flush with the existing deck height.", "plain_english": "A deck extension is extra platform added to make the stage bigger. Crews often build it out over the pit or into the seats.", "purpose_function": "It enlarges the usable stage for a given show, letting a production add a thrust, catwalk, or wider playing space the permanent deck does not provide.", "practical_application": "A crew bolts staging platforms over a covered orchestra pit to form a deck extension that brings performers closer to the audience.", "category": "Stage Platforms", "related_terms": ["Deck", "Platform", "Thrust stage", "Apron", "Orchestra pit"], "common_mistakes": ["UNSAFE: Building a deck extension over a pit or edge without rated support, guardrails, or adequate load capacity, risking collapse or a fall", "Failing to level and lock a deck extension flush with the main deck, leaving a trip hazard or gap", "Assuming any platform can hold performance loads without checking its rated capacity"], "scenario_contexts": ["A theatre extending the stage over a pit cover to add a thrust for a concert", "A touring crew adding a deck extension to match a set's downstage edge in a shallow venue"]}, "de8a7ac9-9ec2-4edc-b746-19e852a088f5": {"definition": "A curtain that opens and closes horizontally by drawing (traversing) along a track, with the fabric riding on carriers so the panels part to the sides or overlap at the centre. Also called a traveler or traverse curtain, it may be operated by hand lines or a motorized track.", "plain_english": "A draw curtain slides open and shut sideways along a track. Its panels pull apart to the sides, like curtains on a home window.", "purpose_function": "It lets crew open or close the stage picture from the sides without flying the fabric up and down, useful where there is little overhead height.", "practical_application": "A stagehand pulls the operating line to part the draw curtain and reveal the set at the top of the show.", "category": "Stage Curtains", "related_terms": ["Traveler", "Front curtain", "Grand curtain", "Masking", "Batten"], "common_mistakes": ["Confusing a draw curtain with a fly-out curtain; a draw curtain moves sideways on a track, not up and down", "Setting the wrong overlap at centre, leaving a gap that lets the audience see backstage", "Forcing a jammed carrier instead of clearing the track, which can tear the curtain or break the operating line"], "scenario_contexts": ["A school stage with low headroom using a draw curtain that parts to the sides", "A stage manager cueing a draw curtain to close for a scene change"]}, "07b2f944-0ef4-4d74-a8c0-42334aacdfac": {"definition": "A powered platform that raises and lowers a section of the stage, or performers and scenery, between stage level and areas above or below the deck. Also called a stage lift; common types include orchestra pit lifts, understage lifts, and scenery lifts driven by hydraulic, screw, or chain-drive mechanisms.", "plain_english": "An elevator lift is a powered part of the stage floor that moves up and down. Crews use it to raise or lower scenery, performers, or the pit.", "purpose_function": "It changes stage levels and moves heavy scenery or performers vertically, allowing fast reveals and level changes without carrying loads by hand.", "practical_application": "An operator lowers the orchestra pit lift to seat the musicians, then raises it later to extend the stage.", "category": "Stage Machinery", "related_terms": ["Elevator stage", "Orchestra pit lift", "Trap", "Understage", "Deck"], "common_mistakes": ["UNSAFE: Standing or reaching into the gap at a moving lift's edge, where a person can be caught in the shear point between platform and fixed floor", "UNSAFE: Loading a lift beyond its rated capacity or riding it without authorization, risking mechanical failure, a dropped load, or a fall", "Confusing an elevator lift, which moves vertically, with a revolve, which turns on one level"], "scenario_contexts": ["A venue lowering a pit lift to create an orchestra pit, then raising it to deck level for a play", "A crew raising a set piece from the understage on a scenery lift during a blackout"]}, "1616cd5a-2fe8-4352-934e-dedb697af893": {"definition": "A fire-rated barrier, usually of woven fibreglass or other flame-resistant fabric on a steel batten or frame, installed at the proscenium opening to separate the stage from the auditorium during a fire. It descends automatically on a signal such as a fusible link, heat/smoke detection, or loss of holding power, and by manual release, slowing the spread of smoke and flame and protecting audience egress. Also called a safety curtain or proscenium fire safety curtain.", "plain_english": "A fire curtain is a fireproof barrier at the front of the stage. In a fire it drops down to block flames and smoke from reaching the audience. This gives people time to get out.", "purpose_function": "It seals the proscenium opening in a fire, holding back smoke and flame so the audience can escape and firefighters can respond; building codes require it on many large proscenium stages.", "practical_application": "During a safety check, the crew confirms the fire curtain releases and lowers fully to the stage floor without obstruction.", "category": "Safety Systems", "related_terms": ["Proscenium", "Front curtain", "Smoke pocket", "Deluge system", "Flame retardant"], "common_mistakes": ["UNSAFE: Blocking the fire curtain's path or its smoke pockets with scenery, props, or cable, which can stop it sealing the opening in a fire", "UNSAFE: Disabling, tying off, or bypassing the automatic release to keep the curtain up, which defeats a required life-safety system", "Confusing the fire curtain with the decorative front curtain; the fire curtain is a rated fire barrier, not a show drape"], "scenario_contexts": ["A stage manager checking the fire curtain drops freely during a pre-show safety inspection", "A fire marshal requiring an unobstructed fire curtain path before allowing an audience into a proscenium house"]}, "02658d14-7bbb-49ad-baeb-9677738e078c": {"definition": "The primary curtain hung just upstage of the proscenium at the front of the stage, used to conceal the stage before the show and during scene changes and to open and reveal the acting area. Also called the main curtain, house curtain, act curtain, or grand drape; it may fly out, draw to the sides, or lift as a swag.", "plain_english": "The front curtain is the main curtain at the front of the stage. It hides the stage before the show, then opens to reveal it.", "purpose_function": "It hides the set before the performance and during changes, and its opening or closing marks the start and end of acts, framing the show for the audience.", "practical_application": "The stage manager calls the cue to open the front curtain as the house lights fade and the show begins.", "category": "Stage Curtains", "related_terms": ["Grand curtain", "Draw curtain", "Proscenium", "Teaser", "Fire curtain"], "common_mistakes": ["Confusing the front curtain, a decorative show drape, with the fire curtain, a rated safety barrier", "Assuming the front curtain always flies out; it may instead draw to the sides or lift as a swag", "Opening the front curtain before masking or scenery is set, revealing crew or an unready stage"], "scenario_contexts": ["A crew flying the front curtain out to reveal the opening scene", "A theatre closing the front curtain for an intermission scene change"]}, "1f963539-4d09-42de-a19e-85f4cb58e805": {"definition": "A reflective projection surface onto which an image is projected from the same side as the viewer, so the projector sits in front of the screen and light bounces back toward the audience. Surfaces are characterised by gain and viewing angle; theatrical versions may be a matte white or grey cloth, a rigid screen, or a seamless filled fabric hung as a drop.", "plain_english": "A front-projection screen shows an image beamed from the audience's side. The projector sits out front, and light bounces off the screen back to viewers.", "purpose_function": "It provides a bright, reflective surface for images projected from the front, so scenes, backgrounds, or video can be shown without a projector behind the stage.", "practical_application": "A crew flies in a white front-projection screen and aligns a front-mounted projector to display a moving backdrop.", "category": "Projection Surfaces", "related_terms": ["Rear-projection screen", "Cyclorama", "Scrim", "Backdrop", "Projector"], "common_mistakes": ["Confusing front projection with rear projection; front-projection light comes from the audience side, not from behind the screen", "Letting performers or set pieces block the projector beam, casting shadows on a front-projection screen", "Assuming any white cloth works equally; screen gain and viewing angle affect brightness and evenness"], "scenario_contexts": ["A conference using a front-projection screen fed by a projector hung over the audience", "A play projecting scenic images onto a front-projection screen behind the actors"]}, "dba71069-67be-466a-95bd-7dd50bc85f93": {"definition": "The main decorative curtain at the front of the stage, hung just behind the proscenium, that conceals the stage before the performance and opens to reveal the acting area. It is synonymous with the grand drape, main curtain, house curtain, or act curtain, and is often a rich, full-fullness fabric such as velour.", "plain_english": "The grand curtain is the main show curtain at the front of the stage. It is often plush fabric that hides the stage until the show starts.", "purpose_function": "It hides the set before the show and during changes and marks the start and end of acts, while its rich fabric frames the stage picture for the audience.", "practical_application": "A crew opens the grand curtain at the start of the show, then closes it for intermission.", "category": "Stage Curtains", "related_terms": ["Front curtain", "Draw curtain", "Proscenium", "Teaser", "Fire curtain"], "common_mistakes": ["Confusing the grand curtain, a decorative drape, with the fire curtain, a rated safety barrier", "Assuming the grand curtain always draws to the sides; it may instead fly out or lift as a swag", "Treating grand drape and act curtain as different curtains, when they usually name the same main front curtain"], "scenario_contexts": ["A theatre opening the grand curtain as the overture ends and the first scene begins", "A crew closing the grand curtain to mask a scene change between acts"]}, "e6f96cbd-19d9-412a-a0f3-6e54e8240e42": {"definition": "The large decorative curtain hung immediately upstage of the proscenium arch that closes the stage off from the audience before and after a performance and between acts; also called the house curtain, main curtain, main drape, or act curtain. It is typically a heavy, often pleated fabric such as velour and must meet flame-retardancy requirements for theatrical textiles.", "plain_english": "It is the big front curtain at a theater. It opens to start the show and closes to hide the stage.", "purpose_function": "It visually separates the stage from the audience, hides setup and scene changes, and marks the start, end, and act breaks of a show.", "practical_application": "A stagehand opens the grand drape at the top of the show and closes it at intermission to mask the scene change.", "category": "Soft Goods", "related_terms": ["House curtain", "Main curtain", "Proscenium", "Fire curtain", "Valance", "Traveler curtain"], "common_mistakes": ["Assuming the grand drape and the fire safety curtain are the same; the fire curtain is a separate fire-rated barrier, not the decorative front curtain", "UNSAFE: Using untreated or untested fabric for a grand drape; theatrical curtains must pass flame-retardancy testing before stage use"], "scenario_contexts": ["A crew flies in the grand drape for the pre-show look and opens it as the house lights dim", "A road house closes the grand drape between acts to reset scenery out of view"]}, "812449b2-904b-407b-8b06-f68ee6ade159": {"definition": "A protective barrier system installed along the exposed edges of an elevated stage platform, riser, or walkway to keep people from falling to a lower level. Under OSHA it consists of a top rail, an intermediate midrail, and supporting posts, with the top rail set about 42 inches above the walking surface and able to resist a 200-pound outward or downward force.", "plain_english": "It is a railing built along the edge of a raised platform. It stops people from falling off the side.", "purpose_function": "It provides fall protection at the open edges of raised work and performance surfaces, keeping crew and performers from stepping or falling over the edge.", "practical_application": "A carpenter fits guardrails to the open back and sides of a raised platform before anyone is allowed to work or perform on it.", "category": "Fall Protection", "related_terms": ["Handrail", "Platform", "Riser", "Toe board", "Deck", "Lift platform"], "common_mistakes": ["UNSAFE: Leaving the open edge of an elevated platform without a guardrail; OSHA requires fall protection at raised edges above the trigger height", "UNSAFE: Building a guardrail too low or too weak; the top rail must be about 42 inches high and withstand a 200-pound force", "Confusing a guardrail, which protects a platform edge, with a handrail, which is grasped for support on stairs"], "scenario_contexts": ["A crew guards the rear edge of a tall choir riser before the choir loads in", "An inspector checks that platform guardrails meet height and strength rules before a show opens"]}, "3364340c-6cc1-4622-9750-b3ae112e4409": {"definition": "A curtain or drop rigged to open and close by flying straight up and down as a single unit, rather than being drawn apart horizontally like a traveler. The name comes from its vertical, blade-like travel on a batten carried by lift lines.", "plain_english": "It is a curtain that lifts straight up and drops straight down. It moves like a window blind instead of sliding sideways.", "purpose_function": "It reveals or hides the stage with a fast vertical move, useful where there is no wing room to draw a curtain sideways or where a clean up-and-down reveal is wanted.", "practical_application": "An operator flies out a guillotine curtain to reveal a set instantly instead of parting a traveler from the center.", "category": "Soft Goods", "related_terms": ["House curtain", "Traveler curtain", "Drop", "Batten", "Fly system", "Kabuki drop"], "common_mistakes": ["Confusing a guillotine curtain with a traveler; a guillotine flies vertically while a traveler is pulled apart horizontally", "UNSAFE: Standing under a guillotine curtain or its batten as it flies in, where the moving batten and weights can strike a person"], "scenario_contexts": ["A production uses a guillotine curtain to drop in and reveal a scene between numbers", "A venue without wing space for a traveler rigs the front curtain to fly as a guillotine"]}, "a6febae5-8809-41f1-8ec1-4cff1e21e486": {"definition": "A graspable rail provided alongside stairs, ramps, and raised walkways to give hand support and help prevent falls. Under OSHA the handrail is set 30 to 38 inches above the stair tread nosing or walking surface, must be a graspable size, and must withstand a 200-pound force.", "plain_english": "It is a rail you hold onto while using stairs or a ramp. It gives your hand support so you do not slip and fall.", "purpose_function": "It gives people a secure handhold on stairs, ramps, and steep paths, reducing the chance of a slip or fall while moving between levels.", "practical_application": "A carpenter mounts a handrail beside the escape stairs off a raised platform so crew can steady themselves in the dark.", "category": "Fall Protection", "related_terms": ["Guardrail", "Stair unit", "Platform", "Ramp", "Escape stair", "Riser"], "common_mistakes": ["Treating guardrail and handrail as the same thing; a handrail is grasped for support, a guardrail blocks an edge", "UNSAFE: Setting a handrail at the wrong height or making it too thick to grip; it must be a graspable size and 30 to 38 inches high"], "scenario_contexts": ["A crew adds handrails to a set of stage stairs before actors use them in low light", "An inspector measures handrail height and grip size on backstage stairs before opening"]}, "d2caff2e-56a2-4857-ad6e-e3e1b9e103cc": {"definition": "The main curtain hung just upstage of the proscenium arch that separates the stage from the auditorium and opens and closes to begin, end, and break up a performance; also called the grand drape, main curtain, or act curtain. It is usually a heavy fabric such as velour and must meet theatrical flame-retardancy requirements.", "plain_english": "It is the main front curtain of a theater. It closes to hide the stage and opens when the show begins.", "purpose_function": "It masks the stage from the audience before and after the show and during act breaks, and its opening and closing frame the start and end of the performance.", "practical_application": "The operator closes the house curtain at intermission so the crew can change the set out of the audience's view.", "category": "Soft Goods", "related_terms": ["Grand drape", "Main curtain", "Traveler curtain", "Guillotine curtain", "Proscenium", "Fire curtain"], "common_mistakes": ["Confusing the house curtain with the fire safety curtain; the fire curtain is a separate fire-rated barrier at the proscenium", "UNSAFE: Rigging a heavy house curtain without checking line-set weight and locking the fly line, which risks a runaway batten"], "scenario_contexts": ["An operator opens the house curtain as the house lights fade for the top of the show", "A stage manager calls the house curtain closed at the end of the act"]}, "a32e4721-03f0-4392-bc38-88cb797600ff": {"definition": "A staging effect in which a piece of fabric or a drop is held up along a batten by a row of release devices and then falls to the deck all at once on cue, revealing whatever is behind it. Modern systems commonly use electromagnetic release units triggered electrically, a technique named after reveal effects in Japanese kabuki theatre.", "plain_english": "It is a curtain trick where fabric is held up, then dropped all at once. It falls to the floor to reveal a surprise behind it.", "purpose_function": "It creates a sudden, dramatic reveal by dropping fabric out of the way in an instant, faster and cleaner than flying or drawing a curtain.", "practical_application": "A crew loads a light drop onto electromagnetic kabuki releases and hits the trigger so the fabric falls on the downbeat to reveal the band.", "category": "Soft Goods", "related_terms": ["Drop", "Batten", "Guillotine curtain", "Fly system", "House curtain", "Masking"], "common_mistakes": ["UNSAFE: Firing a kabuki drop with crew or performers standing under the fabric and its hardware, which fall on release", "Assuming any heavy fabric works; kabuki fabric must be light enough to drop cleanly and be flame-retardant treated"], "scenario_contexts": ["A concert opener uses a kabuki drop to reveal the band on the first big hit", "An awards show drops a kabuki curtain to unveil a set piece on cue"]}, "a20ab930-ccd2-487f-8fa2-19e68cd7eb3a": {"definition": "A tall, narrow vertical curtain hung at the side of the stage, usually in pairs and in a series from downstage to upstage, used to mask the offstage wings from the audience and to help frame the acting area. Legs are typically flat, non-fullness drapes of a light-absorbing fabric such as velour and are used together with overhead borders.", "plain_english": "It is a tall, narrow curtain hung at the side of the stage. It hides the backstage side areas from the crowd.", "purpose_function": "It masks the offstage wing spaces from the audience's view and, with borders overhead, neatly frames the stage picture.", "practical_application": "A crew hangs a pair of legs at each wing position to hide the backstage area and create clean entrances.", "category": "Soft Goods", "related_terms": ["Legs", "Border", "Masking", "Wing", "Teaser", "Traveler curtain"], "common_mistakes": ["Confusing legs, which mask the sides, with borders, which mask overhead; they work as a set but cover different areas", "UNSAFE: Hanging a leg made of untreated fabric; stage masking must be flame-retardant treated to meet fire codes"], "scenario_contexts": ["A crew sets several pairs of legs down each side to mask the wings for a dance show", "A designer adjusts leg positions to tighten the sightlines into the offstage space"]}, "e350b375-946b-483f-a127-beab6cf27b6a": {"definition": "The set of tall, narrow vertical curtains hung at the sides of the stage, in pairs and in a series from downstage to upstage, that mask the offstage wings from the audience and help frame the acting area. They are usually flat, non-fullness drapes of a light-absorbing fabric such as velour and are used together with overhead borders.", "plain_english": "They are the tall, narrow curtains hung along the sides of the stage. They hide the backstage side areas from the crowd.", "purpose_function": "They mask the offstage wing spaces from the audience's view and, with borders overhead, neatly frame the stage picture.", "practical_application": "A crew hangs legs at each wing position to hide the backstage area and create clean entrances for performers.", "category": "Soft Goods", "related_terms": ["Leg", "Border", "Masking", "Wing", "Teaser", "Traveler curtain"], "common_mistakes": ["Confusing legs, which mask the sides, with borders, which mask overhead; they work as a set but cover different areas", "UNSAFE: Hanging legs made of untreated fabric; stage masking must be flame-retardant treated to meet fire codes"], "scenario_contexts": ["A crew sets several pairs of legs down each side to mask the wings for a dance show", "A designer moves the legs to tighten the sightlines into the offstage space"]}, "81f65165-981e-417d-ad10-f6d59122be3a": {"definition": "A powered platform, or section of stage floor, that raises and lowers on a mechanical lift to move performers, scenery, or equipment between the stage deck and levels above or below it. Also called a stage lift or elevator stage, it is rated for a specific working load and designed and operated to entertainment machinery standards.", "plain_english": "It is a platform that moves up and down like an elevator. It lifts people or scenery between the stage and the space below.", "purpose_function": "It changes stage levels and moves heavy loads or performers vertically, allowing fast reveals and scene changes without carrying items on and off.", "practical_application": "A crew loads a set piece onto the lift platform below the deck and raises it into place for the next scene.", "category": "Stage Machinery", "related_terms": ["Elevator stage", "Orchestra pit lift", "Trap", "Deck", "Understage", "Guardrail"], "common_mistakes": ["UNSAFE: Loading a lift platform beyond its rated capacity, which can overload the drive and cause a dropped or falling load", "UNSAFE: Standing or reaching into the gap between a moving lift platform and the fixed floor, a shear and crush point", "Confusing a lift platform, which changes height, with a revolve, which turns on one level"], "scenario_contexts": ["An opera house raises a full set from the understage on a lift platform during a blackout", "A concert venue brings a drum riser up to deck level on a lift platform between acts"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"ee84c9ea-9d0d-46bc-908e-af33588787f0": {"definition": "The primary curtain hung immediately upstage of the proscenium arch that opens and closes to reveal or conceal the stage from the audience before, after, and between the acts of a performance; also called the house curtain, grand drape, or act curtain. It is usually a heavy, often pleated fabric such as velour and must meet theatrical flame-retardancy requirements.", "plain_english": "It is the big front curtain in a theater. It opens to start the show and closes to hide the stage.", "purpose_function": "It separates the stage from the audience, hides setup and scene changes, and marks the start, end, and act breaks of a show.", "practical_application": "An operator opens the main curtain at the top of the show and closes it at intermission to hide the scene reset.", "category": "Soft Goods", "related_terms": ["House curtain", "Grand drape", "Proscenium", "Fire curtain", "Traveler curtain", "Valance"], "common_mistakes": ["Assuming the main curtain and the fire safety curtain are the same; the fire curtain is a separate fire-rated barrier at the proscenium", "UNSAFE: Using untreated or untested fabric for a main curtain; theatrical curtains must pass flame-retardancy testing before stage use"], "scenario_contexts": ["An operator opens the main curtain as the house lights fade for the top of the show", "A stage manager calls the main curtain closed at the end of the act so the crew can reset"]}, "ef399dac-f778-4d82-8fe7-a8cba8221d10": {"definition": "A sewn fabric sleeve running along the bottom hem of a stage masking drape, such as a leg, border, or black, into which a pipe, bar, or chain is inserted to weight the fabric so it hangs straight and flat. It is a form of the bottom pipe pocket or chain pocket used on hanging stage soft goods.", "plain_english": "It is a sewn sleeve at the bottom of a stage curtain. A pipe or chain slides inside to weigh the fabric down so it hangs flat.", "purpose_function": "It holds a weight pipe or chain so a masking drape hangs smoothly and straight instead of curling, wrinkling, or blowing around.", "practical_application": "A crew member slides a length of pipe into the masking pocket at the bottom of a leg so the drape hangs flat on stage.", "category": "Soft Goods", "related_terms": ["Leg", "Border", "Masking", "Pipe pocket", "Chain pocket", "Drop"], "common_mistakes": ["Confusing the bottom masking pocket with the tie-line webbing at the top of the drape; the pocket weights the bottom, the webbing hangs the top", "Loading a pipe that is too heavy or too long for the pocket, which can tear the hem or bow the fabric"], "scenario_contexts": ["A crew loads weight pipe into the bottom masking pockets of new legs during a hang", "A stagehand replaces a bent pipe in a border's masking pocket so the fabric hangs level"]}, "aa24b206-48f5-4ec4-95ab-dc97c6b911cb": {"definition": "A traveler curtain hung partway upstage, near the middle of the stage depth, that draws open and closed horizontally on a track to divide the stage into a shallow downstage playing area and a masked upstage space. It lets a scene play in front while the upstage area is set or masked behind it.", "plain_english": "It is a curtain that slides open and shut across the middle of the stage. It hides the back half so a scene can play up front.", "purpose_function": "It splits the stage into a shallow front area and a hidden back area, so one scene plays downstage while the crew resets the upstage behind the closed curtain.", "practical_application": "A crew closes the midstage traveler to play a scene in one while the next full set is built upstage out of the audience's view.", "category": "Soft Goods", "related_terms": ["Traveler curtain", "Track", "Masking", "In one", "Upstage", "House curtain"], "common_mistakes": ["Confusing a midstage traveler with the main house curtain at the proscenium; the traveler is set farther upstage", "Leaving a gap where the two panels meet at center, which breaks the masking and lets the audience see backstage"], "scenario_contexts": ["A touring show closes the midstage traveler to play a scene in one during a set change", "A dance concert uses a midstage traveler to shorten the stage for an intimate number"]}, "3b6d39f8-34ba-4b01-8773-2fb5c098a079": {"definition": "A height-adjustable stand with an angled desk or rack that holds sheet music or a score at a comfortable reading height for a seated or standing performer. Common types include the lightweight folding wire stand and the heavier orchestral stand with a solid desk, and stage models often accept a clip-on stand light.", "plain_english": "It is an adjustable stand that holds sheet music while you play. It sits at eye level so you can read and play at the same time.", "purpose_function": "It holds a performer's music at a readable angle and height so both hands stay free to play the instrument.", "practical_application": "A stagehand sets and adjusts the height of the music stands for the orchestra and clips a stand light onto each before the concert.", "category": "Stage Equipment", "related_terms": ["Podium", "Stand light", "Orchestra shell", "Orchestra pit", "Riser", "Choral riser"], "common_mistakes": ["Setting the desk too high so it blocks the sightline between the player and the conductor or audience", "Overloading a light folding wire stand with heavy binders so it tips or collapses"], "scenario_contexts": ["A crew places and adjusts the height of a music stand at each orchestra chair before a concert", "A pit musician clips a stand light to a music stand to read the score in a dark pit"]}, "39cb9d2c-2075-4524-b7c0-2d1c92c15b71": {"definition": "The overhead sound-reflecting element of an orchestra shell system, a suspended array of hard panels hung above the players that reflects and blends the ensemble's sound and projects it toward the audience. It works with the shell towers or rear wall to form an acoustic enclosure on the stage.", "plain_english": "It is a hard ceiling hung above the musicians. It bounces their sound back down and out toward the crowd so the group is heard clearly.", "purpose_function": "It reflects sound that would otherwise be lost upward into the fly space, helping musicians hear one another and sending a blended sound out to the audience.", "practical_application": "A crew flies in the orchestra canopy over the players and adjusts its height and tilt to blend the ensemble and project sound to the house.", "category": "Acoustic Equipment", "related_terms": ["Orchestra shell", "Reflector", "Ceiling reflector", "Orchestra pit", "Riser", "Music stand"], "common_mistakes": ["Thinking the canopy is only decoration; it is an acoustic reflector that shapes how the ensemble sounds, not just scenery", "UNSAFE: Flying a heavy canopy without verifying rigging capacity and fitting secondary safety attachments over the players below"], "scenario_contexts": ["A concert hall lowers the orchestra canopy to the correct height for a symphony program", "A crew removes the canopy and shell to switch the stage from a concert to a theatrical setup"]}, "93c26145-a677-443b-a485-3a5f0ca57201": {"definition": "A powered stage lift that raises and lowers the floor of the orchestra pit so the same area can serve as a sunken pit for musicians, an extension of the stage apron, or a continuation of the audience seating level. Also called an orchestra pit lift, it is rated for a specific working load and built and operated to entertainment machinery standards.", "plain_english": "It is a big platform that raises and lowers the orchestra pit floor. The same spot can become a pit, extra stage, or more seating.", "purpose_function": "It lets one area switch roles between an orchestra pit, a forestage, and audience seating, so a venue can be reset for different kinds of shows.", "practical_application": "A crew lowers the orchestra lift to seat the musicians below stage level, then raises it later to add rows of seats for a lecture.", "category": "Stage Machinery", "related_terms": ["Orchestra pit", "Lift platform", "Elevator stage", "Apron", "Forestage", "Trap"], "common_mistakes": ["UNSAFE: Loading the orchestra lift beyond its rated capacity, which can overload the drive and cause a dropped or falling load", "UNSAFE: Standing or reaching into the gap between the moving lift and the fixed floor, a shear and crush point", "Assuming a given lift can be stopped freely at any height by hand; depending on the system it may be limited to programmed or interlocked positions, so run it only to the levels and by the controls the machinery is set up for"], "scenario_contexts": ["An opera house lowers the orchestra lift to seat the pit orchestra below the stage", "A touring venue raises the orchestra lift to stage level to extend the apron for a concert"]}, "6a031292-cfd5-4d8d-a25b-b74d1560afce": {"definition": "A system of hard, movable panels and towers, often topped by an overhead canopy, that forms a partial enclosure around an orchestra or choir on stage to reflect and project their sound toward the audience. Also called an acoustic shell or bandshell, it is set up on a proscenium or open stage to improve on-stage ensemble hearing and blend.", "plain_english": "It is a set of hard walls and a ceiling placed around the musicians. It bounces their sound out to the audience instead of letting it escape backstage.", "purpose_function": "It reflects the ensemble's sound forward and helps players hear each other, replacing the soft, sound-absorbing backstage space with a hard, reflective enclosure.", "practical_application": "A crew rolls the shell towers into place and flies in the canopy to set the stage for a symphony concert.", "category": "Acoustic Equipment", "related_terms": ["Orchestra canopy", "Reflector", "Orchestra pit", "Riser", "Choral riser", "Music stand"], "common_mistakes": ["Thinking the shell is only scenery; it is an acoustic tool that shapes how the ensemble sounds", "UNSAFE: Rolling heavy shell towers without enough crew or without following the maker's setup and bracing steps, which risks a tip-over"], "scenario_contexts": ["A crew assembles the orchestra shell to convert a theater stage for a concert band", "A hall stores the shell towers offstage and rolls them out for classical programs"]}, "f1c29d23-6ac3-40dc-80c3-010d92f4a258": {"definition": "A small raised platform on which a person stands to be seen and elevated above others, most often the low platform a conductor stands on to lead an ensemble. The term is also used loosely for a lectern, but strictly a podium is the platform stood upon, while a lectern is the slanted stand a speaker reads from.", "plain_english": "It is a small raised platform a person stands on. A conductor uses one so the players can all see them.", "purpose_function": "It raises a conductor or speaker above the group so they can be seen, and for a conductor so the whole ensemble can follow their gestures.", "practical_application": "A stagehand places and levels the conductor's podium at the front of the orchestra and checks that it does not rock.", "category": "Stage Platforms", "related_terms": ["Riser", "Platform", "Lectern", "Music stand", "Rostrum", "Orchestra pit"], "common_mistakes": ["Calling a lectern a podium; a podium is the platform you stand on, while a lectern is the stand you read from", "Using a wobbly or unlevel podium; a conductor's podium must be stable and level for safe, confident use"], "scenario_contexts": ["A crew sets a conductor's podium at its spike mark before an orchestra concert", "A venue provides a low podium so a speaker can be seen over a standing audience"]}, "4b34324a-c748-46f1-aae6-9dba2d356921": {"definition": "A freestanding, movable stair unit used to provide access between stage levels, such as from the house floor or wings up onto a platform or stage, and often fitted with a handrail. Also called a step unit or escape stair, it is built or rated to code for tread depth, riser height, and load, and is positioned and secured wherever temporary access is needed.", "plain_english": "It is a set of movable steps you can place where needed. Crew and performers use them to get on and off a raised stage or platform.", "purpose_function": "It gives safe, movable access between two levels where no fixed stair exists, such as onto a platform, riser, or the stage edge.", "practical_application": "A crew rolls portable stairs to the front of a raised platform and locks them in place so actors can climb up safely.", "category": "Stage Access", "related_terms": ["Stair unit", "Escape stair", "Handrail", "Guardrail", "Platform", "Riser"], "common_mistakes": ["UNSAFE: Using portable stairs without locking the wheels or securing the unit, so it rolls or shifts underfoot", "UNSAFE: Building steps with uneven riser heights or missing a required handrail, which causes trips and falls", "Assuming any steps meet code; tread depth, riser height, and load must meet stair standards"], "scenario_contexts": ["A crew sets portable stairs at a platform edge so performers can enter from the house", "A load-in uses portable stairs to reach a tall riser until a permanent stair is built"]}, "441e3c04-1cc7-42cd-850c-c48ca23a0c87": {"definition": "A flat viewing surface, typically a matte or gain-treated white or grey fabric or vinyl, onto which images from a projector are cast for an audience. In front-projection use the projector and audience are on the same side, so the image is reflected off the screen surface back toward the viewers.", "plain_english": "It is a flat surface, usually white cloth, that a projector shines images onto. The audience watches the picture on it.", "purpose_function": "It provides a controlled, even surface that reflects projected light so images appear bright and sharp to the audience rather than washing out on scenery or walls.", "practical_application": "A technician flies in or sets up a front-projection screen and aims the projector from the audience side, then focuses and keystone-corrects the image.", "category": "Projection", "related_terms": ["Rear-projection screen", "Cyclorama", "Scrim", "Projector", "Screen gain", "Backdrop"], "common_mistakes": ["Confusing a front-projection screen with a rear-projection screen; the projector position and screen material differ between the two", "Placing performers or scenery between a front projector and the screen, which casts unwanted shadows onto the image", "UNSAFE: Using an untested fabric screen on stage; theatrical textiles and drops must pass flame-resistance testing before use"], "scenario_contexts": ["A corporate event uses a large front-projection screen for slides while presenters stand to the side to avoid casting shadows", "A theatre flies a projection screen in for a scene with video content and flies it out afterward"]}, "ad579f80-7ab4-4c35-9ec4-c9fd5e1dddff": {"definition": "A sloped, walkable surface that connects two levels of differing height, used to move performers, wheeled scenery, or equipment between the stage floor and a raised platform or between the stage and offstage. An accessible ramp is limited to a maximum running slope of 1:12 (one unit of rise per twelve units of run) under building accessibility requirements.", "plain_english": "It is a sloped surface that links two levels. People and wheeled gear can roll up or down it instead of using stairs.", "purpose_function": "It bridges a height difference smoothly so wheeled loads and people can transition between levels without steps, and provides accessible routes on and around the stage.", "practical_application": "A carpenter builds a ramp to roll a wagon or wheelchair from house level onto a raised deck, keeping the slope within code limits and adding edge protection.", "category": "Platforms", "related_terms": ["Platform", "Riser", "Deck", "Wagon", "Guardrail", "Rolling platform"], "common_mistakes": ["UNSAFE: Building a ramp too steep; an accessible ramp must not exceed a 1:12 running slope, and steep ramps are a fall and tipping hazard", "UNSAFE: Leaving an elevated ramp edge unguarded; open edges above the fall-protection trigger height need guardrails or edge protection", "Using a slick surface on a ramp; ramps carrying foot or wheel traffic need a slip-resistant finish"], "scenario_contexts": ["A crew installs a ramp so a rolling platform can be pushed up onto a raised stage deck during a scene change", "A venue adds a code-compliant accessible ramp to give wheelchair access between the audience floor and the stage"]}, "a569ddc6-7478-4a59-8859-6dbe35340f83": {"definition": "A traveler curtain hung near the upstage (rear) area of the stage that opens and closes horizontally on a track. It is used to mask the back of the stage, close off an upstage area, or create a shallower playing space in front of it.", "plain_english": "It is a curtain near the back of the stage that opens and closes sideways. It hides the back area or makes the stage shallower.", "purpose_function": "It provides an upstage masking and division line that can be opened or closed during a show to hide backstage areas or reveal an upstage scene.", "practical_application": "A stagehand closes the rear traveler to create a shallow scene downstage, then opens it to reveal a full-depth set behind.", "category": "Soft Goods", "related_terms": ["Traveler curtain", "Midstage traveler", "Grand drape", "Backdrop", "Cyclorama", "Curtain track"], "common_mistakes": ["Confusing the rear traveler with a fixed backdrop; a traveler runs on a track and opens sideways rather than hanging static", "Overlooking that the rear traveler defines a masking line, so gaps or overlap at center may reveal the backstage area"], "scenario_contexts": ["A dance show closes the rear traveler to hide a set change happening upstage", "A concert uses the rear traveler as a neutral backing behind the performers"]}, "887747e0-a8ec-45b6-9870-5550decad96d": {"definition": "A translucent screen onto which an image is projected from behind, so the audience views the transmitted image from the opposite (front) side. Because the projector is behind the screen, performers can stand in front of the image without casting shadows on it.", "plain_english": "It is a see-through screen. The projector sits behind it, so actors in front do not cast shadows on the picture.", "purpose_function": "It lets projected images be shown with the projector hidden backstage and keeps performers and scenery in front of the image from blocking the light path or casting shadows.", "practical_application": "A technician places the projector upstage of a translucent screen and, when needed, flips the image horizontally so text and graphics read correctly from the audience.", "category": "Projection", "related_terms": ["Projection screen", "Scrim", "Cyclorama", "Projector", "Screen gain", "Backdrop"], "common_mistakes": ["Forgetting to horizontally flip (mirror) the source image, so text appears reversed to the audience", "Confusing rear projection with front projection; rear projection needs a translucent screen and backstage throw space behind it", "UNSAFE: Using an untested fabric or film screen on stage; theatrical projection textiles must meet flame-resistance requirements"], "scenario_contexts": ["A theatre projects a moving skyline from backstage onto a rear-projection screen so actors can perform in front of it", "A TV or corporate set uses rear projection to keep projectors and cabling hidden behind the screen"]}, "fe2936a5-01ca-4dd9-97e5-4afcdea39957": {"definition": "A rigid, sound-reflective panel, often of hardwood, laminate, or clear acrylic, placed overhead or as part of an acoustic shell to reflect sound energy toward the audience and back to performers. It redirects early reflections to improve projection, clarity, and the ability of performers to hear one another on stage.", "plain_english": "It is a hard, smooth panel hung above the stage. It bounces sound out to the crowd and back to the players.", "purpose_function": "It exists to reflect and direct acoustic energy, boosting loudness and clarity for the audience and helping ensemble members hear each other so they can stay together.", "practical_application": "A crew positions or angles overhead reflector panels above an orchestra or choir to project sound outward and reinforce onstage ensemble hearing.", "category": "Acoustics", "related_terms": ["Acoustic shell", "Orchestra shell", "Retractable acoustic curtain", "Reverberation", "Sound absorption", "Cyclorama"], "common_mistakes": ["Confusing a reflector panel, which reflects sound, with an absorptive panel or curtain, which soaks sound up", "Angling reflector panels poorly, so reflections miss the audience or create uneven or harsh sound onstage"], "scenario_contexts": ["An orchestra concert uses overhead reflector panels to project the ensemble's sound into a large hall", "A choir rehearsal room uses reflector panels so singers can hear one another and stay in tune"]}, "bb97287f-4720-4b07-b78e-6addb3276270": {"definition": "A heavy sound-absorbing drape that can be deployed or withdrawn, usually on a track or motorized system, to vary a room's acoustics. Deployed, it absorbs sound energy to reduce reverberation; retracted and stored, it uncovers reflective surfaces so the room sounds more live.", "plain_english": "It is a thick drape that can be pulled out or hidden away. Out, it soaks up sound; hidden, the room sounds more lively.", "purpose_function": "It provides variable acoustics, letting one space be tuned drier for speech or amplified sound and more reverberant for acoustic music by covering or uncovering absorptive area.", "practical_application": "A technician deploys retractable acoustic curtains to cut reverberation for a rock show, then retracts them for an orchestral concert that wants a livelier room.", "category": "Acoustics", "related_terms": ["Variable acoustics", "Sound absorption", "Reverberation", "Acoustic shell", "Reflector panel", "Curtain track"], "common_mistakes": ["Assuming any stage curtain changes acoustics meaningfully; effective absorption needs enough mass, area, and coverage", "Expecting curtains to block sound between rooms; they mainly absorb within a room rather than isolate it", "UNSAFE: Installing an untreated acoustic drape on stage; theatrical textiles must meet flame-resistance requirements before use"], "scenario_contexts": ["A multipurpose hall deploys retractable acoustic curtains to make the room drier for an amplified conference session", "A rehearsal room retracts its acoustic curtains to add liveliness for a string quartet"]}, "943a9b10-e811-407b-a237-b5e0358c660e": {"definition": "In scene changes and stage automation, the end position to which a moving scenic element—such as a curtain, wagon, deck, or drop—travels in order to uncover (reveal) a previously hidden scene, performer, or object to the audience. It is one of the named target positions an automated or manually run element is set to reach on a cue.", "plain_english": "It is the spot where a moving set piece or curtain stops. There it uncovers a scene or object for the crowd to see.", "purpose_function": "It defines the exact stopping point that exposes the intended stage picture, so a reveal lands cleanly and repeatably on the cue every performance.", "practical_application": "An automation operator programs the reveal position as a target so a wagon or drape stops precisely where the hidden scene becomes visible.", "category": "Scene Changes", "related_terms": ["Traveler curtain", "Wagon", "Rolling platform", "Deck", "Backdrop", "Cue"], "common_mistakes": ["Setting the reveal position short or long, so scenery or masking still hides part of the intended picture", "Assuming every performance needs no adjustment; drift in tracks or rigging can shift where the element actually stops"], "scenario_contexts": ["A magic-style reveal moves a drape to its reveal position to expose a performer who was hidden behind it", "A wagon rolls to its programmed reveal position, uncovering a new set for the next scene"]}, "678034dc-c37b-4abe-a9f2-2b8e31e0709b": {"definition": "A raised platform section used to elevate performers, an ensemble, or equipment above the stage or floor, such as choral, orchestra, or drum risers; in staircase construction the term also denotes the vertical face between two consecutive treads. Modular risers are commonly built as framed platform units with defined height and load ratings.", "plain_english": "It is a low platform that lifts performers up. A choir or drummer stands on one so the crowd can see them.", "purpose_function": "It raises people or gear above surrounding levels to improve sightlines and separation, letting the audience see rear rows of performers and giving instruments their own elevated area.", "practical_application": "A crew sets modular choral risers in stepped tiers so a choir's back rows are visible, adding guardrails on the exposed rear edges.", "category": "Platforms", "related_terms": ["Platform", "Deck", "Guardrail", "Tread", "Rolling platform", "Ramp"], "common_mistakes": ["UNSAFE: Leaving the exposed rear or side edge of a tall riser without a guardrail; open elevated edges above the trigger height need fall protection", "UNSAFE: Overloading a riser past its rated capacity; each platform has a stated load limit that must not be exceeded", "Confusing the platform sense of riser with the stair sense, the vertical board between two treads"], "scenario_contexts": ["A choir stands on tiered risers so every singer is visible and heard over the group in front", "A band places its drum kit on a drum riser to raise and separate it on a concert stage"]}, "d28b5b1e-e458-488d-8845-6cd70e10ddb4": {"definition": "A stage platform mounted on casters so it can be moved on and off stage or repositioned during scene changes; functionally a wagon carrying scenery, performers, or equipment. Casters are typically lockable or braked so the unit can be held stationary once placed.", "plain_english": "It is a platform on wheels. The crew rolls it on and off stage to change scenes fast.", "purpose_function": "It lets a whole set piece or group of performers be moved quickly and quietly as a unit, speeding scene changes without carrying scenery piece by piece.", "practical_application": "A crew preloads a set onto a rolling platform offstage, rolls it into position on a cue, and locks the casters before anyone steps on.", "category": "Platforms", "related_terms": ["Wagon", "Caster", "Platform", "Deck", "Jack", "Riser"], "common_mistakes": ["UNSAFE: Failing to lock or brake the casters before use; an unlocked rolling platform can shift under performers and cause falls", "UNSAFE: Exceeding the platform's or casters' rated load; overloading can collapse the unit or cause loss of control while moving", "Confusing a rolling platform with a fixed platform; the caster mount changes its stability and how it must be secured"], "scenario_contexts": ["A crew rolls a fully dressed room set onstage on a wagon during a blackout, then locks it in place", "A performer is revealed atop a rolling platform that is pushed into view on a cue"]}, "3d7551a6-fc68-4f08-98d9-5f782c202979": {"definition": "A scenic wagon is a low rolling platform mounted on casters on which scenery is built or placed so an entire set piece or setting can be moved on and off stage as a single unit. Also called a wagon or truck, it may be pushed by hand, tracked, or driven by cable, winch, or an air-caster system.", "plain_english": "A scenic wagon is a large rolling platform on wheels. Crews build scenery on top of it. Then they roll the whole set on and off the stage as one piece.", "purpose_function": "It exists to shift large or heavy scenery quickly and quietly as one unit, so a full setting can appear or clear in a single move instead of many hand-carried pieces.", "practical_application": "A crew builds a room set on a scenic wagon in the wings, then rolls it into place during a blackout for the next scene.", "category": "Stage Platforms", "related_terms": ["Wagon", "Truck", "Revolve", "Caster", "Stage deck", "Tracking"], "common_mistakes": ["Confusing a scenic wagon, which rolls in a straight or tracked path, with a revolve, which turns in place on a pivot", "Building a tall set high on a wagon without checking its balance, so the wagon becomes top-heavy and can tip when moved", "UNSAFE: Exceeding the wagon's rated load or using casters not rated for the weight, risking a caster failure or collapse under performers and scenery"], "scenario_contexts": ["Rolling a complete room setting on and off stage during a scene change", "Tracking a large set unit downstage on a guided wagon for a reveal", "Moving heavy scenery quietly on casters instead of carrying it piece by piece"]}, "826cdb42-1c51-48ee-9778-94edce6e02c3": {"definition": "A scrim is an open-weave gauze fabric hung on stage that reads as an opaque, solid surface when lit from the front and becomes transparent when front light is removed and the scene behind it is lit. This selective opacity lets designers make a painted picture appear to dissolve into a revealed scene, or create haze and depth effects.", "plain_english": "A scrim is a loosely woven cloth used on stage. Lit from the front, it looks solid. Lit from behind instead, it turns see-through. This lets a scene appear or vanish.", "purpose_function": "It exists to switch between opaque and transparent purely with lighting, so a crew can reveal or hide a scene, or add a soft, hazy layer of depth, without moving any scenery.", "practical_application": "A lighting designer front-lights a painted scrim to show a solid backdrop, then fades the front light and brings up the scene behind to make the backdrop dissolve away.", "category": "Soft goods / scrim", "related_terms": ["Sharkstooth scrim", "Bobbinet", "Cyclorama", "Backdrop", "Gauze", "Soft goods"], "common_mistakes": ["Confusing a scrim, an open-weave gauze that can turn transparent, with an opaque backdrop or cyclorama that never sees through", "Lighting the scrim from an angle that lets front light spill onto the scene behind, which spoils the solid-to-transparent effect", "UNSAFE: Hanging a scrim that is not flame-retardant to NFPA 701, which is required for stage fabrics over performers and audiences"], "scenario_contexts": ["Making a painted backdrop dissolve to reveal a scene behind it by shifting the lighting", "Adding a soft, hazy layer in front of the action to give a dream or memory look", "Using a black scrim downstage to hide performers until they are back-lit for an entrance"]}, "99bda5e0-aed8-4cea-83d0-21b0d3164c1a": {"definition": "A sharkstooth scrim is a specific scrim woven with a rectangular open mesh, its warp and fill forming a pattern likened to a shark's teeth, giving the most opaque appearance of the common scrims when front-lit while still turning transparent when lit from behind. It is the standard theatrical scrim for the solid-to-transparent reveal effect and is widely available in black or white, seamless in tall drop heights.", "plain_english": "A sharkstooth scrim is a type of stage gauze with a wide, open weave. Front light makes it look solid. Light behind it makes it turn see-through. It gives the cleanest appear-and-vanish effect of the scrims.", "purpose_function": "Its rectangular open weave gives a strong solid look under front light yet clears to transparency when back-lit, so it is chosen when the crispest dissolve or reveal is needed.", "practical_application": "A crew hangs a black sharkstooth scrim downstage, front-lights it as a solid wall, then reveals performers behind it by cross-fading to light upstage of the scrim.", "category": "Soft goods / scrim", "related_terms": ["Scrim", "Bobbinet", "Cyclorama", "Backdrop", "Gauze", "Soft goods"], "common_mistakes": ["Assuming any netting behaves like a sharkstooth scrim; bobbinet has a finer hexagonal mesh and reads more transparent, giving a different effect", "Letting stray front light hit a sharkstooth scrim you want transparent, which keeps it looking solid and kills the reveal", "UNSAFE: Rigging a sharkstooth scrim that has not been treated or certified flame-retardant to NFPA 701 for stage use"], "scenario_contexts": ["Creating a sharp solid-to-transparent reveal of performers or scenery in a musical or play", "Hanging a painted sharkstooth scrim as a solid drop, then dissolving it to the scene behind", "Choosing a sharkstooth over finer netting when the most opaque front-lit look is needed"]}, "bf827d49-15e4-468b-81c0-813f105a617a": {"definition": "A shell ceiling panel is a hard, sound-reflecting overhead panel that forms the roof, or canopy, of an acoustic (orchestra) shell, suspended or supported above the players to reflect their sound forward and downward toward the audience. Panels are typically rigid, low-porosity surfaces angled to project sound and to return early reflections that help musicians hear one another.", "plain_english": "A shell ceiling panel is a hard panel placed above an orchestra. It is the roof of the acoustic shell. It bounces the players' sound out to the audience and back to the musicians.", "purpose_function": "It caps the acoustic shell overhead so sound that would otherwise escape upward is reflected out to the house, raising loudness and clarity and giving the ensemble early reflections to play together.", "practical_application": "Stage crew fly in or raise the shell ceiling panels above the platform towers before an orchestral concert, then adjust their height and angle for the program.", "category": "Acoustic shell", "related_terms": ["Shell tower", "Stage enclosure", "Acoustic shell", "Ceiling reflector", "Concert-hall cloud", "Early reflections"], "common_mistakes": ["Confusing a reflecting shell ceiling panel, which projects sound, with an absorptive treatment that soaks sound up", "Assuming the panels are cosmetic; their hard, angled surfaces are tuned to direct sound and change the stage's acoustics", "UNSAFE: Suspending shell ceiling panels without rated rigging hardware and secondary safety cables, risking a fall of a heavy panel onto people below"], "scenario_contexts": ["Capping an acoustic shell overhead before an orchestral concert to project sound to the house", "Adjusting the height or angle of ceiling panels to tune stage support for different ensembles", "Reflecting early sound back to musicians so they can hear each other on a large stage"]}, "75366efb-758a-4bd0-baff-d4d5d717da06": {"definition": "A shell tower is a tall, hard-walled, self-standing or tracked unit placed at the sides and rear of an orchestra platform that forms a vertical wall of the acoustic (orchestra) shell, reflecting sound outward to the audience and inward to the players. Towers are usually mounted on casters for setup and storage and are locked and often ganged together to form the shell's side and back enclosure.", "plain_english": "A shell tower is a tall unit with a hard wall placed beside and behind an orchestra. Towers form the side and back walls of the acoustic shell. They reflect sound to the audience and help players hear each other.", "purpose_function": "It provides the vertical reflecting walls of an acoustic shell, keeping the players' sound from spilling into the wings and returning it to the house and to the ensemble for better blend and support.", "practical_application": "Crew roll the shell towers out of storage, set them in an arc around the platform, lock the casters, and gang them before a concert.", "category": "Acoustic shell", "related_terms": ["Shell ceiling panel", "Stage enclosure", "Acoustic shell", "Ceiling reflector", "Caster", "Early reflections"], "common_mistakes": ["Confusing a shell tower, a hard reflecting wall unit, with soft masking that absorbs and hides rather than reflects sound", "Leaving casters unlocked or towers unganged, so a tall, top-heavy tower can roll or tip", "UNSAFE: Moving or standing tall shell towers without following the manufacturer's stability, ballast, and locking procedures, risking a tip-over that can crush a person"], "scenario_contexts": ["Setting shell towers in an arc around an orchestra platform to form the shell's side and back walls", "Rolling towers out of storage and ganging them together before a concert", "Keeping the players' sound out of the wings so more of it reaches the audience"]}, "94e4777e-929e-4417-9d3e-9cf0f227a42a": {"definition": "Soft goods is the collective term for the fabric elements used on a stage, including curtains, drops, legs, borders, tabs, scrims, and cycloramas, as distinct from the hard scenery built of wood and metal. In professional practice these fabrics are expected to be flame-retardant treated to meet stage fire codes such as NFPA 701.", "plain_english": "Soft goods is the general name for all stage fabrics and curtains. It covers drops, legs, borders, and scrims. The name separates cloth items from scenery built of wood and metal.", "purpose_function": "The term groups all stage fabrics together so crews, designers, and rental houses can specify, order, hang, and maintain drapery and drops as one class of equipment with shared handling and fire-safety needs.", "practical_application": "A production electrician or stagehand pulls the soft goods package, curtains, borders, legs, and a cyc, from stock and hangs each on its assigned batten.", "category": "Soft goods", "related_terms": ["Drapery", "Masking", "Leg", "Border", "Backdrop", "Scrim"], "common_mistakes": ["Using soft goods to mean only the main curtain; the term covers all stage fabrics, including legs, borders, drops, and scrims", "Confusing soft goods (fabric) with hard scenery (built flats and platforms)", "UNSAFE: Treating soft goods as ordinary fabric; stage soft goods must be flame-retardant to NFPA 701 and re-treated or replaced when the treatment no longer passes"], "scenario_contexts": ["Pulling and hanging a soft-goods package of curtains, legs, borders, and a cyc for a show", "Specifying and ordering stage fabrics from a rental house as one class of equipment", "Checking flame-retardant certification on all soft goods before a fire inspection"]}, "103c036e-51e7-47d5-9f94-6e6dc47a5ba2": {"definition": "A sound curtain is a heavy, high-mass, often quilted or multi-layer fabric barrier hung to reduce airborne sound transmission or absorb noise, used to isolate or quiet a space rather than to mask sightlines. Constructions typically combine a mass-loaded barrier layer with an absorptive facing, and stage-rated versions are made flame-retardant to codes such as NFPA 701.", "plain_english": "A sound curtain is a heavy curtain made to block or soak up noise. It is thick and often padded. Crews hang it to keep sound in or out of a space, like a movable soundproof wall.", "purpose_function": "It exists to control noise, adding mass to block sound passing through and an absorptive face to cut reflections, giving a portable way to isolate or quiet an area without building a permanent wall.", "practical_application": "A crew hangs sound curtains around a noisy generator or between a rehearsal area and a live stage to lower the noise reaching the other side.", "category": "Soft goods / acoustic", "related_terms": ["Blackout drape", "Acoustic panel", "Soft goods", "Masking", "Sound absorption", "Noise control"], "common_mistakes": ["Assuming a sound curtain blocks noise like a solid wall; a hung curtain reduces sound but does not fully soundproof a space", "Confusing a sound curtain, built for noise control, with light masking drapes, which only hide offstage areas", "UNSAFE: Installing a sound curtain that is not flame-retardant to NFPA 701 in a stage or assembly space, creating a fire hazard"], "scenario_contexts": ["Hanging sound curtains around a noisy generator or compressor to lower the noise it puts out", "Dividing a rehearsal area from a live stage to cut sound bleeding between them", "Adding a temporary acoustic barrier where building a permanent wall is not practical"]}, "d5182791-d3db-4cf5-bcce-46b205802fc5": {"definition": "The stage deck is the working walking-and-performing surface of the stage, the top layer of the stage floor or of a raised platform system on which the action takes place. It may be a permanent floor or an assembly of modular platform units (decks) whose tops are levelled and joined flush to form a continuous performance surface.", "plain_english": "A stage deck is the working floor of the stage. It is the flat surface performers stand and move on. Many stages are built from modular deck pieces joined level and flush.", "purpose_function": "It provides a level, load-bearing surface for performers, scenery, and equipment, and when built from modular decks it lets crews assemble stages and raised areas of many shapes and heights.", "practical_application": "A crew bolts modular decks onto legs or supports, levels them, and locks them together flush to build the stage deck for an event.", "category": "Stage Platforms", "related_terms": ["Deck", "Platform", "Stage floor", "Subfloor", "Sprung floor", "Scenic wagon"], "common_mistakes": ["Leaving decks slightly uneven or with gaps at their joints, creating a trip hazard on the stage deck", "Confusing the finished stage deck (the surface) with the supporting structure of legs and framing beneath it", "UNSAFE: Loading a stage deck beyond its rated capacity or supporting it inadequately, or leaving open edges without guardrails, risking collapse or a fall"], "scenario_contexts": ["Building a raised stage from modular decks for a concert or event", "Levelling and locking deck units flush so performers have a smooth, safe surface", "Adding guardrails and checking load ratings on an elevated stage deck before use"]}, "d58adf51-2709-4f1a-a753-d47541fe108d": {"definition": "A stage enclosure is an assembly of hard, sound-reflecting panels, side and rear towers plus overhead ceiling panels, set up around a performing group to project and blend their sound toward the audience; it is the general term for an acoustic (orchestra) shell or band shell. By surrounding the players with reflecting surfaces, it keeps sound from escaping into the fly loft and wings and returns early reflections to the ensemble.", "plain_english": "A stage enclosure is a set of hard panels placed around an orchestra or band. It surrounds the players at the sides, back, and above. It blends their sound and sends it out to the audience.", "purpose_function": "It exists to turn an open, absorptive stage house into a reflective room around the players, so more of their sound reaches the audience with better loudness, clarity, and ensemble blend.", "practical_application": "Before an orchestral concert, crew set up the stage enclosure by rolling the shell towers into an arc and flying in or raising the ceiling panels above them.", "category": "Acoustic shell", "related_terms": ["Acoustic shell", "Shell tower", "Shell ceiling panel", "Ceiling reflector", "Concert-hall cloud", "Early reflections"], "common_mistakes": ["Confusing a stage enclosure, made of hard reflecting panels, with soft masking, which absorbs and hides instead of reflecting sound", "Assuming the enclosure is only decorative; its reflecting surfaces materially change the stage's loudness and blend", "UNSAFE: Assembling shell towers and overhead ceiling panels without the maker's stability, ballast, locking, and rated-rigging procedures, risking a tip-over or a fall of overhead panels"], "scenario_contexts": ["Setting up an acoustic shell around an orchestra before a concert to project their sound", "Converting an open, absorptive stage house into a reflective room for acoustic music", "Striking and storing the enclosure's towers and panels after the performance"]}, "ead33b86-f311-49b8-8ba5-4ca2ec82ba05": {"definition": "A raised, load-bearing horizontal deck built to create an elevated performance, seating, or working surface on stage. A standard unit has a rigid framed top skinned with plywood, carried on removable legs or a scaffold-type substructure, and is rated for a design live load; exposed edges above the trigger height require guardrails.", "plain_english": "It is a raised floor section built on the stage. It gives actors or gear a higher place to stand.", "purpose_function": "It builds elevation and levels into the stage picture so performers, choirs, orchestras, or scenery can be raised for sightlines, staging, or seating.", "practical_application": "A carpenter bolts platform units together, sets them on legs to the called height, and adds guardrails before crew or performers go up.", "category": "Stage Platforms", "related_terms": ["Riser", "Deck", "Stage stairs", "Guardrail", "Handrail", "Lift platform"], "common_mistakes": ["UNSAFE: Loading a platform beyond its rated live load, which can overstress the frame or legs and cause a collapse", "UNSAFE: Leaving an elevated platform edge unguarded; open edges above the OSHA trigger height require a guardrail", "Assuming any platform height is stable without bracing or attaching units together, allowing the assembly to rack or tip"], "scenario_contexts": ["A crew builds tiered platforms to raise a choir and orchestra for a concert", "A stagehand levels platform legs on an uneven floor and locks the units together before a set loads in"]}, "11208be4-045d-4abf-8200-1c45f2c0ff0c": {"definition": "A self-contained stair unit built to give access between stage levels, platforms, or between the stage and the auditorium; also called a stair unit or step unit. Each step has a uniform riser height and tread depth, and units used for egress or crew access must meet stair-geometry and handrail requirements.", "plain_english": "These are a set of steps built for the stage. They let people move safely between stage heights.", "purpose_function": "They provide safe vertical access between platforms, decks, and floor levels so performers and crew can move between heights without jumping or climbing.", "practical_application": "A carpenter builds a stair unit to fit a platform's height, keeps the risers even, and fits a handrail before the stairs are used.", "category": "Stage Platforms", "related_terms": ["Stage platform", "Riser", "Handrail", "Escape stair", "Deck", "Guardrail"], "common_mistakes": ["UNSAFE: Building steps with uneven riser heights, which creates a trip-and-fall hazard because people misjudge the next step", "UNSAFE: Omitting a handrail on stairs used for access or egress, removing the handhold that helps prevent falls", "Confusing stage stairs used by performers with code-compliant egress stairs, which must meet building-code geometry"], "scenario_contexts": ["A crew adds a stair unit off the back of a platform so actors can exit into the wings", "A stagehand fits handrails to stage stairs used in low light before a show opens"]}, "54c0d610-5af3-4309-8cc3-eea5a0383393": {"definition": "An opening built into the stage floor, fitted with a removable or hinged cover, through which performers, scenery, or effects can pass between the stage deck and the space below it. Named types include the grave trap, corner trap, and star trap; the trap opens into an understage trap room and is an open-hole fall hazard when uncovered.", "plain_english": "It is a hidden door in the stage floor. Actors or props can pass through it from below.", "purpose_function": "It links the stage deck to the space beneath, allowing entrances, exits, disappearances, and scenery moves from below the floor.", "practical_application": "A crew opens a grave trap for an actor to rise from the understage, then closes and secures the cover once the effect is done.", "category": "Stage Machinery", "related_terms": ["Trap room", "Understage", "Lift platform", "Deck", "Grave trap", "Stage platform"], "common_mistakes": ["UNSAFE: Leaving an open trap unguarded or unlit, creating a fall-through hazard for anyone crossing the deck", "UNSAFE: Standing or working directly under an open trap where a person or object can fall onto you from the deck", "Assuming every stage has traps; a trap needs an understage space below the deck to open into"], "scenario_contexts": ["A production stages a ghost rising through a grave trap during a blackout", "A stage manager guards an open trap with crew and a marker while it is used across a scene"]}, "f9b36335-f159-42b2-8498-e38da28004d7": {"definition": "A wheeled platform, also called a wagon or truck, on which scenery is built or mounted so an entire set piece or setting can be rolled on and off stage or repositioned for fast scene changes. Wagons may roll freely on casters, run in floor tracks, or pivot as a jackknife, and their casters are braked or blocked when parked.", "plain_english": "It is a rolling platform on wheels. A whole set sits on it and rolls on and off stage fast.", "purpose_function": "It lets a complete scene move as one unit, making scene changes fast and quiet instead of striking and rebuilding scenery piece by piece.", "practical_application": "A crew builds a room set on a wagon in the wings and rolls it into place on cue, then brakes the casters once it is set.", "category": "Stage Machinery", "related_terms": ["Deck", "Jackknife stage", "Turntable stage", "Stage platform", "Understage", "Revolve"], "common_mistakes": ["UNSAFE: Moving a heavy wagon without controlling its speed or path, where its momentum can crush a hand, foot, or bystander", "UNSAFE: Parking a wagon without setting brakes or blocks, letting a loaded unit roll on a raked or sloped floor", "Confusing a wagon, which slides across the floor, with a revolve, which turns about a fixed center"], "scenario_contexts": ["A crew rolls a full kitchen set onstage on a wagon during a blackout", "A touring show uses tracked wagons to move settings on and off along guides in the deck"]}, "33cd377a-06cc-4f40-8687-4900f9d04e5f": {"definition": "A curtain, also called a tableau curtain, that opens by being drawn up and out toward the upper corners by diagonal draw lines attached to the back of the fabric, gathering it into draped swags rather than parting flat or flying straight up. It gives a decorative, festooned reveal of the stage.", "plain_english": "It is a curtain pulled up and out to the sides. It gathers into draped folds as it opens.", "purpose_function": "It opens the stage with a decorative, swagged look, framing the opening in soft folds instead of the plain parting of a traveler.", "practical_application": "An operator hauls the tab lines to draw the curtain up into swags for an ornate reveal at the top of a show.", "category": "Soft Goods", "related_terms": ["Traveler curtain", "Grand drape", "Valance", "Guillotine curtain", "House curtain", "Border"], "common_mistakes": ["Confusing a tab curtain with a traveler; a tab draws up into diagonal swags while a traveler slides flat along a track", "UNSAFE: Hanging a tab curtain made of untreated fabric; stage curtains must be flame-retardant treated to meet fire codes"], "scenario_contexts": ["A variety theater opens its show by drawing the front curtain up into a tableau of swags", "A designer specifies a tab curtain for a period look with draped, festooned folds"]}, "4cde4064-e69f-4753-b372-870c4b68cd2a": {"definition": "A curtain that opens and closes horizontally by riding on carriers along an overhead track, drawn from the center as a bi-parting pair or from one side as a one-way draw; the term also refers to the track-and-carrier system that moves it. It is a common form for the main curtain and for mid- and upstage masking.", "plain_english": "It is a curtain that slides open sideways on a track. It works like curtains on a window rod.", "purpose_function": "It opens and closes the stage or divides the space by drawing fabric sideways, needing overhead track and offstage room rather than fly height.", "practical_application": "An operator pulls the operating line to part the traveler from center, sending the panels offstage along the track.", "category": "Soft Goods", "related_terms": ["Traveler curtain", "House curtain", "Grand drape", "Tab curtain", "Guillotine curtain", "Masking"], "common_mistakes": ["Confusing a traveler, which draws sideways on a track, with a guillotine curtain, which flies straight up and down", "UNSAFE: Hanging a traveler from untreated fabric; stage curtains must be flame-retardant treated to meet fire codes"], "scenario_contexts": ["A road house draws the traveler closed at intermission to hide a scene change", "A crew hangs an upstage traveler to split the stage into a shallow forestage playing area"]}, "71fce77d-a2ca-4784-ae6e-178c77ffe1b6": {"definition": "A stage curtain that opens and closes by sliding horizontally on carriers along an overhead track, parting from the center as a bi-parting pair or drawing from one side; also simply called a traveler. It is widely used as the main curtain and as mid- or upstage masking where sideways draw is preferred over flying the curtain.", "plain_english": "It is a stage curtain that opens by sliding along a track. It parts to the sides like window curtains.", "purpose_function": "It reveals or hides the stage, or divides it, by drawing fabric sideways along a track, so it needs offstage width rather than overhead fly space.", "practical_application": "An operator hauls the draw line to close the traveler curtain across the stage before a scene change.", "category": "Soft Goods", "related_terms": ["Traveler", "House curtain", "Grand drape", "Tab curtain", "Guillotine curtain", "Masking"], "common_mistakes": ["Confusing a traveler curtain, drawn sideways on a track, with a guillotine curtain that flies straight up and down", "UNSAFE: Hanging a traveler curtain of untreated fabric; stage curtains must be flame-retardant treated to meet fire codes"], "scenario_contexts": ["A theater closes the traveler curtain to mask a set change between acts", "A crew rigs a mid-stage traveler curtain to create a shallow scene in front of the main set"]}, "979c4713-88dc-4d10-9da0-244f66389797": {"definition": "A revolving circular section of stage floor, also called a revolve, that rotates about a central pivot to change scenes or move scenery and performers into and out of the audience's view. It may be a permanent understage-driven unit or a portable ring built onto the deck, and its rotating edge and drive create pinch, shear, and trip hazards.", "plain_english": "It is a round part of the stage floor that spins. Turning it swaps one set for another.", "purpose_function": "It changes scenes smoothly by rotating scenery into or out of view, allowing continuous action and fast transitions without carrying set pieces on and off.", "practical_application": "An operator turns the revolve on cue to bring the next set into view while the previous scene rotates offstage.", "category": "Stage Machinery", "related_terms": ["Revolve", "Stage wagon", "Lift platform", "Understage", "Deck", "Jackknife stage"], "common_mistakes": ["UNSAFE: Stepping across the gap between a moving turntable and the fixed deck, a shear and trip point that can trap a foot", "UNSAFE: Standing near or reaching into the drive or edge of a rotating turntable, where clothing or limbs can be caught", "Confusing a turntable, which rotates about a center, with a wagon, which slides across the floor"], "scenario_contexts": ["A musical uses a turntable to rotate between a street scene and an interior without a blackout", "A crew builds a portable revolve onto the deck to spin a two-sided set unit"]}, "fb29e496-78ea-486c-896c-07d8872426c9": {"definition": "A short horizontal drape hung across the top of the stage opening or a scenic unit to mask the overhead space and finish the top edge of the picture; when placed just behind the proscenium to set the height of the opening it is often called the teaser. It is a fixed masking soft good, usually of the same fabric as the main curtain.", "plain_english": "It is a short curtain across the top of the stage opening. It hides lights and rigging up high.", "purpose_function": "It masks the overhead area above the acting space, hiding lights, battens, and rigging while framing the top of the stage picture.", "practical_application": "A crew hangs the valance across the front of the stage to hide the first electric and set the height of the opening.", "category": "Soft Goods", "related_terms": ["Teaser", "Border", "Grand drape", "Proscenium", "Traveler curtain", "Masking"], "common_mistakes": ["Confusing a valance or teaser, which masks overhead, with legs, which mask the sides of the stage", "UNSAFE: Hanging a valance of untreated fabric near stage lighting; stage soft goods must be flame-retardant treated to meet fire codes"], "scenario_contexts": ["A crew hangs a valance behind the proscenium to hide the top of the rigging from the audience", "A designer lowers the valance to shorten the stage opening for a smaller scene"]}, "9c9046b3-571b-4ddb-ae31-f40b57bf4b2f": {"definition": "Wing-and-border masking is the traditional proscenium masking arrangement in which vertical legs (wings) hung in pairs down the sides of the stage combine with horizontal borders hung overhead to conceal the offstage wings, fly loft, lighting, and rigging from the audience while framing the acting area. Successive pairs of legs and borders create a repeating series of masked openings from downstage to upstage, with the legs setting the side limits and the borders setting the top edge of each visible stage frame.", "plain_english": "Wing-and-border masking uses tall side curtains and short overhead curtains to hide the backstage. The side curtains are called legs, or wings. The top curtains are called borders. Together they act like a picture frame and block the view of lights and crew.", "purpose_function": "It controls the audience's sightlines: the legs block views into the side wings while the borders hide the overhead fly loft, lighting, and rigging, so only the framed stage picture is seen. The repeating leg-and-border openings also leave clean gaps for performers and scenery to move on and off.", "practical_application": "A stagehand hangs matching pairs of legs and borders on the fly battens, then checks sightlines from the extreme end seats and the front rows to confirm no offstage area, instrument, or crew member shows through any opening.", "category": "Soft goods / masking", "related_terms": ["Leg", "Border", "Black masking", "Teaser", "Tormentor", "Sightline"], "common_mistakes": ["Confusing wing-and-border masking, a series of separate side and overhead drapes, with a full-stage black box that encloses the acting area on three sides.", "Leaving gaps between successive legs, so the audience sees straight into the offstage wings from side seats.", "Setting borders too high or too shallow, so overhead lights and rigging show over the top of the opening from the front rows.", "UNSAFE: Hanging masking drapery that is not flame-retardant to NFPA 701; stage soft goods must pass the NFPA 701 flame-propagation test and be re-treated or replaced when the treatment no longer passes."], "scenario_contexts": ["Masking a proscenium play so the audience sees only the set through a clean rectangular frame.", "Hiding lighting booms, cable runs, and waiting actors in the side wings during a performance.", "Creating a repeating series of leg openings that give performers concealed entrance and exit points.", "Concealing the fly loft and overhead electrics on a touring house stage."]}, "bc9ccb09-be9f-4725-8568-3d8fee6fb1c4": {"definition": "A horizontal pipe or bar, most commonly 1-1/2-inch nominal Schedule 40 steel pipe, suspended above the stage from a fly system's lift lines, from which scenery, lighting instruments, drapery, or other loads are hung.", "plain_english": "A batten is a long metal pipe hung above the stage. Crews attach lights, curtains, or scenery to it. The fly system then raises and lowers the pipe.", "purpose_function": "It gives a strong, standardized horizontal support that can be raised and lowered, so a venue can hang and reposition overhead loads such as lighting, masking, and scenery.", "practical_application": "A technician clamps fixtures or ties scenery to a batten at working height, then flies it to its trim, keeping the total load within the lineset's rated capacity.", "category": "Fly System Hardware", "related_terms": ["Lineset", "Fly loft", "Trim", "Counterweight system", "Gridiron"], "common_mistakes": ["UNSAFE: Loading a batten beyond its lineset's rated capacity, which can overstress the lines and cause a runaway or dropped load.", "Confusing a batten (just the pipe) with the lineset (the pipe plus all its lift lines and rigging).", "Assuming every batten spans the full stage width or hangs at the same height."], "scenario_contexts": ["Hanging a row of lighting fixtures on an electric batten before a show.", "Tying a painted backdrop to a batten and flying it out of view.", "Adding pipe weight to a batten and re-balancing the counterweight arbor."]}, "10e9a24d-a0c1-4e8c-9a6d-c85083b6e138": {"definition": "The designated location of a particular batten (lineset) within the fly system, identified by its lineset number and its distance upstage from a reference such as the plaster or setting line, along with its set trim height.", "plain_english": "This is where a certain hanging pipe sits in the fly system. It is named by a number and by how far back it is from the front. Its set height is part of it too.", "purpose_function": "Numbering and naming batten positions lets a crew plan a hang, refer to each lineset the same way every time, and place scenery and lighting exactly where the designer wants.", "practical_application": "Crews read batten positions off the hanging plot to load the correct lineset, then mark trims so each pipe returns to the same height every performance.", "category": "Fly System Concept", "related_terms": ["Lineset", "Batten", "Hanging plot", "Trim", "Plaster line"], "common_mistakes": ["Confusing a batten position (which lineset) with a trim (the height that batten is flown to).", "Mislabeling positions so scenery or lights end up on the wrong lineset.", "Measuring positions from the wrong reference instead of the plaster or setting line."], "scenario_contexts": ["Reading a hanging plot to assign fixtures and scenery to numbered batten positions.", "Calling a lineset by its position number when cueing the fly operator.", "Spacing scenic pieces across successive batten positions to build stage depth."]}, "988dacd1-d02e-47b6-a254-0c2e52ff928c": {"definition": "A raised working platform or gallery running along a side wall of the stage house, elevated above the stage floor, from which operators work the fly system's operating lines or ropes.", "plain_english": "A fly floor is a raised walkway along the side of the stage. Crew stand on it to work the ropes or handles that raise and lower scenery.", "purpose_function": "It gives fly operators a safe, dedicated place to run the operating lines above the busy stage floor, keeping the controls clear of onstage traffic.", "practical_application": "A flyman works from the fly floor, operating the lines and locking rail there while watching the stage and taking cues.", "category": "Fly System Structure", "related_terms": ["Fly gallery", "Pin rail", "Locking rail", "Fly loft", "Counterweight system"], "common_mistakes": ["Using 'fly floor' and 'fly gallery' interchangeably without noting venue or regional differences.", "UNSAFE: Leaving tools or loose gear on a fly floor, where they can fall onto people below.", "Assuming every stage has a fly floor; many counterweight systems are operated from stage level."], "scenario_contexts": ["Operating hemp or counterweight lines from the fly floor during a performance.", "Passing cues to fly operators stationed on the fly floor.", "Keeping sandbags or spot lines within reach on the fly floor."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"e2c7aa77-6c44-4973-b3a6-1cc2cd864ab9": {"definition": "An elevated narrow platform or balcony along the side of the stage house, above the stage floor, that carries the pin rail or operating rail and from which the fly lines are worked.", "plain_english": "A fly gallery is a high balcony along the stage wall. It holds the rail where lines are tied off. Crew work the flying lines from up there.", "purpose_function": "It places the tie-off rail and operating lines above the stage, so lines can be belayed and worked without crowding the stage floor.", "practical_application": "Operators on the fly gallery make off (tie) hemp lines to the pin rail and haul scenery up or down on cue.", "category": "Fly System Structure", "related_terms": ["Fly floor", "Pin rail", "Hemp system", "Fly loft", "Locking rail"], "common_mistakes": ["Confusing the fly gallery (a side operating platform) with the gridiron (the structure at the top of the fly loft).", "UNSAFE: Trusting a pin rail belay without confirming each line is properly made off.", "Assuming 'fly gallery' and 'fly floor' always mean exactly the same thing in every venue."], "scenario_contexts": ["Tying off hemp lines to the pin rail on the fly gallery.", "Working counterweight lines from a fly gallery during scene changes.", "Reaching the fly gallery by ladder or stair to rig a spot line."]}, "78cf6627-b16c-4b79-b568-cf96d96be7f0": {"definition": "To lower a batten or flown scenic or lighting piece from the fly loft downward toward or onto the stage; 'in' denotes downward travel to a lower, in-view or working trim.", "plain_english": "To fly something in means to lower it from above down toward the stage. Crews fly in a backdrop so the audience can see it, or to reach it for work.", "purpose_function": "Flying a piece in brings scenery, lighting, or masking down into the audience's view, or down to a height where crew can reach it.", "practical_application": "On a cue, the fly operator flies in a curtain or scenic drop so it appears onstage at its set trim.", "category": "Fly System Operation", "related_terms": ["Fly out", "Trim", "Batten", "Lineset", "Fly path"], "common_mistakes": ["Reversing 'in' and 'out'; in lowers a piece toward the stage, out raises it away.", "UNSAFE: Flying a piece in without a clear-stage call, risking striking crew or performers below.", "Flying in past the set trim and crashing the batten onto the deck or scenery."], "scenario_contexts": ["Flying in a painted drop at the top of a scene.", "Bringing an electric in to focus lights at working height.", "Flying in a border to mask the fly loft from the audience."]}, "ecdb0385-35f6-41a6-b1f3-7df59754f35c": {"definition": "The tall volume of the stage house above the proscenium and stage, extending up to the gridiron, into which battens and scenery are raised out of the audience's sightlines.", "plain_english": "The fly loft is the tall space above the stage. Scenery is lifted up into it so the audience cannot see it. A full-height loft can hide a whole backdrop.", "purpose_function": "It provides the vertical height needed to store and hide flown scenery, lighting, and masking directly above the stage until they are needed.", "practical_application": "Crews rig battens in the fly loft and fly pieces up into it between cues; a loft roughly twice the proscenium opening height lets a full drop fly completely out of sight.", "category": "Fly System Structure", "related_terms": ["Fly space", "Gridiron", "Batten", "Fly out", "Proscenium"], "common_mistakes": ["Confusing the fly loft (the space) with the gridiron (the steel structure at its top).", "Assuming any high ceiling is a fly loft; a true fly loft is tall enough to hide full-height scenery.", "UNSAFE: Working in the fly loft or on the grid without fall protection and tethered tools."], "scenario_contexts": ["Flying a full-height backdrop up into the fly loft to hide it.", "Rigging linesets and spot lines in the fly loft during load-in.", "Checking loft clearance before ordering tall scenery."]}, "fee519a6-ed16-4e1d-93aa-10ca7de24ac6": {"definition": "To raise a batten or flown piece upward into the fly loft, out of the audience's sightlines; 'out' denotes upward travel to a higher, stored, out-of-view trim.", "plain_english": "To fly something out means to lift it up into the space above the stage. Crews fly out a drop so it rises out of view above the stage.", "purpose_function": "Flying a piece out clears it from the stage and hides it overhead, opening the stage picture and storing the piece until its next cue.", "practical_application": "On a cue, the fly operator flies out a backdrop so it rises out of sight into the loft.", "category": "Fly System Operation", "related_terms": ["Fly in", "Fly loft", "Trim", "Batten", "Fly path"], "common_mistakes": ["Reversing 'out' and 'in'; out raises a piece away from the stage, in lowers it.", "UNSAFE: Flying out too far or too fast, jamming the batten or arbor against its limit and shock-loading the lines.", "Losing track of the high trim and running the batten hard into the gridiron."], "scenario_contexts": ["Flying out a drop at a scene change to reveal the next setting.", "Storing an electric overhead by flying it out between focus sessions.", "Flying out masking to open up the full fly loft."]}, "8fdfb053-fa82-412a-bae0-b0f9fc40171a": {"definition": "The vertical route a flown batten or scenic piece travels between its in and out trims, together with the clear volume that must be kept free of people and obstructions while the piece is moving.", "plain_english": "The fly path is the up-and-down lane a flying piece moves through. It must stay clear of people and objects. Nothing should block a piece as it moves.", "purpose_function": "Defining the fly path keeps the travel of a flown piece clear, so it does not strike people, scenery, or other linesets as it moves.", "practical_application": "Before flying a piece, crew confirm its fly path is clear top to bottom and call the move so no one steps into the path.", "category": "Fly System Concept", "related_terms": ["Fly in", "Fly out", "Trim", "Lineset", "Gridiron"], "common_mistakes": ["UNSAFE: Standing in or storing gear in a fly path while a piece is flying.", "UNSAFE: Moving a lineset without a spoken warning and a check that the fly path is clear.", "Forgetting that adjacent linesets or scenery can foul a fly path."], "scenario_contexts": ["Clearing the fly path before flying in a heavy drop.", "Checking that two scenic pieces will not collide in overlapping fly paths.", "Calling 'heads up' to warn people out of a fly path during a move."]}, "2be7a474-d62a-493b-b08e-7d32a99b741d": {"definition": "The overall volume above the stage available for flying scenery — essentially the fly loft — extending from the stage floor up to the gridiron and used to raise and store flown pieces out of sight.", "plain_english": "Fly space is the room above the stage used to lift and store scenery. More fly space means bigger and taller pieces can be flown out of view.", "purpose_function": "Fly space provides the overhead room a venue needs to raise, store, and hide scenery, lighting, and masking above the stage.", "practical_application": "Designers check a venue's fly space before planning flown scenery, since limited fly space caps how tall a piece can be and still fly out of view.", "category": "Fly System Structure", "related_terms": ["Fly loft", "Gridiron", "Batten", "Fly out", "Proscenium"], "common_mistakes": ["Treating fly space as unlimited; loft height and existing linesets limit what can be flown.", "Confusing fly space (the overhead volume) with wing space (offstage floor area to the sides).", "UNSAFE: Planning flown scenery without confirming actual clear fly space and lineset capacity."], "scenario_contexts": ["Assessing fly space during a site survey before a tour.", "Deciding whether a backdrop can fly fully out given the available fly space.", "Sharing limited fly space among lighting, scenery, and masking linesets."]}, "1486a0bb-d77c-45da-8013-9f23c54f3c17": {"definition": "The complete overhead rigging assembly above a stage used to raise (fly out) and lower (fly in) scenery, drapes, lighting, and other loads. It comprises battens, lift lines, sheaves (loft blocks and a head block), and a means of counterbalance or power such as a counterweight arbor or a motorized hoist.", "plain_english": "A fly system is the set of ropes, pulleys, and pipes above a stage. Crews use it to lift scenery and lights up out of sight, then lower them back down.", "purpose_function": "It lets a crew move heavy overhead loads on and off stage quickly and under control, storing scenery above the stage between uses.", "practical_application": "A stagehand loads a batten, balances it against its counterweight, and operates the system from the fly rail or a motor controller to change scenery.", "category": "Fly systems", "related_terms": ["Line set", "Fly tower", "Gridiron", "Lighting batten", "Hoist", "Grid deck"], "common_mistakes": ["UNSAFE: Flying a counterweight set before its arbor is loaded to match the batten load, or unloading it out of balance; an out-of-weight system can run away and cause a fall or crushing injury.", "UNSAFE: Standing or working directly under a suspended load while it is being flown.", "Confusing 'fly in' (lowering toward the stage) with 'fly out' (raising into the loft).", "Assuming any batten can hold any load without checking the system's rated capacity and distributed-load limits."], "scenario_contexts": ["Changing a painted backdrop between acts of a play.", "Flying a lighting batten out to focus fixtures, then back in for the performance.", "Storing scenery overhead in the fly tower during scenes where it is not used."]}, "76fe2076-d5d6-47d7-9b9e-1884ce27802f": {"definition": "The tall enclosed portion of the stagehouse (also called the fly loft) that rises above the proscenium and stage, providing the vertical volume into which scenery and battens are flown out of the audience's sightlines. Its usable height is commonly at least about twice the proscenium opening height to permit full flying.", "plain_english": "A fly tower is the tall space above the stage, hidden from the audience. It is high enough to lift full-size scenery completely out of view.", "purpose_function": "It provides the height needed to hide flown scenery above the stage, so pieces can disappear from view instead of being carried offstage.", "practical_application": "A designer checks the fly tower height early to confirm a full-height drop can be flown out without showing its bottom edge to the audience.", "category": "Overhead structure", "related_terms": ["Fly system", "Gridiron", "Grid deck", "Full flying height", "Line set", "Proscenium"], "common_mistakes": ["Confusing the fly tower (the tall volume) with the gridiron (the steel structure at its top).", "Assuming every stage has a fly tower; many venues have low ceilings or dead-hung pipes instead.", "Underestimating the required height, so tall scenery cannot fly fully out of sight."], "scenario_contexts": ["A theatre planner sizing a new stagehouse to allow full flying of drops.", "A touring crew checking whether a venue's fly tower can store their scenery overhead."]}, "82d50713-d621-4f91-93cb-f1142db78aaa": {"definition": "The design condition in which a fly system has enough overhead clearance to raise a full-height piece of scenery, such as a backdrop, completely above the proscenium opening and out of the audience's sightlines. It generally requires a gridiron height of roughly twice the proscenium opening height or more.", "plain_english": "Full flying height means the stage is tall enough to lift a full backdrop completely out of sight. The bottom of the drop clears the top of the opening the audience looks through.", "purpose_function": "It defines whether scenery can be hidden fully overhead, which determines how a show can change its look without visible scenery hanging in view.", "practical_application": "A technician confirms full flying height before hanging a tall drop, so it will not show below the masking when it is flown out.", "category": "Fly systems", "related_terms": ["Fly tower", "Gridiron", "Line set", "Fly system", "Proscenium", "Masking"], "common_mistakes": ["Confusing full flying height with the maximum travel of a single line set.", "Forgetting to allow for the batten, hardware, and trim clearance, so the drop does not fully clear sightlines.", "Assuming a tall fly tower guarantees full flying for every piece regardless of the piece's height."], "scenario_contexts": ["Hanging a two-story backdrop and checking that it flies out above the masking.", "Evaluating a venue on tour to see whether drops can fully disappear overhead."]}, "be497079-9e38-48b0-9378-8195037059ba": {"definition": "The walkable working surface at the top of the fly tower, formed by closely spaced steel bars or gratings laid over the gridiron beams. It supports the loft (head) blocks and gives crew access to install, adjust, and maintain the overhead rigging.", "plain_english": "The grid deck is the floor you can walk on at the very top of the stage. Crews stand on it to reach and service the pulleys and lines above the stage.", "purpose_function": "It gives riggers safe standing access to the overhead sheaves and lines, and carries the blocks that redirect the lift lines.", "practical_application": "A rigger climbs to the grid deck to reposition a loft block or spot a line when adding a new line set.", "category": "Overhead structure", "related_terms": ["Gridiron", "Grid well", "Fly tower", "Line set", "Fly system", "Hoist"], "common_mistakes": ["UNSAFE: Carrying loose tools or hardware onto the grid deck without tethers or a tool bucket; dropped objects can strike and kill crew below.", "UNSAFE: Working on the grid deck without fall protection where required, or without clearing the stage beneath.", "Confusing the grid deck (the walking surface) with the gridiron (the supporting steel framework)."], "scenario_contexts": ["Spotting a new line set from the grid deck.", "Inspecting or replacing worn loft-block sheaves overhead."]}, "e6ca61a0-ebfc-49b5-82a8-6161f2f8f05e": {"definition": "An opening or gap between the gridiron beams through which lift lines and cables pass down to the stage below. It provides the clearance the lines need to run freely from the loft blocks to their battens.", "plain_english": "A grid well is a gap in the steel floor above the stage. The ropes and cables drop through this gap to reach the pipes below.", "purpose_function": "It lets the lift lines pass through the gridiron without rubbing the structure, keeping each line aligned with its block and batten.", "practical_application": "When spotting a new line, a rigger routes the cable through the correct grid well so it runs straight down to the batten.", "category": "Overhead structure", "related_terms": ["Gridiron", "Grid deck", "Line set", "Fly system", "Fly tower", "Hoist"], "common_mistakes": ["Routing a lift line through the wrong grid well, causing the line to rub the structure or pull the batten out of level.", "UNSAFE: Leaving an open grid well unguarded as a trip hazard or a dropped-object path to the stage below.", "Confusing the grid well (the opening) with the grid deck (the walking surface)."], "scenario_contexts": ["Passing a new lift line down through the gridiron to a batten.", "Aligning cables so each one runs cleanly through its grid well."]}, "8339414b-fb88-463e-a9f0-fb11f83b2c19": {"definition": "The load-bearing steel framework of beams spanning the top of the fly tower, above the stage (commonly shortened to 'the grid'). It supports the loft (head) blocks and other rigging hardware from which the lift lines hang, and forms the structure on which the grid deck is laid.", "plain_english": "The gridiron is the strong steel frame at the top of the stage. It holds up the pulleys that carry the ropes and pipes used to fly scenery.", "purpose_function": "It anchors the overhead blocks and carries the full weight of everything flown, transferring those loads into the building structure.", "practical_application": "A rigger mounts loft blocks to the gridiron beams to redirect lift lines toward the fly-rail side of the stage.", "category": "Overhead structure", "related_terms": ["Grid deck", "Grid well", "Fly tower", "Line set", "Fly system", "Hoist"], "common_mistakes": ["Using 'gridiron' and 'fly tower' interchangeably; the grid is the steel structure at the top, the tower is the whole tall space.", "UNSAFE: Hanging loads from the gridiron without confirming the member's rated capacity and the load path into the building structure.", "Assuming the grid can take a point load anywhere; blocks must land on rated members."], "scenario_contexts": ["Mounting head blocks to the gridiron when installing a counterweight set.", "Inspecting gridiron steel and connections during a rigging safety survey."]}, "518353f2-921b-4b7e-b509-755a770918af": {"definition": "A mechanical device — manual, electric, or pneumatic — that raises and lowers a load by winding a chain, wire rope, or fiber rope over a drum or sprocket. In entertainment overhead rigging, powered hoists fly battens, trusses, and scenery, and their use is addressed by the ANSI E1.6 powered-rigging standards; electric chain hoists also fall under ASME B30.16.", "plain_english": "A hoist is a machine that lifts or lowers a heavy load with a chain or cable. In theatres it raises lights, trusses, and scenery over the stage.", "purpose_function": "It provides controlled powered lifting so heavy overhead loads can be raised, held, and lowered without hand-hauling counterweights.", "practical_application": "A crew uses electric chain hoists to fly a lighting truss to trim height, then locks it off at the working position.", "category": "Rigging equipment", "related_terms": ["Line set", "Lighting batten", "Fly system", "Gridiron", "Grid deck", "Fly tower"], "common_mistakes": ["UNSAFE: Exceeding a hoist's rated working load limit, or using a standard hoist to lift or hold people; personnel or performer flying requires a listed, rated system under the applicable standard.", "UNSAFE: Suspending a load over people on a single non-redundant hoist where the standard requires secondary safety or a rated over-the-audience system.", "Skipping the pre-use inspection of chain, hook, brake, and limit switches.", "Confusing a hoist (the lifting machine) with the line set or batten it lifts."], "scenario_contexts": ["Flying a lighting or audio truss with motorized chain hoists at load-in.", "Raising a scenic unit to trim and locking it off for the performance."]}, "8952d0cd-558d-416a-8192-099776309fc9": {"definition": "A horizontal pipe suspended over the stage from a line set, used to hang and often to power overhead lighting fixtures. When fitted with a raceway and circuits it is commonly called an 'electric'; it carries the luminaires, their cabling, and sometimes data lines.", "plain_english": "A lighting batten is a pipe that hangs over the stage. Stage lights clamp onto it, and it can carry the power cables that feed those lights.", "purpose_function": "It provides a rigid, flyable support, and often the power feed, for overhead lighting so fixtures can be positioned and raised or lowered together.", "practical_application": "Electricians hang and cable fixtures on a lighting batten at deck level, then fly it to trim height for focus.", "category": "Rigging equipment", "related_terms": ["Line set", "Fly system", "Hoist", "Gridiron", "Grid deck", "Fly tower"], "common_mistakes": ["UNSAFE: Overloading a lighting batten past its rated distributed load or point-load limits, risking a batten or system failure overhead.", "UNSAFE: Failing to safety-cable each fixture and accessory to the batten as a secondary means of support.", "Confusing a bare pipe batten with a wired 'electric' that already carries circuits."], "scenario_contexts": ["Hanging and focusing a wash of fixtures on an overhead electric.", "Adding a fixture and re-balancing the line set before flying the batten out."]}, "a0b3c7ac-2235-486e-bf53-bac6c147d11a": {"definition": "One complete unit of a fly system that raises and lowers a single batten: the batten, the lift lines running up to the loft blocks and across to the head block, and the counterbalance (a counterweight arbor) or hoist that moves it. Adjacent line sets are spaced along the stage on set centers, commonly about 6 to 8 inches apart.", "plain_english": "A line set is everything needed to fly one pipe. It includes the pipe, the ropes or cables that lift it, and the weights or motor that move it. The sets are lined up in rows across the stage.", "purpose_function": "It groups all the parts that move one batten into a single balanced unit, so a crew can fly that pipe on its own.", "practical_application": "A stagehand assigns a drop to an empty line set, loads matching counterweight, and flies it from the fly rail.", "category": "Fly systems", "related_terms": ["Lighting batten", "Fly system", "Gridiron", "Grid deck", "Hoist", "Fly tower"], "common_mistakes": ["UNSAFE: Flying a line set that is out of weight (the batten and arbor loads are not matched); an unbalanced set can run away and cause serious injury.", "UNSAFE: Loading or unloading a counterweight set out of sequence so the arbor becomes heavier than the batten, letting the empty batten fly up violently; always follow the system's loading procedure and keep the set balanced.", "Confusing a line set (the whole flying unit) with just its batten.", "Leaving a loaded or unbalanced line set unlocked instead of securing the rope lock."], "scenario_contexts": ["Assigning scenery and electrics to line sets while planning a hang.", "Balancing a loaded line set before the first flying cue."]}, "b4e603c3-f8da-41c3-be6d-748ce8720a67": {"definition": "The fixed, numbered location of a single line set within a fly system, defined by its set upstage distance from the plaster line, which determines where along the stage's depth that line set's batten hangs and flies.", "plain_english": "It is the numbered spot where one flying pipe lives above the stage. The number tells the crew how far upstage that pipe hangs.", "purpose_function": "It gives every line set a fixed, identifiable place so scenery, lighting, and drapery can be planned, hung, and called by number without confusion.", "practical_application": "A technician reads the line-set position number to know which batten to load, trim, or fly for a given piece.", "category": "Fly System Layout", "related_terms": ["Line set", "Batten position", "Line-set schedule", "Pipe batten", "Plaster line"], "common_mistakes": ["Confusing the line-set position (its fixed location on the grid) with the batten's trim height (how high it is flown)", "Assuming positions are evenly spaced when the actual upstage spacing between line sets varies"], "scenario_contexts": ["A designer marking which line-set position each electric and drop will hang on", "A flyman locating a specific line-set position to hang a border"]}, "fdd90c29-65f6-487f-8186-767e1533e2e0": {"definition": "A master chart listing every line set in a fly system by number and position, recording what is hung on each batten, its trim heights, and its load, used to plan and coordinate the entire hang.", "plain_english": "It is a chart that lists every flying pipe and what hangs on it. Crews use it to plan the whole rig and share the plan.", "purpose_function": "It organizes the hang so scenery, electrics, and drapery are assigned to specific line sets without conflict, and so weights and trims are tracked.", "practical_application": "The stage crew works from the line-set schedule during load-in to hang each element on its assigned batten and set its trim.", "category": "Rigging Documentation", "related_terms": ["Line set", "Line-set position", "Pipe batten", "Batten", "Trim"], "common_mistakes": ["Failing to update the line-set schedule when the hang changes, so recorded weights and trims no longer match the rig", "UNSAFE: Loading a batten from the schedule without independently confirming the counterweight arbor is correctly balanced before flying"], "scenario_contexts": ["A production electrician building the schedule before load-in to assign each fixture bar to a line set", "A stage manager referencing the line-set schedule to call scenery moves by line number"]}, "1aac4023-0f16-41b3-8cee-b51222956ab4": {"definition": "A theatrical flying system in which battens are raised and lowered by electric- or hydraulic-powered hoists controlled from a console or pendant, rather than by manual counterweight, allowing programmed speed, repeatable positions, and load monitoring.", "plain_english": "It is a flying system that lifts pipes with motors instead of by hand. An operator runs it from a control panel.", "purpose_function": "It moves heavy overhead loads with controlled, repeatable speed and position, and it can monitor load and travel to keep operation within safe limits.", "practical_application": "An operator programs cues and runs the powered hoists from a console to fly scenery in and out during a show.", "category": "Powered Flying", "related_terms": ["Hoist", "Counterweight system", "Fly system", "Automated rigging", "Pipe batten"], "common_mistakes": ["Assuming a motorized set needs no weight checks; hoist load limits and monitoring still govern what may be hung", "UNSAFE: Standing or working under a moving powered batten instead of keeping the area below clear during travel"], "scenario_contexts": ["A venue with an ETC Prodigy or JR Clancy powered hoist system flying scenery on programmed cues", "A retrofit replacing counterweight line sets with motorized hoists to automate scenery moves"]}, "7c123b0f-c163-4694-b3af-1a0e455161f3": {"definition": "A horizontal length of steel pipe — conventionally 1.5-inch nominal (1.9-inch outside diameter) Schedule 40 pipe — suspended from a line set's lift lines, from which scenery, lighting instruments, or drapery are hung.", "plain_english": "It is the long steel pipe that hangs above the stage. Scenery, lights, and curtains are tied to it so they can fly up and down.", "purpose_function": "It provides a strong, standard-diameter horizontal support to which loads attach so they can be flown together as a single line set.", "practical_application": "A technician clamps lighting fixtures or ties scenery to the pipe batten, then the line set flies it to trim.", "category": "Battens & Supports", "related_terms": ["Batten", "Line set", "Lighting batten", "Scenery batten", "Trim"], "common_mistakes": ["Assuming any pipe fits standard clamps; battens are 1.5-inch nominal (1.9-inch OD) Schedule 40 pipe, not 2-inch", "UNSAFE: Point-loading or overloading a batten beyond its and the line set's rated capacity"], "scenario_contexts": ["A lighting crew hanging a bar of fixtures on a pipe batten", "Joining two battens with a batten splice to extend a line set's usable length"]}, "5066d737-fc17-4eab-b499-3444215eddcf": {"definition": "A batten on a line set designated for flying scenery — drops, framed flats, or soft goods — as distinct from battens reserved for lighting (electrics); it is identified as a scenery line on the line-set schedule.", "plain_english": "It is a flying pipe used to hang scenery instead of lights. Crews mark it on the plan so scenery and lights do not share a pipe.", "purpose_function": "It keeps scenery loads on their own line sets, separated from electrics, so hangs, weights, and cues stay organized.", "practical_application": "The crew ties a backdrop or attaches a flat to the scenery batten, balances the arbor to match, then flies it to trim.", "category": "Battens & Supports", "related_terms": ["Pipe batten", "Lighting batten", "Line set", "Line-set schedule", "Trim"], "common_mistakes": ["Confusing a scenery batten with a lighting batten (electric) and hanging fixtures on a batten not wired or planned for them", "UNSAFE: Attaching scenery to a batten without re-balancing the counterweight arbor to match the new load"], "scenario_contexts": ["Hanging a painted backdrop on a designated scenery batten", "A line-set schedule marking which battens carry scenery versus electrics"]}, "b4b93972-847e-483b-aeb0-5ab2dcc19e27": {"definition": "A walkable overhead access floor formed by a tightly tensioned lattice of steel aircraft cable stretched across a rigid structural frame above the stage, letting technicians stand and work almost anywhere overhead while remaining nearly transparent to light; it is the common short name for a tension-wire grid.", "plain_english": "It is a walk-on floor of tight steel wires hung above the stage. Crew can stand almost anywhere on it to reach lights, and light still passes through.", "purpose_function": "It gives safe, full-coverage overhead access for hanging and focusing equipment, unlike catwalks that reach only fixed spots.", "practical_application": "A lighting technician walks out onto the tension grid to hang and focus fixtures directly above any part of the stage.", "category": "Overhead Access", "related_terms": ["Tension-wire grid", "Gridiron", "Grid deck", "Catwalk", "Fly loft"], "common_mistakes": ["Thinking the wire surface is unsafe underfoot when it is engineered to be walked on and to catch dropped tools", "UNSAFE: Exceeding the grid's rated live load, or walking on it before confirming it is rated and installed for personnel"], "scenario_contexts": ["Focusing a lighting rig by walking directly above each fixture on the tension grid", "A venue choosing a tension grid instead of a gridiron with catwalks for overhead access"]}, "71dff602-ebe3-428f-a722-0eef19f7bba3": {"definition": "An engineered overhead work surface consisting of a dense grid of high-tension steel wire rope (aircraft cable) stretched across a structural steel frame, forming a floor technicians can walk on to access lighting and rigging while light passes between the wires; commonly shortened to \"tension grid.\"", "plain_english": "It is a strong floor made of tightly stretched steel cables above the stage. People walk on it to reach lights, and the gaps let light shine through.", "purpose_function": "It provides continuous, walk-anywhere overhead access and a catch surface for dropped objects, improving safety and flexibility over fixed catwalks.", "practical_application": "Crew access the tension-wire grid to rig, cable, and focus lighting anywhere overhead without repositioning a personnel lift.", "category": "Overhead Access", "related_terms": ["Tension grid", "Gridiron", "Catwalk", "Grid deck", "Fly loft"], "common_mistakes": ["Assuming a tension-wire grid removes the need for fall protection and load rules; personnel limits, load limits, and site policy still apply", "UNSAFE: Overloading the grid or dragging point loads across it beyond its rated capacity"], "scenario_contexts": ["A new theatre installing a tension-wire grid for overhead lighting access", "Technicians walking a tension-wire grid to re-focus a repertory lighting plot"]}, "bf3e8cbd-da42-4cca-84e3-79649447b75c": {"definition": "A fixed or portable ladder that provides personnel access to elevated technical areas such as catwalks, grids, lighting positions, and truss. In fixed installations its rungs, side rails, clearances, and cages are governed by OSHA 29 CFR 1910.23; portable-ladder pitch and use follow OSHA 1910.23 and 1926.1053.", "plain_english": "An access ladder lets crew climb up to high work areas. These include catwalks, the grid, and lighting positions. Fixed ladders must meet OSHA rules for spacing and strength. Always keep three points of contact when you climb.", "purpose_function": "It gives crew a safe, code-compliant way to reach overhead rigging, lighting, and audio positions that cannot be reached from the floor.", "practical_application": "A technician climbs an access ladder to reach a catwalk or grid to hang, focus, or service lighting, speakers, and rigging hardware, keeping three points of contact and hoisting tools separately.", "category": "Access Equipment", "related_terms": ["Access platform", "Audio catwalk", "Fall protection", "Grid", "Personal fall arrest system", "Guardrail"], "common_mistakes": ["UNSAFE: Carrying tools or gear by hand while climbing instead of keeping three points of contact and hoisting equipment up separately", "UNSAFE: Using a damaged or non-compliant ladder, or one at the wrong angle, instead of an OSHA-compliant ladder set at about a 4:1 pitch", "Overreaching from the ladder instead of climbing down and repositioning it", "Using a ladder where a proper access platform or lift is required for the task"], "scenario_contexts": ["Climbing to a lighting catwalk to focus fixtures before a show", "Accessing the grid to attach rigging points or spot lines", "Reaching an over-stage audio position to service a flown speaker"]}, "8767852c-4423-49a2-b62b-eaff924a810c": {"definition": "An elevated, guarded work surface—fixed, mobile, or carried on a powered lift—that supports personnel and tools for work at height. Guarding, edge protection, and load rating follow OSHA 29 CFR 1910.28 and 1910.29 (guardrail systems); for mobile elevating work platforms the manufacturer's technical limits also apply.", "plain_english": "An access platform is a raised, railed floor where crew stand to work up high. It can be fixed, rolling, or lifted by a machine. Guardrails stop falls, and the platform has a weight limit. Never overload it or climb on the rails.", "purpose_function": "It provides a stable, fall-protected place to work overhead on rigging, lighting, and audio without balancing on a ladder.", "practical_application": "A crew uses an access platform or personnel lift to reach trim height for hanging truss, focusing lights, or servicing flown speakers, staying within the rated load and inside the guardrails.", "category": "Access Equipment", "related_terms": ["Access ladder", "Audio catwalk", "Guardrail", "Fall protection", "Trim height", "Personnel lift"], "common_mistakes": ["UNSAFE: Standing on or leaning over the guardrail to extend reach instead of repositioning the platform", "UNSAFE: Exceeding the platform's rated load with combined people and equipment weight", "Moving an elevated mobile platform with people aboard against the manufacturer's instructions", "Failing to set brakes, outriggers, or wheel locks before climbing on"], "scenario_contexts": ["Hanging and focusing overhead lighting at trim height", "Servicing a flown line-array cabinet at height", "Installing rigging points where a fixed catwalk does not reach"]}, "82dbda60-e8bf-4ae9-a0e9-25fd9bf9f8d1": {"definition": "In manual counterweight rigging, the arbor is the vertical steel carriage that holds counterweights and connects to the lift lines, balancing the load on a batten so the lineset can be raised and lowered by hand. Manual counterweight rigging systems, including the arbor, are covered by ANSI/ESTA E1.4-1.", "plain_english": "An arbor is a tall metal frame that holds stacked counterweights. It hangs on the same ropes that hold a lighting or scenery pipe. The weights balance the load so one person can move it by hand. The arbor weight must match the load, or the pipe becomes dangerous.", "purpose_function": "It carries counterweights that offset the weight on the batten, so a heavy lineset stays balanced and moves safely with little effort.", "practical_application": "When a technician loads or strikes scenery or fixtures on a lineset, they add or remove matching counterweights on the arbor to keep the system in balance before operating it.", "category": "Counterweight Rigging", "related_terms": ["Batten", "Lineset", "Counterweight", "Lift line", "Loading gallery", "Purchase line"], "common_mistakes": ["UNSAFE: Operating an out-of-weight lineset when the arbor and batten loads are not matched, which can cause a runaway and serious injury", "UNSAFE: Loading or striking the batten before the arbor is correspondingly weighted, instead of following a safe load/unload sequence", "Overloading the arbor beyond the system's rated capacity", "Leaving loose or unsecured counterweight bricks on the arbor"], "scenario_contexts": ["Balancing a lighting electric after adding fixtures", "Loading counterweights from the loading gallery to match new scenery", "Rebalancing a lineset before a scene change"]}, "54f31850-679a-4b48-a178-96490beb2306": {"definition": "A permanently installed, elevated and guarded walkway placed over the audience or stage to give access to, and mounting for, loudspeakers and audio equipment. As a walking-working surface it must meet OSHA 29 CFR 1910.28/1910.29 guarding requirements, and any equipment suspended from it over people is subject to overhead-rigging and secondary-safety practice.", "plain_english": "An audio catwalk is a narrow, railed bridge high above the room. Crew walk it to reach and aim speakers and other audio gear. Guardrails protect the crew from falling. Anything hung over people below must be rigged and safety-tied.", "purpose_function": "It gives audio crew safe overhead access to place, aim, cable, and service loudspeakers in fixed sound positions above the room.", "practical_application": "A technician uses the audio catwalk to reach front-of-house or delay loudspeakers to aim, cable, and service them, securing any suspended gear with rated hardware and safety cables.", "category": "Audio Position", "related_terms": ["Access ladder", "Balcony rail position", "Guardrail", "Fall protection", "Delay loudspeaker", "Front of house"], "common_mistakes": ["UNSAFE: Hanging a speaker or gear over the audience from a catwalk without rated rigging hardware and a secondary safety (safety cable)", "UNSAFE: Working on a catwalk without the required guardrails or fall protection, or leaving loose tools that can fall on people below", "Overloading the catwalk beyond its rated capacity with equipment and personnel", "Routing cable so it is unsupported or creates a trip hazard along the walkway"], "scenario_contexts": ["Aiming and cabling front-of-house cluster loudspeakers over the house", "Servicing mid-room delay speakers during a load-in", "Running and dressing audio cable to overhead speaker positions"]}, "88dab7f1-1ba0-4f0d-98a9-3911f0e67fea": {"definition": "A load-rated structural framework, usually welded aluminum lattice, used to support or fly loudspeaker systems and their rigging. Its design and load ratings are governed by ANSI/ESTA E1.2 (aluminum trusses and towers) and the manufacturer's load tables; when ground-supported outdoors it also falls under ANSI/ESTA E1.21.", "plain_english": "An audio truss is a strong metal lattice beam. Crews hang or stand line-array speakers on it. Every truss has a load chart. The chart sets how much weight it can carry and how far apart the pick points can be. Going past those limits can collapse it.", "purpose_function": "It provides a rated, rigid structure to suspend or support heavy loudspeaker arrays safely at the correct height and angle.", "practical_application": "A rigger assembles audio truss, attaches it to hoists or towers, and flies line-array cabinets from it, staying within the manufacturer's span, point-load, and total-load ratings.", "category": "Rigging Structure", "related_terms": ["Automated rigging", "Chain hoist", "Line array", "Working load limit", "Shackle", "Ground support"], "common_mistakes": ["UNSAFE: Loading truss beyond its rated span or point-load limits, or ignoring the manufacturer's load chart, which risks collapse over people", "UNSAFE: Combining incompatible or mixed-brand truss sections whose connectors and ratings do not match", "Applying point loads between panel points instead of at rated node/pick points", "Neglecting a secondary safety on flown loudspeakers and rigging hardware"], "scenario_contexts": ["Flying a line-array from motorized hoists at a concert", "Building a ground-supported speaker tower for an outdoor festival", "Rigging front-fill or delay speakers on truss over a crowd"]}, "2cca6a46-8640-4dfd-b253-110442cc0c95": {"definition": "Rigging that raises, lowers, positions, or moves loads using powered hoists or machinery under electronic, often computerized multi-axis control. Design, manufacture, installation, and operation are governed by the ANSI/ESTA E1.6 family—E1.6-1 (powered hoist systems), E1.6-2 (electric chain hoists), and E1.6-3 (selection and use of serially manufactured electric chain hoists)—with ASME B30.16 applying to underhung hoists.", "plain_english": "Automated rigging uses motors and computers to move rigging instead of hand power. An operator can raise, lower, or move many pieces on cue. Safety systems watch load, position, and speed. They stop the motion if something is wrong. It must follow strict entertainment rules.", "purpose_function": "It lets a system move scenery, lighting, and audio precisely and repeatably on cue, with load and position monitoring that manual rigging cannot provide.", "practical_application": "An operator programs and runs cues on an automation console to fly scenery or speaker arrays, while the system monitors load, speed, and position and enforces limits and emergency stops.", "category": "Motorized Rigging", "related_terms": ["Chain hoist", "Audio truss", "Working load limit", "Emergency stop", "Load cell", "Powered hoist"], "common_mistakes": ["UNSAFE: Bypassing or ignoring limit switches, load monitoring, or emergency stops to force a move", "UNSAFE: Moving automated loads over people without secondary safeties, load verification, and clear communication", "Assuming a saved cue is still safe without re-checking loads and the stage after any change", "Operating without the required inspection, testing, and qualified-operator procedures"], "scenario_contexts": ["Flying moving scenery on precise cues during a theatrical performance", "Repositioning speaker arrays or lighting pods between numbers in a concert", "Running multi-hoist truss lifts during load-in with load monitoring"]}, "27a14379-2169-4949-bda3-4c1d51ec502f": {"definition": "The vertical face or fascia of a theatre balcony, commonly used as a mounting position for fill/delay loudspeakers and lighting aimed at the stage or audience. Equipment mounted here hangs over the seating below and is subject to overhead-rigging and secondary-safety practice.", "plain_english": "The balcony front is the tall front wall of a balcony. Crews mount small speakers and lights on it to cover the seats and the stage. Because the gear hangs above people, it must be fixed with rated hardware. A safety cable backs up each unit.", "purpose_function": "It offers a forward, elevated mounting line for fill loudspeakers and lighting that improve coverage and timing for the main floor and stage.", "practical_application": "A technician mounts and aims front-fill or delay speakers and lighting on the balcony front, using rated brackets or clamps and secondary safeties because the gear hangs over the audience.", "category": "House Position", "related_terms": ["Balcony rail position", "Delay loudspeaker", "Front fill", "Audio catwalk", "Safety cable", "Front of house"], "common_mistakes": ["UNSAFE: Mounting a speaker or fixture over the seats without rated hardware and a secondary safety cable", "UNSAFE: Attaching to decorative fascia or trim that is not structural or rated for the load", "Aiming fill speakers poorly so timing and coverage get worse instead of better", "Ignoring cable strain relief and dressing on the exposed face"], "scenario_contexts": ["Adding front-fill speakers to cover the first rows from the balcony face", "Mounting delay speakers to time-align with the main system", "Placing front lighting to reach the stage from the balcony front"]}, "4ddd865f-1cee-41cb-acfb-ef813ec93b37": {"definition": "A lighting and audio mounting position along the top rail (front railing) of a balcony, used to clamp fixtures or small loudspeakers aimed at the stage or audience. Clamped equipment hangs over the seating below and requires rated clamps and a secondary safety per rigging practice.", "plain_english": "The balcony rail position is the pipe or rail at the front edge of a balcony. Crews clamp lights and sometimes small speakers to it. It gives a straight-on angle to the stage. Every clamped unit over people needs a rated clamp and a safety cable.", "purpose_function": "It provides a low, frontal angle from the house for lighting the stage and for fill loudspeakers, at a point between the stage and the rear of the room.", "practical_application": "An electrician clamps and cables fixtures along the balcony rail, sets their focus on the stage, and fits a safety cable to each unit because they hang above the audience.", "category": "House Position", "related_terms": ["Balcony front", "Front of house", "Safety cable", "C-clamp", "Audio catwalk", "Delay loudspeaker"], "common_mistakes": ["UNSAFE: Clamping a fixture or speaker over the audience without a rated clamp and a secondary safety cable", "UNSAFE: Overloading the rail beyond its structural or clamp rating", "Poor focus or aim that spills into the audience's eyes or misses the stage", "Leaving cable unsupported or creating a trip or pinch hazard along the rail"], "scenario_contexts": ["Clamping front light onto the balcony rail for a stage wash", "Adding small fill speakers along the balcony rail", "Focusing balcony-rail specials during a tech rehearsal"]}, "b8cdc34f-a29f-4c01-b71f-bfb5300ea360": {"definition": "A beam clamp is a rigging attachment device that grips the flange of a structural steel I-beam or wide-flange beam to create an overhead anchor (pick point) for a load, without drilling or welding. It carries a marked working load limit (WLL) and, for entertainment use, must be selected and used within its rated flange range and load in accordance with ASME B30.26 and applicable ANSI/ESTA E1 rigging practice.", "plain_english": "A beam clamp is a metal clamp that grips a steel roof beam. It gives riggers a strong point to hang lights or speakers from. It has a stamped weight limit you must never go over. It clamps on with no drilling.", "purpose_function": "It provides a fast, removable overhead attachment point on existing steel structure, transferring the hung load into the building frame so hoists, slings, or trusses can be flown.", "practical_application": "A rigger clamps it onto a venue's roof steel, confirms the flange width and load rating, then hangs a chain hoist or sling from its eye to fly truss or speakers.", "category": "Rigging Hardware", "related_terms": ["Shackle", "Chain hoist", "Sling", "Working load limit", "Truss", "Pick point"], "common_mistakes": ["UNSAFE: Exceeding the clamp's marked working load limit, or applying side or angled loading it is not rated for, which can spread the jaws and drop the load.", "UNSAFE: Using a beam clamp on a beam whose flange width or thickness is outside the clamp's rated range, so it cannot seat and grip properly.", "Confusing working load limit with breaking strength; the WLL already includes the design factor and must not be exceeded.", "Failing to verify the building steel itself can carry the load before clamping to it."], "scenario_contexts": ["Rigging a line-array speaker cluster from a venue's exposed roof beam using rated beam clamps.", "Creating a temporary hoist pick point for flying truss during a concert load-in.", "Inspecting beam clamps for jaw spread, thread damage, and legible load markings before use."]}, "f7fee471-0d0c-4391-997c-66e3a2164daf": {"definition": "In stage rigging, a bridge is an elevated walkway or platform, fixed or flown, that lets crew reach overhead equipment above the stage, most commonly a lighting bridge used to hang, cable, and focus luminaires. As an occupied working-at-height surface it must meet fall-protection requirements such as guardrails under OSHA 29 CFR 1910.28 and 1910.29.", "plain_english": "A bridge is a raised walkway above the stage. Crew stand on it to reach and aim the lights and rigging overhead. It usually has a guardrail so no one falls. A lighting bridge is the most common kind.", "purpose_function": "It gives crew safe standing access to overhead luminaires, cabling, and rigging so they can be hung, focused, and maintained without a ladder or lift each time.", "practical_application": "An electrician walks out onto the lighting bridge to focus fixtures and dress cable, using the guardrail or fall protection the venue's safety plan requires.", "category": "Overhead Access", "related_terms": ["Catwalk", "Lighting bridge", "Fly gallery", "Guardrail", "Fall arrest system", "Loading gallery"], "common_mistakes": ["UNSAFE: Overloading a bridge with crew and gear beyond its rated live load, or resting tools and fixtures on the guardrail.", "UNSAFE: Working at the edge of a bridge without the guardrail or personal fall protection the venue requires.", "Confusing a fixed architectural bridge with a flown scenic bridge that moves on the rigging system."], "scenario_contexts": ["Focusing front-of-house luminaires from a lighting bridge over the auditorium.", "Running and dressing cable along a bridge during a lighting rig install.", "Inspecting a bridge's guardrails and toe boards before crew access."]}, "dfa8f6d6-8779-47dc-a02e-1a0f51fed634": {"definition": "'Bring in' is a fly-system command and action meaning to lower a flown batten, piece of scenery, drape, or lighting bar from its high (out) trim down toward stage level. It is the opposite of 'take out' or 'fly out,' and on counterweight or powered systems it is executed by the flyperson or hoist operator on a clear cue.", "plain_english": "'Bring in' means lower something hung up in the air down toward the stage. A flyperson moves the line so a curtain or scenery comes down. The opposite command is 'take out.' It is always done on a clear cue.", "purpose_function": "It is the standard verbal cue that tells the fly operator to move a load downward, giving the show a shared, unambiguous language for controlling flown pieces safely.", "practical_application": "On the stage manager's cue the flyperson brings in the main drape, watching the load and the deck to make sure the path is clear.", "category": "Fly Operations", "related_terms": ["Fly out", "Trim", "Batten", "Counterweight system", "Flyperson", "Cue"], "common_mistakes": ["UNSAFE: Bringing in a batten without confirming the landing area and the deck below are clear of people and obstructions.", "UNSAFE: Moving a load before hearing and acknowledging the cue, or without a spotter when the view of the deck is blocked.", "Confusing 'bring in' (lower toward the stage) with 'take out' (raise up to the grid)."], "scenario_contexts": ["Bringing in the grand drape at the end of an act on the stage manager's call.", "Lowering a lighting electric to working height to refocus, then taking it back out to trim.", "Flying in a scenic drop during a blackout scene change."]}, "1ca9fe23-a48e-4216-aac2-8ee94dc25c99": {"definition": "A cable bridge (also called a cable ramp or crossover) is a rigid, ramped floor protector, usually rubber or polyurethane, laid over cables and hoses so people, carts, and vehicles can cross them without crushing the cable or tripping. Internal channels hold the cable, and beveled edges plus a hinged lid manage the trip hazard and keep egress paths clear.", "plain_english": "A cable bridge is a tough ramp you lay over cables on the floor. It lets people and carts roll across without stepping on the wires. It stops the cable from getting crushed. It also keeps people from tripping.", "purpose_function": "It protects cable runs from foot and wheel traffic and reduces the trip hazard where cables must cross a walkway, doorway, or vehicle path.", "practical_application": "Crew lay cable bridges across a lobby or loading path so audio and power cables can cross safely and stay clear of the audience's feet.", "category": "Cable Management", "related_terms": ["Cable drop", "Cable pick", "Trip hazard", "Egress route", "Multicore"], "common_mistakes": ["UNSAFE: Leaving cables loose across a walkway or egress route instead of using a cable bridge, creating a trip and evacuation hazard.", "Overfilling the channels so the lid does not close flush, leaving a raised lip that people catch a foot on.", "Using a light-duty bridge where vehicles will cross, so it crushes and fails to protect the cable."], "scenario_contexts": ["Protecting a snake and power run where it crosses a public corridor at a trade show.", "Covering cables across a fire lane so a forklift can cross during load-in.", "Bridging cables through a doorway to keep an accessible route clear."]}, "a9322ebd-5539-41f0-abdd-db29b504725e": {"definition": "A cable drop is a point at which cabling is routed vertically down from an overhead position such as a grid, catwalk, truss, or ceiling to equipment or connections at a lower level, and by extension the bundle of cable run at that point. The drop is dressed and strain-relieved so its weight is not carried by the connectors and so it does not swing into performers or scenery.", "plain_english": "A cable drop is where cables come straight down from up high to the gear below. Think of a power cord running down a wall from the ceiling. Crew tie off the cable so its weight does not pull on the plugs. They also keep it from swinging.", "purpose_function": "It delivers signal and power from overhead distribution down to fixtures, speakers, or stage boxes, keeping cable off the floor and organized along a planned vertical path.", "practical_application": "A rigger or electrician runs a cable drop from a catwalk down to a downstage lighting position, strain-relieving it so the connectors carry no load.", "category": "Cable Management", "related_terms": ["Cable pick", "Cable bridge", "Strain relief", "Catwalk", "Grid", "Multicore"], "common_mistakes": ["UNSAFE: Letting the cable's weight hang on the connectors instead of a strain relief, which can pull plugs apart and drop cable or fixtures below.", "Leaving a drop free to swing into performers, scenery, or moving battens.", "Confusing a cable drop (cable coming down) with a cable pick (cable being supported up overhead)."], "scenario_contexts": ["Dropping DMX and power from a catwalk to a wall-mounted lighting position.", "Running a mic and monitor drop from the grid to a downstage vocal position.", "Dressing and tying off a cable drop so it clears a flying scenic piece."]}, "4a2ae707-fab1-4593-8969-aefd4a812c5c": {"definition": "A cable pick is an overhead point that gathers and supports (picks up) a bundle of cable so it is suspended and routed clear of the floor or a gap, typically using tie-line, a pick-up sling, or a dedicated pick point on the grid or truss. It carries the suspended weight of the cable and must be rigged to hold that load without the cable slipping or overloading the attachment.", "plain_english": "A cable pick is a spot up high that holds a bunch of cable off the ground. Crew tie the cables up so they hang neatly instead of lying across the floor. The pick must be strong enough to hold that weight. It keeps walkways clear.", "purpose_function": "It keeps heavy cable runs off the deck and out of walkways by carrying their weight overhead, routing them neatly from a source to where they drop down.", "practical_application": "A rigger ties a cable pick on the grid to lift a heavy feeder bundle across the stage, then lets it drop to the dimmer racks on the far side.", "category": "Cable Management", "related_terms": ["Cable drop", "Cable bridge", "Pick point", "Tie-line", "Grid", "Sling"], "common_mistakes": ["UNSAFE: Overloading a pick with more cable weight than the attachment point or tie-line is rated to hold, risking a drop onto people below.", "UNSAFE: Picking to non-structural elements such as conduit or sprinkler pipe, or using a knot or tie-line not rated for the suspended load.", "Confusing a cable pick (supporting cable overhead) with a cable drop (routing cable down)."], "scenario_contexts": ["Picking a feeder cable across the stage from the grid to reach distant dimmer racks.", "Suspending a mic-cable bundle overhead to keep a crossover clear during a live shoot.", "Adding picks along a long overhead cable run to share the load between points."]}, "2eee9458-ad04-4802-81bf-dcea546eac2d": {"definition": "A catwalk is a permanent, narrow elevated walkway above a stage or auditorium that gives crew access to overhead lighting, rigging, and equipment. As a working walkway exposed to falls of 4 feet (1.2 m) or more it must be protected by a guardrail system under OSHA 29 CFR 1910.28(b)(5), with a top rail generally about 42 inches (107 cm) high per 1910.29.", "plain_english": "A catwalk is a narrow walkway high above the stage. Crew use it to reach and aim the lights and rigging overhead. It has a guardrail along the side so no one falls off. It is a fixed part of the building.", "purpose_function": "It provides safe, permanent standing access to overhead positions so crew can hang, focus, cable, and maintain equipment without lifts or ladders.", "practical_application": "A lighting tech walks the catwalk to focus front-of-house fixtures and run cable, staying inside the guardrails while working over the audience.", "category": "Overhead Access", "related_terms": ["Bridge", "Catwalk hatch", "Ceiling access", "Guardrail", "Grid", "Fall arrest system"], "common_mistakes": ["UNSAFE: Dropping or leaving unsecured tools and gear on a catwalk, which can fall onto people below; tools should be tethered and a toe board fitted.", "UNSAFE: Removing or leaning over the guardrail, or exceeding the catwalk's rated load with crew and equipment.", "Assuming any narrow platform is a rated catwalk; access must meet walking-working-surface and fall-protection standards."], "scenario_contexts": ["Focusing house spotlights and wash fixtures from a catwalk over the auditorium.", "Running a cable drop from the catwalk down to a stage lighting position.", "Inspecting catwalk guardrails, toe boards, and flooring before a crew call."]}, "9e3e2ecb-dea3-485b-97b8-cb8c6bc0b150": {"definition": "A catwalk hatch is a hinged or removable access opening, in the catwalk floor or in a wall or ceiling at the catwalk, through which crew climb onto or move along the catwalk, often from a ladder or an adjacent level. Because an open hatch creates a fall opening, it must be guarded or closed when not in use so no one steps into it, consistent with OSHA walking-working-surface requirements.", "plain_english": "A catwalk hatch is a small door or trapdoor that lets crew get onto the catwalk. It is often at the top of a ladder. When it is open there is a hole someone could fall through. So crew close it or guard it right away.", "purpose_function": "It provides a controllable entry and exit point to the catwalk while keeping the walkway enclosed and the fall opening covered when access is not needed.", "practical_application": "A tech climbs a fixed ladder, opens the catwalk hatch to step onto the walkway, then closes it behind them to remove the floor opening.", "category": "Overhead Access", "related_terms": ["Catwalk", "Bridge", "Ceiling access", "Guardrail", "Ladder", "Grid"], "common_mistakes": ["UNSAFE: Leaving a floor hatch open and unguarded behind you, creating a hole someone can step or fall into.", "UNSAFE: Climbing through a hatch with tools or gear in your hands instead of hoisting them separately, so you cannot keep three points of contact.", "Blocking a hatch so it cannot be used as an exit in an emergency."], "scenario_contexts": ["Opening a floor hatch at the top of a ladder to reach a lighting catwalk.", "Closing the catwalk hatch after entry to restore the guarded walking surface.", "Checking that a hatch latches and is not blocked before a show."]}, "7cc056c6-a868-47d3-ba16-a0c19036a16e": {"definition": "Ceiling access refers to the means and openings, such as catwalks, hatches, crawlways, grids, or removable ceiling panels, provided so crew can reach the overhead void of a venue to install, rig, cable, and maintain equipment above the ceiling. Because it involves work at height and sometimes confined or restricted spaces, it is governed by fall-protection and walking-working-surface requirements such as OSHA 29 CFR 1910.28.", "plain_english": "Ceiling access means the ways crew get up into the space above a room's ceiling. This can be a hatch, a walkway, or a removable panel. Crew use it to rig and fix gear overhead. Because it is high up, fall-safety rules apply.", "purpose_function": "It lets crew safely reach overhead structure and equipment for rigging, cabling, and maintenance, while keeping the routes controlled and up to fall-protection standards.", "practical_application": "A rigger uses a ceiling access hatch and catwalk to reach the roof steel, attach a beam clamp, and hang a hoist for a flown rig.", "category": "Overhead Access", "related_terms": ["Catwalk", "Catwalk hatch", "Bridge", "Grid", "Beam clamp", "Fall arrest system"], "common_mistakes": ["UNSAFE: Standing on a suspended ceiling or ceiling tiles, which are not walking surfaces and will not hold a person's weight.", "UNSAFE: Entering an overhead void without fall protection, adequate lighting, or checking for confined-space and electrical hazards.", "Assuming any ceiling opening is a rated access route; access must meet walking-working-surface standards."], "scenario_contexts": ["Using a ceiling hatch to reach roof steel for a new rigging point.", "Accessing the overhead void to run cable to a ceiling-mounted projector or speaker.", "Planning safe ceiling access routes before a rig install in an existing building."]}, "4a0285bd-dbcd-4091-ab00-769a6eb71729": {"definition": "The concealed space between a suspended (dropped) ceiling and the structural floor slab or roof deck above it, typically containing building structure, ductwork, and building services. In rigging it is the zone that must be surveyed to reach genuine load-bearing structure, because suspended-ceiling grids and their hanger wires are not rated to carry rigging loads.", "plain_english": "The hidden gap between a room's drop ceiling and the real roof or floor above it. Riggers open it up to reach the strong steel that can safely hold hung loads.", "purpose_function": "It houses a building's structure and services out of sight while giving riggers access to real structural members for attaching suspension points.", "practical_application": "A rigger lifts ceiling tiles to inspect the void, locate structural steel, and confirm it can take the load before fixing a hanging point.", "category": "Venue Structure", "related_terms": ["Dead-hung pipe", "Hanging point", "Beam clamp", "Working load limit", "Load path", "Rigging point"], "common_mistakes": ["UNSAFE: Attaching rigging loads to the suspended-ceiling grid or its hanger wires, which are only meant to support ceiling tiles, not point loads.", "UNSAFE: Assuming any steel found in the void is structural and load-rated without confirmation from a structural engineer or venue documentation.", "Confusing services and pipework in the void, such as conduit and ductwork, with load-bearing structure.", "Failing to check the void for hazards such as live electrical conduit or fire-stopping before working in it."], "scenario_contexts": ["Surveying a hotel ballroom's ceiling void to find beams for hanging an AV or lighting rig.", "Routing loudspeaker and data cabling through the void during a permanent install.", "Confirming with a structural engineer whether steel in the void can carry a proposed point load."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"4c945e10-b465-47fe-a3d5-34ff38441842": {"definition": "A portable electric chain hoist used in entertainment rigging to raise, lower, and hold overhead loads such as trusses, loudspeakers, and scenery on a load chain. Its design, inspection, maintenance, and use are governed by ANSI/ESTA E1.6-1, E1.6-2, and E1.6-3 and by ASME B30.16.", "plain_english": "An electric hoist that pulls a metal chain to lift and hold heavy gear like trusses and speakers overhead. Crews use it to fly rigs up to working height.", "purpose_function": "It provides controlled, powered vertical movement of flown loads so heavy rigs can be lifted to trim height and held there.", "practical_application": "A rigger hangs the motor from a beam clamp or sling, attaches the load, and runs it up to trim height using a motor controller.", "category": "Powered Hoist", "related_terms": ["Chainfall", "Load chain", "Motor controller", "Truss", "Working load limit", "Bridle"], "common_mistakes": ["UNSAFE: Flying loads over people with a standard fixed-speed hoist; lifting over people requires hoists meeting D8 Plus or C1-type redundant-brake criteria and secondary safety measures.", "UNSAFE: Exceeding the hoist's rated working load limit or ignoring shock and dynamic loading.", "UNSAFE: Two-blocking the hoist or running a twisted, kinked, or damaged load chain.", "Confusing a chain motor, which is powered, with a chainfall, which is a hand-operated chain hoist."], "scenario_contexts": ["Flying a lighting truss to trim height in an arena using a bank of chain motors.", "Suspending line-array loudspeakers from a motor through a bridle.", "Running motors up together on a computer control system to lift a large grid evenly."]}, "a0af56ea-3da8-4346-8ce5-03cc6dabb75b": {"definition": "A manually operated chain hoist that lifts or positions a load by pulling a hand chain through a geared mechanism to move the load chain; also called a chain block or hand chain hoist. It is covered by ASME B30.16 and ASME HST-2.", "plain_english": "A hand-powered hoist that lifts a load when you pull a loop of chain. Gears do the hard work. It works like a block and tackle made of chain.", "purpose_function": "It gives one worker a large mechanical advantage to lift or fine-position heavy loads by hand, without needing electrical power.", "practical_application": "A technician uses a chainfall to make a dead hang, tension a bridle, or adjust a point where no electric motor is available.", "category": "Manual Hoist", "related_terms": ["Chain motor", "Load chain", "Lever hoist", "Working load limit", "Dead-hung pipe", "Bridle"], "common_mistakes": ["UNSAFE: Using a pipe or 'cheater bar' to extend the hand chain for more leverage, which can overload and fail the hoist.", "UNSAFE: Exceeding the rated working load limit or side-loading the hoist.", "UNSAFE: Leaving a suspended load held only on a chainfall as the sole means of support, with no secondary safety.", "Confusing a chainfall (hand chain hoist) with a lever hoist (come-along) or an electric chain motor."], "scenario_contexts": ["Making a permanent dead-hung point where mains power for a motor is unavailable.", "Fine-tuning the height of one leg of a bridle to level a load.", "Lifting a heavy motor or load a short distance during rig-out."]}, "7cd45378-42ee-4ea8-8085-82c1a00832d5": {"definition": "A defined floor area beneath overhead rigging work or a suspended load into which entry is restricted to authorized, informed personnel, with all others excluded by barriers, signage, or spotters. It parallels OSHA's controlled access zone (29 CFR 1926.502(g)) and the standing rule that no one may pass or work under a suspended load.", "plain_english": "A marked-off zone on the floor under rigging work that only trained crew may enter. It keeps everyone else away from anything that could fall.", "purpose_function": "It protects people from dropped tools, hardware, or loads by keeping the area under overhead work clear of anyone not directly involved.", "practical_application": "During a load-in, riggers barricade the deck below and post spotters so the public and other crews stay out while gear is flown.", "category": "Rigging Safety", "related_terms": ["Suspended load", "Fall protection", "Exclusion zone", "Chain motor", "Spotter", "Hard hat"], "common_mistakes": ["UNSAFE: Allowing anyone to stand or pass under a suspended load or active overhead rigging.", "UNSAFE: Treating a controlled-access area as optional for 'quick' lifts, when a dropped object can be fatal from height.", "UNSAFE: Failing to keep barriers and spotters in place for the whole duration of overhead work.", "Assuming a hard hat alone removes the need to keep the area below clear."], "scenario_contexts": ["Barricading the floor beneath a truss being flown during an arena load-in.", "Restricting access under a motorized grid while points are being built.", "Clearing the house below before flying a batten in or out in a theatre."]}, "af54a2ab-e49b-4316-b282-6dc0ce567de6": {"definition": "The steel carriage in a manual counterweight rigging system that holds stacked counterweights (bricks) to balance the load on a batten, riding up and down in guides (T-track or tension-wire) as the set is operated. Its design and use are specified in ANSI/ESTA E1.4-1.", "plain_english": "The metal cradle that holds the stack of steel weights in a stage rigging system. It slides up and down to balance whatever hangs on the pipe.", "purpose_function": "It carries the counterweight that offsets the batten load, so a heavy pipe of scenery or lighting can be moved with little effort.", "practical_application": "A rigger adds or removes bricks on the arbor to match weight added to or taken off the batten, keeping the set in balance.", "category": "Counterweight Rigging", "related_terms": ["Counterweight system", "Batten", "Lift line", "Purchase line", "Rope lock", "Head block"], "common_mistakes": ["UNSAFE: Loading or unloading the arbor out of sequence so the set becomes badly out of balance and runs away.", "UNSAFE: Loading bricks onto the arbor while people work below the batten or on the loading gallery without clear communication.", "UNSAFE: Loading the arbor beyond the system's rated capacity.", "Confusing a single-purchase arbor (1:1) with a double-purchase arbor (2:1), which changes travel and counterweight needed."], "scenario_contexts": ["Balancing an electric batten after hanging lighting fixtures.", "Loading bricks from a loading gallery before flying in a piece of scenery.", "Inspecting arbor guides and spreader plates during a rigging check."]}, "f18d0231-c7e1-4f40-ba18-18e24cc5d168": {"definition": "A manually operated stage rigging system that balances the load on a batten against stacked counterweights carried in an arbor, connected by lift lines running over a head block and loft blocks and operated from an endless purchase line secured by a rope lock. It is standardized in ANSI/ESTA E1.4-1 as manual counterweight rigging.", "plain_english": "A stage system that balances a loaded pipe against a stack of steel weights. Once balanced, one person can raise or lower heavy scenery by hand.", "purpose_function": "It lets a single operator raise and lower heavy battens of scenery, lighting, or drapery by hand by keeping load and counterweight nearly equal.", "practical_application": "A flyman balances each set by loading bricks, then runs battens in and out by hand on the purchase line during a show.", "category": "Counterweight Rigging", "related_terms": ["Counterweight arbor", "Batten", "Purchase line", "Head block", "Loft block", "Rope lock"], "common_mistakes": ["UNSAFE: Releasing the rope lock on an unbalanced (out-of-weight) set, which lets the load or arbor run away.", "UNSAFE: Using the rope lock as a brake to stop a moving or unbalanced set instead of only holding a balanced one.", "UNSAFE: Working under a batten while it is being loaded or is out of balance.", "Assuming the rope lock is a safety device; it is only meant to hold a properly balanced set."], "scenario_contexts": ["Flying scenery in and out during a theatrical performance.", "Weighting a new lighting batten before a hang.", "Training new crew on safe operation and brick-loading procedures."]}, "f47a523f-aa2e-421d-94b3-afcf6fcdfe92": {"definition": "A pipe or batten suspended in a fixed position from overhead structure and not intended to be raised or lowered during use, as opposed to a counterweighted or motorized flying set. It is rigidly supported on fixed-length hardware such as chain, cable, or hanger clamps.", "plain_english": "A pipe hung at one fixed height that does not move up or down. It just stays put to hold lights, drapes, or scenery.", "purpose_function": "It provides a permanent, low-cost hanging position where a movable flying set is not needed.", "practical_application": "A technician clamps fixtures to a dead-hung pipe knowing it stays at a set trim for the run of the show.", "category": "Dead Hanging", "related_terms": ["Dead-hung position", "Batten", "Counterweight system", "Chainfall", "Hanging point", "Pipe clamp"], "common_mistakes": ["UNSAFE: Overloading a dead-hung pipe beyond the rated capacity of its weakest component or support point.", "UNSAFE: Supporting the pipe from non-structural elements, or spacing supports too far apart so the pipe deflects or fails.", "UNSAFE: Omitting a secondary (safety) attachment on fixtures on the assumption that the pipe itself does not move.", "Assuming a dead-hung pipe can later be flown; it has no lift lines or counterweight."], "scenario_contexts": ["Hanging a permanent border light or drape at a fixed trim.", "Adding a fixed pipe where no counterweight set exists.", "Suspending a small loudspeaker cluster at a set height in a house of worship."]}, "07395af3-aa38-4542-8d90-6f1f0676b8ed": {"definition": "A fixed suspended location or trim height at which a load is rigidly hung and held, with no capacity for controlled raising or lowering; the state of being dead-hung. It contrasts with a flown position served by a counterweight set or powered hoist.", "plain_english": "A set height where gear is hung and left in place, with no way to move it up or down. It stays fixed until someone rerigs it.", "purpose_function": "It defines a permanent trim for equipment that does not need to move, simplifying the rig and reducing moving parts.", "practical_application": "A designer specifies a fixture at a dead-hung position when it never needs to travel during the show.", "category": "Dead Hanging", "related_terms": ["Dead-hung pipe", "Trim height", "Flown position", "Hanging point", "Counterweight system", "Chain motor"], "common_mistakes": ["Confusing a dead-hung position with a flown one that can be moved on a motor or counterweight set.", "UNSAFE: Trying to reposition a dead-hung load under tension without proper re-rigging and load control.", "Assuming the trim can be tweaked quickly; changing a dead-hung position means physically re-rigging.", "Forgetting to record the dead-hung trim height for focus and sightline reference."], "scenario_contexts": ["Specifying a fixed trim for a permanently installed loudspeaker.", "Documenting the dead-hung height of house borders for a repertory plot.", "Setting a scenic piece at a fixed height for the run of a show."]}, "26caaa43-bc1e-4467-a0c5-4e8ed2ae13b9": {"definition": "A truss or tower positioned out in the audience, away from the main system, that supports delay loudspeakers electronically delayed to align with sound arriving from the main PA and so extend coverage to distant listeners. The truss or tower structure is governed by ANSI/ESTA E1.2 (aluminum trusses and towers) and, for outdoor use, ANSI/ESTA E1.21.", "plain_english": "A truss or tower set back in the crowd that holds extra speakers. Those speakers play a little late so their sound lines up with the main system.", "purpose_function": "It carries delay loudspeakers out into the audience so far-off listeners hear clear, on-time sound instead of a weak, late signal from the main PA.", "practical_application": "A system tech flies delay boxes on the truss, then sets a delay time so they align with the mains at that distance.", "category": "Loudspeaker Rigging", "related_terms": ["Chain motor", "Line array", "Ground-supported tower", "Signal delay", "Working load limit", "Bridle"], "common_mistakes": ["UNSAFE: Loading a delay truss or tower beyond its rated capacity, or omitting engineered ballast and guying against wind outdoors.", "UNSAFE: Flying delay loudspeakers over the audience without hoists and safeties rated for lifting over people.", "Setting the delay time wrong so the delay speakers smear or echo against the mains.", "Confusing a delay truss with a fill; delays cover distance, while fills cover gaps near the stage."], "scenario_contexts": ["Placing delay towers halfway back at a large outdoor festival.", "Timing delay loudspeakers to the main array for a stadium show.", "Extending coverage down a long, narrow room with a mid-hall delay truss."]}, "bf34020e-b9a4-4be3-99d0-3b1b79448300": {"definition": "In rigging, the fall zone is the area (including but not limited to the space directly beneath a suspended load) in which it is reasonably foreseeable that all or part of the load could fall in the event of an accident. Personnel are kept clear of the fall zone whenever a load is being hoisted, moved, or held overhead.", "plain_english": "The fall zone is the ground area where a hanging load could land if it drops. Nobody should stand there while something is lifted or held overhead.", "purpose_function": "It defines the danger area around a suspended load so people can be kept clear, preventing crushing or impact injuries if a load, its hardware, or its rigging fails.", "practical_application": "Riggers rope off or spot the fall zone during load-ins and flying, and never stand or pass under a moving load or a load held on a hoist.", "category": "Rigging Safety", "related_terms": ["Hanging point", "Working load limit", "Chain hoist", "Overhead load", "Design factor"], "common_mistakes": ["UNSAFE: Walking or standing under a suspended or moving load to save time; the fall zone must stay clear whenever a load is overhead.", "UNSAFE: Assuming the fall zone is only the spot directly beneath the load, when debris or a swinging load can fall well outside that point.", "UNSAFE: Thinking a load held stationary on a hoist is safe to stand under; a hoist or rigging failure can still drop it."], "scenario_contexts": ["Spotting and clearing the deck beneath a motorized truss as it is flown in during load-in.", "Roping off the area under a point where a chain hoist is lifting a line-array cluster.", "Keeping crew out from under a counterweight batten while scenery is loaded onto it overhead."]}, "81c933db-4cd6-4779-be03-412db54615fc": {"definition": "The flies (or fly loft) are the tall volume of space directly above the stage, enclosed by the stage house, into which scenery, drops, electrics, and curtains are raised ('flown out') by the fly system so they hide above the audience's sightlines. The space runs from above the proscenium up to the gridiron.", "plain_english": "The flies are the tall open space above the stage. Scenery and curtains are pulled up into it, out of sight, until they are needed.", "purpose_function": "The flies provide the height needed to store scenery and drops overhead, so pieces can be raised and lowered quickly to change scenes without carrying them on and off.", "practical_application": "A technician flies backdrops, borders, and electrics into the flies between scenes and checks that each flown piece clears the grid and other line sets.", "category": "Stage House", "related_terms": ["Fly system", "Gridiron", "Batten", "Counterweight system", "Proscenium", "Trim height"], "common_mistakes": ["Confusing the flies (the space) with the fly system (the mechanical rigging that raises and lowers loads within that space).", "UNSAFE: Working or standing beneath the flies while line sets are moving without watching for descending battens or scenery.", "Assuming every theatre has flies; venues without a full stage house have little or no fly space."], "scenario_contexts": ["Flying a painted backdrop out into the flies to reveal the set behind it.", "Storing lighting electrics overhead in the flies between focus sessions.", "Setting trim heights so scenery hides fully in the flies above the sightlines."]}, "37234b2d-6656-44cc-ba19-beedb86d7d75": {"definition": "'Float it' is the instruction to lay a scenic flat down to the floor in a controlled fall rather than carrying it. The flat is pushed off vertical and allowed to drop face-up; air trapped beneath the surface cushions the descent so it settles gently, while a worker steadies the bottom rail with a foot.", "plain_english": "To 'float' a flat means to let a tall scenery panel fall flat to the floor on purpose. The air trapped underneath slows it, so it lands softly instead of slamming down.", "purpose_function": "It lets one or two people lay a large, light flat down quickly without carrying its full weight, using air resistance to control and slow the fall.", "practical_application": "A carpenter floats a flat during a scene change or strike, bracing the bottom rail with a foot and clearing people and objects from the landing area before letting it drop.", "category": "Scenery Handling", "related_terms": ["Flat", "Strike", "Walking a flat", "Deck", "Scenic carpentry"], "common_mistakes": ["UNSAFE: Floating a flat without first clearing people and objects from the area where it will land; a dropping flat can strike anyone underneath.", "UNSAFE: Floating a heavy, framed, or hard-covered flat; only light soft-covered flats float safely, others must be carried or walked down.", "UNSAFE: Floating a flat with hardware, glass, or set dressing still attached that can break or fly loose on impact.", "Letting go of the bottom rail so the flat slides or kicks out instead of settling in place."], "scenario_contexts": ["Laying a soft-covered flat down during a fast scene change.", "Striking a set at the end of a run and floating light flats to stack them.", "Lowering a flat to the deck when there is no room to carry or walk it out."]}, "a5a263f7-6248-456f-adc4-d8377952cdf9": {"definition": "A followspot bridge is an elevated walkway or platform, usually set high at the rear or side of the auditorium, built as a fixed operating position for followspot operators and their spotlights. It gives a stable, guarded standing position with a clear throw and sightline to the stage.", "plain_english": "A followspot bridge is a high walkway where spotlight operators stand. From up there they have a clear view to aim their beams and follow performers around the stage.", "purpose_function": "It places followspot operators at a height and angle that give good light onto performers, while keeping them and their equipment safely off the auditorium floor.", "practical_application": "A spot operator climbs to the followspot bridge before the show, sets up and cables the spotlight there, and runs cues following performers from that fixed position.", "category": "Overhead Access", "related_terms": ["Followspot", "Front-of-house catwalk", "Lighting bridge", "Control booth", "Throw distance"], "common_mistakes": ["Confusing a followspot bridge (an operating position over the house) with an onstage lighting bridge used mainly to hang fixtures.", "UNSAFE: Leaning tools, gel frames, or spotlights on the bridge rail without a safety tether, where they can fall onto the audience below.", "Assuming every venue has one; many rooms use a followspot room, booth, or floor position instead."], "scenario_contexts": ["Operating a long-throw followspot from the bridge during a musical number.", "Rigging and cabling spotlights on the followspot bridge during focus.", "Choosing the bridge over a floor position to get a steeper, cleaner lighting angle."]}, "eb7708e9-861b-4073-a544-15e08f0f51fc": {"definition": "A front-of-house catwalk is a narrow elevated access walkway above or within the auditorium ceiling (the 'front of house'), from which lighting fixtures are hung, cabled, and focused to light the stage from the audience side. It gives crew safe overhead access to FOH lighting positions.", "plain_english": "A front-of-house catwalk is a narrow walkway up in the ceiling over the audience. Crew stand on it to hang and aim the stage lights that shine from the audience side.", "purpose_function": "It provides a safe, permanent way to reach lighting positions above the audience, so fixtures can light the stage from the front without ladders or lifts every time.", "practical_application": "An electrician walks the FOH catwalk to hang, cable, and focus front light, clamping each fixture to the pipe and adding a safety cable before it is used.", "category": "Overhead Access", "related_terms": ["Followspot bridge", "Lighting bridge", "Front of house", "Cove", "Safety cable"], "common_mistakes": ["UNSAFE: Setting tools or fixtures on the catwalk without a safety cable or tether, so they can fall onto the audience below.", "UNSAFE: Hanging more fixtures than the catwalk or its pipe is rated to carry, overloading the structure.", "Confusing the FOH catwalk (over the house) with an onstage bridge or the gridiron over the stage."], "scenario_contexts": ["Hanging and focusing front-of-house wash and key light before a show.", "Running control or DMX cable along the catwalk to FOH fixtures.", "Accessing a dead fixture over the audience for a lamp change from the catwalk."]}, "e03b068b-2add-4bc5-ad91-968801f4a6fa": {"definition": "In the stage house, a gallery is a raised, narrow walkway running along a side or rear wall above the stage floor, giving crew a working level for the fly system: the fly gallery carries the operating lines and the loading gallery is where counterweights are added to arbors. (In the auditorium, 'gallery' also names an upper tier of audience seating.)", "plain_english": "A gallery is a high, narrow walkway along the wall above the stage. Crew stand on it to work the ropes and weights that raise and lower scenery.", "purpose_function": "It gives crew a fixed working level up in the stage house to operate fly lines and load counterweights, instead of doing all of that from the stage floor.", "practical_application": "A flyperson works line sets from the fly gallery, or loads and unloads counterweights from the loading gallery to match the scenery hung on each batten.", "category": "Overhead Access", "related_terms": ["Fly gallery", "Loading gallery", "Pin rail", "Counterweight system", "Gridiron", "Arbor"], "common_mistakes": ["UNSAFE: Knocking or dropping tools, weights, or hardware off the gallery onto people on the stage floor below.", "UNSAFE: Loading or unloading counterweights out of sequence with the batten load, so the line set becomes badly unbalanced and runs away.", "Confusing the fly gallery (the operating level) with the loading gallery (where counterweights are added to the arbor)."], "scenario_contexts": ["Operating counterweight line sets from the fly gallery during a performance.", "Adding brick weights to an arbor from the loading gallery to balance a new electric.", "Reaching the pin rail on the gallery to tie off hemp lines."]}, "6815e86a-a59b-4175-98dc-60eacc0d7c8d": {"definition": "A gantry is an overhead structural framework that spans a space and is supported by legs or uprights at each side, from which loads are suspended or along which a hoist or crane travels. In staging it also refers to a ground-supported 'goalpost' or tower-and-beam structure used to fly or support equipment where no permanent overhead rigging exists.", "plain_english": "A gantry is a bridge-like frame held up by legs on each side. Loads hang from it, or a hoist rides along it, when there is no ceiling to rig from.", "purpose_function": "It creates its own overhead support point, so loads can be hung or lifted in spaces (such as arenas or outdoors) that have no fixed rigging structure.", "practical_application": "A rigger erects a ground-supported gantry or goalpost to fly a line array or truss where the roof cannot be used, verifying each leg and its base loading.", "category": "Support Structure", "related_terms": ["Ground support", "Goalpost", "Truss", "Hanging point", "Chain hoist", "Working load limit"], "common_mistakes": ["UNSAFE: Loading a gantry or its legs beyond their rated capacity, or without engineered base plates, so it can buckle or overturn.", "UNSAFE: Failing to plumb, brace, or ballast a ground-supported gantry, letting it sway or collapse under wind or side load.", "Assuming a gantry can be placed anywhere; the load path down each leg to the floor must be rated and verified."], "scenario_contexts": ["Erecting a ground-supported goalpost gantry to fly a PA in an arena with no house points.", "Running a hoist along an overhead gantry beam to move heavy equipment in a scene shop.", "Using a gantry structure outdoors, where ANSI/ESTA E1.21 wind and load rules apply."]}, "515eca38-6a8b-4e05-8d29-1ab6b981dd4f": {"definition": "A hanging point (or rigging point) is a location, such as a structural attachment on the building, grid, or truss, from which a load is suspended in the air. Each point has a rated capacity (working load limit) set by the weakest element in its load path, which must never be exceeded.", "plain_english": "A hanging point is the spot up high where a load is hung from. Each point can safely hold only a set weight, and you must never hang more than that.", "purpose_function": "It transfers the weight of flown equipment safely into the building's structure, so loads such as truss, speakers, and scenery can hang overhead without failing.", "practical_application": "A rigger locates or installs hanging points on the structure, confirms each point's rated capacity against the load, and attaches slings, shackles, or hoists to them.", "category": "Rigging Point", "related_terms": ["Working load limit", "Fall zone", "Bridle", "Shackle", "Chain hoist", "Load path"], "common_mistakes": ["UNSAFE: Hanging a load heavier than the point's rated capacity, or guessing the capacity instead of confirming it from an engineer or documentation.", "UNSAFE: Rating a point by its strongest part and ignoring the weakest link in the load path (beam clamp, shackle, sling, or structure).", "UNSAFE: Adding side load or a wide bridle angle that multiplies the force on the point beyond its vertical rating.", "Reusing 'house points' without checking their current condition, rating, or paperwork."], "scenario_contexts": ["Marking out and rating hanging points on an arena roof grid before a load-in.", "Selecting structural beams as hanging points for a truss and calculating each point's share of the load.", "Rigging a bridle between two hanging points to position a hoist over a target."]}, "6faffcbf-e716-495a-b310-54ebcd554b3a": {"definition": "A hatch is a covered opening in a floor, wall, ceiling, or platform that provides access or a passage between levels or spaces. In a theatre this includes trap-style openings in the stage floor, loading hatches in the scene dock or grid, and access hatches onto galleries or the roof.", "plain_english": "A hatch is a small covered opening you can pass through, like a door set into a floor or wall. In a theatre it might lead under the stage or up to a walkway.", "purpose_function": "It gives controlled access or a route for people or equipment between levels or spaces, while its cover closes the opening off and keeps it safe when not in use.", "practical_application": "A technician opens a hatch to pass gear up to the grid or down to the trap room, then closes and secures it so no one falls through.", "category": "Stage Opening", "related_terms": ["Trap", "Grid", "Scene dock", "Understage", "Loading gallery"], "common_mistakes": ["UNSAFE: Leaving a floor or grid hatch open and unguarded, creating a fall-through hazard in low backstage light.", "UNSAFE: Standing on or stacking loads on a hatch cover that is not rated to carry that weight.", "Confusing a hatch (a covered access opening) with a trap (a stage-floor opening used for entrances and effects)."], "scenario_contexts": ["Passing cable and tools up through a grid access hatch during a rig.", "Opening an understage hatch to move a performer or prop into the trap room.", "Securing a roof or loading-gallery hatch after moving equipment through it."]}, "bdc35d40-2091-4bf3-ae36-b2ce3bbd8687": {"definition": "A head block is the large multiple-sheave block at the head of a counterweight or hemp lineset, mounted above the operating rail, through which all of that set's lift lines pass together and change direction before dropping to the arbor or hand line. Because every lift line of the set runs over it, the head block gathers the lines coming from the separate loft blocks and carries the full suspended load of the lineset.", "plain_english": "A head block is a large pulley at the top of a stage flying system. All the lift lines for one pipe pass over it together. It turns them to run straight down to the crew or the weights. It carries the full weight of that load.", "purpose_function": "It collects all the lift lines of a lineset from their separate loft blocks and turns them from running across the grid to running straight down, delivering them in line to the arbor or hand line so the whole batten can be raised and lowered as one unit.", "practical_application": "During a rigging inspection a technician checks the head block's sheaves, bearings, wire-rope grooves, and mounting steel, because it carries the entire load of the lineset and its failure would drop everything on that batten.", "category": "Fly system hardware", "related_terms": ["Loft block", "Counterweight system", "Arbor", "Lift line", "Batten", "Pin rail"], "common_mistakes": ["Confusing the head block with a loft block: loft blocks are the several pulleys spread along the grid that support the lift lines, while the head block is the single multi-sheave block that gathers them all at the head of the set.", "Assuming each lift line only carries its own share of the load at the head block; because every line of the set passes over it, the head block must be rated for the full lineset load, not one line's share.", "UNSAFE: Loading or operating a lineset without inspecting the head block; a worn sheave, failed bearing, or cracked mounting can release the entire suspended load, and overhead rigging must be inspected by a qualified person per ANSI/ESTA E1.4-1 and ASME B30 before use."], "scenario_contexts": ["Tracing all of one batten's lift lines from the loft blocks to the head block during a counterweight system inspection.", "Diagnosing a noisy or binding lineset by checking the head block sheaves and bearings.", "Reading a rigging drawing to confirm the head block is mounted directly over the operating rail.", "Specifying a head block rated for the full lineset load on a new counterweight installation."]}, "ca2df5db-b9e5-43f3-bd48-7c0afd0c1d20": {"definition": "Head-block level is the elevation at the top of a fly system at which the head block is installed, generally just beneath the gridiron and above the loft blocks and operating rail. It serves as a reference height for the head of a lineset; as the arbor rises toward the top of its travel it approaches head-block level, which helps set the batten's maximum out (high) trim.", "plain_english": "Head-block level is the height where the head block sits, near the very top of the fly system. It marks how high things can go. When the counterweights rise close to it, the pipe is near its highest point.", "purpose_function": "It gives riggers a fixed reference elevation at the head of the system, used to describe how high a lineset reaches and to plan the available travel and high trim of its batten.", "practical_application": "A rigger uses head-block level as a datum when measuring grid heights, planning trims, and confirming an arbor has enough travel to bring its batten to the needed high trim before the arbor reaches the head block.", "category": "Trim and travel", "related_terms": ["Head block", "Gridiron", "High trim", "Out trim", "Arbor", "Batten"], "common_mistakes": ["Confusing head-block level, the fixed height of the head block, with high trim, the highest position a particular batten is set to for a show; the head block stays put while trims change from cue to cue.", "Assuming a batten can be flown all the way up to head-block level; out-travel is limited by arbor travel and by the loft blocks, so the batten stops well below the head block.", "Ignoring available arbor travel when planning a high trim, then finding the arbor bottoms out at the head block before the batten reaches the wanted height."], "scenario_contexts": ["Recording grid and head-block heights on a rigging line schedule for a venue.", "Checking that a new lineset's arbor has enough travel below head-block level to reach the required high trim.", "Explaining to a student why a batten cannot fly all the way up to the gridiron."]}, "a7317be9-493d-4ff7-bd91-4237f9869179": {"definition": "A hemp system (hemp rigging) is a manually operated fly system in which sets of hand lines—historically natural-fiber hemp or manila rope, today often synthetic—run up to loft blocks, across the grid to a head block, and down to a pin rail, where they are tied off on belaying pins. It is the earliest form of stage rigging and has no counterweight assist, so operators raise and lower the full weight of the load by muscle, often adding sandbags to help balance the lines.", "plain_english": "A hemp system is the oldest way to fly stage scenery. Ropes run up over pulleys and back down to a rail. The crew ties them off on pins. There are no weights to help, so people lift the full load by hand.", "purpose_function": "It lets a crew raise, lower, and store overhead scenery, drapery, and lights using only rope, blocks, and hand power, giving a simple, low-cost way to fly loads where no counterweight or powered system is installed.", "practical_application": "In an older 'hemp house' theatre, stagehands work the hemp lines from the pin rail, hauling loads up by hand and belaying (tying off) the lines on pins, usually in teams and using sandbags to manage heavy pieces.", "category": "Fly system type", "related_terms": ["Pin rail", "Loft block", "Head block", "Counterweight system", "Sandbag", "Batten"], "common_mistakes": ["Calling every fiber rope line 'hemp' by fiber type; the rope may be manila or synthetic, but the manual rope-and-pin system keeps the name 'hemp' regardless of the actual fiber.", "Confusing a hemp system with a counterweight system; a hemp set has no arbor or weights to balance the load, so the operator supports the entire weight directly.", "UNSAFE: Releasing or belaying a loaded hemp line without enough trained crew or proper technique; with no counterweight, an unbalanced line can run away and drop the load, so loads must be controlled by adequate qualified crew and tied off correctly per ANSI/ESTA E1.4-1 and qualified-rigger guidance.", "UNSAFE: Using worn, cut, or degraded rope on a hemp line; fiber rope must be inspected and removed from service when damaged, because a rope failure drops the suspended load."], "scenario_contexts": ["Operating scenery from the pin rail in a historic hemp house with no counterweight system.", "Hanging a temporary drop on a spot line hauled up by hand over loft blocks.", "Teaching new stagehands to belay and tie off hemp lines safely on belaying pins.", "Adding sandbags to balance a heavy piece on a hemp set before a scene change."]}, "be3dd931-de26-42f2-b64e-cf60eaba6b02": {"definition": "High trim is the higher of the preset height positions to which a flown batten and its scenery, drape, or lighting are set—its raised or 'out' position, usually flown up out of the audience's sightlines for storage or between cues. It is one of the plotted trim heights recorded for a lineset, contrasted with low trim, the lowered 'in' or playing position.", "plain_english": "High trim is the up position for a flown pipe and whatever hangs on it. It is set high, usually out of the audience's view. Crews fly a piece to its high trim to store it or clear the stage.", "purpose_function": "It defines a repeatable raised height for a lineset so the same piece stops at the same 'out' position every time, keeping it clear of the stage picture, other scenery, and the audience's sightlines.", "practical_application": "An operator flies a batten up until its trim marks line up at the plotted high trim, then confirms it is level and clear before tying off or recording the height in the show's cue or line-set schedule.", "category": "Trim and travel", "related_terms": ["Low trim", "In trim", "Trim", "Batten", "Sightline", "Lineset"], "common_mistakes": ["Swapping high and low trim: high trim is the raised, stored 'out' position, while low trim is the lowered playing 'in' position.", "Setting a high trim without checking sightlines, so the piece is still visible from some seats when it should be masked out of view.", "UNSAFE: Flying to a high trim that lets a piece or its arbor strike the grid, other scenery, or a person overhead; trims must be planned and travel checked so nothing collides, following safe rigging practice per ANSI/ESTA E1.4-1."], "scenario_contexts": ["Setting the out (high) trim for a border so it masks the fly loft but hangs clear above the set.", "Flying a lit backdrop to high trim between scenes to clear the stage.", "Recording high and low trims for every lineset during a technical rehearsal."]}, "cfbc4409-6481-4e89-b917-4952f999832e": {"definition": "'In trim' means a flown batten and its load are sitting at their correct, plotted trim height and hanging level end to end—at the exact position set for that moment in the show. Saying a piece is 'in trim' confirms it has reached its designated mark and is even, neither too high nor too low nor tilted.", "plain_english": "'In trim' means a flown pipe is sitting at exactly the right height. It is also hanging level, not tilted to one side. When a piece is in trim, it is where it should be and ready to go.", "purpose_function": "It is the confirmation state operators aim for: it tells the crew a lineset has reached its plotted height and is level, so the stage picture looks right and the piece is set for the cue.", "practical_application": "During a cue an operator flies a piece until its trim marks align and it hangs level, then calls or logs it as 'in trim' so the stage manager and crew know it is set correctly.", "category": "Trim and travel", "related_terms": ["Trim", "High trim", "Low trim", "Out trim", "Batten", "Lineset"], "common_mistakes": ["Reporting a piece 'in trim' when it is at the right height but visibly tilted; being in trim requires the batten to be level as well as at the correct height.", "Assuming 'in trim' means fully flown in or down; it means at the plotted trim for that cue, which may be a high, mid, or low position.", "UNSAFE: Working or walking under a batten before confirming it is truly in trim and secured; a piece still moving or not tied off can shift or drop, so keep clear until the load is set and secured following safe rigging practice."], "scenario_contexts": ["Confirming a lit drop is 'in trim' and level before the stage manager calls the next cue.", "Adjusting one lift line so a batten that hangs low on one end comes level and sits in trim.", "Checking that an electric is in trim at its plotted height before focus begins."]}, "b4512deb-9c2e-4ce4-a562-35fe652cb56d": {"definition": "A lift line is one of the suspension cables (today typically wire rope, historically fiber rope) that runs from a batten up to its loft blocks, across the gridiron to the head block, and down to the arbor or hand line, physically carrying the batten and its load. A counterweight or hemp lineset uses several lift lines spaced along the batten so the load is supported at multiple points and can be raised and lowered as one unit.", "plain_english": "A lift line is a strong wire rope that holds up a stage pipe and its load. Several lift lines run from the pipe up over pulleys and back down to the weights or the crew. Together they carry the whole load and raise or lower it.", "purpose_function": "Lift lines transmit the weight of the batten and everything hung on it from the several loft blocks to the head block and on to the arbor or hand line, so the whole load is supported at multiple points and can be flown up and down together.", "practical_application": "A rigger inspects each lift line for broken wires, kinks, corrosion, and secure end terminations, and checks that all lines of a set are evenly tensioned so the batten hangs level and no single line is overloaded.", "category": "Fly system hardware", "related_terms": ["Loft block", "Head block", "Arbor", "Batten", "Counterweight system", "Wire rope"], "common_mistakes": ["Assuming each lift line carries only its own local share of the load; because the lines share one batten and all pass over the head block, the head block and its lines must be rated for the full lineset load.", "Confusing a lift line with the operating (hand) line; lift lines suspend the batten, while the operating line is what the crew pulls to move the set.", "UNSAFE: Keeping a lift line in service with broken wires, kinks, or corrosion; damaged wire rope must be inspected and removed from service per ASME B30 and ANSI/ESTA E1.4-1 because a lift-line failure drops the suspended load."], "scenario_contexts": ["Inspecting each lift line of a counterweight set for broken wires and secure terminations before a load-in.", "Adjusting lift-line tension so a batten that hangs low on one end comes level.", "Tracing a set's lift lines from the batten up through the loft blocks to the head block during a rigging survey.", "Replacing a wire-rope lift line and its end fittings after damage is found during inspection."]}, "7e115c28-8a4d-4391-b12b-4e16ed2f4001": {"definition": "A lighting bridge is an overhead access structure suspended above the stage that carries stage-lighting instruments and gives crew a working platform to hang, cable, focus, and maintain them. Unlike a fixed building catwalk, a lighting bridge is a load-rated structure hung over the acting area, and in some houses it is a powered or counterweighted unit that can be raised and lowered.", "plain_english": "A lighting bridge is a walkway hung over the stage to hold and reach stage lights. Crew stand on it to aim and fix the lights above the actors. Some bridges can be raised and lowered like a big pipe.", "purpose_function": "It combines a lighting hanging position with a walk-on platform, so technicians can safely reach the instruments to focus and service them instead of working from a ladder or personnel lift over the stage.", "practical_application": "During focus, an electrician stands on the lighting bridge to aim and adjust the fixtures mounted on it, running cable along the bridge and clipping into fall protection where the structure and local rules require it.", "category": "Overhead Access", "related_terms": ["Lighting catwalk", "Lighting truss", "Followspot bridge", "Batten", "Fall protection", "Loading gallery"], "common_mistakes": ["Treating any overhead lighting position as a 'bridge'; a bridge is a walk-on load-rated platform, whereas many positions are just battens, pipes, or trusses with no crew access.", "Assuming a lighting bridge that can be flown may be raised with crew still on it; movable bridges have rated occupancy and travel limits that must be followed.", "UNSAFE: Overloading a lighting bridge with fixtures plus crew beyond its rated capacity, or working on it without required fall protection; overhead platforms must be used within their rated load and per OSHA 1910/1926 fall-protection and ANSI/ESTA E1.4 rigging requirements."], "scenario_contexts": ["Focusing front light for a scene from an over-stage lighting bridge.", "Running and dressing cable to the fixtures hung on a lighting bridge during load-in.", "Lowering a movable lighting bridge to deck level to re-hang and service its instruments safely.", "Assigning a hang position on the No. 1 lighting bridge in a theatre's light plot."]}, "500fadf9-2550-4c9c-a363-36948242761e": {"definition": "A lighting catwalk is a fixed, elevated walkway built into a theatre or venue that gives crew access to overhead lighting positions to hang, cable, focus, and maintain instruments over the stage or auditorium. As a permanent part of the building structure it does not move, distinguishing it from a flown lighting bridge or a hung lighting truss.", "plain_english": "A lighting catwalk is a narrow walkway built high in the ceiling of a theatre. Crew walk out on it to hang, aim, and fix the lights over the stage or seats. It is part of the building and does not move.", "purpose_function": "It provides safe, permanent overhead access so technicians can reach lighting (and often audio and rigging) positions to work on them, rather than relying on ladders or lifts for routine focus and maintenance.", "practical_application": "A technician walks the house or over-stage catwalk to hang and focus front-of-house fixtures, keeping tools tethered and clipping into any provided anchor points while working at height.", "category": "Overhead Access", "related_terms": ["Lighting bridge", "Catwalk", "Front-of-house catwalk", "Cove", "Fall protection", "Lighting truss"], "common_mistakes": ["Confusing a fixed lighting catwalk with a lighting bridge; a catwalk is permanent building structure, while a bridge is a rigged, sometimes movable platform over the stage.", "Assuming a catwalk's guardrail alone makes any task safe; reaching out or leaning over may still require personal fall protection and tool tethers.", "UNSAFE: Dropping tools or fixtures from a catwalk onto people below, or carrying loads that exceed the catwalk's rating; secure and tether everything and follow OSHA 1910/1926 fall-protection and falling-object rules when working overhead."], "scenario_contexts": ["Hanging and focusing front-of-house wash from a house lighting catwalk.", "Accessing an over-stage catwalk to service instruments and dress cable between shows.", "Establishing a drop zone below the catwalk before passing tools or fixtures up.", "Marking permanent catwalk positions on a venue's lighting hang plot."]}, "1b7f391d-6f74-4a63-81a4-ac85b22a843e": {"definition": "A lighting truss is a prefabricated, load-rated lattice structure, usually of welded aluminum chords and diagonal webbing, used to suspend and support stage-lighting fixtures overhead. Its triangulated construction gives high strength and stiffness at low weight, and it is flown from rigging points by chain hoists or dead-hung, with its safe working load and allowable point loads set by the manufacturer's load tables.", "plain_english": "A lighting truss is a light but strong metal frame that holds stage lights up high. It is made of aluminium bars joined in a lattice, like a bridge girder. Motors or fixed points lift it and its lights over the stage.", "purpose_function": "It provides a rigid, portable, load-rated beam to hang many fixtures across a span and fly them together, spreading the load to a few rigging points instead of many separate hangs.", "practical_application": "A rigger builds truss on the ground, hangs fixtures and cable, attaches chain hoists at rated pick points, and flies it to trim, staying within the manufacturer's span, point-load, and total-load limits.", "category": "Rigging Structure", "related_terms": ["Chain motor", "Rigging point", "Safe working load", "Lighting bridge", "Span", "Dead-hung pipe"], "common_mistakes": ["Reading the truss rating as one fixed number; allowable load depends on span and on whether it is a uniformly distributed or point load, so the manufacturer's load table for that span must be used.", "Mixing truss sections, connectors, or spigots from different systems or makers, which voids the load rating because the parts are not verified to work together.", "UNSAFE: Overloading a truss, exceeding its rated span, or hanging point loads beyond the load table; entertainment trusses must be used within manufacturer limits and per ANSI/ESTA E1.2 and E1.21, since overloading can collapse the truss and drop it."], "scenario_contexts": ["Assembling and loading a front truss on the ground before flying it to trim with chain hoists.", "Checking a manufacturer load table to confirm fixture weights are within the truss's rating for its span.", "Dead-hanging a short truss from building steel to carry a cluster of fixtures over a small stage.", "Inspecting truss chords, welds, and connectors for damage before it is rigged."]}, "87dcae0a-179e-411e-8e2a-68576ea3021f": {"definition": "A loading bridge is the elevated gallery near the top of the fly loft, at or just below arbor top-of-travel, from which crew add and remove counterweights on the arbors. It is the working platform of the counterweight loading operation, so counterweights can be matched to a batten's load high in the stage house.", "plain_english": "A loading bridge is a high walkway near the top of the stage house. Crew stand on it to add or take off the metal weights that balance flown pipes. This is done so a loaded pipe is easy to move by hand.", "purpose_function": "It puts crew at the height of the arbors when they are at the top of travel, so weight can be loaded onto or stripped from an arbor to balance a batten before or after scenery, drapery, or lighting is hung on it.", "practical_application": "When a piece is hung on an out-of-balance batten, a loader on the loading bridge adds counterweight bricks to the arbor to match the new load before the set is operated from the locking rail.", "category": "Counterweight Rigging", "related_terms": ["Loading gallery", "Arbor", "Counterweight system", "Locking rail", "Batten", "Head block"], "common_mistakes": ["Confusing the loading bridge with the locking rail; loading happens high at the loading bridge, while the set is operated and locked off at the locking rail, usually near stage level.", "Loading or unloading weight while the batten is being worked below, instead of coordinating so the arbor is safely accessible and the set is not moved during loading.", "UNSAFE: Overloading or stripping an arbor out of balance without controlling the system; a badly out-of-balance set can run away, so crew must load to balance and follow safe counterweight procedure and calls per ANSI/ESTA E1.4-1."], "scenario_contexts": ["Loading counterweight bricks onto an arbor from the loading bridge after an electric is hung.", "Stripping weight off an arbor on the loading bridge before a batten's scenery is struck.", "Coordinating calls between the loading bridge and the locking rail during a weight change.", "Checking that counterweights on the loading bridge are stacked and secured, not left loose near the edge."]}, "0510de0e-285a-40ff-9073-0b6c6f6c0186": {"definition": "A loading gallery is the elevated walkway high in the stage house, at or near arbor top-of-travel, where crew add and remove counterweights on the arbors of a counterweight fly system. Storage racks for counterweight bricks are typically kept there so weight can be matched to each batten's load. The term is often used interchangeably with loading bridge.", "plain_english": "A loading gallery is a high walkway in the stage house where crew load the counterweights. It sits near the top, where the weight carriers reach when a pipe is down. Crew add or remove weights there to balance each pipe.", "purpose_function": "It provides access and storage at arbor height so loaders can balance each lineset by adding or removing counterweight bricks, keeping the flown load manageable to operate by hand from below.", "practical_application": "A loader works from the loading gallery, taking bricks from the racks and setting them on the arbor to match a newly hung load, in step with the operator's calls before the set is run.", "category": "Counterweight Rigging", "related_terms": ["Loading bridge", "Arbor", "Counterweight system", "Locking rail", "Batten", "Fly loft"], "common_mistakes": ["Thinking the loading gallery is where the set is operated; operating and locking happen at the locking rail, while the gallery is only for adding and removing weight high in the house.", "Leaving counterweight bricks unsecured or stacked past the rack edge on the gallery, where they can be knocked off onto crew below.", "UNSAFE: Loading or unloading an arbor out of balance without controlling the lineset; an unbalanced counterweight set can run away, so weight must be brought to balance following safe procedure and calls per ANSI/ESTA E1.4-1."], "scenario_contexts": ["Adding counterweight from the loading gallery racks after hanging a heavy drop.", "Removing bricks on the loading gallery before a lighting electric is de-rigged.", "Restocking and organizing the counterweight racks on the loading gallery during a dark day.", "Coordinating a weight change between the loading gallery and the operator at the locking rail."]}, "44e8a81c-25cc-4b75-8a94-d10ec19f274c": {"definition": "The locking rail is the rail carrying the rope locks for a counterweight fly system's operating lines, at the operating position from which the crew work the sets. Each lineset's rope lock is mounted on it, letting an operator hold a balanced set in place; it is the counterweight-system counterpart to the hemp system's pin rail.", "plain_english": "A locking rail is the row of rope locks that hold each flown pipe in place. An operator pulls a rope lock to stop a pipe from moving. It is where the crew work the fly system from.", "purpose_function": "It gathers all the rope locks at one operating position so an operator can secure each balanced lineset and release it to fly, giving a single, organized place to run the counterweight system.", "practical_application": "An operator stands at the locking rail, releases the rope lock for a set, flies the batten to trim, then re-engages the lock, working from the cue sheet and stage manager's calls.", "category": "Counterweight Rigging", "related_terms": ["Rope lock", "Pin rail", "Counterweight system", "Arbor", "Operating line", "Loading gallery"], "common_mistakes": ["Treating the rope lock as a brake; a rope lock only holds a balanced set in place and is not designed to stop or hold a badly out-of-balance load.", "Confusing the locking rail with the pin rail; the locking rail carries rope locks in a counterweight system, while the pin rail carries belaying pins in a hemp system.", "UNSAFE: Releasing a rope lock at the locking rail on an out-of-balance set; the set can run away and drop or fly the load, so balance must be confirmed before the lock is released, per ANSI/ESTA E1.4-1 and safe operating procedure."], "scenario_contexts": ["Operating linesets from the locking rail during a performance run.", "Confirming a set is in balance before releasing its rope lock at the locking rail.", "Locating a specific lineset's rope lock on the locking rail from the line-set schedule.", "Inspecting rope locks on the locking rail for proper adjustment and secure mounting."]}, "d395c518-9813-4ff4-8cfe-791a497b7b7a": {"definition": "A loft block is a sheave block mounted on the gridiron above each point where a lift line rises from the batten, turning that lift line from vertical to horizontal so it can run across the grid to the head block. A counterweight or hemp lineset uses several loft blocks, one per lift line, spaced along the batten to support the load at multiple points.", "plain_english": "A loft block is a pulley fixed to the steel grid high above the stage. A lift line rises from the pipe and turns sideways over it. Each pipe uses several loft blocks to send its lines across to one big pulley.", "purpose_function": "Each loft block redirects one lift line at its hang point and carries that line's share of the load, together spacing the support along the batten and feeding all the lines across the grid to the head block.", "practical_application": "During inspection a rigger checks each loft block's sheave, bearing, wire-rope groove, and mounting for wear or damage, since a failed loft block releases the lift line it supports.", "category": "Fly system hardware", "related_terms": ["Head block", "Lift line", "Gridiron", "Batten", "Arbor", "Counterweight system"], "common_mistakes": ["Confusing loft blocks with the head block; loft blocks are the several blocks spread along the grid that each turn one lift line, while the head block is the single multi-sheave block that gathers them all.", "Assuming all loft blocks carry equal load; an uneven or off-center hang can put more load on some blocks and lift lines than others.", "UNSAFE: Leaving a worn sheave, failed bearing, or loose mounting on a loft block in service; overhead rigging must be inspected by a qualified person per ANSI/ESTA E1.4-1 and ASME B30, since a loft-block failure drops its lift line and part of the load."], "scenario_contexts": ["Inspecting the loft blocks along a lineset for worn sheaves and secure mounting during a rigging survey.", "Tracing a lift line from the batten up to its loft block and across to the head block.", "Adding or repositioning a loft block when a lineset's lift-line spacing is changed.", "Diagnosing a binding or noisy set by checking the loft-block bearings and grooves."]}, "0933a6de-c2c0-4302-a7b1-bb9ea1b5a78f": {"definition": "Low trim is the lower of the preset height positions to which a flown batten and its scenery, drape, or lighting are set—its lowered or 'in' position, generally the playing height at which the piece is seen or used on stage. It is one of the plotted trim heights recorded for a lineset, contrasted with high trim, the raised 'out' position.", "plain_english": "Low trim is the down position for a flown pipe and whatever hangs on it. It is the height used when the piece is seen or used in the show. Crews fly a piece to its low trim so it lands in the same spot each time.", "purpose_function": "It defines a repeatable lowered height for a lineset so the same piece stops at the same 'in' position every time, keeping the stage picture consistent from cue to cue and performance to performance.", "practical_application": "An operator flies a batten down until its trim marks align at the plotted low trim, then confirms it is level and clear before the cue continues or the height is logged on the line-set schedule.", "category": "Trim and travel", "related_terms": ["High trim", "In trim", "Trim", "Batten", "Lineset", "Sightline"], "common_mistakes": ["Swapping low and high trim: low trim is the lowered playing 'in' position, while high trim is the raised, stored 'out' position.", "Flying to low trim without checking clearances, so the piece lands into scenery, furniture, or a performer's path.", "UNSAFE: Bringing a batten to a low trim over people without warning or spotters; loads must be flown in with the area clear and proper calls given, following safe rigging practice per ANSI/ESTA E1.4-1."], "scenario_contexts": ["Setting the low (in) trim for a backdrop so it meets the deck at the right playing height.", "Flying a lighting electric to its low trim for focus, then back to high trim for the show.", "Recording high and low trims for every lineset during a technical rehearsal.", "Confirming a piece is level and clear at low trim before the next cue is called."]}, "05edf33f-78f9-4532-97ce-b9e74a77b31c": {"definition": "A mother truss is a large primary load-bearing truss, flown from the venue's overhead steel or from hoists, that in turn supports secondary (daughter) trusses, hanging points, or equipment suspended beneath it. It forms the top level of a layered rigging structure, gathering the combined loads of the sub-hung elements and transferring them to a limited number of rated overhead attachment points.", "plain_english": "A mother truss is a big main truss hung overhead. Smaller trusses and gear hang from it. It gathers many loads and passes them up to a few strong support points.", "purpose_function": "It provides a strong spanning top structure that collects the weight of many sub-hung trusses and points, transferring their combined load to a limited set of rated overhead anchor or hoist positions.", "practical_application": "A rigger flies the mother truss to trim first, then hangs daughter trusses, lighting, and effects beneath it, confirming the combined load stays within the mother truss's and the anchor points' rated capacities.", "category": "Rigging Structure", "related_terms": ["Truss", "Daughter truss", "Bridle", "Hanging point", "Chain motor", "Working load limit"], "common_mistakes": ["Treating the mother truss like an ordinary span and ignoring that it carries the summed weight of everything hung beneath it, not just its own load.", "Confusing the mother truss (the top carrying truss) with the daughter trusses it supports.", "UNSAFE: Loading a mother truss beyond the working load limit of the truss or its suspension points; combined sub-hung loads must be calculated and kept within rated capacity per ANSI/ESTA E1.2 and ASME B30 before flying."], "scenario_contexts": ["Rigging a large touring lighting rig where a mother truss carries several smaller trusses over a wide stage.", "Calculating point loads so a mother truss and its hoists stay within rated capacity.", "Building a layered ceiling grid where scenery and lighting hang from a common mother truss."]}, "e436bdc9-ff38-4dce-a3fa-24a9b72e4bcf": {"definition": "In entertainment rigging, a motor is an electric chain hoist used to raise, lower, and hold flown loads such as truss, scenery, and equipment overhead. The load hangs from a chain that feeds through a motorized gearbox and load brake; the same unit may hang fixed while its chain lifts the load, or be inverted so the body climbs its own chain.", "plain_english": "In rigging, a motor is an electric chain hoist. It lifts heavy gear up on a chain and holds it in the air. Crews use motors to fly trusses and scenery overhead.", "purpose_function": "It gives crews a powered, repeatable way to lift and hold heavy overhead loads at height, replacing hand hauling and keeping the load locked in place with a brake when it is not moving.", "practical_application": "A rigger hangs a motor from a rated point, hooks its chain to the truss, and runs it up to trim from a controller, checking the chain, hook, and brake before trusting the load overhead.", "category": "Powered Hoist", "related_terms": ["Chain motor", "Motor controller", "Working load limit", "Chain bag", "Load brake", "Hanging point"], "common_mistakes": ["Naming a hoist only by its class, such as 'one-ton motor', without checking the unit's actual rated capacity and duty rating.", "Forgetting that most entertainment chain hoists are not rated to lift people and must not be used for personnel unless specifically designed and certified for it.", "UNSAFE: Suspending a load over people with a single hoist that has no secondary safety and no verified brake; overhead lifting must follow ASME B30.16 and ANSI/ESTA E1.6-1, including load ratings, brakes, and inspection."], "scenario_contexts": ["Flying a lighting truss to trim with chain motors at load-in.", "Inspecting a chain hoist's chain, hook, and brake before a show.", "Choosing the right capacity motor for a calculated point load."]}, "af609f19-ff0e-4e2e-bdfa-9345b6ffef0d": {"definition": "A motor controller is the electrical control system that commands one or more chain hoists—switching them up, down, and stop, and on many systems setting their speed. It supplies switched, phase-correct power to each motor and provides operator controls plus safety functions such as emergency stop, direction interlocks, and, on variable-speed systems, position feedback.", "plain_english": "A motor controller is the box and controls that run the chain motors. It tells each motor to go up, stop, or come down. It also has an emergency stop to cut power fast if something goes wrong.", "purpose_function": "It lets an operator drive hoists safely and in coordination, delivering correct power and direction to each motor while enforcing stop and interlock functions so loads move only as commanded.", "practical_application": "An operator selects single motors or groups on the controller, checks phase and direction, then runs the rig to trim, keeping a hand near the emergency stop while loads are moving.", "category": "Motorized Rigging", "related_terms": ["Motor", "Chain motor", "Emergency stop", "Automated rigging", "Working load limit", "Trim"], "common_mistakes": ["Assuming the controller checks the load; a basic contactor controller only switches power and does not sense weight or overload on its own.", "Running motors with reversed phase so pressing 'up' drives the load down; motor direction must be verified before lifting.", "UNSAFE: Bypassing or ignoring the emergency stop and direction limits to save time; controller safety functions and interlocks required by ANSI/ESTA E1.6-1 and E1.6-2 must be working before any load moves."], "scenario_contexts": ["Grouping several hoists on a controller to fly a large grid level and together.", "Confirming correct phase and direction on the controller before the first lift.", "Hitting the emergency stop on the controller when a load starts to snag."]}, "47963356-be63-47bb-905a-406986a2f9e9": {"definition": "A mule block is a fixed sheave block used to change the direction of a running line—most often to turn an operating line, hand line, or lift line around a corner or obstruction so it can reach a remote position. It redirects the line without raising or lowering the load itself, unlike a head block or loft block.", "plain_english": "A mule block is a pulley that turns a rope around a corner. Crews use it to route an operating or lift line past something in the way. It changes the line's direction but does not lift the load itself.", "purpose_function": "It reroutes a line's path so an operator or arbor can be placed where it is needed, letting rigging run around walls, beams, or other equipment instead of dropping in a straight line.", "practical_application": "A rigger adds a mule block to lead a counterweight set's operating line to a different locking rail, sizing and rating the block for the line's tension and turn angle.", "category": "Fly system hardware", "related_terms": ["Head block", "Loft block", "Operating line", "Lift line", "Sheave", "Counterweight system"], "common_mistakes": ["Confusing a mule block with a head or loft block; a mule block only turns a line's direction and does not carry the lineset's suspended load like those blocks do.", "Under-sizing the block or ignoring the wrap angle, so the sheave and its mounting see more force than expected at a sharp turn.", "UNSAFE: Mounting a mule block to unrated structure or with the wrong pin or shackle; a redirect point carries real force and must be rigged to rated capacity per ANSI/ESTA E1.4-1 and ASME B30.26 hardware ratings."], "scenario_contexts": ["Leading a counterweight operating line around a wall to a remote locking rail with a mule block.", "Turning a lift line horizontally across the grid to reach an off-center head block.", "Sizing a redirect block for the tension and turn angle shown in a rigging plot."]}, "cb3940ec-2046-4a1c-8e9c-747e46dabc61": {"definition": "The operating line is the rope an operator hauls to raise and lower a counterweight or hemp lineset. In a counterweight system it is an endless loop: fixed to the top of the arbor, it runs up over the head block, down through the locking rail to the operator, around a tension pulley at the stage floor, and back up to the bottom of the arbor. It is also called the hand line or purchase line.", "plain_english": "The operating line is the rope a crew pulls to raise and lower a flown pipe. It runs in a loop from the counterweights, over a top pulley, down to the operator, and back. Pulling it moves the load.", "purpose_function": "It gives the operator a continuous hand line to drive a lineset in both directions and to hold or lock it at trim, transferring the operator's effort to the arbor and batten.", "practical_application": "An operator releases the rope lock, hauls the operating line to fly the set to trim, then re-engages the lock; a frayed or slack operating line is a red flag during inspection.", "category": "Counterweight Rigging", "related_terms": ["Arbor", "Head block", "Rope lock", "Counterweight system", "Lift line", "Tension pulley"], "common_mistakes": ["Confusing the operating (hand) line with the lift lines; the operating line drives the arbor, while the lift lines connect the arbor to the batten and load.", "Trusting the rope lock alone to hold a set; the rope lock is meant to hold a balanced set, not to stop a heavy out-of-weight load.", "UNSAFE: Running a set that is badly out of balance so the operating line can rip through the hands or run away; linesets must be weighted to balance and handled per ANSI/ESTA E1.4-1 before operating."], "scenario_contexts": ["Hauling the operating line to fly a lit drop to its trim during a cue.", "Inspecting the operating line for fraying and correct tension at the floor block.", "Engaging the rope lock on the operating line to hold a balanced set at trim."]}, "674a32e8-05bd-4881-b3c6-f76f6a6b53e8": {"definition": "Out trim is the raised, flown-out preset height of a batten and its load—its stored or cleared position, flown up above the audience's sightlines. It is one of the plotted trim heights recorded for a lineset, contrasted with in trim, the lowered playing position.", "plain_english": "Out trim is the up, stored position for a flown pipe and its load. It is set high, usually out of the audience's view. Crews fly a piece to out trim to clear the stage or store it.", "purpose_function": "It fixes a repeatable raised height so a piece stops at the same 'out' position every time, keeping it clear of the stage picture, sightlines, and other scenery.", "practical_application": "An operator flies a batten up until its trim marks reach the plotted out trim, checks that it is level and clear overhead, then records the height in the lineset schedule.", "category": "Trim and travel", "related_terms": ["In trim", "High trim", "Low trim", "Trim", "Batten", "Lineset"], "common_mistakes": ["Swapping out trim and in trim: out trim is the raised, stored position, while in trim is the lowered playing position.", "Setting an out trim without checking clearances overhead, so the batten, load, or arbor collides with the grid or other scenery.", "UNSAFE: Flying to an out trim that lets a piece strike the grid, other flown pieces, or a person aloft; travel and clearances must be planned and checked per ANSI/ESTA E1.4-1."], "scenario_contexts": ["Setting the out trim for a border so it masks the loft but hangs clear above the set.", "Flying a backdrop to out trim between scenes to clear the stage.", "Recording in and out trims for every lineset during technical rehearsal."]}, "2671db46-a733-42f4-9a8c-a7d3c52364ef": {"definition": "Overstage describes the space and equipment located directly above the stage or performance area—the fly loft, grid, battens, and rigging suspended over the acting space. The term distinguishes overhead rigging and positions from understage (below the stage floor) equipment.", "plain_english": "Overstage means the area right above the stage. It covers the pipes, rigging, and gear hung over the acting space. Crews say overstage to tell it apart from the space under the stage floor.", "purpose_function": "The term groups all the overhead rigging space and its equipment, so crews can clearly separate work and hazards above the stage from those below it.", "practical_application": "A production electrician plans overstage rigging—battens, motors, and cable runs above the stage—while a separate team handles understage traps and lifts.", "category": "Stage House", "related_terms": ["Fly loft", "Grid", "Batten", "Understage", "Flies", "Hanging point"], "common_mistakes": ["Using 'overstage' loosely for anything backstage; it specifically means the space and rigging above the stage, not the wings or understage.", "Forgetting that overstage work is overhead work, so tools and hardware aloft can fall on people below.", "UNSAFE: Working overstage without securing tools and clearing or protecting the area below; dropped objects are a serious hazard and overhead work must follow fall-protection and dropped-object practice per OSHA 29 CFR 1910/1926."], "scenario_contexts": ["Coordinating overstage rigging positions on a hang plot before load-in.", "Clearing the deck below when crews are working overstage on the grid.", "Separating overstage lighting battens from understage lift equipment in a venue survey."]}, "639863cd-3f96-465a-a58c-d6d7122fc826": {"definition": "A perch is a vertical side-lighting position located just upstage of the proscenium in the wings, where fixtures are mounted on a pipe, ladder, or small platform to light the stage from a steep side angle. Also called a proscenium perch, it provides high side light close to the proscenium opening while staying hidden from the audience.", "plain_english": "A perch is a lighting spot in the wings, just behind the proscenium arch. Lights mount there to hit the stage from a steep side angle. It sits at the side, often up high, out of the audience's view.", "purpose_function": "It gives designers a strong side-lighting angle near the proscenium that front-of-house positions cannot reach, shaping performers from the side while staying out of the audience's sightlines.", "practical_application": "An electrician rigs and focuses fixtures on the perch to add side light on downstage performers, cabling them back to nearby dimmers or a distro.", "category": "Lighting Position", "related_terms": ["Boom", "Box boom", "Proscenium", "Sidelight", "Ladder", "Wing"], "common_mistakes": ["Confusing a perch with a box boom; a perch sits in the wings just behind the proscenium, while a box boom is a vertical position out in the auditorium's side wall or box.", "Overloading a perch pipe or platform with more fixtures and cable than it is rated to hold.", "UNSAFE: Mounting fixtures on a perch without safety cables and secure clamps; anything hung overhead near the cast and audience must be secured against falling per ANSI/ESTA E1.4-1 and manufacturer rigging guidance."], "scenario_contexts": ["Adding steep side light on downstage actors from a perch position.", "Focusing perch fixtures to skim across the front of the stage.", "Cabling and safetying units on a perch before a show."]}, "8ffb20f7-2799-4181-983d-935e2e09dad6": {"definition": "In entertainment and overhead rigging, a pick is a single point from which a load is suspended or lifted—one hoist or hang location in a rigging plot—and, used as a verb or as 'the pick,' the act or instance of lifting a load at such a point. Riggers count the picks in a venue to describe how many separate suspension points a production requires.", "plain_english": "A pick is one point where a load hangs from above. Riggers count the picks to know how many hang points a show needs. As a verb, to pick a load means to lift it. Each pick must be strong enough for its share of the weight.", "purpose_function": "It names a single suspension or lift location so riggers can plan, count, and rate every point that will carry part of the overhead load.", "practical_application": "A rigger reads the rigging plot to place each pick, then rates the hoist, hardware, and structure at that point for the load it will carry.", "category": "Rigging point", "related_terms": ["Pick point", "Bridle", "Chain hoist", "Working load limit", "Dead hang", "Shackle"], "common_mistakes": ["Treating a pick as automatically safe without checking that the hoist, hardware, and overhead structure are each rated for the load at that point.", "Confusing the number of picks with the total load; more picks spread the weight, but each point still carries only its own rated share.", "UNSAFE: Loading a pick beyond the working load limit of its weakest part—hoist, sling, shackle, or structure—which can drop the load on people below; every pick must stay within the rated capacity of every component and the structure per ASME B30 and ANSI/ESTA E1 practice."], "scenario_contexts": ["Counting the picks in an arena to plan how many chain hoists a touring show needs.", "Rating the hoist and hardware at each pick for its share of a flown line-array.", "Marking on the deck where each pick lands before flying points up to the structure."]}}$ape$::jsonb)) d WHERE g.id=d.id;
COMMIT;
